{
  "name": "OutfitForge - Game Ready Character Designer",
  "description": "An AI-powered character outfit generator that allows you to upload a base model and design high-quality, game-ready outfits using Gemini models.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type ImageSize = '1K' | '2K' | '4K';
export type ModelType = 'gemini-2.5-flash-image' | 'gemini-3-pro-image-preview';

export interface GeneratedOutfit {
  id: string;
  url: string;
  prompt: string;
  timestamp: number;
  model: ModelType;
}

export interface AppState {
  baseImage: string | null;
  outfits: GeneratedOutfit[];
  isGenerating: boolean;
  selectedModel: ModelType;
  selectedSize: ImageSize;
  error: string | null;
}

export interface WindowAIS {
  hasSelectedApiKey: () => Promise<boolean>;
  openSelectKey: () => Promise<void>;
}

declare global {
  interface Window {
    aistudio: WindowAIS;
  }
}

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ModelType, ImageSize } from "../types";

export class GeminiService {
  private static async getAIInstance() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  static async generateOutfit(
    baseImageBase64: string,
    prompt: string,
    model: ModelType,
    size: ImageSize = '1K'
  ): Promise<string> {
    const ai = await this.getAIInstance();

    // For outfit generation, we want the model to understand this is a character design task.
    // We append specific "game-ready" keywords to the prompt to guide the style.
    const enhancedPrompt = `
      High-detail game-ready character outfit concept art. 
      Add the following outfit to the character in the image: ${prompt}.
      Maintain the original character's pose, facial features, and body proportions. 
      Professional concept art style, neutral background, realistic textures, PBR materials, 8k resolution, Unreal Engine 5 render style.
    `.trim();

    try {
      const mimeType = baseImageBase64.split(';')[0].split(':')[1];
      const base64Data = baseImageBase64.split(',')[1];

      const response: GenerateContentResponse = await ai.models.generateContent({
        model: model,
        contents: {
          parts: [
            {
              inlineData: {
                data: base64Data,
                mimeType: mimeType,
              },
            },
            {
              text: enhancedPrompt,
            },
          ],
        },
        config: model === 'gemini-3-pro-image-preview' ? {
          imageConfig: {
            aspectRatio: "1:1",
            imageSize: size
          }
        } : undefined
      });

      // Find the image part in candidates
      if (response.candidates && response.candidates[0].content.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
          }
        }
      }

      throw new Error("No image was generated in the response.");
    } catch (error: any) {
      console.error("Gemini Generation Error:", error);
      if (error.message?.includes("Requested entity was not found")) {
        throw new Error("RE_SELECT_KEY");
      }
      throw error;
    }
  }
}

import React, { useState, useCallback, useEffect } from 'react';
import { ModelType, ImageSize, GeneratedOutfit, AppState } from './types';
import { GeminiService } from './services/geminiService';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import MainEditor from './components/MainEditor';
import ResultGallery from './components/ResultGallery';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    baseImage: null,
    outfits: [],
    isGenerating: false,
    selectedModel: 'gemini-2.5-flash-image',
    selectedSize: '1K',
    error: null,
  });

  const [prompt, setPrompt] = useState('');

  const handleBaseImageUpload = (imageUrl: string) => {
    setState(prev => ({ ...prev, baseImage: imageUrl, error: null }));
  };

  const checkAndSelectKey = async () => {
    if (state.selectedModel === 'gemini-3-pro-image-preview') {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) {
        await window.aistudio.openSelectKey();
        // Assuming success after call per instructions
        return true;
      }
    }
    return true;
  };

  const handleGenerate = async () => {
    if (!state.baseImage) {
      setState(prev => ({ ...prev, error: "Please upload a base character first." }));
      return;
    }
    if (!prompt.trim()) {
      setState(prev => ({ ...prev, error: "Please enter an outfit description." }));
      return;
    }

    setState(prev => ({ ...prev, isGenerating: true, error: null }));

    try {
      await checkAndSelectKey();

      const generatedUrl = await GeminiService.generateOutfit(
        state.baseImage,
        prompt,
        state.selectedModel,
        state.selectedSize
      );

      const newOutfit: GeneratedOutfit = {
        id: Math.random().toString(36).substr(2, 9),
        url: generatedUrl,
        prompt: prompt,
        timestamp: Date.now(),
        model: state.selectedModel,
      };

      setState(prev => ({
        ...prev,
        outfits: [newOutfit, ...prev.outfits],
        isGenerating: false
      }));
    } catch (error: any) {
      console.error(error);
      if (error.message === "RE_SELECT_KEY") {
        setState(prev => ({ ...prev, error: "API Key session expired. Please re-select your key." }));
        await window.aistudio.openSelectKey();
      } else {
        setState(prev => ({ ...prev, error: error.message || "An error occurred during generation.", isGenerating: false }));
      }
      setState(prev => ({ ...prev, isGenerating: false }));
    }
  };

  return (
    <div className="flex flex-col h-screen bg-slate-950 text-slate-100 overflow-hidden">
      <Header />

      <div className="flex flex-1 overflow-hidden">
        <Sidebar 
          selectedModel={state.selectedModel}
          onModelChange={(m) => setState(prev => ({ ...prev, selectedModel: m }))}
          selectedSize={state.selectedSize}
          onSizeChange={(s) => setState(prev => ({ ...prev, selectedSize: s }))}
          onGenerate={handleGenerate}
          isGenerating={state.isGenerating}
          prompt={prompt}
          onPromptChange={setPrompt}
        />

        <main className="flex-1 flex flex-col p-6 overflow-y-auto space-y-8">
          {state.error && (
            <div className="bg-red-500/20 border border-red-500 text-red-200 p-4 rounded-xl mb-4 animate-pulse">
              {state.error}
            </div>
          )}

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 h-full min-h-0">
            <MainEditor 
              baseImage={state.baseImage} 
              onUpload={handleBaseImageUpload}
              isGenerating={state.isGenerating}
            />

            <ResultGallery 
              outfits={state.outfits} 
              isGenerating={state.isGenerating}
            />
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React from 'react';
import { ModelType, ImageSize } from '../types';

interface SidebarProps {
  selectedModel: ModelType;
  onModelChange: (model: ModelType) => void;
  selectedSize: ImageSize;
  onSizeChange: (size: ImageSize) => void;
  onGenerate: () => void;
  isGenerating: boolean;
  prompt: string;
  onPromptChange: (val: string) => void;
}

const Sidebar: React.FC<SidebarProps> = ({
  selectedModel,
  onModelChange,
  selectedSize,
  onSizeChange,
  onGenerate,
  isGenerating,
  prompt,
  onPromptChange
}) => {
  const outfitPresets = [
    "Cyberpunk tactical armor with neon accents",
    "Gothic victorian dress with ornate embroidery",
    "Sci-fi pilot suit with glowing oxygen lines",
    "Medieval knight plating with royal blue tabard",
    "Streetwear ninja outfit with tech-wear details",
    "Space explorer suit with weathered textures"
  ];

  return (
    <aside className="w-80 bg-slate-900 border-r border-slate-800 p-6 flex flex-col space-y-8 shrink-0">
      <section>
        <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-3 block">
          Model Engine
        </label>
        <div className="grid grid-cols-1 gap-2">
          <button
            onClick={() => onModelChange('gemini-2.5-flash-image')}
            className={`px-4 py-3 rounded-xl border text-left transition-all ${
              selectedModel === 'gemini-2.5-flash-image'
                ? 'bg-indigo-500/20 border-indigo-500 text-indigo-100'
                : 'bg-slate-800 border-slate-700 text-slate-400 hover:border-slate-600'
            }`}
          >
            <div className="font-medium">Nano Banana</div>
            <div className="text-[10px] opacity-60">Standard Speed Generation</div>
          </button>
          <button
            onClick={() => onModelChange('gemini-3-pro-image-preview')}
            className={`px-4 py-3 rounded-xl border text-left transition-all ${
              selectedModel === 'gemini-3-pro-image-preview'
                ? 'bg-purple-500/20 border-purple-500 text-purple-100'
                : 'bg-slate-800 border-slate-700 text-slate-400 hover:border-slate-600'
            }`}
          >
            <div className="font-medium">Nano Banana Pro</div>
            <div className="text-[10px] opacity-60">High Fidelity (Requires Pro Key)</div>
          </button>
        </div>
      </section>

      {selectedModel === 'gemini-3-pro-image-preview' && (
        <section className="animate-in fade-in slide-in-from-top-2 duration-300">
          <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-3 block">
            Target Resolution
          </label>
          <div className="grid grid-cols-3 gap-2">
            {(['1K', '2K', '4K'] as ImageSize[]).map((size) => (
              <button
                key={size}
                onClick={() => onSizeChange(size)}
                className={`py-2 rounded-lg border text-sm font-medium transition-all ${
                  selectedSize === size
                    ? 'bg-purple-500 text-white border-purple-400'
                    : 'bg-slate-800 border-slate-700 text-slate-400 hover:border-slate-600'
                }`}
              >
                {size}
              </button>
            ))}
          </div>
        </section>
      )}

      <section className="flex-1 flex flex-col min-h-0">
        <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-3 block">
          Outfit Description
        </label>
        <textarea
          value={prompt}
          onChange={(e) => onPromptChange(e.target.value)}
          placeholder="e.g. A futuristic mech-pilot suit with matte black finish and gold trim..."
          className="flex-1 w-full bg-slate-800 border border-slate-700 rounded-xl p-4 text-sm text-slate-100 placeholder:text-slate-500 focus:outline-none focus:ring-2 focus:ring-indigo-500 resize-none"
        />

        <div className="mt-4 flex flex-wrap gap-2">
          {outfitPresets.map((preset) => (
            <button
              key={preset}
              onClick={() => onPromptChange(preset)}
              className="text-[10px] bg-slate-800 hover:bg-slate-700 text-slate-400 px-2 py-1 rounded transition-colors"
            >
              + {preset.split(' ').slice(0, 2).join(' ')}
            </button>
          ))}
        </div>
      </section>

      <button
        onClick={onGenerate}
        disabled={isGenerating}
        className={`w-full py-4 rounded-xl font-bold text-white shadow-lg transition-all transform active:scale-95 ${
          isGenerating
            ? 'bg-slate-700 cursor-not-allowed'
            : 'bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500'
        }`}
      >
        {isGenerating ? (
          <span className="flex items-center justify-center">
            <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" fill="none" viewBox="0 0 24 24">
              <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
              <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
            </svg>
            Generating...
          </span>
        ) : 'Forging Outfit'}
      </button>
    </aside>
  );
};

export default Sidebar;

import React, { useRef } from 'react';

interface MainEditorProps {
  baseImage: string | null;
  onUpload: (url: string) => void;
  isGenerating: boolean;
}

const MainEditor: React.FC<MainEditorProps> = ({ baseImage, onUpload, isGenerating }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        onUpload(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const triggerUpload = () => {
    if (!isGenerating) {
      fileInputRef.current?.click();
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-900/50 rounded-2xl border border-slate-800/50 overflow-hidden relative">
      <div className="absolute top-4 left-4 z-10">
        <span className="bg-slate-950/80 backdrop-blur-md text-[10px] text-slate-400 px-2 py-1 rounded border border-slate-800 uppercase tracking-widest font-bold">
          Input Slot: Base Model
        </span>
      </div>

      <div 
        className={`flex-1 flex flex-col items-center justify-center p-8 transition-all ${
          !baseImage ? 'cursor-pointer hover:bg-slate-800/30' : ''
        }`}
        onClick={!baseImage ? triggerUpload : undefined}
      >
        {baseImage ? (
          <div className="relative group w-full h-full flex items-center justify-center">
            <img 
              src={baseImage} 
              alt="Base Character" 
              className="max-h-full max-w-full object-contain rounded-lg shadow-2xl"
            />
            <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
              <button 
                onClick={triggerUpload}
                className="bg-white text-black px-6 py-2 rounded-full font-bold hover:scale-105 transition-transform"
              >
                Swap Base Model
              </button>
            </div>
          </div>
        ) : (
          <div className="text-center space-y-4">
            <div className="w-20 h-20 bg-slate-800 rounded-full flex items-center justify-center mx-auto border-2 border-dashed border-slate-700">
              <svg className="w-10 h-10 text-slate-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
              </svg>
            </div>
            <div>
              <p className="text-lg font-medium">No character base yet</p>
              <p className="text-sm text-slate-500">Upload a T-pose or A-pose character base</p>
            </div>
            <button className="bg-indigo-500 hover:bg-indigo-400 text-white px-6 py-2 rounded-xl transition-colors font-medium">
              Browse Files
            </button>
          </div>
        )}
      </div>

      <input 
        type="file" 
        ref={fileInputRef} 
        className="hidden" 
        accept="image/*" 
        onChange={handleFileChange}
      />

      <div className="p-4 border-t border-slate-800 flex justify-between items-center text-xs text-slate-500">
        <span>Ready for Outfit Layering</span>
        <span>Supports PNG, JPG, WEBP</span>
      </div>
    </div>
  );
};

export default MainEditor;

