                  <div className="absolute top-2 right-2 flex gap-1">
                    <span className="bg-black/60 backdrop-blur-sm text-[8px] text-white px-1.5 py-0.5 rounded uppercase font-bold tracking-tighter">
                      {outfit.model.includes('pro') ? 'PRO' : 'FLASH'}
                    </span>
                  </div>
                </div>

                <div className="p-3 bg-slate-900/90 backdrop-blur-md">
                  <p className="text-[10px] text-slate-400 line-clamp-2 italic mb-2">"{outfit.prompt}"</p>
                  <div className="flex justify-between items-center">
                    <span className="text-[9px] text-slate-600">{new Date(outfit.timestamp).toLocaleTimeString()}</span>
                    <div className="flex space-x-2">
                       <a 
                        href={outfit.url} 
                        download={`outfit-${outfit.id}.png`}
                        className="text-[10px] text-indigo-400 hover:text-indigo-300 font-bold uppercase"
                       >
                         Download PNG
                       </a>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default ResultGallery;

