  const getOutlineStyle = (outfit: GeneratedOutfit) => {
    if (!outfit.outline?.enabled) return {};
    const thickness = outfit.outline.thickness === 'thin' ? '1px' : outfit.outline.thickness === 'medium' ? '2.5px' : '4px';
    const color = outfit.outline.color;

    // Creating a crisp outline using multiple drop shadows with 0 blur
    return {
      filter: `
        drop-shadow(${thickness} 0 0 ${color}) 
        drop-shadow(-${thickness} 0 0 ${color}) 
        drop-shadow(0 ${thickness} 0 ${color}) 
        drop-shadow(0 -${thickness} 0 ${color})
      `
    };
  };

