import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ModelType, ImageSize, AspectRatio, OutlineConfig } from "../types";

export class GeminiService {
  private static async getAIInstance() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  static async generateOutfit(
    baseImageBase64: string,
    prompt: string,
    model: ModelType,
    aspectRatio: AspectRatio,
    outline: OutlineConfig,
    size: ImageSize = '1K'
  ): Promise<string> {
    const ai = await this.getAIInstance();

    let outlineInstruction = "";
    if (outline.enabled) {
      const glowStr = outline.glow ? "with a soft bloom/outer glow effect" : "with sharp, clean edges";
      outlineInstruction = `CRITICAL STYLE: Render a solid ${outline.color} outline around the character's entire silhouette ${glowStr}. 
      Outline thickness: ${outline.thickness}. This must look like a professional game character highlight or selection effect.`;
    }

    const enhancedPrompt = `
      GAME-READY ASSET FORGERY. 
      Subject Outfit: ${prompt}.

      CORE INSTRUCTION: 
      You must replicate the EXACT art style of the attached base image. 
      - If the base is 2D digital art, the output must be 2D digital art with matching brushwork.
      - If the base is a 3D render, match the material properties, shader quality, and lighting setup perfectly.
      - Match the color palette's saturation and contrast levels.

      TECHNICAL SPEC: 
      - Character isolated on 100% PURE TRANSPARENT BACKGROUND. 
      - NO shadows on the ground, NO floor, NO environment.
      - DO NOT alter the character's face, body proportions, or pose. Only change the clothing/armor/outfit.
      - The generated outfit must look like it belongs to the same universe and was created by the same artist.
      ${outlineInstruction}
    `.trim();

    try {
      const mimeType = baseImageBase64.split(';')[0].split(':')[1];
      const base64Data = baseImageBase64.split(',')[1];

      const response: GenerateContentResponse = await ai.models.generateContent({
        model: model,
        contents: {
          parts: [
            {
              inlineData: {
                data: base64Data,
                mimeType: mimeType,
              },
            },
            {
              text: enhancedPrompt,
            },
          ],
        },
        config: {
          imageConfig: {
            aspectRatio: aspectRatio,
            ...(model === 'gemini-3-pro-image-preview' && { imageSize: size })
          }
        }
      });

      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
          }
        }
      }

      throw new Error("Generation failed to return image data.");
    } catch (error: any) {
      console.error("Gemini Error:", error);
      if (error.message?.includes("Requested entity was not found")) {
        throw new Error("RE_SELECT_KEY");
      }
      throw error;
    }
  }
}

