import React, { useState, useEffect } from 'react';
import { ModelType, ImageSize, AspectRatio, GeneratedOutfit, AppState, OutlineConfig } from './types';
import { GeminiService } from './services/geminiService';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import MainEditor from './components/MainEditor';
import ResultGallery from './components/ResultGallery';

const LOCAL_STORAGE_KEY = 'outfitforge_saved_assets';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    baseImage: null,
    outfits: [],
    isGenerating: false,
    selectedModel: 'gemini-2.5-flash-image',
    selectedSize: '1K',
    selectedAspectRatio: '1:1',
    outline: {
      enabled: false,
      color: '#4f46e5',
      thickness: 'medium',
      glow: false
    },
    error: null,
  });

  const [prompt, setPrompt] = useState('');

  // Load saved outfits from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem(LOCAL_STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setState(prev => ({ ...prev, outfits: parsed }));
      } catch (e) {
        console.error("Failed to parse saved outfits", e);
      }
    }
  }, []);

  // Sync outfits to localStorage whenever they change
  useEffect(() => {
    if (state.outfits.length > 0) {
      localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(state.outfits));
    }
  }, [state.outfits]);

  const handleBaseImageUpload = (imageUrl: string) => {
    setState(prev => ({ ...prev, baseImage: imageUrl, error: null }));
  };

  const checkAndSelectKey = async () => {
    if (state.selectedModel === 'gemini-3-pro-image-preview') {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) {
        await window.aistudio.openSelectKey();
        return true;
      }
    }
    return true;
  };

  const handleGenerate = async () => {
    if (!state.baseImage) {
      setState(prev => ({ ...prev, error: "Upload a base character first." }));
      return;
    }
    if (!prompt.trim()) {
      setState(prev => ({ ...prev, error: "Describe the outfit first." }));
      return;
    }

    setState(prev => ({ ...prev, isGenerating: true, error: null }));

    try {
      await checkAndSelectKey();

      const generatedUrl = await GeminiService.generateOutfit(
        state.baseImage,
        prompt,
        state.selectedModel,
        state.selectedAspectRatio,
        state.outline,
        state.selectedSize
      );

      const newOutfit: GeneratedOutfit = {
        id: Math.random().toString(36).substr(2, 9),
        url: generatedUrl,
        prompt: prompt,
        timestamp: Date.now(),
        model: state.selectedModel,
        aspectRatio: state.selectedAspectRatio,
        outline: state.outline.enabled ? { ...state.outline } : undefined,
        isSaved: false
      };

      setState(prev => ({
        ...prev,
        outfits: [newOutfit, ...prev.outfits],
        isGenerating: false
      }));
    } catch (error: any) {
      if (error.message === "RE_SELECT_KEY") {
        await window.aistudio.openSelectKey();
      } else {
        setState(prev => ({ ...prev, error: error.message || "Failed to generate outfit.", isGenerating: false }));
      }
      setState(prev => ({ ...prev, isGenerating: false }));
    }
  };

  const updateOutfitMetadata = (id: string, name: string, description: string) => {
    setState(prev => ({
      ...prev,
      outfits: prev.outfits.map(o => 
        o.id === id ? { ...o, name, description, isSaved: true } : o
      )
    }));
  };

  const deleteOutfit = (id: string) => {
    setState(prev => {
      const newOutfits = prev.outfits.filter(o => o.id !== id);
      localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(newOutfits));
      return { ...prev, outfits: newOutfits };
    });
  };

  const updateOutline = (updates: Partial<OutlineConfig>) => {
    setState(prev => ({
      ...prev,
      outline: { ...prev.outline, ...updates }
    }));
  };

  return (
    <div className="flex flex-col min-h-screen bg-slate-950 text-slate-100 overflow-x-hidden">
      <Header />

      <div className="flex flex-col lg:flex-row flex-1 overflow-hidden">
        <Sidebar 
          selectedModel={state.selectedModel}
          onModelChange={(m) => setState(prev => ({ ...prev, selectedModel: m }))}
          selectedSize={state.selectedSize}
          onSizeChange={(s) => setState(prev => ({ ...prev, selectedSize: s }))}
          selectedAspectRatio={state.selectedAspectRatio}
          onAspectRatioChange={(a) => setState(prev => ({ ...prev, selectedAspectRatio: a }))}
          outline={state.outline}
          onOutlineChange={updateOutline}
          onGenerate={handleGenerate}
          isGenerating={state.isGenerating}
          prompt={prompt}
          onPromptChange={setPrompt}
        />

        <main className="flex-1 flex flex-col p-4 lg:p-6 overflow-y-auto space-y-6">
          {state.error && (
            <div className="bg-red-500/10 border border-red-500/50 text-red-200 p-3 rounded-lg text-sm flex justify-between items-center">
              {state.error}
              <button onClick={() => setState(prev => ({...prev, error: null}))}>✕</button>
            </div>
          )}

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 flex-1 min-h-0">
            <MainEditor 
              baseImage={state.baseImage} 
              onUpload={handleBaseImageUpload}
              isGenerating={state.isGenerating}
            />
            <ResultGallery 
              outfits={state.outfits} 
              isGenerating={state.isGenerating}
              onUpdateMetadata={updateOutfitMetadata}
              onDelete={deleteOutfit}
            />
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

