import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ModelType, ImageSize, AspectRatio, OutlineConfig } from "../types";

export class GeminiService {
  private static async getAIInstance() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  static async generateOutfit(
    baseImageBase64: string,
    prompt: string,
    model: ModelType,
    aspectRatio: AspectRatio,
    outline: OutlineConfig,
    size: ImageSize = '1K'
  ): Promise<string> {
    const ai = await this.getAIInstance();

    let outlineInstruction = "";
    if (outline.enabled) {
      const glowStr = outline.glow ? "with a soft bloom/outer glow effect" : "with sharp, clean edges";
      outlineInstruction = `CRITICAL STYLE: Render a solid ${outline.color} outline around the character's entire silhouette ${glowStr}. 
      Outline thickness: ${outline.thickness}. This must look like a professional game character highlight or selection effect.`;
    }

    const enhancedPrompt = `
      GAME-READY ASSET FORGERY. 
      Subject Outfit: ${prompt}.

      CORE INSTRUCTION: 
      You must replicate the EXACT art style, brushwork, lighting, and material quality of the attached base image. 
      - If the base is 2D digital art, the output must be 2D digital art with matching lineart and coloring.
      - If the base is a 3D render, match the shaders, PBR textures, and rim lighting perfectly.

      TECHNICAL SPEC: 
      - Character MUST be isolated on a 100% PURE FLAT SOLID BACKGROUND (Pure White #FFFFFF or Pure Black #000000).
      - NO shadows on the ground, NO floor planes, NO environment props.
      - DO NOT alter the character's face, body proportions, or pose. Only change the clothing and equipment.
      - Ensure the edges are sharp and clean for alpha channel extraction.
      ${outlineInstruction}
    `.trim();

    try {
      const mimeType = baseImageBase64.split(';')[0].split(':')[1];
      const base64Data = baseImageBase64.split(',')[1];

      const response: GenerateContentResponse = await ai.models.generateContent({
        model: model,
        contents: {
          parts: [
            {
              inlineData: {
                data: base64Data,
                mimeType: mimeType,
              },
            },
            {
              text: enhancedPrompt,
            },
          ],
        },
        config: {
          imageConfig: {
            aspectRatio: aspectRatio,
            ...(model === 'gemini-3-pro-image-preview' && { imageSize: size })
          }
        }
      });

      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
          }
        }
      }

      throw new Error("Generation failed to return image data.");
    } catch (error: any) {
      console.error("Gemini Error:", error);
      if (error.message?.includes("Requested entity was not found")) {
        throw new Error("RE_SELECT_KEY");
      }
      throw error;
    }
  }
}

import React, { useState, useEffect } from 'react';
import { ModelType, ImageSize, AspectRatio, GeneratedOutfit, AppState, OutlineConfig } from './types';
import { GeminiService } from './services/geminiService';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import MainEditor from './components/MainEditor';
import ResultGallery from './components/ResultGallery';

const LOCAL_STORAGE_KEY = 'outfitforge_saved_assets';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    baseImage: null,
    outfits: [],
    isGenerating: false,
    selectedModel: 'gemini-2.5-flash-image',
    selectedSize: '1K',
    selectedAspectRatio: '1:1',
    outline: {
      enabled: false,
      color: '#4f46e5',
      thickness: 'medium',
      glow: false
    },
    error: null,
  });

  const [prompt, setPrompt] = useState('');

  useEffect(() => {
    const saved = localStorage.getItem(LOCAL_STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setState(prev => ({ ...prev, outfits: parsed }));
      } catch (e) {
        console.error("Failed to parse saved outfits", e);
      }
    }
  }, []);

  useEffect(() => {
    if (state.outfits.length > 0) {
      localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(state.outfits));
    }
  }, [state.outfits]);

  const handleBaseImageUpload = (imageUrl: string) => {
    setState(prev => ({ ...prev, baseImage: imageUrl, error: null }));
  };

  const checkAndSelectKey = async () => {
    if (state.selectedModel === 'gemini-3-pro-image-preview') {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) {
        await window.aistudio.openSelectKey();
        return true;
      }
    }
    return true;
  };

  const handleGenerate = async () => {
    if (!state.baseImage) {
      setState(prev => ({ ...prev, error: "Upload a base character first." }));
      return;
    }
    if (!prompt.trim()) {
      setState(prev => ({ ...prev, error: "Describe the outfit first." }));
      return;
    }

    setState(prev => ({ ...prev, isGenerating: true, error: null }));

    try {
      await checkAndSelectKey();

      const generatedUrl = await GeminiService.generateOutfit(
        state.baseImage,
        prompt,
        state.selectedModel,
        state.selectedAspectRatio,
        state.outline,
        state.selectedSize
      );

      const newOutfit: GeneratedOutfit = {
        id: Math.random().toString(36).substr(2, 9),
        url: generatedUrl,
        prompt: prompt,
        timestamp: Date.now(),
        model: state.selectedModel,
        aspectRatio: state.selectedAspectRatio,
        outline: state.outline.enabled ? { ...state.outline } : undefined,
        isSaved: false
      };

      setState(prev => ({
        ...prev,
        outfits: [newOutfit, ...prev.outfits],
        isGenerating: false
      }));
    } catch (error: any) {
      if (error.message === "RE_SELECT_KEY") {
        await window.aistudio.openSelectKey();
      } else {
        setState(prev => ({ ...prev, error: error.message || "Failed to generate outfit.", isGenerating: false }));
      }
      setState(prev => ({ ...prev, isGenerating: false }));
    }
  };

  const updateOutfitMetadata = (id: string, name: string, description: string) => {
    setState(prev => ({
      ...prev,
      outfits: prev.outfits.map(o => 
        o.id === id ? { ...o, name, description, isSaved: true } : o
      )
    }));
  };

  const updateOutfitUrl = (id: string, newUrl: string) => {
    setState(prev => ({
      ...prev,
      outfits: prev.outfits.map(o => o.id === id ? { ...o, url: newUrl } : o)
    }));
  };

  const deleteOutfit = (id: string) => {
    setState(prev => {
      const newOutfits = prev.outfits.filter(o => o.id !== id);
      localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(newOutfits));
      return { ...prev, outfits: newOutfits };
    });
  };

  const updateOutline = (updates: Partial<OutlineConfig>) => {
    setState(prev => ({
      ...prev,
      outline: { ...prev.outline, ...updates }
    }));
  };

  return (
    <div className="flex flex-col min-h-screen bg-slate-950 text-slate-100 overflow-x-hidden">
      <Header />

      <div className="flex flex-col lg:flex-row flex-1 overflow-hidden">
        <Sidebar 
          selectedModel={state.selectedModel}
          onModelChange={(m) => setState(prev => ({ ...prev, selectedModel: m }))}
          selectedSize={state.selectedSize}
          onSizeChange={(s) => setState(prev => ({ ...prev, selectedSize: s }))}
          selectedAspectRatio={state.selectedAspectRatio}
          onAspectRatioChange={(a) => setState(prev => ({ ...prev, selectedAspectRatio: a }))}
          outline={state.outline}
          onOutlineChange={updateOutline}
          onGenerate={handleGenerate}
          isGenerating={state.isGenerating}
          prompt={prompt}
          onPromptChange={setPrompt}
        />

        <main className="flex-1 flex flex-col p-4 lg:p-6 overflow-y-auto space-y-6">
          {state.error && (
            <div className="bg-red-500/10 border border-red-500/50 text-red-200 p-3 rounded-lg text-sm flex justify-between items-center">
              {state.error}
              <button onClick={() => setState(prev => ({...prev, error: null}))}>✕</button>
            </div>
          )}

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 flex-1 min-h-0">
            <MainEditor 
              baseImage={state.baseImage} 
              onUpload={handleBaseImageUpload}
              isGenerating={state.isGenerating}
            />
            <ResultGallery 
              outfits={state.outfits} 
              isGenerating={state.isGenerating}
              onUpdateMetadata={updateOutfitMetadata}
              onUpdateOutfitUrl={updateOutfitUrl}
              onDelete={deleteOutfit}
            />
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { GeneratedOutfit } from '../types';

interface ResultGalleryProps {
  outfits: GeneratedOutfit[];
  isGenerating: boolean;
  onUpdateMetadata: (id: string, name: string, description: string) => void;
  onUpdateOutfitUrl: (id: string, newUrl: string) => void;
  onDelete: (id: string) => void;
}

type BgMode = 'checker' | 'dark' | 'light';

const ResultGallery: React.FC<ResultGalleryProps> = ({ outfits, isGenerating, onUpdateMetadata, onUpdateOutfitUrl, onDelete }) => {
  const [bgMode, setBgMode] = useState<BgMode>('checker');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [tempName, setTempName] = useState('');
  const [tempDesc, setTempDesc] = useState('');

  const startEditing = (outfit: GeneratedOutfit) => {
    setEditingId(outfit.id);
    setTempName(outfit.name || '');
    setTempDesc(outfit.description || '');
  };

  const saveMetadata = (id: string) => {
    onUpdateMetadata(id, tempName, tempDesc);
    setEditingId(null);
  };

  const extractAlpha = async (outfit: GeneratedOutfit) => {
    setProcessingId(outfit.id);

    try {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.src = outfit.url;

      await new Promise((resolve, reject) => { 
        img.onload = resolve;
        img.onerror = reject;
      });

      const canvas = document.createElement('canvas');
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d', { willReadFrequently: true });
      if (!ctx) return;

      ctx.drawImage(img, 0, 0);
      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const data = imageData.data;

      // Sample background color from corner
      const bgR = data[0];
      const bgG = data[1];
      const bgB = data[2];

      const tolerance = 45; // Increased tolerance for compressed edges

      for (let i = 0; i < data.length; i += 4) {
        const r = data[i];
        const g = data[i + 1];
        const b = data[i + 2];

        const dist = Math.sqrt(
          Math.pow(r - bgR, 2) + 
          Math.pow(g - bgG, 2) + 
          Math.pow(b - bgB, 2)
        );

        if (dist < tolerance) {
          data[i + 3] = 0; // Transparent
        }
      }

      ctx.putImageData(imageData, 0, 0);
      const transparentUrl = canvas.toDataURL('image/png');
      onUpdateOutfitUrl(outfit.id, transparentUrl);
    } catch (err) {
      console.error("Alpha extraction failed:", err);
    } finally {
      setProcessingId(null);
    }
  };

  const getOutlineStyle = (outfit: GeneratedOutfit) => {
    if (!outfit.outline?.enabled) return {};
    const thickness = outfit.outline.thickness === 'thin' ? '1px' : outfit.outline.thickness === 'medium' ? '3px' : '6px';
    const color = outfit.outline.color;
    const blur = outfit.outline.glow ? '8px' : '0px';

    return {
      filter: `
        drop-shadow(${thickness} 0 ${blur} ${color}) 
        drop-shadow(-${thickness} 0 ${blur} ${color}) 
        drop-shadow(0 ${thickness} ${blur} ${color}) 
        drop-shadow(0 -${thickness} ${blur} ${color})
      `
    };
  };

  const getBgClass = () => {
    switch (bgMode) {
      case 'dark': return 'bg-slate-950';
      case 'light': return 'bg-white';
      default: return 'bg-slate-900 checker-bg';
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-900/50 rounded-2xl border border-slate-800/50 overflow-hidden shadow-2xl">
      <style>{`
        .checker-bg {
          background-image: linear-gradient(45deg, #1e293b 25%, transparent 25%), 
                            linear-gradient(-45deg, #1e293b 25%, transparent 25%), 
                            linear-gradient(45deg, transparent 75%, #1e293b 75%), 
                            linear-gradient(-45deg, transparent 75%, #1e293b 75%);
          background-size: 20px 20px;
          background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
        }
      `}</style>

      <div className="p-4 border-b border-slate-800 flex items-center justify-between bg-slate-900/80 backdrop-blur-md sticky top-0 z-20">
        <div className="flex items-center gap-3">
          <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Output Hub</h3>
          <div className="flex rounded-md border border-slate-700 overflow-hidden">
            {(['checker', 'dark', 'light'] as BgMode[]).map(mode => (
              <button
                key={mode}
                onClick={() => setBgMode(mode)}
                className={`px-2 py-1 text-[8px] uppercase font-bold transition-all ${bgMode === mode ? 'bg-indigo-600 text-white' : 'bg-slate-800 text-slate-500'}`}
              >
                {mode}
              </button>
            ))}
          </div>
        </div>
        <span className="text-[9px] bg-indigo-500/20 text-indigo-400 px-2 py-0.5 rounded-full font-bold">
          {outfits.length} Assets
        </span>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6">
        {outfits.length === 0 && !isGenerating ? (
          <div className="h-full flex flex-col items-center justify-center opacity-20 text-center py-20">
            <svg className="w-16 h-16 mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
            </svg>
            <p className="text-sm font-medium">No assets forged yet</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 gap-8">
            {isGenerating && (
              <div className="aspect-square rounded-xl bg-slate-800/50 border-2 border-dashed border-slate-700 flex flex-col items-center justify-center animate-pulse">
                <div className="w-10 h-10 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                <span className="text-xs text-slate-500 font-bold uppercase tracking-widest">Synthesizing...</span>
              </div>
            )}

            {outfits.map((outfit) => (
              <div key={outfit.id} className="group flex flex-col bg-slate-800/80 rounded-2xl overflow-hidden border border-slate-700/50 shadow-xl transition-all hover:border-indigo-500/50">
                <div className={`relative flex-shrink-0 flex items-center justify-center p-6 ${getBgClass()} transition-colors duration-300 min-h-[350px]`}>
                  <img 
                    src={outfit.url} 
                    alt={outfit.prompt} 
                    style={getOutlineStyle(outfit)}
                    className="w-full h-auto object-contain max-h-[500px] z-10 transition-transform group-hover:scale-105 duration-700"
                  />

                  <div className="absolute top-4 right-4 flex flex-col gap-2 z-20">
                    <button 
                      onClick={() => onDelete(outfit.id)}
                      className="bg-red-500/80 backdrop-blur-md p-1.5 rounded-md text-white hover:bg-red-600 transition-colors"
                      title="Delete Asset"
                    >
                      <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                      </svg>
                    </button>

                    <button 
                      onClick={() => extractAlpha(outfit)}
                      disabled={processingId === outfit.id}
                      className={`p-1.5 rounded-md text-white backdrop-blur-md transition-all ${processingId === outfit.id ? 'bg-indigo-600 animate-pulse' : 'bg-indigo-500/80 hover:bg-indigo-600'}`}
                      title="Remove Background / Extract Alpha"
                    >
                      <svg className={`w-3 h-3 ${processingId === outfit.id ? 'animate-spin' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 10l-2 1m0 0l-2-1m2 1v2.5M20 7l-2 1m2-1l-2-1m2 1v2.5M14 4l-2-1-2 1M4 7l2-1M4 7l2 1M4 7v2.5M12 21l-2-1m2 1l2-1m-2 1v-2.5M6 18l-2-1v-2.5M18 18l2-1v-2.5" />
                      </svg>
                    </button>

                    <span className="bg-black/80 backdrop-blur-md text-[8px] text-white px-2 py-1 rounded-md border border-white/10 font-black tracking-widest">
                      {outfit.aspectRatio}
                    </span>
