export type ImageSize = '1K' | '2K' | '4K';
export type ModelType = 'gemini-2.5-flash-image' | 'gemini-3-pro-image-preview';
export type AspectRatio = '1:1' | '3:4' | '4:3' | '9:16' | '16:9';

export interface OutlineConfig {
  enabled: boolean;
  color: string;
  thickness: 'thin' | 'medium' | 'bold';
  glow: boolean;
}

export interface GeneratedOutfit {
  id: string;
  url: string;
  prompt: string;
  timestamp: number;
  model: ModelType;
  aspectRatio: AspectRatio;
  outline?: OutlineConfig;
  name?: string;
  description?: string;
  isSaved?: boolean;
}

export interface AppState {
  baseImage: string | null;
  styleImage: string | null;
  outfits: GeneratedOutfit[];
  isGenerating: boolean;
  selectedModel: ModelType;
  selectedSize: ImageSize;
  selectedAspectRatio: AspectRatio;
  outline: OutlineConfig;
  error: string | null;
}

/**
 * Fixed: The environment already provides an AIStudio interface and a window.aistudio property.
 * We augment the global AIStudio interface directly to avoid "identical modifiers" 
 * and "subsequent property declaration" errors on the Window interface.
 */
declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }
}

import React, { useState, useEffect } from 'react';
import { ModelType, ImageSize, AspectRatio, GeneratedOutfit, AppState, OutlineConfig } from './types';
import { GeminiService } from './services/geminiService';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import MainEditor from './components/MainEditor';
import ResultGallery from './components/ResultGallery';

const LOCAL_STORAGE_KEY = 'outfitforge_saved_assets';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    baseImage: null,
    styleImage: null,
    outfits: [],
    isGenerating: false,
    selectedModel: 'gemini-2.5-flash-image',
    selectedSize: '1K',
    selectedAspectRatio: '1:1',
    outline: {
      enabled: false,
      color: '#4f46e5',
      thickness: 'medium',
      glow: false
    },
    error: null,
  });

  const [prompt, setPrompt] = useState('');

  useEffect(() => {
    const saved = localStorage.getItem(LOCAL_STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setState(prev => ({ ...prev, outfits: parsed }));
      } catch (e) {
        console.error("Failed to parse saved outfits", e);
      }
    }
  }, []);

  useEffect(() => {
    if (state.outfits.length > 0) {
      localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(state.outfits));
    }
  }, [state.outfits]);

  const handleBaseImageUpload = (imageUrl: string) => {
    setState(prev => ({ ...prev, baseImage: imageUrl, error: null }));
  };

  const handleStyleImageUpload = (imageUrl: string | null) => {
    setState(prev => ({ ...prev, styleImage: imageUrl, error: null }));
  };

  const checkAndSelectKey = async () => {
    if (state.selectedModel === 'gemini-3-pro-image-preview') {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) {
        await window.aistudio.openSelectKey();
        return true;
      }
    }
    return true;
  };

  const handleGenerate = async () => {
    if (!state.baseImage) {
      setState(prev => ({ ...prev, error: "Upload a base character first." }));
      return;
    }
    if (!prompt.trim()) {
      setState(prev => ({ ...prev, error: "Describe the outfit first." }));
      return;
    }

    setState(prev => ({ ...prev, isGenerating: true, error: null }));

    try {
      await checkAndSelectKey();

      const generatedUrl = await GeminiService.generateOutfit(
        state.baseImage,
        state.styleImage,
        prompt,
        state.selectedModel,
        state.selectedAspectRatio,
        state.outline,
        state.selectedSize
      );

      const newOutfit: GeneratedOutfit = {
        id: Math.random().toString(36).substr(2, 9),
        url: generatedUrl,
        prompt: prompt,
        timestamp: Date.now(),
        model: state.selectedModel,
        aspectRatio: state.selectedAspectRatio,
        outline: state.outline.enabled ? { ...state.outline } : undefined,
        isSaved: false
      };

      setState(prev => ({
        ...prev,
        outfits: [newOutfit, ...prev.outfits],
        isGenerating: false
      }));
    } catch (error: any) {
      if (error.message === "RE_SELECT_KEY") {
        await window.aistudio.openSelectKey();
      } else {
        setState(prev => ({ ...prev, error: error.message || "Failed to generate outfit.", isGenerating: false }));
      }
      setState(prev => ({ ...prev, isGenerating: false }));
    }
  };

  const updateOutfitMetadata = (id: string, name: string, description: string) => {
    setState(prev => ({
      ...prev,
      outfits: prev.outfits.map(o => 
        o.id === id ? { ...o, name, description, isSaved: true } : o
      )
    }));
  };

  const updateOutfitUrl = (id: string, newUrl: string) => {
    setState(prev => ({
      ...prev,
      outfits: prev.outfits.map(o => o.id === id ? { ...o, url: newUrl } : o)
    }));
  };

  const deleteOutfit = (id: string) => {
    setState(prev => {
      const newOutfits = prev.outfits.filter(o => o.id !== id);
      localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(newOutfits));
      return { ...prev, outfits: newOutfits };
    });
  };

  const updateOutline = (updates: Partial<OutlineConfig>) => {
    setState(prev => ({
      ...prev,
      outline: { ...prev.outline, ...updates }
    }));
  };

  return (
    <div className="flex flex-col min-h-screen bg-slate-950 text-slate-100 overflow-x-hidden">
      <Header />

      <div className="flex flex-col lg:flex-row flex-1 overflow-hidden">
        <Sidebar 
          selectedModel={state.selectedModel}
          onModelChange={(m) => setState(prev => ({ ...prev, selectedModel: m }))}
          selectedSize={state.selectedSize}
          onSizeChange={(s) => setState(prev => ({ ...prev, selectedSize: s }))}
          selectedAspectRatio={state.selectedAspectRatio}
          onAspectRatioChange={(a) => setState(prev => ({ ...prev, selectedAspectRatio: a }))}
          outline={state.outline}
          onOutlineChange={updateOutline}
          onGenerate={handleGenerate}
          isGenerating={state.isGenerating}
          prompt={prompt}
          onPromptChange={setPrompt}
        />

        <main className="flex-1 flex flex-col p-4 lg:p-6 overflow-y-auto space-y-6">
          {state.error && (
            <div className="bg-red-500/10 border border-red-500/50 text-red-200 p-3 rounded-lg text-sm flex justify-between items-center animate-in slide-in-from-top-4 duration-300">
              <div className="flex items-center gap-2">
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                </svg>
                {state.error}
              </div>
              <button onClick={() => setState(prev => ({...prev, error: null}))}>✕</button>
            </div>
          )}

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 flex-1 min-h-0">
            <MainEditor 
              baseImage={state.baseImage} 
              styleImage={state.styleImage}
              onUploadBase={handleBaseImageUpload}
              onUploadStyle={handleStyleImageUpload}
              isGenerating={state.isGenerating}
            />
            <ResultGallery 
              outfits={state.outfits} 
              isGenerating={state.isGenerating}
              onUpdateMetadata={updateOutfitMetadata}
              onUpdateOutfitUrl={updateOutfitUrl}
              onDelete={deleteOutfit}
            />
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ModelType, ImageSize, AspectRatio, OutlineConfig } from "../types";

export class GeminiService {
  private static async getAIInstance() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  static async generateOutfit(
    baseImageBase64: string,
    styleImageBase64: string | null,
    prompt: string,
    model: ModelType,
    aspectRatio: AspectRatio,
    outline: OutlineConfig,
    size: ImageSize = '1K'
  ): Promise<string> {
    const ai = await this.getAIInstance();

    let outlineInstruction = "";
    if (outline.enabled) {
      const glowStr = outline.glow ? "with a soft bloom/outer glow effect" : "with sharp, clean edges";
      outlineInstruction = `CRITICAL STYLE: Render a solid ${outline.color} outline around the character's entire silhouette ${glowStr}. 
      Outline thickness: ${outline.thickness}. This must look like a professional game character highlight or selection effect.`;
    }

    const styleContext = styleImageBase64 
      ? `ADOPT THE VISUAL STYLE OF THE SECOND IMAGE. Use its color palette, brushstrokes, material rendering, and overall aesthetic.`
      : `Replicate the EXACT art style, brushwork, lighting, and material quality of the attached base character image.`;

    const enhancedPrompt = `
      GAME-READY ASSET FORGERY. 
      Subject Outfit Modification: ${prompt}.

      CORE INSTRUCTION: 
      - The first image provided is the BASE CHARACTER. Keep its pose, proportions, and facial features identical.
      - ${styleContext}

      TECHNICAL SPEC: 
      - Character MUST be isolated on a 100% PURE FLAT SOLID BACKGROUND (Pure White #FFFFFF or Pure Black #000000).
      - NO shadows on the ground, NO floor planes, NO environment props.
      - Ensure the edges are sharp and clean for alpha channel extraction.
      ${outlineInstruction}
    `.trim();

    try {
      const parts: any[] = [];

      // Add Base Image
      const baseMime = baseImageBase64.split(';')[0].split(':')[1];
      const baseData = baseImageBase64.split(',')[1];
      parts.push({
        inlineData: { data: baseData, mimeType: baseMime }
      });

      // Add Style Image if present
      if (styleImageBase64) {
        const styleMime = styleImageBase64.split(';')[0].split(':')[1];
        const styleData = styleImageBase64.split(',')[1];
        parts.push({
          inlineData: { data: styleData, mimeType: styleMime }
        });
      }

      // Add Text Prompt
      parts.push({ text: enhancedPrompt });

      const response: GenerateContentResponse = await ai.models.generateContent({
        model: model,
        contents: { parts },
        config: {
          imageConfig: {
            aspectRatio: aspectRatio,
            ...(model === 'gemini-3-pro-image-preview' && { imageSize: size })
          }
        }
      });

      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
          }
        }
      }

      throw new Error("Generation failed to return image data.");
    } catch (error: any) {
      console.error("Gemini Error:", error);
      if (error.message?.includes("Requested entity was not found")) {
        throw new Error("RE_SELECT_KEY");
      }
      throw error;
    }
  }
}

import React, { useRef, useState } from 'react';

interface MainEditorProps {
