import React, { useState } from 'react';
import { GeneratedOutfit } from '../types';

interface ResultGalleryProps {
  outfits: GeneratedOutfit[];
  isGenerating: boolean;
  onUpdateMetadata: (id: string, name: string, description: string) => void;
  onUpdateOutfitUrl: (id: string, newUrl: string) => void;
  onDelete: (id: string) => void;
}

type BgMode = 'checker' | 'dark' | 'light';

const ResultGallery: React.FC<ResultGalleryProps> = ({ outfits, isGenerating, onUpdateMetadata, onUpdateOutfitUrl, onDelete }) => {
  const [bgMode, setBgMode] = useState<BgMode>('checker');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [tempName, setTempName] = useState('');
  const [tempDesc, setTempDesc] = useState('');

  const startEditing = (outfit: GeneratedOutfit) => {
    setEditingId(outfit.id);
    setTempName(outfit.name || '');
    setTempDesc(outfit.description || '');
  };

  const saveMetadata = (id: string) => {
    onUpdateMetadata(id, tempName, tempDesc);
    setEditingId(null);
  };

  /**
   * Advanced Alpha Extraction
   * Uses multi-point sampling and soft-edge feathering for a "game-ready" feel.
   */
  const extractAlpha = async (outfit: GeneratedOutfit) => {
    setProcessingId(outfit.id);

    try {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.src = outfit.url;

      await new Promise((resolve, reject) => { 
        img.onload = resolve;
        img.onerror = reject;
      });

      const canvas = document.createElement('canvas');
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d', { willReadFrequently: true });
      if (!ctx) return;

      ctx.drawImage(img, 0, 0);
      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const data = imageData.data;

      // Sample 4 corners to find the most representative background color
      const corners = [
        [data[0], data[1], data[2]], // Top-left
        [data[(canvas.width - 1) * 4], data[(canvas.width - 1) * 4 + 1], data[(canvas.width - 1) * 4 + 2]], // Top-right
        [data[(data.length - canvas.width * 4)], data[(data.length - canvas.width * 4) + 1], data[(data.length - canvas.width * 4) + 2]], // Bottom-left
        [data[data.length - 4], data[data.length - 3], data[data.length - 2]] // Bottom-right
      ];

      // Average corners for the target key color
      const bgR = corners.reduce((acc, c) => acc + c[0], 0) / 4;
      const bgG = corners.reduce((acc, c) => acc + c[1], 0) / 4;
      const bgB = corners.reduce((acc, c) => acc + c[2], 0) / 4;

      const tolerance = 35; // Base threshold
      const feather = 20;   // Range for soft transition

      for (let i = 0; i < data.length; i += 4) {
        const r = data[i];
        const g = data[i + 1];
        const b = data[i + 2];
        const currentAlpha = data[i + 3];

        // Skip if already transparent
        if (currentAlpha === 0) continue;

        // Calculate Euclidean color distance
        const dist = Math.sqrt(
          Math.pow(r - bgR, 2) + 
          Math.pow(g - bgG, 2) + 
          Math.pow(b - bgB, 2)
        );

        if (dist < tolerance) {
          data[i + 3] = 0; // Pure background
        } else if (dist < tolerance + feather) {
          // Soft transition for anti-aliased edges
          const alphaScale = (dist - tolerance) / feather;
          data[i + 3] = Math.min(currentAlpha, Math.round(alphaScale * 255));

          // Optional: Color spill reduction
          // Blend towards subject color if very close to edge
          // (Simple version: just leave color as is but reduce opacity)
        }
      }

      ctx.putImageData(imageData, 0, 0);
      const transparentUrl = canvas.toDataURL('image/png');
      onUpdateOutfitUrl(outfit.id, transparentUrl);
    } catch (err) {
      console.error("Alpha extraction failed:", err);
    } finally {
      setProcessingId(null);
    }
  };

  const getOutlineStyle = (outfit: GeneratedOutfit) => {
    if (!outfit.outline?.enabled) return {};
    const thickness = outfit.outline.thickness === 'thin' ? '1px' : outfit.outline.thickness === 'medium' ? '3px' : '6px';
    const color = outfit.outline.color;
    const blur = outfit.outline.glow ? '8px' : '0px';

    return {
      filter: `
        drop-shadow(${thickness} 0 ${blur} ${color}) 
        drop-shadow(-${thickness} 0 ${blur} ${color}) 
        drop-shadow(0 ${thickness} ${blur} ${color}) 
        drop-shadow(0 -${thickness} ${blur} ${color})
      `
    };
  };

  const getBgClass = () => {
    switch (bgMode) {
      case 'dark': return 'bg-slate-950';
      case 'light': return 'bg-white';
      default: return 'bg-slate-900 checker-bg';
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-900/50 rounded-2xl border border-slate-800/50 overflow-hidden shadow-2xl">
      <style>{`
        .checker-bg {
