                className={`px-3 py-1.5 text-[8px] lg:text-[9px] uppercase font-black transition-all ${bgMode === mode ? 'bg-indigo-600 text-white' : 'bg-slate-800 text-slate-500 hover:text-slate-300'}`}
              >
                {mode}
              </button>
            ))}
          </div>
        </div>
        <span className="text-[9px] bg-indigo-500/20 text-indigo-400 px-2 py-0.5 rounded-full font-bold border border-indigo-500/30">
