export class GeminiService {
  private static async getAIInstance() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  /**
   * Resizes an image to ensure it doesn't exceed API limits while maintaining quality.
   */
  private static async optimizeImage(base64: string, maxDim: number = 1024): Promise<string> {
    return new Promise((resolve) => {
      const img = new Image();
      img.onload = () => {
        let width = img.width;
        let height = img.height;
        if (width > maxDim || height > maxDim) {
          if (width > height) {
            height *= maxDim / width;
            width = maxDim;
          } else {
            width *= maxDim / height;
            height = maxDim;
          }
        }
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', 0.85));
      };
      img.src = base64;
    });
  }

  static async generateOutfit(
    baseImageBase64: string,
    styleImageBase64: string | null,
    prompt: string,
    model: ModelType,
    aspectRatio: AspectRatio,
    outline: OutlineConfig,
    size: ImageSize = '1K'
  ): Promise<string> {
    const ai = await this.getAIInstance();

    // Optimize inputs
    const optimizedBase = await this.optimizeImage(baseImageBase64);
    const optimizedStyle = styleImageBase64 ? await this.optimizeImage(styleImageBase64) : null;

    let outlineInstruction = "";
    if (outline.enabled) {
      const glowStr = outline.glow ? "with a soft bloom/outer glow effect" : "with sharp, clean edges";
      outlineInstruction = `CRITICAL STYLE: Render a solid ${outline.color} outline around the character's entire silhouette ${glowStr}. 
      Outline thickness: ${outline.thickness}. This highlight effect is permanent in the rendered pixels.`;
    }

    const styleContext = optimizedStyle 
      ? `ADOPT THE VISUAL STYLE OF THE SECOND IMAGE. Use its color palette, brushstrokes, and material rendering.`
      : `Replicate the EXACT art style and lighting of the attached base character image.`;

    const enhancedPrompt = `
      GAME-READY CHARACTER ASSET GENERATION. 
      Task: Redesign character outfit to: ${prompt}.

      CONSTRAINTS: 
      - Maintain identical character pose, proportions, and features from the first image.
      - ${styleContext}
      - BACKGROUND: Must be 100% PURE FLAT SOLID COLOR (#FFFFFF or #000000). No gradients, no floors, no shadows.
      ${outlineInstruction}
    `.trim();

    try {
      const parts: any[] = [];

      const processPart = (b64: string) => ({
        inlineData: { 
          data: b64.split(',')[1], 
          mimeType: b64.split(';')[0].split(':')[1] 
        }
      });

      parts.push(processPart(optimizedBase));
      if (optimizedStyle) parts.push(processPart(optimizedStyle));
      parts.push({ text: enhancedPrompt });

      const response: GenerateContentResponse = await ai.models.generateContent({
        model,
        contents: { parts },
        config: {
          imageConfig: {
            aspectRatio,
            ...(model === 'gemini-3-pro-image-preview' && { imageSize: size })
          }
        }
      });

      const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (imagePart?.inlineData) {
        return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
      }

      throw new Error("The engine did not return an image. Try adjusting your prompt.");
    } catch (error: any) {
      console.error("Gemini Error:", error);
      if (error.message?.includes("Requested entity was not found")) throw new Error("RE_SELECT_KEY");
      throw error;
    }
  }
}

