import React, { useState, useMemo } from 'react';
import { GeneratedOutfit } from '../types';

interface ResultGalleryProps {
  outfits: GeneratedOutfit[];
  isGenerating: boolean;
  onUpdateMetadata: (id: string, name: string, description: string) => void;
  onUpdateOutfitUrl: (id: string, newUrl: string) => void;
  onDelete: (id: string) => void;
}

type BgMode = 'checker' | 'dark' | 'light';

const ResultGallery: React.FC<ResultGalleryProps> = ({ outfits, isGenerating, onUpdateMetadata, onUpdateOutfitUrl, onDelete }) => {
  const [bgMode, setBgMode] = useState<BgMode>('checker');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [tempName, setTempName] = useState('');
  const [tempDesc, setTempDesc] = useState('');

  const startEditing = (outfit: GeneratedOutfit) => {
    setEditingId(outfit.id);
    setTempName(outfit.name || '');
    setTempDesc(outfit.description || '');
  };

  const saveMetadata = (id: string) => {
    onUpdateMetadata(id, tempName, tempDesc);
    setEditingId(null);
  };

  /**
   * Optimized Alpha Extraction
   * Samples corners and edge centers for robust background detection.
   */
  const extractAlpha = async (outfit: GeneratedOutfit) => {
    if (processingId) return;
    setProcessingId(outfit.id);

    try {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.src = outfit.url;

      await new Promise((resolve, reject) => { 
        img.onload = resolve;
        img.onerror = reject;
      });

      const canvas = document.createElement('canvas');
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d', { willReadFrequently: true });
      if (!ctx) return;

      ctx.drawImage(img, 0, 0);
      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const data = imageData.data;

      // Sample background color (8 points around the frame)
      const samples = [
        [0, 0], [canvas.width - 1, 0], [0, canvas.height - 1], [canvas.width - 1, canvas.height - 1],
        [Math.floor(canvas.width / 2), 0], [0, Math.floor(canvas.height / 2)],
        [canvas.width - 1, Math.floor(canvas.height / 2)], [Math.floor(canvas.width / 2), canvas.height - 1]
      ];

      let totalR = 0, totalG = 0, totalB = 0;
      samples.forEach(([x, y]) => {
        const i = (y * canvas.width + x) * 4;
        totalR += data[i];
        totalG += data[i + 1];
        totalB += data[i + 2];
      });

      const bgR = totalR / samples.length;
      const bgG = totalG / samples.length;
      const bgB = totalB / samples.length;

      const tolerance = 40; 
      const feather = 25;   

      // Perform background removal in a single loop
      for (let i = 0; i < data.length; i += 4) {
        const r = data[i], g = data[i + 1], b = data[i + 2], a = data[i + 3];
        if (a === 0) continue;

        const dist = Math.sqrt(Math.pow(r - bgR, 2) + Math.pow(g - bgG, 2) + Math.pow(b - bgB, 2));

        if (dist < tolerance) {
          data[i + 3] = 0;
        } else if (dist < tolerance + feather) {
          const ratio = (dist - tolerance) / feather;
          data[i + 3] = Math.min(a, Math.round(ratio * 255));
        }
      }

      ctx.putImageData(imageData, 0, 0);
      onUpdateOutfitUrl(outfit.id, canvas.toDataURL('image/png'));
    } catch (err) {
      console.error("Alpha extraction failed:", err);
    } finally {
      setProcessingId(null);
    }
  };

  const getBgClass = useMemo(() => {
    switch (bgMode) {
      case 'dark': return 'bg-slate-950';
      case 'light': return 'bg-white';
      default: return 'bg-slate-900 checker-bg';
    }
  }, [bgMode]);

  return (
    <div className="flex flex-col h-full bg-slate-900/40 rounded-[2rem] border border-slate-800/50 overflow-hidden shadow-2xl">
      <style>{`
        .checker-bg {
          background-image: linear-gradient(45deg, #1e293b 25%, transparent 25%), 
                            linear-gradient(-45deg, #1e293b 25%, transparent 25%), 
                            linear-gradient(45deg, transparent 75%, #1e293b 75%), 
                            linear-gradient(-45deg, transparent 75%, #1e293b 75%);
          background-size: 20px 20px;
          background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
        }
      `}</style>

      <div className="p-5 border-b border-slate-800/80 flex items-center justify-between bg-slate-900/90 backdrop-blur-xl sticky top-0 z-20">
        <div className="flex items-center gap-4">
          <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">Asset Forge Gallery</h3>
          <div className="flex bg-slate-800/50 p-1 rounded-xl border border-slate-700/50">
            {(['checker', 'dark', 'light'] as BgMode[]).map(mode => (
              <button
                key={mode}
                onClick={() => setBgMode(mode)}
                className={`px-3 py-1.5 text-[8px] uppercase font-black rounded-lg transition-all ${bgMode === mode ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-500 hover:text-slate-300'}`}
              >
                {mode}
              </button>
            ))}
          </div>
        </div>
        <div className="flex items-center gap-2">
           <span className="text-[9px] bg-indigo-500/10 text-indigo-400 px-3 py-1 rounded-full font-black border border-indigo-500/20">
            {outfits.length} UNIQUE ASSETS
          </span>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-10 custom-scrollbar">
        {outfits.length === 0 && !isGenerating ? (
          <div className="h-full flex flex-col items-center justify-center opacity-10 text-center py-20 grayscale">
            <svg className="w-24 h-24 mb-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
