import React, { useState, useEffect, useReducer, useCallback } from 'react';
import { ModelType, ImageSize, AspectRatio, GeneratedOutfit, AppState, OutlineConfig } from './types';
import { GeminiService } from './services/geminiService';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import MainEditor from './components/MainEditor';
import ResultGallery from './components/ResultGallery';

const LOCAL_STORAGE_KEY = 'outfitforge_v2_assets';

type Action = 
  | { type: 'ADD_OUTFIT'; payload: GeneratedOutfit }
  | { type: 'UPDATE_OUTFIT'; id: string; updates: Partial<GeneratedOutfit> }
  | { type: 'DELETE_OUTFIT'; id: string }
  | { type: 'SET_OUTFITS'; payload: GeneratedOutfit[] }
  | { type: 'SET_BASE_IMAGE'; payload: string | null }
  | { type: 'SET_STYLE_IMAGE'; payload: string | null }
  | { type: 'SET_GENERATING'; payload: boolean }
  | { type: 'SET_ERROR'; payload: string | null }
  | { type: 'UPDATE_CONFIG'; payload: Partial<AppState> };

function appReducer(state: AppState, action: Action): AppState {
  switch (action.type) {
    case 'ADD_OUTFIT': return { ...state, outfits: [action.payload, ...state.outfits] };
    case 'UPDATE_OUTFIT': return {
      ...state,
      outfits: state.outfits.map(o => o.id === action.id ? { ...o, ...action.updates } : o)
    };
    case 'DELETE_OUTFIT': return { ...state, outfits: state.outfits.filter(o => o.id !== action.id) };
    case 'SET_OUTFITS': return { ...state, outfits: action.payload };
    case 'SET_BASE_IMAGE': return { ...state, baseImage: action.payload };
    case 'SET_STYLE_IMAGE': return { ...state, styleImage: action.payload };
    case 'SET_GENERATING': return { ...state, isGenerating: action.payload };
    case 'SET_ERROR': return { ...state, error: action.payload };
    case 'UPDATE_CONFIG': return { ...state, ...action.payload };
    default: return state;
  }
}

const App: React.FC = () => {
  const [state, dispatch] = useReducer(appReducer, {
    baseImage: null,
    styleImage: null,
    outfits: [],
    isGenerating: false,
    selectedModel: 'gemini-2.5-flash-image',
    selectedSize: '1K',
    selectedAspectRatio: '1:1',
    outline: { enabled: false, color: '#4f46e5', thickness: 'medium', glow: false },
    error: null,
  });

  const [prompt, setPrompt] = useState('');

  // Persistencia optimizada
  useEffect(() => {
    const saved = localStorage.getItem(LOCAL_STORAGE_KEY);
    if (saved) {
      try {
        dispatch({ type: 'SET_OUTFITS', payload: JSON.parse(saved) });
      } catch (e) {
        console.error("Storage corrupt", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(state.outfits));
  }, [state.outfits]);

  const handleGenerate = async () => {
    if (!state.baseImage) return dispatch({ type: 'SET_ERROR', payload: "Please upload a base character model." });
    if (!prompt.trim()) return dispatch({ type: 'SET_ERROR', payload: "Design prompt cannot be empty." });

    dispatch({ type: 'SET_GENERATING', payload: true });
    dispatch({ type: 'SET_ERROR', payload: null });

    try {
      if (state.selectedModel === 'gemini-3-pro-image-preview') {
        if (!(await window.aistudio.hasSelectedApiKey())) {
          await window.aistudio.openSelectKey();
        }
      }

      const generatedUrl = await GeminiService.generateOutfit(
        state.baseImage,
        state.styleImage,
        prompt,
        state.selectedModel,
        state.selectedAspectRatio,
        state.outline,
        state.selectedSize
      );

      const newOutfit: GeneratedOutfit = {
        id: crypto.randomUUID(),
        url: generatedUrl,
        originalUrl: generatedUrl,
        prompt: prompt,
        timestamp: Date.now(),
        model: state.selectedModel,
        aspectRatio: state.selectedAspectRatio,
        outline: state.outline.enabled ? { ...state.outline } : undefined,
      };

      dispatch({ type: 'ADD_OUTFIT', payload: newOutfit });
    } catch (error: any) {
      const msg = error.message === "RE_SELECT_KEY" ? "API Key error. Please re-select." : error.message;
      dispatch({ type: 'SET_ERROR', payload: msg });
      if (error.message === "RE_SELECT_KEY") await window.aistudio.openSelectKey();
    } finally {
      dispatch({ type: 'SET_GENERATING', payload: false });
    }
  };

  const updateOutfitUrl = useCallback((id: string, newUrl: string) => {
    dispatch({ type: 'UPDATE_OUTFIT', id, updates: { url: newUrl } });
  }, []);

  const updateMetadata = useCallback((id: string, name: string, description: string) => {
    dispatch({ type: 'UPDATE_OUTFIT', id, updates: { name, description, isSaved: true } });
  }, []);

  return (
    <div className="flex flex-col min-h-screen bg-[#050505] text-slate-100 selection:bg-indigo-500/30">
      <Header />

      <div className="flex flex-col lg:flex-row flex-1 overflow-hidden">
        <Sidebar 
          selectedModel={state.selectedModel}
          onModelChange={(m) => dispatch({ type: 'UPDATE_CONFIG', payload: { selectedModel: m } })}
          selectedSize={state.selectedSize}
          onSizeChange={(s) => dispatch({ type: 'UPDATE_CONFIG', payload: { selectedSize: s } })}
          selectedAspectRatio={state.selectedAspectRatio}
          onAspectRatioChange={(a) => dispatch({ type: 'UPDATE_CONFIG', payload: { selectedAspectRatio: a } })}
          outline={state.outline}
          onOutlineChange={(u) => dispatch({ type: 'UPDATE_CONFIG', payload: { outline: { ...state.outline, ...u } } })}
          onGenerate={handleGenerate}
          isGenerating={state.isGenerating}
          prompt={prompt}
          onPromptChange={setPrompt}
        />

        <main className="flex-1 flex flex-col p-4 lg:p-8 overflow-y-auto space-y-8 custom-scrollbar">
          {state.error && (
            <div className="bg-red-500/10 border border-red-500/20 text-red-400 p-4 rounded-2xl flex justify-between items-center animate-in fade-in slide-in-from-top-4">
              <span className="text-xs font-bold uppercase tracking-wider">{state.error}</span>
              <button onClick={() => dispatch({ type: 'SET_ERROR', payload: null })} className="hover:scale-110 transition-transform">✕</button>
            </div>
          )}

          <div className="grid grid-cols-1 xl:grid-cols-[1fr_1.2fr] gap-8 flex-1 min-h-0">
            <MainEditor 
              baseImage={state.baseImage} 
              styleImage={state.styleImage}
              onUploadBase={(url) => dispatch({ type: 'SET_BASE_IMAGE', payload: url })}
              onUploadStyle={(url) => dispatch({ type: 'SET_STYLE_IMAGE', payload: url })}
              isGenerating={state.isGenerating}
            />
            <ResultGallery 
              outfits={state.outfits} 
              isGenerating={state.isGenerating}
              onUpdateMetadata={updateMetadata}
              onUpdateOutfitUrl={updateOutfitUrl}
              onDelete={(id) => dispatch({ type: 'DELETE_OUTFIT', id })}
            />
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

export class ImageProcessor {
  /**
   * Ejecuta la extracción de alpha de forma optimizada.
   */
  static async processAlpha(
    sourceUrl: string, 
    threshold: number, 
    feather: number
  ): Promise<string> {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = sourceUrl;

    await new Promise((resolve, reject) => { 
      img.onload = resolve;
      img.onerror = reject;
    });

    const canvas = document.createElement('canvas');
    canvas.width = img.width;
    canvas.height = img.height;
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) throw new Error("Canvas context failed");

    ctx.drawImage(img, 0, 0);
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const data = imageData.data;

    // Sampling optimizado (esquinas y centros de bordes)
    const samples = [
      [0, 0], [canvas.width - 1, 0], [0, canvas.height - 1], [canvas.width - 1, canvas.height - 1],
      [Math.floor(canvas.width / 2), 0], [0, Math.floor(canvas.height / 2)],
      [canvas.width - 1, Math.floor(canvas.height / 2)], [Math.floor(canvas.width / 2), canvas.height - 1]
    ];

    let tR = 0, tG = 0, tB = 0;
    samples.forEach(([x, y]) => {
      const i = (y * canvas.width + x) * 4;
      tR += data[i]; tG += data[i + 1]; tB += data[i + 2];
    });

    const bgR = tR / samples.length;
    const bgG = tG / samples.length;
    const bgB = tB / samples.length;

    // Procesamiento de píxeles altamente optimizado
    for (let i = 0; i < data.length; i += 4) {
      if (data[i + 3] === 0) continue;

      const r = data[i], g = data[i+1], b = data[i+2];
      const dist = Math.sqrt((r - bgR) ** 2 + (g - bgG) ** 2 + (b - bgB) ** 2);

      if (dist < threshold) {
        data[i + 3] = 0;
      } else if (dist < threshold + feather) {
        data[i + 3] = Math.round(((dist - threshold) / feather) * 255);
      }
    }

    ctx.putImageData(imageData, 0, 0);
    return canvas.toDataURL('image/png');
  }
}

import React, { useState, useMemo, useCallback } from 'react';
import { GeneratedOutfit } from '../types';
import { ImageProcessor } from '../services/imageProcessor';

interface ResultGalleryProps {
  outfits: GeneratedOutfit[];
  isGenerating: boolean;
  onUpdateMetadata: (id: string, name: string, description: string) => void;
  onUpdateOutfitUrl: (id: string, newUrl: string) => void;
  onDelete: (id: string) => void;
}

type BgMode = 'checker' | 'dark' | 'light';

const ResultGallery: React.FC<ResultGalleryProps> = ({ outfits, isGenerating, onUpdateMetadata, onUpdateOutfitUrl, onDelete }) => {
  const [bgMode, setBgMode] = useState<BgMode>('checker');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [alphaConfig, setAlphaConfig] = useState({ threshold: 45, feather: 25 });

  const [metaInputs, setMetaInputs] = useState({ name: '', desc: '' });

  const handleEditMeta = (outfit: GeneratedOutfit) => {
    setEditingId(outfit.id);
    setMetaInputs({ name: outfit.name || '', desc: outfit.description || '' });
  };

  const handleAlphaExtraction = async (outfit: GeneratedOutfit) => {
    if (processingId) return;
    setProcessingId(outfit.id);
    try {
      const result = await ImageProcessor.processAlpha(
        outfit.originalUrl || outfit.url, 
        alphaConfig.threshold, 
        alphaConfig.feather
      );
      onUpdateOutfitUrl(outfit.id, result);
    } catch (e) {
      console.error("Alpha process failed", e);
    } finally {
      setProcessingId(null);
    }
  };

  const bgStyles = useMemo(() => {
    switch (bgMode) {
      case 'dark': return 'bg-[#0a0a0a]';
      case 'light': return 'bg-slate-100';
      default: return 'bg-[#0f172a] checker-bg';
    }
  }, [bgMode]);

  return (
    <div className="flex flex-col h-full bg-[#0a0a0a] rounded-[2.5rem] border border-slate-800/40 overflow-hidden shadow-[0_0_50px_rgba(0,0,0,0.5)]">
      <style>{`
        .checker-bg {
          background-image: linear-gradient(45deg, #050505 25%, transparent 25%), linear-gradient(-45deg, #050505 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #050505 75%), linear-gradient(-45deg, transparent 75%, #050505 75%);
          background-size: 32px 32px;
          background-position: 0 0, 0 16px, 16px -16px, -16px 0px;
        }
      `}</style>

      {/* Control Bar */}
      <div className="p-6 border-b border-slate-800/60 bg-[#0a0a0a]/80 backdrop-blur-2xl sticky top-0 z-30 space-y-4">
        <div className="flex items-center justify-between">
          <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">Vault / {outfits.length} Assets</h3>
          <div className="flex bg-slate-900/50 p-1 rounded-xl border border-slate-800">
            {(['checker', 'dark', 'light'] as BgMode[]).map(mode => (
              <button key={mode} onClick={() => setBgMode(mode)} className={`px-4 py-2 text-[9px] uppercase font-black rounded-lg transition-all ${bgMode === mode ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>
                {mode}
              </button>
            ))}
          </div>
        </div>

        <div className="grid grid-cols-2 gap-8 px-4 py-3 bg-white/[0.02] rounded-2xl border border-white/[0.05]">
          <div className="space-y-2">
            <div className="flex justify-between"><label className="text-[8px] font-bold text-slate-500 uppercase tracking-widest">Threshold</label><span className="text-[10px] font-mono text-indigo-400">{alphaConfig.threshold}</span></div>
            <input type="range" min="1" max="150" value={alphaConfig.threshold} onChange={(e) => setAlphaConfig(p => ({...p, threshold: +e.target.value}))} className="w-full h-1 bg-slate-800 rounded-full appearance-none accent-indigo-500 cursor-pointer" />
          </div>
          <div className="space-y-2">
            <div className="flex justify-between"><label className="text-[8px] font-bold text-slate-500 uppercase tracking-widest">Softness</label><span className="text-[10px] font-mono text-indigo-400">{alphaConfig.feather}</span></div>
            <input type="range" min="0" max="100" value={alphaConfig.feather} onChange={(e) => setAlphaConfig(p => ({...p, feather: +e.target.value}))} className="w-full h-1 bg-slate-800 rounded-full appearance-none accent-indigo-500 cursor-pointer" />
          </div>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-12 custom-scrollbar pb-24">
        {outfits.length === 0 && !isGenerating ? (
          <div className="h-full flex flex-col items-center justify-center opacity-10 py-32 grayscale">
            <svg className="w-20 h-20 mb-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
            <p className="text-xs font-black uppercase tracking-[0.4em]">Ready for Generation</p>
          </div>
        ) : (
          <div className="flex flex-col gap-16">
            {isGenerating && (
              <div className="aspect-square rounded-[3rem] bg-indigo-500/[0.03] border-2 border-dashed border-indigo-500/20 flex flex-col items-center justify-center animate-pulse">
