import { ImageProcessor } from '../services/imageProcessor';

interface ResultGalleryProps {
  outfits: GeneratedOutfit[];
  isGenerating: boolean;
  onUpdateMetadata: (id: string, name: string, description: string) => void;
  onUpdateOutfitUrl: (id: string, newUrl: string) => void;
  onDelete: (id: string) => void;
}

type BgMode = 'checker' | 'dark' | 'light';
type ExportFormat = 'png' | 'jpg' | 'webp';

const ResultGallery: React.FC<ResultGalleryProps> = ({ outfits, isGenerating, onUpdateMetadata, onUpdateOutfitUrl, onDelete }) => {
  const [bgMode, setBgMode] = useState<BgMode>('checker');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [alphaConfig, setAlphaConfig] = useState({ threshold: 45, feather: 25 });
  const [exportFormat, setExportFormat] = useState<ExportFormat>('png');
  const [exportBgColor, setExportBgColor] = useState('#ffffff');

  const [metaInputs, setMetaInputs] = useState({ name: '', desc: '' });

  const handleEditMeta = (outfit: GeneratedOutfit) => {
    setEditingId(outfit.id);
    setMetaInputs({ name: outfit.name || '', desc: outfit.description || '' });
  };

  const handleAlphaExtraction = async (outfit: GeneratedOutfit) => {
    if (processingId) return;
    setProcessingId(outfit.id);
    try {
      const result = await ImageProcessor.processAlpha(
        outfit.originalUrl || outfit.url, 
        alphaConfig.threshold, 
        alphaConfig.feather
      );
      onUpdateOutfitUrl(outfit.id, result);
    } catch (e) {
      console.error("Alpha process failed", e);
    } finally {
      setProcessingId(null);
    }
  };

  const handleExport = async (outfit: GeneratedOutfit) => {
    try {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.src = outfit.url;
      await new Promise((resolve) => (img.onload = resolve));

      const canvas = document.createElement('canvas');
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      if (exportFormat === 'jpg') {
        ctx.fillStyle = exportBgColor;
        ctx.fillRect(0, 0, canvas.width, canvas.height);
      }

      ctx.drawImage(img, 0, 0);

      const mimeType = exportFormat === 'jpg' ? 'image/jpeg' : `image/${exportFormat}`;
      const quality = 0.92;
      const dataUrl = canvas.toDataURL(mimeType, quality);

      const link = document.createElement('a');
      link.download = `${outfit.name?.replace(/\s+/g, '-') || 'asset'}-${outfit.id.slice(0, 5)}.${exportFormat}`;
      link.href = dataUrl;
      link.click();
    } catch (err) {
      console.error("Export failed:", err);
    }
  };

  const bgStyles = useMemo(() => {
    switch (bgMode) {
      case 'dark': return 'bg-[#0a0a0a]';
      case 'light': return 'bg-slate-100';
      default: return 'bg-[#0f172a] checker-bg';
    }
  }, [bgMode]);

  return (
    <div className="flex flex-col h-full bg-[#0a0a0a] rounded-[2.5rem] border border-slate-800/40 overflow-hidden shadow-[0_0_50px_rgba(0,0,0,0.5)]">
      <style>{`
        .checker-bg {
          background-image: linear-gradient(45deg, #050505 25%, transparent 25%), linear-gradient(-45deg, #050505 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #050505 75%), linear-gradient(-45deg, transparent 75%, #050505 75%);
          background-size: 32px 32px;
          background-position: 0 0, 0 16px, 16px -16px, -16px 0px;
        }
      `}</style>

      {/* Control Bar */}
      <div className="p-6 border-b border-slate-800/60 bg-[#0a0a0a]/80 backdrop-blur-2xl sticky top-0 z-30 space-y-4">
        <div className="flex items-center justify-between">
          <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">Vault / {outfits.length} Assets</h3>
          <div className="flex bg-slate-900/50 p-1 rounded-xl border border-slate-800">
            {(['checker', 'dark', 'light'] as BgMode[]).map(mode => (
              <button key={mode} onClick={() => setBgMode(mode)} className={`px-4 py-2 text-[9px] uppercase font-black rounded-lg transition-all ${bgMode === mode ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>
                {mode}
              </button>
            ))}
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 px-4 py-3 bg-white/[0.02] rounded-2xl border border-white/[0.05]">
          <div className="space-y-3">
            <div className="flex justify-between items-center">
              <label className="text-[8px] font-bold text-slate-500 uppercase tracking-widest">Alpha Settings</label>
              <span className="text-[8px] text-slate-600 italic">Adjust for background removal</span>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1">
                <div className="flex justify-between"><span className="text-[9px] text-slate-400">Threshold</span><span className="text-[9px] font-mono text-indigo-400">{alphaConfig.threshold}</span></div>
                <input type="range" min="1" max="150" value={alphaConfig.threshold} onChange={(e) => setAlphaConfig(p => ({...p, threshold: +e.target.value}))} className="w-full h-1 bg-slate-800 rounded-full appearance-none accent-indigo-500 cursor-pointer" />
              </div>
              <div className="space-y-1">
                <div className="flex justify-between"><span className="text-[9px] text-slate-400">Softness</span><span className="text-[9px] font-mono text-indigo-400">{alphaConfig.feather}</span></div>
                <input type="range" min="0" max="100" value={alphaConfig.feather} onChange={(e) => setAlphaConfig(p => ({...p, feather: +e.target.value}))} className="w-full h-1 bg-slate-800 rounded-full appearance-none accent-indigo-500 cursor-pointer" />
              </div>
            </div>
          </div>

          <div className="space-y-3">
            <div className="flex justify-between items-center">
              <label className="text-[8px] font-bold text-slate-500 uppercase tracking-widest">Global Export</label>
              <div className="flex items-center gap-2">
                 <div className="flex bg-slate-800 rounded-lg p-0.5">
                  {(['png', 'jpg', 'webp'] as ExportFormat[]).map(fmt => (
                    <button 
                      key={fmt} 
                      onClick={() => setExportFormat(fmt)}
                      className={`px-2 py-1 text-[8px] font-black uppercase rounded ${exportFormat === fmt ? 'bg-indigo-500 text-white' : 'text-slate-500 hover:text-slate-300'}`}
                    >
                      {fmt}
                    </button>
                  ))}
                </div>
                {exportFormat === 'jpg' && (
                  <input 
                    type="color" 
                    value={exportBgColor} 
                    onChange={(e) => setExportBgColor(e.target.value)}
                    className="w-5 h-5 rounded-md border-none cursor-pointer bg-transparent"
                    title="JPG Background Color"
                  />
                )}
              </div>
            </div>
            <div className="text-[9px] text-slate-600 leading-tight">
              {exportFormat === 'png' ? 'Supports transparency (RGBA).' : exportFormat === 'jpg' ? 'Smallest file size. Transparent areas will use fill color.' : 'Modern web format with high compression.'}
            </div>
          </div>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-12 custom-scrollbar pb-24">
        {outfits.length === 0 && !isGenerating ? (
          <div className="h-full flex flex-col items-center justify-center opacity-10 py-32 grayscale">
            <svg className="w-20 h-20 mb-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
            <p className="text-xs font-black uppercase tracking-[0.4em]">Ready for Generation</p>
          </div>
        ) : (
          <div className="flex flex-col gap-16">
            {isGenerating && (
              <div className="aspect-square rounded-[3rem] bg-indigo-500/[0.03] border-2 border-dashed border-indigo-500/20 flex flex-col items-center justify-center animate-pulse">
                <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-6" />
                <span className="text-[10px] text-indigo-400 font-black uppercase tracking-widest">Processing Shaders...</span>
              </div>
            )}

            {outfits.map((outfit) => (
              <div key={outfit.id} className="group flex flex-col bg-slate-900/20 rounded-[3rem] border border-white/[0.03] transition-all hover:border-indigo-500/30 overflow-hidden">
                <div className={`relative flex items-center justify-center p-12 lg:p-20 ${bgStyles} transition-colors duration-1000 min-h-[500px]`}>
                  <img 
                    src={outfit.url} 
                    alt={outfit.prompt} 
                    className={`w-full h-auto object-contain max-h-[600px] z-10 transition-all duration-700 ${processingId === outfit.id ? 'opacity-50 blur-sm scale-95' : 'group-hover:scale-[1.02]'}`}
                    style={{
                      filter: outfit.outline?.enabled ? `drop-shadow(0 0 ${outfit.outline.glow ? '12px' : '0'} ${outfit.outline.color})` : 'none'
                    }}
                  />

                  <div className="absolute top-8 right-8 flex flex-col gap-3 z-20">
                    <button onClick={() => onDelete(outfit.id)} className="bg-red-500/10 hover:bg-red-500 text-red-500 hover:text-white p-3 rounded-2xl transition-all border border-red-500/20 shadow-lg"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
                    <button onClick={() => handleAlphaExtraction(outfit)} disabled={!!processingId} className={`p-3 rounded-2xl transition-all border shadow-lg ${processingId === outfit.id ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-indigo-500/10 hover:bg-indigo-600 text-indigo-400 hover:text-white border-indigo-500/20'}`} title="Run Alpha Extraction"><svg className={`w-5 h-5 ${processingId === outfit.id ? 'animate-spin' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 10l-2 1m0 0l-2-1m2 1v2.5M20 7l-2 1m2-1l-2-1m2 1v2.5M14 4l-2-1-2 1M4 7l2-1M4 7l2 1M4 7v2.5M12 21l-2-1m2 1l2-1m-2 1v-2.5M6 18l-2-1v-2.5M18 18l2-1v-2.5" /></svg></button>
                    <button onClick={() => onUpdateOutfitUrl(outfit.id, outfit.originalUrl || outfit.url)} className="bg-slate-800/50 hover:bg-slate-700 p-3 rounded-2xl text-slate-400 transition-all border border-slate-700 shadow-lg" title="Restore Original"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m0 0H15" /></svg></button>
                  </div>

                  {processingId === outfit.id && (
                    <div className="absolute inset-0 flex items-center justify-center z-30">
                      <div className="bg-indigo-600 text-white px-6 py-3 rounded-full font-black text-[10px] tracking-widest shadow-2xl animate-bounce">SPLICING PIXELS</div>
                    </div>
                  )}
                </div>

                <div className="p-10 bg-[#080808] flex flex-col space-y-8">
                  {editingId === outfit.id ? (
                    <div className="space-y-6 animate-in slide-in-from-bottom-2">
                      <input value={metaInputs.name} onChange={e => setMetaInputs(p => ({...p, name: e.target.value}))} placeholder="Asset Name (e.g. Proto-Scythe)" className="w-full bg-slate-900 border border-slate-800 rounded-2xl px-6 py-4 text-sm outline-none focus:ring-2 focus:ring-indigo-500/30 text-white" />
                      <textarea value={metaInputs.desc} onChange={e => setMetaInputs(p => ({...p, desc: e.target.value}))} placeholder="Lore or technical details..." className="w-full bg-slate-900 border border-slate-800 rounded-2xl px-6 py-4 text-sm outline-none focus:ring-2 focus:ring-indigo-500/30 h-24 resize-none text-white" />
                      <div className="flex gap-4">
                        <button onClick={() => { onUpdateMetadata(outfit.id, metaInputs.name, metaInputs.desc); setEditingId(null); }} className="flex-1 bg-white text-black text-[10px] font-black uppercase tracking-widest py-4 rounded-2xl hover:bg-slate-200 transition-all">Save Asset</button>
                        <button onClick={() => setEditingId(null)} className="px-8 bg-slate-800 text-slate-400 text-[10px] font-black uppercase py-4 rounded-2xl">Cancel</button>
                      </div>
                    </div>
                  ) : (
                    <>
                      <div className="flex justify-between items-start gap-6">
                        <div className="min-w-0 flex-1">
                          <h4 className="text-xl font-black text-white truncate tracking-tight uppercase">{outfit.name || "Untagged Asset"}</h4>
                          <p className="text-sm text-slate-400 mt-2 line-clamp-2 font-medium leading-relaxed opacity-70">{outfit.description || outfit.prompt}</p>
                        </div>
                        <button onClick={() => handleEditMeta(outfit)} className="shrink-0 px-4 py-2 bg-indigo-500/10 text-indigo-400 text-[9px] font-black uppercase rounded-lg border border-indigo-500/20 hover:bg-indigo-500/20 transition-all">Edit Metadata</button>
                      </div>
                      <div className="flex items-center justify-between pt-8 border-t border-white/[0.05]">
                        <span className="text-[10px] font-bold text-slate-600 uppercase tracking-widest">{new Date(outfit.timestamp).toLocaleDateString()}</span>
                        <div className="flex items-center gap-3">
                           <button 
                            onClick={() => handleExport(outfit)}
                            className="bg-indigo-600 hover:bg-indigo-500 text-white text-[10px] font-black uppercase px-8 py-4 rounded-2xl shadow-xl shadow-indigo-600/20 hover:scale-105 active:scale-95 transition-all flex items-center gap-2"
                          >
                            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                            Export as {exportFormat}
                          </button>
                        </div>
                      </div>
                    </>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default ResultGallery;

import { AspectRatio, ModelType } from './types';

export const GAME_STYLE_CATEGORIES = [
  {
    name: "Sci-Fi / Cyber",
    defaultPrompt: "futuristic sleek armored suit with integrated glowing circuits, high-tech carbon fiber textures and HUD interface elements",
    styles: [
      "Mecha Exoskeleton", 
      "Neon Cyberpunk", 
      "High-Tech Stealth Suit", 
