export const OUTLINE_COLORS = [
  { name: 'Neon', value: '#3b82f6' },
  { name: 'Fire', value: '#ef4444' },
  { name: 'Acid', value: '#10b981' },
  { name: 'Gold', value: '#f59e0b' },
  { name: 'Ghost', value: '#ffffff' },
  { name: 'Shadow', value: '#000000' }
];

export const ASPECT_RATIOS: AspectRatio[] = ['1:1', '3:4', '4:3', '9:16', '16:9'];

export const MODEL_OPTIONS: { id: ModelType; label: string; color: string }[] = [
  { id: 'gemini-2.5-flash-image', label: 'FLASH', color: 'indigo' },
  { id: 'gemini-3-pro-image-preview', label: 'PRO', color: 'purple' }
];

import React, { useState } from 'react';
import { ModelType, ImageSize, AspectRatio, OutlineConfig } from '../types';
import { GAME_STYLE_CATEGORIES, OUTLINE_COLORS, ASPECT_RATIOS, MODEL_OPTIONS } from '../constants';

interface SidebarProps {
  selectedModel: ModelType;
  onModelChange: (model: ModelType) => void;
  selectedSize: ImageSize;
  onSizeChange: (size: ImageSize) => void;
  selectedAspectRatio: AspectRatio;
  onAspectRatioChange: (ratio: AspectRatio) => void;
  outline: OutlineConfig;
  onOutlineChange: (updates: Partial<OutlineConfig>) => void;
  onGenerate: () => void;
  isGenerating: boolean;
  prompt: string;
  onPromptChange: (val: string) => void;
}

const Sidebar: React.FC<SidebarProps> = ({
  selectedModel,
  onModelChange,
  selectedAspectRatio,
  onAspectRatioChange,
  outline,
  onOutlineChange,
  onGenerate,
  isGenerating,
  prompt,
  onPromptChange
}) => {
  const [activeCategory, setActiveCategory] = useState(0);

  const handleCategoryClick = (idx: number) => {
    setActiveCategory(idx);
    // Automatically fill with default prompt when switching categories
    onPromptChange(GAME_STYLE_CATEGORIES[idx].defaultPrompt);
  };

  return (
    <aside className="w-full lg:w-80 bg-slate-900 border-b lg:border-b-0 lg:border-r border-slate-800 p-5 lg:p-6 flex flex-col space-y-6 lg:space-y-8 shrink-0 overflow-y-auto custom-scrollbar">
      <section>
        <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-3 block">Inference Engine</label>
        <div className="grid grid-cols-2 gap-2">
          {MODEL_OPTIONS.map((opt) => (
            <button
              key={opt.id}
              onClick={() => onModelChange(opt.id)}
              className={`px-3 py-2 rounded-lg border text-xs font-bold transition-all transform active:scale-95 ${
                selectedModel === opt.id
                  ? `bg-${opt.color}-600 border-${opt.color}-500 text-white shadow-lg shadow-${opt.color}-600/20`
                  : 'bg-slate-800 border-slate-700 text-slate-400 hover:border-slate-600'
              }`}
            >
              {opt.label}
            </button>
          ))}
        </div>
      </section>

      <section>
        <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-3 block">Canvas Aspect</label>
        <div className="grid grid-cols-5 gap-1.5">
          {ASPECT_RATIOS.map((ratio) => (
            <button
              key={ratio}
              onClick={() => onAspectRatioChange(ratio)}
              className={`py-1.5 rounded-md border text-[10px] font-bold transition-all ${
                selectedAspectRatio === ratio
                  ? 'bg-indigo-500 text-white border-indigo-400 shadow-md'
                  : 'bg-slate-800 border-slate-700 text-slate-400 hover:border-slate-600'
              }`}
            >
              {ratio}
            </button>
          ))}
        </div>
      </section>

      <section className="bg-slate-950/40 p-4 rounded-2xl border border-slate-800/50 space-y-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className={`w-1.5 h-1.5 rounded-full ${outline.enabled ? 'bg-indigo-500 animate-pulse' : 'bg-slate-700'}`} />
            <label className="text-[10px] font-bold text-slate-300 uppercase tracking-widest">Asset Outline</label>
          </div>
          <button
            onClick={() => onOutlineChange({ enabled: !outline.enabled })}
            className={`w-9 h-5 rounded-full transition-all relative ${outline.enabled ? 'bg-indigo-500' : 'bg-slate-700'}`}
          >
            <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all shadow-sm ${outline.enabled ? 'left-5' : 'left-1'}`} />
          </button>
        </div>

        {outline.enabled && (
          <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-300">
            <div className="grid grid-cols-6 gap-1.5">
              {OUTLINE_COLORS.map((c) => (
                <button
                  key={c.value}
                  onClick={() => onOutlineChange({ color: c.value })}
                  className={`w-full aspect-square rounded-md border-2 transition-all hover:scale-110 ${outline.color === c.value ? 'border-white shadow-lg' : 'border-transparent opacity-60 hover:opacity-100'}`}
                  style={{ backgroundColor: c.value }}
                />
              ))}
            </div>

            <div className="flex items-center justify-between py-1 px-1 bg-slate-900/50 rounded-lg">
              <span className="text-[9px] text-slate-400 font-bold uppercase tracking-tight pl-2">Glow Bloom</span>
              <button
                onClick={() => onOutlineChange({ glow: !outline.glow })}
                className={`w-8 h-4 rounded-full transition-all relative ${outline.glow ? 'bg-indigo-400' : 'bg-slate-600'}`}
              >
                <div className={`absolute top-0.5 w-3 h-3 bg-white rounded-full transition-all shadow-sm ${outline.glow ? 'left-4.5' : 'left-0.5'}`} />
              </button>
            </div>

            <div className="flex gap-1.5">
              {(['thin', 'medium', 'bold'] as const).map((t) => (
                <button
                  key={t}
                  onClick={() => onOutlineChange({ thickness: t })}
                  className={`flex-1 py-1.5 text-[9px] rounded-lg border font-black uppercase tracking-tighter transition-all ${
                    outline.thickness === t ? 'bg-white text-slate-900 border-white shadow-md' : 'bg-slate-800 border-slate-700 text-slate-500 hover:text-slate-300'
                  }`}
                >
                  {t}
                </button>
              ))}
            </div>
          </div>
        )}
      </section>

      <section className="flex flex-col flex-1 min-h-0 space-y-4">
        <div>
          <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-3 block">Style Archetypes</label>
          <div className="flex border-b border-slate-800 mb-4 overflow-x-auto no-scrollbar">
            {GAME_STYLE_CATEGORIES.map((cat, idx) => (
              <button
                key={cat.name}
                onClick={() => handleCategoryClick(idx)}
                className={`px-3 py-2 text-[9px] font-black uppercase tracking-widest whitespace-nowrap transition-all border-b-2 ${activeCategory === idx ? 'border-indigo-500 text-indigo-400' : 'border-transparent text-slate-600 hover:text-slate-400'}`}
              >
                {cat.name.split(' ')[0]}
              </button>
            ))}
          </div>
          <div className="grid grid-cols-2 gap-2 max-h-48 overflow-y-auto custom-scrollbar pr-1">
            {GAME_STYLE_CATEGORIES[activeCategory].styles.map((style) => (
              <button
                key={style}
                onClick={() => onPromptChange(style)}
                className="text-left text-[9px] bg-slate-800/40 hover:bg-indigo-500/10 hover:text-indigo-300 hover:border-indigo-500/30 text-slate-400 px-3 py-2 rounded-xl transition-all border border-slate-700/50 font-bold uppercase tracking-tight leading-tight"
              >
                {style}
              </button>
            ))}
          </div>
        </div>

        <div className="space-y-2">
          <div className="flex justify-between items-center">
