import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ModelType, ImageSize, AspectRatio, OutlineConfig } from "../types";

export class GeminiService {
  private static async getAIInstance() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  private static async optimizeImage(base64: string, maxDim: number = 1024): Promise<string> {
    return new Promise((resolve) => {
      const img = new Image();
      img.onload = () => {
        let width = img.width;
        let height = img.height;
        if (width > maxDim || height > maxDim) {
          if (width > height) {
            height *= maxDim / width;
            width = maxDim;
          } else {
            width *= maxDim / height;
            height = maxDim;
          }
        }
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', 0.85));
      };
      img.src = base64;
    });
  }

  static async generateOutfit(
    baseImageBase64: string,
    styleImageBase64: string | null,
    prompt: string,
    model: ModelType,
    aspectRatio: AspectRatio,
    outline: OutlineConfig,
    isCharacterSheet: boolean,
    size: ImageSize = '1K'
  ): Promise<string> {
    const ai = await this.getAIInstance();
    const optimizedBase = await this.optimizeImage(baseImageBase64);
    const optimizedStyle = styleImageBase64 ? await this.optimizeImage(styleImageBase64) : null;

    const systemInstruction = `You are a Principal Concept Artist at a AAA Game Studio. Your expertise is technical character design for high-fidelity titles.
    CRITICAL QUALITY STANDARDS:
    1. ANATOMICAL FIDELITY: You must strictly adhere to the base body proportions provided. Do not deviate from the character's height, build, or pose.
    2. MATERIAL DEFINITION: Render realistic materials: brushed metal, carbon fiber, weathered leather, micro-fibers, and PBR-ready surfaces.
    3. TOPOLOGY FRIENDLY: Design outfits with clean lines that follow the body's natural topology for 3D modeling.
    4. LIGHTING: Strictly neutral, flat directional lighting to serve as a texture reference. Zero artistic bloom or dramatic contrast.
    5. PRESENTATION: Clean, professional output. No messy artifacts, floating parts, or extra limbs. 
    6. BACKGROUND: Strictly flat solid #111111 or #FFFFFF.`;

    let userPrompt = `TASK: Synthesize a professional game asset. 
    SUBJECT: Maintain character likeness from reference. 
    DESIGN: ${prompt}.`;

    if (isCharacterSheet) {
      userPrompt = `TASK: Generate a technical 3-view Character Concept Sheet.
      LAYOUT: Render 3 distinct orthographic-style views side-by-side: [FRONT], [SIDE (90 deg)], [BACK].
      CONSISTENCY: Every detail (belts, buckles, armor plates) must be identical across all three views.
      POSTURE: Strict A-pose or T-pose for clear rigging visibility.
      DESIGN REQUIREMENTS: ${prompt}.`;
    }

    if (outline.enabled) {
      userPrompt += ` \nSTYLE: Render with a sharp ${outline.thickness} silhouette outline in color ${outline.color}.`;
    }

    try {
      const parts: any[] = [];
      const processPart = (b64: string) => ({
        inlineData: { 
          data: b64.split(',')[1], 
          mimeType: b64.split(';')[0].split(':')[1] 
        }
      });

      parts.push(processPart(optimizedBase));
      if (optimizedStyle) parts.push(processPart(optimizedStyle));
      parts.push({ text: userPrompt });

      const response: GenerateContentResponse = await ai.models.generateContent({
        model,
        contents: { parts },
        config: {
          systemInstruction,
          imageConfig: {
            aspectRatio: isCharacterSheet ? '16:9' : aspectRatio,
            ...(model === 'gemini-3-pro-image-preview' && { imageSize: size })
          }
        }
      });

      const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (imagePart?.inlineData) {
        return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
      }

      throw new Error("Pipeline returned no visual data.");
    } catch (error: any) {
      if (error.message?.includes("Requested entity was not found")) throw new Error("RE_SELECT_KEY");
      throw error;
    }
  }
}

