  const baseInputRef = useRef<HTMLInputElement>(null);
  const styleInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>, type: 'base' | 'style') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        if (type === 'base') onUploadBase(reader.result as string);
        else onUploadStyle(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const triggerUpload = (type: 'base' | 'style') => {
    if (!isGenerating) {
      if (type === 'base') baseInputRef.current?.click();
