import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ModelType, ImageSize, AspectRatio, OutlineConfig } from "../types";

export class GeminiService {
  private static async getAIInstance() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  private static async optimizeImage(base64: string, maxDim: number = 1024): Promise<string> {
    return new Promise((resolve) => {
      const img = new Image();
      img.onload = () => {
        let width = img.width;
        let height = img.height;
        if (width > maxDim || height > maxDim) {
          if (width > height) {
            height *= maxDim / width;
            width = maxDim;
          } else {
            width *= maxDim / height;
            height = maxDim;
          }
        }
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', 0.85));
      };
      img.src = base64;
    });
  }

  static async generateOutfit(
    baseImageBase64: string,
    styleImageBase64: string | null,
    prompt: string,
    model: ModelType,
    aspectRatio: AspectRatio,
    outline: OutlineConfig,
    isCharacterSheet: boolean,
    size: ImageSize = '1K'
  ): Promise<string> {
    const ai = await this.getAIInstance();
    const optimizedBase = await this.optimizeImage(baseImageBase64);
    const optimizedStyle = styleImageBase64 ? await this.optimizeImage(styleImageBase64) : null;

    const systemInstruction = `You are an Elite Character Concept Artist. Your task is to design garments and armor with surgical precision based on a provided 3D reference base.

    CORE DIRECTIVES:
    1. ANATOMICAL SYNC: The outfit must perfectly wrap around the provided base character. Do not change the character's body type, head size, or height.
    2. MATERIAL FIDELITY: Explicitly render textures for: ballistic nylon, carbon fiber, matte ceramics, polished chrome, tactical leather, and translucent fabrics.
    3. TOPOLOGY-READINESS: Design seams and panels that follow natural body topology for easy retopology in 3D pipelines.
    4. TECHNICAL LIGHTING: Use a neutral '3-point studio lighting' setup. Avoid heavy artistic shadows.
    5. PRESENTATION: Output must be clean game-asset quality. No extra limbs, no blurry artifacts, no floating meshes.
    6. ENVIRONMENT: Render against a strictly solid #000000 or #FFFFFF background.`;

    let userPrompt = `DESIGN INJUNCTION: Synthesize a professional game-ready outfit for the provided subject.
    OUTFIT SPECS: ${prompt}.
    CONSTRAINT: Ensure the outfit is logically layered (undergarments, padding, primary armor, accessories).`;

    if (isCharacterSheet) {
      userPrompt = `TASK: Technical 3-view Character Sheet.
      LAYOUT: Horizontal arrangement of [FRONTAL VIEW], [90-DEGREE PROFILE VIEW], [BACK VIEW].
      INTEGRITY: Every buckle, light, and armor scratch must be spatially consistent across all three views.
      POSTURE: Keep the subject in the provided A-pose for clear visibility.
      DESIGN: ${prompt}.`;
    }

    if (outline.enabled) {
      userPrompt += ` \nSILHOUETTE: Render with a sharp ${outline.thickness} outline in color ${outline.color}.`;
    }

    try {
      const parts: any[] = [];
      const processPart = (b64: string) => ({
        inlineData: { 
          data: b64.split(',')[1], 
          mimeType: b64.split(';')[0].split(':')[1] 
        }
      });

      parts.push(processPart(optimizedBase));
      if (optimizedStyle) parts.push(processPart(optimizedStyle));
      parts.push({ text: userPrompt });

      const response: GenerateContentResponse = await ai.models.generateContent({
        model,
        contents: { parts },
        config: {
          systemInstruction,
          imageConfig: {
            aspectRatio: isCharacterSheet ? '16:9' : aspectRatio,
            ...(model === 'gemini-3-pro-image-preview' && { imageSize: size })
          }
        }
      });

      const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (imagePart?.inlineData) {
        return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
      }

      throw new Error("Pipeline returned no visual data.");
    } catch (error: any) {
      if (error.message?.includes("Requested entity was not found")) throw new Error("RE_SELECT_KEY");
      throw error;
    }
  }
}

import { GeneratedOutfit } from "../types";

const DB_NAME = "OutfitForgeDB";
const STORE_NAME = "outfits";
const DB_VERSION = 1;

export class StorageService {
  private static db: IDBDatabase | null = null;

  private static async getDB(): Promise<IDBDatabase> {
    if (this.db) return this.db;

    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION);

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: "id" });
        }
      };

      request.onsuccess = (event) => {
        this.db = (event.target as IDBOpenDBRequest).result;
        resolve(this.db!);
      };

      request.onerror = (event) => {
        reject((event.target as IDBOpenDBRequest).error);
      };
    });
  }

  static async saveOutfit(outfit: GeneratedOutfit): Promise<void> {
    const db = await this.getDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([STORE_NAME], "readwrite");
      const store = transaction.objectStore(STORE_NAME);
      const request = store.put(outfit);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  static async getAllOutfits(): Promise<GeneratedOutfit[]> {
    const db = await this.getDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([STORE_NAME], "readonly");
      const store = transaction.objectStore(STORE_NAME);
      const request = store.getAll();

      request.onsuccess = () => {
        // Sort by timestamp descending
        const results = (request.result as GeneratedOutfit[]).sort((a, b) => b.timestamp - a.timestamp);
        resolve(results);
      };
      request.onerror = () => reject(request.error);
    });
  }

  static async deleteOutfit(id: string): Promise<void> {
    const db = await this.getDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([STORE_NAME], "readwrite");
      const store = transaction.objectStore(STORE_NAME);
      const request = store.delete(id);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  static async clearAll(): Promise<void> {
    const db = await this.getDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([STORE_NAME], "readwrite");
      const store = transaction.objectStore(STORE_NAME);
      const request = store.clear();

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }
}

import React, { useState, useEffect, useReducer, useCallback } from 'react';
import { ModelType, ImageSize, AspectRatio, GeneratedOutfit, AppState, OutlineConfig } from './types';
import { GeminiService } from './services/geminiService';
import { StorageService } from './services/storageService';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import MainEditor from './components/MainEditor';
import ResultGallery from './components/ResultGallery';

type Action = 
  | { type: 'ADD_OUTFIT'; payload: GeneratedOutfit }
  | { type: 'UPDATE_OUTFIT'; id: string; updates: Partial<GeneratedOutfit> }
  | { type: 'DELETE_OUTFIT'; id: string }
  | { type: 'SET_OUTFITS'; payload: GeneratedOutfit[] }
  | { type: 'SET_BASE_IMAGE'; payload: string | null }
  | { type: 'SET_STYLE_IMAGE'; payload: string | null }
  | { type: 'SET_GENERATING'; payload: boolean }
  | { type: 'SET_ERROR'; payload: string | null }
  | { type: 'UPDATE_CONFIG'; payload: Partial<AppState> };

function appReducer(state: AppState, action: Action): AppState {
  switch (action.type) {
    case 'ADD_OUTFIT': return { ...state, outfits: [action.payload, ...state.outfits] };
    case 'UPDATE_OUTFIT': return {
      ...state,
      outfits: state.outfits.map(o => o.id === action.id ? { ...o, ...action.updates } : o)
    };
    case 'DELETE_OUTFIT': return { ...state, outfits: state.outfits.filter(o => o.id !== action.id) };
    case 'SET_OUTFITS': return { ...state, outfits: action.payload };
    case 'SET_BASE_IMAGE': return { ...state, baseImage: action.payload };
    case 'SET_STYLE_IMAGE': return { ...state, styleImage: action.payload };
    case 'SET_GENERATING': return { ...state, isGenerating: action.payload };
    case 'SET_ERROR': return { ...state, error: action.payload };
    case 'UPDATE_CONFIG': return { ...state, ...action.payload };
    default: return state;
  }
}

const App: React.FC = () => {
  const [state, dispatch] = useReducer(appReducer, {
    baseImage: null,
    styleImage: null,
    outfits: [],
    isGenerating: false,
    selectedModel: 'gemini-2.5-flash-image',
    selectedSize: '1K',
    selectedAspectRatio: '1:1',
    outline: { enabled: false, color: '#4f46e5', thickness: 'medium', glow: false },
    error: null,
    isCharacterSheetMode: false,
  });

  const [prompt, setPrompt] = useState('');
  const [activeTab, setActiveTab] = useState<'editor' | 'vault'>('editor');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Load from IndexedDB on mount
  useEffect(() => {
    const loadVault = async () => {
      try {
        const saved = await StorageService.getAllOutfits();
        dispatch({ type: 'SET_OUTFITS', payload: saved });
      } catch (e) {
        console.error("IndexedDB loading failed", e);
        dispatch({ type: 'SET_ERROR', payload: "Failed to load Asset Vault from local storage." });
      }
    };
    loadVault();
  }, []);

  const handleGenerate = async () => {
    if (!state.baseImage) return dispatch({ type: 'SET_ERROR', payload: "Please upload a base character model." });
    if (!prompt.trim()) return dispatch({ type: 'SET_ERROR', payload: "Design prompt cannot be empty." });

    setIsSidebarOpen(false);
    dispatch({ type: 'SET_GENERATING', payload: true });
    dispatch({ type: 'SET_ERROR', payload: null });

    try {
      if (state.selectedModel === 'gemini-3-pro-image-preview') {
        if (!(await window.aistudio.hasSelectedApiKey())) {
          await window.aistudio.openSelectKey();
        }
      }

      const generatedUrl = await GeminiService.generateOutfit(
        state.baseImage,
        state.styleImage,
        prompt,
        state.selectedModel,
        state.selectedAspectRatio,
        state.outline,
        state.isCharacterSheetMode,
        state.selectedSize
      );

      const newOutfit: GeneratedOutfit = {
        id: crypto.randomUUID(),
        url: generatedUrl,
        originalUrl: generatedUrl,
        prompt: prompt,
        timestamp: Date.now(),
        model: state.selectedModel,
        aspectRatio: state.isCharacterSheetMode ? '16:9' : state.selectedAspectRatio,
        outline: state.outline.enabled ? { ...state.outline } : undefined,
        isCharacterSheet: state.isCharacterSheetMode,
      };

      await StorageService.saveOutfit(newOutfit);
      dispatch({ type: 'ADD_OUTFIT', payload: newOutfit });
      setActiveTab('vault'); 
    } catch (error: any) {
      const msg = error.message === "RE_SELECT_KEY" ? "API Key error. Please re-select." : error.message;
      dispatch({ type: 'SET_ERROR', payload: msg });
      if (error.message === "RE_SELECT_KEY") await window.aistudio.openSelectKey();
    } finally {
      dispatch({ type: 'SET_GENERATING', payload: false });
    }
  };

  const updateOutfitUrl = useCallback(async (id: string, newUrl: string) => {
    const outfit = state.outfits.find(o => o.id === id);
    if (outfit) {
      const updated = { ...outfit, url: newUrl };
      await StorageService.saveOutfit(updated);
      dispatch({ type: 'UPDATE_OUTFIT', id, updates: { url: newUrl } });
    }
  }, [state.outfits]);

  const updateMetadata = useCallback(async (id: string, name: string, description: string) => {
    const outfit = state.outfits.find(o => o.id === id);
    if (outfit) {
      const updated = { ...outfit, name, description, isSaved: true };
      await StorageService.saveOutfit(updated);
      dispatch({ type: 'UPDATE_OUTFIT', id, updates: { name, description, isSaved: true } });
    }
  }, [state.outfits]);

  const handleDelete = useCallback(async (id: string) => {
    await StorageService.deleteOutfit(id);
    dispatch({ type: 'DELETE_OUTFIT', id });
  }, []);

  return (
    <div className="fixed inset-0 flex flex-col bg-[#050505] text-slate-100 selection:bg-indigo-500/30">
      <Header />

      <div className="flex flex-1 overflow-hidden relative">
        <Sidebar 
          isOpen={isSidebarOpen}
          onClose={() => setIsSidebarOpen(false)}
          selectedModel={state.selectedModel}
          onModelChange={(m) => dispatch({ type: 'UPDATE_CONFIG', payload: { selectedModel: m } })}
          selectedSize={state.selectedSize}
          onSizeChange={(s) => dispatch({ type: 'UPDATE_CONFIG', payload: { selectedSize: s } })}
          selectedAspectRatio={state.selectedAspectRatio}
          onAspectRatioChange={(a) => dispatch({ type: 'UPDATE_CONFIG', payload: { selectedAspectRatio: a } })}
          outline={state.outline}
          onOutlineChange={(u) => dispatch({ type: 'UPDATE_CONFIG', payload: { outline: { ...state.outline, ...u } } })}
          onGenerate={handleGenerate}
          isGenerating={state.isGenerating}
          prompt={prompt}
          onPromptChange={setPrompt}
          isCharacterSheetMode={state.isCharacterSheetMode}
          onToggleCharacterSheet={() => dispatch({ type: 'UPDATE_CONFIG', payload: { isCharacterSheetMode: !state.isCharacterSheetMode } })}
        />

        <main className="flex-1 flex flex-col relative overflow-hidden">
          {/* Mobile Tab Switcher */}
          <div className="lg:hidden flex border-b border-white/5 bg-black/40 backdrop-blur-xl sticky top-0 z-20">
            <button 
              onClick={() => setActiveTab('editor')}
              className={`flex-1 py-4 text-[10px] font-black uppercase tracking-[0.2em] transition-all border-b-2 ${activeTab === 'editor' ? 'border-indigo-500 text-white' : 'border-transparent text-slate-500'}`}
            >
              Forge Unit
            </button>
            <button 
              onClick={() => setActiveTab('vault')}
              className={`flex-1 py-4 text-[10px] font-black uppercase tracking-[0.2em] transition-all border-b-2 ${activeTab === 'vault' ? 'border-indigo-500 text-white' : 'border-transparent text-slate-500'}`}
            >
              Asset Vault
            </button>
          </div>

          <div className="flex-1 overflow-y-auto p-4 lg:p-8 space-y-8 custom-scrollbar relative">
            {state.error && (
              <div className="bg-red-500/10 border border-red-500/20 text-red-400 p-4 rounded-2xl flex justify-between items-center animate-in fade-in slide-in-from-top-4 z-50">
                <span className="text-[10px] font-bold uppercase tracking-wider">{state.error}</span>
                <button onClick={() => dispatch({ type: 'SET_ERROR', payload: null })} className="hover:scale-110 transition-transform">✕</button>
              </div>
            )}

            <div className="grid grid-cols-1 xl:grid-cols-[1fr_1.4fr] gap-6 lg:gap-8 min-h-full pb-20 lg:pb-0">
              <div className={`${activeTab === 'editor' ? 'block' : 'hidden lg:block'}`}>
                <MainEditor 
                  baseImage={state.baseImage} 
                  styleImage={state.styleImage}
                  onUploadBase={(url) => dispatch({ type: 'SET_BASE_IMAGE', payload: url })}
                  onUploadStyle={(url) => dispatch({ type: 'SET_STYLE_IMAGE', payload: url })}
                  isGenerating={state.isGenerating}
                />
              </div>
              <div className={`${activeTab === 'vault' ? 'block' : 'hidden lg:block'}`}>
                <ResultGallery 
                  outfits={state.outfits} 
                  isGenerating={state.isGenerating}
                  onUpdateMetadata={updateMetadata}
                  onUpdateOutfitUrl={updateOutfitUrl}
                  onDelete={handleDelete}
                />
              </div>
            </div>
          </div>

          {/* Mobile Generation Trigger Button */}
          <div className="lg:hidden fixed bottom-6 left-1/2 -translate-x-1/2 w-[90%] z-40">
             <button 
                onClick={() => setIsSidebarOpen(true)}
                className="w-full py-5 bg-indigo-600 rounded-[2rem] font-black text-[11px] tracking-[0.3em] uppercase shadow-2xl shadow-indigo-600/40 border border-indigo-500 animate-in slide-in-from-bottom-10"
              >
                Configure & Forge
              </button>
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ModelType, ImageSize, AspectRatio, OutlineConfig } from "../types";

export class GeminiService {
  private static async getAIInstance() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  private static async optimizeImage(base64: string, maxDim: number = 1024): Promise<string> {
    return new Promise((resolve) => {
      const img = new Image();
      img.onload = () => {
        let width = img.width;
        let height = img.height;
        if (width > maxDim || height > maxDim) {
          if (width > height) {
            height *= maxDim / width;
            width = maxDim;
          } else {
            width *= maxDim / height;
            height = maxDim;
          }
        }
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', 0.8));
      };
      img.src = base64;
    });
  }

  static async generateOutfit(
    baseImageBase64: string,
    styleImageBase64: string | null,
    prompt: string,
    model: ModelType,
    aspectRatio: AspectRatio,
    outline: OutlineConfig,
    isCharacterSheet: boolean,
    size: ImageSize = '1K'
  ): Promise<string> {
    const ai = await this.getAIInstance();
    const optimizedBase = await this.optimizeImage(baseImageBase64);
    const optimizedStyle = styleImageBase64 ? await this.optimizeImage(styleImageBase64) : null;

    // Estructura de System Instruction de nivel Senior Concept Artist
    const systemInstruction = `You are a Lead Concept Artist specializing in game-ready character assets.
Your goal is to synthesize highly detailed outfits that adhere strictly to the provided base character's anatomy and silhouette.

CORE QUALITY STANDARDS:
- TOPOLOGY: Designs must be model-friendly (logical seams, no impossible shapes).
- MATERIALS: Render realistic PBR materials: carbon fiber, ballistic weave, aged leather, translucent energy emitters, micro-electronics.
- LIGHTING: Use a professional neutral 3-point studio lighting to highlight form and texture. No dramatic shadows.
- ANATOMY: The character's pose, build, and proportions from the base image MUST NOT change.
- CLEANLINESS: Zero artifacts. Sharp, high-frequency details. Solid neutral background.`;

    // Constructor de prompt técnico
    let technicalPrompt = `[TECHNICAL SPECIFICATION]
DESIGN SUBJECT: High-fidelity character outfit generation.
STYLE PARAMETERS: ${prompt}.
ASSET TYPE: ${isCharacterSheet ? 'Orthographic 3-view technical sheet (Front, Side, Back)' : 'Single full-body concept'}.
REQUIRED FIDELITY: 8K, cinematic, hyper-realistic, photorealistic textures.
ENGINE COMPATIBILITY: Unreal Engine 5, PBR Workflow.
`;

    if (isCharacterSheet) {
      technicalPrompt += `\nLAYOUT REQUIREMENTS: 
1. Render three distinct views: full-frontal, 90-degree profile, and full-back.
2. Views must be perfectly horizontally aligned.
3. Every accessory, belt, and armor plate must be consistent and identical across all views.
4. Keep the subject in the exact A-pose or T-pose from the reference.`;
    }

    if (outline.enabled) {
      technicalPrompt += `\nVISUAL EFFECTS: Sharp ${outline.thickness} illustrative stroke outline in HEX ${outline.color}.`;
    }

    try {
      const parts: any[] = [];
      const processPart = (b64: string) => ({
        inlineData: { 
          data: b64.split(',')[1], 
          mimeType: b64.split(';')[0].split(':')[1] 
        }
      });

      parts.push(processPart(optimizedBase));
      if (optimizedStyle) {
        parts.push({ text: "AESTHETIC REFERENCE DRIVER:" });
        parts.push(processPart(optimizedStyle));
      }
      parts.push({ text: technicalPrompt });

      const response: GenerateContentResponse = await ai.models.generateContent({
        model,
        contents: { parts },
        config: {
          systemInstruction,
          imageConfig: {
            aspectRatio: isCharacterSheet ? '16:9' : aspectRatio,
            ...(model === 'gemini-3-pro-image-preview' && { imageSize: size })
          }
        }
      });

      const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (imagePart?.inlineData) {
        return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
      }

      throw new Error("Neural pipeline returned no visual data. Please try a different prompt.");
    } catch (error: any) {
      console.error("Gemini API Error:", error);
      if (error.message?.includes("Requested entity was not found")) throw new Error("RE_SELECT_KEY");
      throw error;
    }
  }
}

