import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ModelType, ImageSize, AspectRatio, OutlineConfig } from "../types";

export class GeminiService {
  private static async getAIInstance() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  private static async optimizeImage(base64: string, maxDim: number = 1024): Promise<string> {
    return new Promise((resolve) => {
      const img = new Image();
      img.onload = () => {
        let width = img.width;
        let height = img.height;
        if (width > maxDim || height > maxDim) {
          if (width > height) {
            height *= maxDim / width;
            width = maxDim;
          } else {
            width *= maxDim / height;
            height = maxDim;
          }
        }
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', 0.8));
      };
      img.src = base64;
    });
  }

  static async generateOutfit(
    baseImageBase64: string,
    styleImageBase64: string | null,
    prompt: string,
    model: ModelType,
    aspectRatio: AspectRatio,
    outline: OutlineConfig,
    isCharacterSheet: boolean,
    size: ImageSize = '1K'
  ): Promise<string> {
    const ai = await this.getAIInstance();
    const optimizedBase = await this.optimizeImage(baseImageBase64);
    const optimizedStyle = styleImageBase64 ? await this.optimizeImage(styleImageBase64) : null;

    // Estructura de System Instruction de nivel Senior Concept Artist
    const systemInstruction = `You are an elite Senior Game Concept Artist. 
Your goal is to synthesize professional-grade outfits that are ready for 3D modeling pipelines.

STRICT DESIGN PRINCIPLES:
1. ANATOMICAL ADHERENCE: Do not alter the body shape, pose, or skeletal proportions of the base character. The outfit must fit like a tight 3D mesh wrapper.
2. PBR MATERIAL RENDERING: Use Physically Based Rendering principles. Distinguish clearly between rough fabrics, polished metals, translucent energy panels, and weathered leathers.
3. TOPOLOGY & SEAMS: Design logical seams and mechanical joints. Think about how a rigger would move this character.
4. LIGHTING: Clean, high-key studio lighting. 3-point light setup. Pure white or deep black background.
5. NO ARTIFACTS: Ensure symmetry where appropriate, sharp edges, and high-frequency detailing (bolts, micro-mesh, buckles).`;

    // Constructor de prompt técnico
    let technicalPrompt = `[ASSET INJUNCTION: HIGH-FIDELITY SYNTHESIS]
CORE DESIGN: ${prompt}.
ASSET FORMAT: ${isCharacterSheet ? 'Orthographic character sheet with front, side, and back views' : 'Full-body detailed concept art'}.
TECHNICAL SPECS: 8K resolution, micro-texture detail, realistic material physics, subsurface scattering on soft parts.
ENVIRONMENT: Neutral void studio background.
`;

    if (isCharacterSheet) {
      technicalPrompt += `\nSHEET PROTOCOL: 
- Synchronize all views perfectly. Front, Profile (Right), and Back.
- Absolute alignment on X and Y axes for all clothing items.
- Maintain the neutral A-pose or T-pose from the subject.
- Do not add background props or scenery.`;
    }

    if (outline.enabled) {
      technicalPrompt += `\nSILHOUETTE ENHANCEMENT: Render a clean ${outline.thickness} stroke outline using color ${outline.color}.`;
    }

    try {
      const parts: any[] = [];
      const processPart = (b64: string) => ({
        inlineData: { 
          data: b64.split(',')[1], 
          mimeType: b64.split(';')[0].split(':')[1] 
        }
      });

      parts.push(processPart(optimizedBase));
      if (optimizedStyle) {
        parts.push({ text: "INFLUENCE AESTHETIC DRIVER FROM THIS IMAGE:" });
        parts.push(processPart(optimizedStyle));
      }
      parts.push({ text: technicalPrompt });

      const response: GenerateContentResponse = await ai.models.generateContent({
        model,
        contents: { parts },
        config: {
          systemInstruction,
          imageConfig: {
            aspectRatio: isCharacterSheet ? '16:9' : aspectRatio,
            ...(model === 'gemini-3-pro-image-preview' && { imageSize: size })
          }
        }
      });

      const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (imagePart?.inlineData) {
        return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
      }

      throw new Error("Neural pipeline returned no visual data. Please try a different prompt.");
    } catch (error: any) {
      console.error("Gemini API Error:", error);
      if (error.message?.includes("Requested entity was not found")) throw new Error("RE_SELECT_KEY");
      throw error;
    }
  }
}

