import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ModelType, ImageSize, AspectRatio, OutlineConfig } from "../types";

export class GeminiService {
  private static async getAIInstance() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  private static async optimizeImage(base64: string, maxDim: number = 1024): Promise<string> {
    return new Promise((resolve) => {
      const img = new Image();
      img.onload = () => {
        let width = img.width;
        let height = img.height;
        if (width > maxDim || height > maxDim) {
          const ratio = width > height ? maxDim / width : maxDim / height;
          width *= ratio;
          height *= ratio;
        }
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', 0.8));
      };
      img.src = base64;
    });
  }

  static async generateEvolution(
    baseCharacter: string,
    parentSprite: string | null,
    prompt: string,
    mutationStrength: number,
    config: {
      model: ModelType,
      aspectRatio: AspectRatio,
      outline: OutlineConfig,
      isCharacterSheet: boolean,
      size: ImageSize
    }
  ): Promise<string> {
    const ai = await this.getAIInstance();
    const optBase = await this.optimizeImage(baseCharacter);
    const optParent = parentSprite ? await this.optimizeImage(parentSprite) : null;

    const systemInstruction = `You are an elite 2D Sprite Iteration Engine.
Your goal is to EVOLVE an existing 2D outfit or design based on new directives while maintaining 100% anatomical consistency with the base character.

ITERATION RULES:
1. ANATOMY LOCK: Never change the underlying character's pose, face, or body shape.
2. HERENCIAL FIDELITY: ${optParent ? `Preserve the core style of the Parent Sprite but modify it based on the new prompt with ${mutationStrength}% intensity.` : 'Create a new base outfit layer.'}
3. 2D RENDERING: Clean lineart, cel-shading, solid background. No 3D effects.
4. CONSISTENCY: Every detail added must feel integrated into the 2D plane of the sprite.`;

    const technicalPrompt = `[MUTATION PROTOCOL]
STRENGTH: ${mutationStrength}/100.
NEW DIRECTIVES: ${prompt}.
ASSET TYPE: ${config.isCharacterSheet ? '2D Orthographic Sprite Sheet' : 'Single Full-Body Sprite'}.
VISUAL QUALITY: 4K, pixel-perfect edges, high-contrast, game-ready 2D asset.`;

    try {
      const parts: any[] = [
        { inlineData: { data: optBase.split(',')[1], mimeType: 'image/jpeg' } },
        { text: "BASE CHARACTER (ANATOMY ANCHOR)" }
      ];

      if (optParent) {
        parts.push({ inlineData: { data: optParent.split(',')[1], mimeType: 'image/jpeg' } });
        parts.push({ text: `PARENT SPRITE (STYLE DNA TO BE MODIFIED BY ${mutationStrength}%)` });
      }

      parts.push({ text: technicalPrompt });

      const response: GenerateContentResponse = await ai.models.generateContent({
        model: config.model,
        contents: { parts },
        config: {
          systemInstruction,
          imageConfig: {
            aspectRatio: config.isCharacterSheet ? '16:9' : config.aspectRatio,
            ...(config.model === 'gemini-3-pro-image-preview' && { imageSize: config.size })
          }
        }
      });

      const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (imagePart?.inlineData) {
        return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
      }
      throw new Error("Neural Link failed to synthesize evolution.");
    } catch (e) {
      console.error(e);
      throw e;
    }
  }
}

import React, { useState, useEffect, useReducer, useCallback } from 'react';
import { ModelType, ImageSize, AspectRatio, GeneratedOutfit, AppState } from './types';
import { GeminiService } from './services/geminiService';
import { StorageService } from './services/storageService';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import MainEditor from './components/MainEditor';
import ResultGallery from './components/ResultGallery';

type Action = 
  | { type: 'ADD_OUTFIT'; payload: GeneratedOutfit }
  | { type: 'SET_PARENT'; payload: GeneratedOutfit | null }
  | { type: 'SET_BASE'; payload: string | null }
  | { type: 'SET_GENERATING'; payload: boolean }
  | { type: 'SET_ERROR'; payload: string | null }
  | { type: 'UPDATE_CONFIG'; payload: Partial<AppState> }
  | { type: 'SET_OUTFITS'; payload: GeneratedOutfit[] };

function appReducer(state: AppState, action: Action): AppState {
  switch (action.type) {
    case 'ADD_OUTFIT': return { ...state, outfits: [action.payload, ...state.outfits] };
    case 'SET_PARENT': return { ...state, activeEvolutionParent: action.payload };
    case 'SET_BASE': return { ...state, baseImage: action.payload };
    case 'SET_GENERATING': return { ...state, isGenerating: action.payload };
    case 'SET_ERROR': return { ...state, error: action.payload };
    case 'UPDATE_CONFIG': return { ...state, ...action.payload };
    case 'SET_OUTFITS': return { ...state, outfits: action.payload };
    default: return state;
  }
}

const App: React.FC = () => {
  const [state, dispatch] = useReducer(appReducer, {
    baseImage: null,
    activeEvolutionParent: null,
    outfits: [],
    isGenerating: false,
    selectedModel: 'gemini-2.5-flash-image',
    selectedSize: '1K',
    selectedAspectRatio: '1:1',
    outline: { enabled: false, color: '#4f46e5', thickness: 'medium', glow: false },
    error: null,
    isCharacterSheetMode: false,
    mutationStrength: 50
  });

  const [prompt, setPrompt] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    StorageService.getAllOutfits().then(data => dispatch({ type: 'SET_OUTFITS', payload: data }));
  }, []);

  const handleForge = async () => {
    if (!state.baseImage) return dispatch({ type: 'SET_ERROR', payload: "Sube un personaje base primero." });

    dispatch({ type: 'SET_GENERATING', payload: true });
    dispatch({ type: 'SET_ERROR', payload: null });

    try {
      const url = await GeminiService.generateEvolution(
        state.baseImage,
        state.activeEvolutionParent?.url || null,
        prompt,
        state.mutationStrength,
        {
          model: state.selectedModel,
          aspectRatio: state.selectedAspectRatio,
          outline: state.outline,
          isCharacterSheet: state.isCharacterSheetMode,
          size: state.selectedSize
        }
      );

      const newAsset: GeneratedOutfit = {
        id: crypto.randomUUID(),
        url: url,
        originalUrl: url,
        parentId: state.activeEvolutionParent?.id,
        prompt: prompt,
        timestamp: Date.now(),
        model: state.selectedModel,
        aspectRatio: state.selectedAspectRatio,
        evolutionStep: (state.activeEvolutionParent?.evolutionStep || 0) + 1,
        isCharacterSheet: state.isCharacterSheetMode
      };

      await StorageService.saveOutfit(newAsset);
      dispatch({ type: 'ADD_OUTFIT', payload: newAsset });
      dispatch({ type: 'SET_PARENT', payload: newAsset }); // El nuevo se vuelve padre
    } catch (e: any) {
      dispatch({ type: 'SET_ERROR', payload: e.message });
    } finally {
      dispatch({ type: 'SET_GENERATING', payload: false });
    }
  };

  return (
    <div className="fixed inset-0 flex flex-col bg-black text-white font-sans">
      <Header />
      <div className="flex flex-1 overflow-hidden relative">
        <Sidebar 
          isOpen={isSidebarOpen}
          onClose={() => setIsSidebarOpen(false)}
          state={state}
          dispatch={dispatch}
          prompt={prompt}
          setPrompt={setPrompt}
          onGenerate={handleForge}
        />
        <main className="flex-1 flex flex-col relative overflow-hidden bg-[#050505]">
          <div className="flex-1 overflow-y-auto p-4 lg:p-8 space-y-8 custom-scrollbar">
            {state.error && (
              <div className="bg-red-500/10 border border-red-500/20 text-red-400 p-4 rounded-3xl flex justify-between items-center animate-in fade-in">
                <span className="text-[10px] font-black uppercase tracking-widest">{state.error}</span>
                <button onClick={() => dispatch({ type: 'SET_ERROR', payload: null })}>✕</button>
              </div>
            )}

            <div className="grid grid-cols-1 xl:grid-cols-[1fr_1.5fr] gap-8">
              <MainEditor 
                baseImage={state.baseImage}
                parentImage={state.activeEvolutionParent?.url || null}
                onUploadBase={(url) => dispatch({ type: 'SET_BASE', payload: url })}
                isGenerating={state.isGenerating}
                onResetParent={() => dispatch({ type: 'SET_PARENT', payload: null })}
              />
              <ResultGallery 
                outfits={state.outfits}
                activeParentId={state.activeEvolutionParent?.id || null}
                onSelectParent={(o) => dispatch({ type: 'SET_PARENT', payload: o })}
                isGenerating={state.isGenerating}
              />
            </div>
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

