import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ModelType, ImageSize, AspectRatio, OutlineConfig, RenderingProtocols } from "../types";

export class GeminiService {
  private static async getAIInstance() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  private static async optimizeImage(base64: string, maxDim: number = 1024): Promise<string> {
    return new Promise((resolve) => {
      const img = new Image();
      img.onload = () => {
        let width = img.width;
        let height = img.height;
        if (width > maxDim || height > maxDim) {
          const ratio = width > height ? maxDim / width : maxDim / height;
          width *= ratio;
          height *= ratio;
        }
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', 0.8));
      };
      img.src = base64;
    });
  }

  static async generateEvolution(
    baseCharacter: string,
    parentSprite: string | null,
    prompt: string,
    mutationStrength: number,
    config: {
      model: ModelType,
      aspectRatio: AspectRatio,
      outline: OutlineConfig,
      isCharacterSheet: boolean,
      size: ImageSize,
      protocols: RenderingProtocols
    }
  ): Promise<string> {
    const ai = await this.getAIInstance();
    const optBase = await this.optimizeImage(baseCharacter);
    const optParent = parentSprite ? await this.optimizeImage(parentSprite) : null;

    // INTEGRACIÓN DEL PROTOCOLO DE PRECISIÓN DEL USUARIO
    const systemInstruction = `Act as the Master Game Asset Architect. You MUST follow this precise rendering protocol:
ANATOMY LOCK: Keep the character’s head and face shape, eyes style and shape, color palette style, body shape, body anatomy proportions, bust size, hands, feet, and art style 109% exactly the same as the base anatomy provided.
MODIFICATION SCOPE: Modify ONLY the character’s outfit, accessories, ornaments, skin, and hair style.

TECHNICAL SPECIFICATIONS:
- BACKGROUND: ${config.protocols.magentaBackground ? 'Pure Magenta (#FF00FF)' : 'Solid Neutral Color'}. No floor, no particles, no scenery, no auras, no effects, no floor shadows.
- RENDERING: ${config.protocols.pixelPerfect ? 'Pixel-perfect rendering, 16-bit color palette, crisp edges, no anti-aliasing, consistent design.' : 'Clean cell shading, professional digital painting.'}
- OUTLINE: ${config.protocols.strongOutline ? 'Strong black outline, clean silhouette.' : 'Standard artistic outline.'}
- VIBE: ${config.protocols.hd2dStyle ? "Queen’s Blade anime's style, fantasy JRPG theme, 2D-HD style sprite, death metal style aesthetic." : 'Modern RPG style.'}
- COMPOSITION: 3/4 view, character centered, game ready resource.

${optParent ? `EVOLUTIONARY CONTEXT: Inject DNA from the Parent Sprite with ${mutationStrength}% mutation intensity into the design while strictly maintaining the Base Anatomy.` : 'INITIAL SYNTHESIS: Forge a new asset over the base anatomy provided.'}`;

    const userInstructions = `[DESIGN DIRECTIVE]
${prompt}
[OUTFIT SPECS]
Include large bust, underboob cutout, sideboobs cutouts, and clothing cutouts consistent with the Queen's Blade aesthetic.
${config.isCharacterSheet ? 'FORMAT: Orthographic character sheet (front/side/back).' : 'FORMAT: Hero Sprite in 3/4 view.'}`;

    try {
      const parts: any[] = [
        { inlineData: { data: optBase.split(',')[1], mimeType: 'image/jpeg' } },
        { text: "LAYER 0: MANDATORY BASE ANATOMY (109% LOCK)" }
      ];

      if (optParent) {
        parts.push({ inlineData: { data: optParent.split(',')[1], mimeType: 'image/jpeg' } });
        parts.push({ text: "LAYER 1: EVOLUTIONARY DNA SOURCE" });
      }

      parts.push({ text: userInstructions });

      const response: GenerateContentResponse = await ai.models.generateContent({
        model: config.model,
        contents: { parts },
        config: {
          systemInstruction,
          imageConfig: {
            aspectRatio: config.isCharacterSheet ? '16:9' : config.aspectRatio,
            ...(config.model === 'gemini-3-pro-image-preview' && { imageSize: config.size })
          }
        }
      });

      const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (imagePart?.inlineData) {
        return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
      }
      throw new Error("Failed to synthesize image part within protocol constraints.");
    } catch (e) {
      console.error(e);
      throw e;
    }
  }
}

