import React, { useState, useEffect, useReducer } from 'react';
import { GeneratedOutfit, AppState } from './types';
import { GeminiService } from './services/geminiService';
import { StorageService } from './services/storageService';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import MainEditor from './components/MainEditor';
import ResultGallery from './components/ResultGallery';

type Action = 
  | { type: 'ADD_OUTFIT'; payload: GeneratedOutfit }
  | { type: 'SET_PARENT'; payload: GeneratedOutfit | null }
  | { type: 'SET_BASE'; payload: string | null }
  | { type: 'SET_GENERATING'; payload: boolean }
  | { type: 'SET_ERROR'; payload: string | null }
  | { type: 'UPDATE_CONFIG'; payload: Partial<AppState> }
  | { type: 'SET_OUTFITS'; payload: GeneratedOutfit[] };

function appReducer(state: AppState, action: Action): AppState {
  switch (action.type) {
    case 'ADD_OUTFIT': return { ...state, outfits: [action.payload, ...state.outfits] };
    case 'SET_PARENT': return { ...state, activeEvolutionParent: action.payload };
    case 'SET_BASE': return { ...state, baseImage: action.payload };
    case 'SET_GENERATING': return { ...state, isGenerating: action.payload };
    case 'SET_ERROR': return { ...state, error: action.payload };
    case 'UPDATE_CONFIG': return { ...state, ...action.payload };
    case 'SET_OUTFITS': return { ...state, outfits: action.payload };
    default: return state;
  }
}

const App: React.FC = () => {
  const [state, dispatch] = useReducer(appReducer, {
    baseImage: null,
    activeEvolutionParent: null,
    outfits: [],
    isGenerating: false,
    selectedModel: 'gemini-2.5-flash-image',
    selectedSize: '1K',
    selectedAspectRatio: '1:1',
    outline: { enabled: false, color: '#4f46e5', thickness: 'medium', glow: false },
    error: null,
    isCharacterSheetMode: false,
    mutationStrength: 50,
    renderingProtocols: {
      magentaBackground: true,
      pixelPerfect: true,
      strongOutline: true,
      hd2dStyle: true
    }
  });

  const [prompt, setPrompt] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    StorageService.getAllOutfits().then(data => dispatch({ type: 'SET_OUTFITS', payload: data }));
  }, []);

  const handleSelectParent = (outfit: GeneratedOutfit) => {
    dispatch({ type: 'SET_PARENT', payload: outfit });
    if (!prompt || prompt.length < 5) {
      setPrompt(outfit.prompt);
    }
  };

  const handleForge = async () => {
    if (!state.baseImage) {
      dispatch({ type: 'SET_ERROR', payload: "ERROR: DEBES SUBIR UN SPRITE BASE PARA ANCLAR LA ANATOMÍA." });
      return;
    }

    dispatch({ type: 'SET_GENERATING', payload: true });
    dispatch({ type: 'SET_ERROR', payload: null });
    if (window.innerWidth < 1024) setIsSidebarOpen(false);

    try {
      const url = await GeminiService.generateEvolution(
        state.baseImage,
        state.activeEvolutionParent?.url || null,
        prompt,
        state.mutationStrength,
        {
          model: state.selectedModel,
          aspectRatio: state.selectedAspectRatio,
          outline: state.outline,
          isCharacterSheet: state.isCharacterSheetMode,
          size: state.selectedSize,
          protocols: state.renderingProtocols
        }
      );

      const newAsset: GeneratedOutfit = {
        id: crypto.randomUUID(),
        url: url,
        originalUrl: url,
        parentId: state.activeEvolutionParent?.id,
        prompt: prompt,
        timestamp: Date.now(),
        model: state.selectedModel,
        aspectRatio: state.selectedAspectRatio,
        evolutionStep: (state.activeEvolutionParent?.evolutionStep || 0) + 1
      };

      await StorageService.saveOutfit(newAsset);
      dispatch({ type: 'ADD_OUTFIT', payload: newAsset });
      dispatch({ type: 'SET_PARENT', payload: newAsset });
    } catch (e: any) {
      dispatch({ type: 'SET_ERROR', payload: e.message || "Fallo en la conexión neuronal." });
    } finally {
      dispatch({ type: 'SET_GENERATING', payload: false });
    }
  };

  return (
    <div className="fixed inset-0 flex flex-col bg-[#050505] text-white font-sans selection:bg-indigo-500/30">
      <Header onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)} isGenerating={state.isGenerating} />

      <div className="flex flex-1 overflow-hidden relative">
        <Sidebar 
          isOpen={isSidebarOpen}
          onClose={() => setIsSidebarOpen(false)}
          state={state}
          dispatch={dispatch}
          prompt={prompt}
          setPrompt={setPrompt}
          onGenerate={handleForge}
        />

        <main className="flex-1 flex flex-col relative overflow-hidden">
          <div className="flex-1 overflow-y-auto p-4 lg:p-10 space-y-8 custom-scrollbar pb-32">
            {state.error && (
              <div className="bg-red-500/10 border border-red-500/20 text-red-400 p-5 rounded-3xl flex justify-between items-center animate-in slide-in-from-top-4 duration-300">
                <span className="text-[10px] font-black uppercase tracking-[0.2em]">{state.error}</span>
                <button 
                  onClick={() => dispatch({ type: 'SET_ERROR', payload: null })}
                  className="w-8 h-8 flex items-center justify-center hover:bg-white/5 rounded-full transition-colors"
                >✕</button>
              </div>
            )}

            <div className="grid grid-cols-1 xl:grid-cols-[1.2fr_1fr] gap-10 items-start">
              <MainEditor 
                baseImage={state.baseImage}
                parentImage={state.activeEvolutionParent?.url || null}
                onUploadBase={(url) => dispatch({ type: 'SET_BASE', payload: url })}
                isGenerating={state.isGenerating}
                onResetParent={() => dispatch({ type: 'SET_PARENT', payload: null })}
                mutationStrength={state.mutationStrength}
                magentaActive={state.renderingProtocols.magentaBackground}
                isSheetMode={state.isCharacterSheetMode}
              />
              <ResultGallery 
                outfits={state.outfits}
                activeParentId={state.activeEvolutionParent?.id || null}
                onSelectParent={handleSelectParent}
                isGenerating={state.isGenerating}
              />
            </div>
          </div>

          <div className="lg:hidden fixed bottom-6 left-6 right-6 z-40">
            <button 
              onClick={handleForge}
              disabled={state.isGenerating || !state.baseImage}
              className={`w-full py-5 rounded-[2rem] font-black text-[11px] tracking-[0.4em] uppercase transition-all shadow-2xl active:scale-95 border border-white/10 ${
                state.isGenerating ? 'bg-slate-800 text-slate-500' : 'bg-indigo-600 text-white shadow-indigo-600/40'
              }`}
            >
              {state.isGenerating ? 'Procesando...' : state.activeEvolutionParent ? 'Mutar ADN' : 'Forjar Base'}
            </button>
          </div>
        </main>
      </div>
    </div>
  );
};

