interface SidebarProps {
  isOpen: boolean;
  onClose: () => void;
  state: AppState;
  dispatch: any;
  prompt: string;
  setPrompt: (v: string) => void;
  onGenerate: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ isOpen, onClose, state, dispatch, prompt, setPrompt, onGenerate }) => {
  const isEvolving = !!state.activeEvolutionParent;

  const toggleProtocol = (key: keyof AppState['renderingProtocols']) => {
    dispatch({ 
      type: 'UPDATE_CONFIG', 
