    dispatch({ 
      type: 'UPDATE_CONFIG', 
      payload: { isCharacterSheetMode: !state.isCharacterSheetMode } 
    });
  };

  const addTag = (tag: string) => {
    const cleanTag = tag.trim();
    if (prompt.toLowerCase().includes(cleanTag.toLowerCase())) return;
    const newPrompt = prompt.trim() ? `${prompt.trim()}, ${cleanTag}` : cleanTag;
    setPrompt(newPrompt);
  };

  return (
    <aside className={`fixed inset-y-0 left-0 z-50 w-80 bg-[#0a0a0a] border-r border-white/5 transition-transform duration-500 ease-out lg:static lg:translate-x-0 ${isOpen ? 'translate-x-0' : '-translate-x-full'}`}>
