          <div className="flex flex-col">
            <h2 className="text-[12px] font-black uppercase tracking-[0.3em]">Módulo de Síntesis</h2>
            <span className="text-[9px] font-bold text-slate-500 uppercase tracking-widest mt-1">Anclaje Anatómico y Evolución</span>
