            </div>
            <textarea 
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              placeholder="Describe el atuendo: Armadura de placas, estilo Queen's Blade, detalles en oro, temática Death Metal..."
              className="w-full flex-1 bg-slate-900/50 border border-white/5 rounded-[2rem] p-6 text-sm text-white h-full outline-none focus:ring-2 focus:ring-indigo-500/30 resize-none transition-all placeholder:text-slate-700 font-medium leading-relaxed"
            />
