          <button 
            onClick={onGenerate}
            disabled={isGenerating || !baseImage}
            className={`w-full py-8 rounded-[2rem] font-black text-[12px] tracking-[0.5em] uppercase transition-all shadow-2xl relative overflow-hidden group ${
