{
  "name": "OutfitForge - Game Ready Character Designer",
  "description": "An AI-powered character outfit generator that allows you to upload a base model and design high-quality, game-ready outfits using Gemini models.",
  "requestFramePermissions": []
}

import React, { useState, useEffect, useReducer } from 'react';
import { GeneratedOutfit, AppState } from './types';
import { GeminiService } from './services/geminiService';
import { StorageService } from './services/storageService';
import { ImageProcessor } from './services/imageProcessor';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import MainEditor from './components/MainEditor';
import ResultGallery from './components/ResultGallery';

type Action = 
  | { type: 'ADD_OUTFIT'; payload: GeneratedOutfit }
  | { type: 'REMOVE_OUTFIT'; payload: string }
  | { type: 'SET_PARENT'; payload: GeneratedOutfit | null }
  | { type: 'SET_BASE'; payload: string | null }
  | { type: 'SET_GENERATING'; payload: boolean }
  | { type: 'SET_ERROR'; payload: string | null }
  | { type: 'UPDATE_CONFIG'; payload: Partial<AppState> }
  | { type: 'SET_OUTFITS'; payload: GeneratedOutfit[] };

function appReducer(state: AppState, action: Action): AppState {
  switch (action.type) {
    case 'ADD_OUTFIT': return { ...state, outfits: [action.payload, ...state.outfits] };
    case 'REMOVE_OUTFIT': return { ...state, outfits: state.outfits.filter(o => o.id !== action.payload) };
    case 'SET_PARENT': return { ...state, activeEvolutionParent: action.payload };
    case 'SET_BASE': return { ...state, baseImage: action.payload };
    case 'SET_GENERATING': return { ...state, isGenerating: action.payload };
    case 'SET_ERROR': return { ...state, error: action.payload };
    case 'UPDATE_CONFIG': return { ...state, ...action.payload };
    case 'SET_OUTFITS': return { ...state, outfits: action.payload };
    default: return state;
  }
}

const App: React.FC = () => {
  const [state, dispatch] = useReducer(appReducer, {
    baseImage: null,
    activeEvolutionParent: null,
    outfits: [],
    isGenerating: false,
    selectedModel: 'gemini-2.5-flash-image',
    selectedSize: '1K',
    selectedAspectRatio: '1:1',
    outline: { enabled: false, color: '#4f46e5', thickness: 'medium', glow: false },
    error: null,
    isCharacterSheetMode: false,
    mutationStrength: 50,
    renderingProtocols: {
      magentaBackground: true,
      pixelPerfect: true,
      strongOutline: true,
      hd2dStyle: true
    }
  });

  const [prompt, setPrompt] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    StorageService.getAllOutfits().then(data => dispatch({ type: 'SET_OUTFITS', payload: data }));
  }, []);

  const handleSelectParent = (outfit: GeneratedOutfit) => {
    dispatch({ type: 'SET_PARENT', payload: outfit });
    setPrompt(outfit.prompt);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleRemoveOutfit = async (id: string) => {
    await StorageService.deleteOutfit(id);
    dispatch({ type: 'REMOVE_OUTFIT', payload: id });
    if (state.activeEvolutionParent?.id === id) {
      dispatch({ type: 'SET_PARENT', payload: null });
    }
  };

  const handleProcessPNG = async (outfit: GeneratedOutfit) => {
    try {
      const transparentUrl = await ImageProcessor.processAlpha(outfit.url, 45, 4);
      const link = document.createElement('a');
      link.href = transparentUrl;
      link.download = `outfit-${outfit.id}.png`;
      link.click();
    } catch (e) {
      dispatch({ type: 'SET_ERROR', payload: "Error processing transparency." });
    }
  };

  const handleForge = async () => {
    if (!state.baseImage) {
      dispatch({ type: 'SET_ERROR', payload: "Falta ADN Base: Sube una imagen de tu personaje." });
      return;
    }

    dispatch({ type: 'SET_GENERATING', payload: true });
    dispatch({ type: 'SET_ERROR', payload: null });

    try {
      const url = await GeminiService.generateEvolution(
        state.baseImage,
        state.activeEvolutionParent?.url || null,
        prompt || "Detailed game character outfit",
        state.mutationStrength,
        {
          model: state.selectedModel,
          aspectRatio: state.selectedAspectRatio,
          outline: state.outline,
          isCharacterSheet: state.isCharacterSheetMode,
          size: state.selectedSize,
          protocols: state.renderingProtocols
        }
      );

      const newAsset: GeneratedOutfit = {
        id: crypto.randomUUID(),
        url: url,
        originalUrl: url,
        parentId: state.activeEvolutionParent?.id,
        prompt: prompt,
        timestamp: Date.now(),
        model: state.selectedModel,
        aspectRatio: state.selectedAspectRatio,
        evolutionStep: (state.activeEvolutionParent?.evolutionStep || 0) + 1
      };

      await StorageService.saveOutfit(newAsset);
      dispatch({ type: 'ADD_OUTFIT', payload: newAsset });
      dispatch({ type: 'SET_PARENT', payload: newAsset });
    } catch (e: any) {
      dispatch({ type: 'SET_ERROR', payload: "Neural Error: " + e.message });
    } finally {
      dispatch({ type: 'SET_GENERATING', payload: false });
    }
  };

  // Determinar el paso actual para la UI
  const currentStep = !state.baseImage ? 1 : state.isGenerating ? 3 : 2;

  return (
    <div className="fixed inset-0 flex flex-col bg-[#050505] text-white font-sans selection:bg-indigo-500/30 overflow-hidden">
      <Header onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)} isGenerating={state.isGenerating} />

      <div className="flex flex-1 overflow-hidden relative">
        <Sidebar 
          isOpen={isSidebarOpen}
          onClose={() => setIsSidebarOpen(false)}
          state={state}
          dispatch={dispatch}
          prompt={prompt}
          setPrompt={setPrompt}
          onGenerate={handleForge}
        />

        <main className="flex-1 flex flex-col relative overflow-hidden bg-[radial-gradient(circle_at_top,_rgba(79,70,229,0.07)_0%,_transparent_50%)]">
          <div className="flex-1 overflow-y-auto p-4 lg:p-10 custom-scrollbar pb-32">

            {/* Indicador de Flujo Superior */}
            <div className="max-w-4xl mx-auto mb-12 flex justify-between relative px-4">
              <div className="absolute top-1/2 left-0 w-full h-px bg-white/5 -translate-y-1/2 z-0" />
              {[1, 2, 3].map((step) => (
                <div key={step} className="relative z-10 flex flex-col items-center gap-2">
                  <div className={`w-10 h-10 rounded-2xl flex items-center justify-center font-black text-sm border-2 transition-all duration-500 ${
                    currentStep === step 
                      ? 'bg-indigo-600 border-indigo-400 shadow-[0_0_15px_rgba(79,70,229,0.5)]' 
                      : currentStep > step ? 'bg-green-500 border-green-400 text-white' : 'bg-slate-900 border-white/10 text-slate-600'
                  }`}>
                    {currentStep > step ? '✓' : step}
                  </div>
                  <span className={`text-[9px] font-black uppercase tracking-widest ${currentStep === step ? 'text-white' : 'text-slate-600'}`}>
                    {step === 1 ? 'ADN' : step === 2 ? 'Diseño' : 'Forja'}
                  </span>
                </div>
              ))}
            </div>

            {state.error && (
              <div className="max-w-4xl mx-auto mb-8 bg-red-500/10 border border-red-500/20 text-red-400 p-5 rounded-3xl flex justify-between items-center animate-in slide-in-from-top-4">
                <span className="text-[10px] font-black uppercase tracking-[0.2em]">{state.error}</span>
                <button onClick={() => dispatch({ type: 'SET_ERROR', payload: null })} className="p-2 hover:bg-white/5 rounded-full transition-colors">✕</button>
              </div>
            )}

            <div className="max-w-6xl mx-auto space-y-20">
              <MainEditor 
                baseImage={state.baseImage}
                parentImage={state.activeEvolutionParent?.url || null}
                onUploadBase={(url) => dispatch({ type: 'SET_BASE', payload: url })}
                isGenerating={state.isGenerating}
                onResetParent={() => dispatch({ type: 'SET_PARENT', payload: null })}
                mutationStrength={state.mutationStrength}
                magentaActive={state.renderingProtocols.magentaBackground}
                isSheetMode={state.isCharacterSheetMode}
                prompt={prompt}
                setPrompt={setPrompt}
                onGenerate={handleForge}
              />

              <div className="pt-16 border-t border-white/5">
                <ResultGallery 
                  outfits={state.outfits}
                  activeParentId={state.activeEvolutionParent?.id || null}
                  onSelectParent={handleSelectParent}
                  onRemoveOutfit={handleRemoveOutfit}
                  onProcessPNG={handleProcessPNG}
                  isGenerating={state.isGenerating}
                />
              </div>
            </div>
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

