import React, { useState, useEffect, useReducer } from 'react';
import { GeneratedOutfit, AppState } from './types';
import { GeminiService } from './services/geminiService';
import { StorageService } from './services/storageService';
import { ImageProcessor } from './services/imageProcessor';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import MainEditor from './components/MainEditor';
import ResultGallery from './components/ResultGallery';

type Action = 
  | { type: 'ADD_OUTFIT'; payload: GeneratedOutfit }
  | { type: 'REMOVE_OUTFIT'; payload: string }
  | { type: 'SET_PARENT'; payload: GeneratedOutfit | null }
  | { type: 'SET_BASE'; payload: string | null }
  | { type: 'SET_GENERATING'; payload: boolean }
  | { type: 'SET_ERROR'; payload: string | null }
  | { type: 'UPDATE_CONFIG'; payload: Partial<AppState> }
  | { type: 'SET_OUTFITS'; payload: GeneratedOutfit[] };

function appReducer(state: AppState, action: Action): AppState {
  switch (action.type) {
    case 'ADD_OUTFIT': return { ...state, outfits: [action.payload, ...state.outfits] };
    case 'REMOVE_OUTFIT': return { ...state, outfits: state.outfits.filter(o => o.id !== action.payload) };
    case 'SET_PARENT': return { ...state, activeEvolutionParent: action.payload };
    case 'SET_BASE': return { ...state, baseImage: action.payload };
    case 'SET_GENERATING': return { ...state, isGenerating: action.payload };
    case 'SET_ERROR': return { ...state, error: action.payload };
    case 'UPDATE_CONFIG': return { ...state, ...action.payload };
    case 'SET_OUTFITS': return { ...state, outfits: action.payload };
    default: return state;
  }
}

const App: React.FC = () => {
  const [state, dispatch] = useReducer(appReducer, {
    baseImage: null,
    activeEvolutionParent: null,
    outfits: [],
    isGenerating: false,
    selectedModel: 'gemini-2.5-flash-image',
    selectedSize: '1K',
    selectedAspectRatio: '1:1',
    outline: { enabled: false, color: '#4f46e5', thickness: 'medium', glow: false },
    error: null,
    isCharacterSheetMode: false,
    mutationStrength: 50,
    renderingProtocols: {
      magentaBackground: true,
      pixelPerfect: true,
      strongOutline: true,
      hd2dStyle: true
    }
  });

  const [prompt, setPrompt] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    StorageService.getAllOutfits().then(data => dispatch({ type: 'SET_OUTFITS', payload: data }));
  }, []);

  const handleSelectParent = (outfit: GeneratedOutfit) => {
    dispatch({ type: 'SET_PARENT', payload: outfit });
    setPrompt(outfit.prompt);
    // Auto-scroll to design console
    const consoleElement = document.getElementById('design-console');
    consoleElement?.scrollIntoView({ behavior: 'smooth', block: 'center' });
  };

  const handleRemoveOutfit = async (id: string) => {
    await StorageService.deleteOutfit(id);
    dispatch({ type: 'REMOVE_OUTFIT', payload: id });
    if (state.activeEvolutionParent?.id === id) {
      dispatch({ type: 'SET_PARENT', payload: null });
    }
  };

  const handleProcessPNG = async (outfit: GeneratedOutfit) => {
    try {
      const transparentUrl = await ImageProcessor.processAlpha(outfit.url, 45, 4);
      const link = document.createElement('a');
      link.href = transparentUrl;
      link.download = `outfit-${outfit.id}.png`;
      link.click();
    } catch (e) {
      dispatch({ type: 'SET_ERROR', payload: "Alpha extraction error." });
    }
  };

  const handleForge = async () => {
    if (!state.baseImage) {
      dispatch({ type: 'SET_ERROR', payload: "Módulo ADN vacío. Por favor carga una base." });
      return;
    }

    dispatch({ type: 'SET_GENERATING', payload: true });
    dispatch({ type: 'SET_ERROR', payload: null });

    try {
      const url = await GeminiService.generateEvolution(
        state.baseImage,
        state.activeEvolutionParent?.url || null,
        prompt || "Detailed game character outfit",
        state.mutationStrength,
        {
          model: state.selectedModel,
          aspectRatio: state.selectedAspectRatio,
          outline: state.outline,
          isCharacterSheet: state.isCharacterSheetMode,
          size: state.selectedSize,
          protocols: state.renderingProtocols
        }
      );

      const newAsset: GeneratedOutfit = {
        id: crypto.randomUUID(),
        url: url,
        originalUrl: url,
        parentId: state.activeEvolutionParent?.id,
        prompt: prompt,
        timestamp: Date.now(),
        model: state.selectedModel,
        aspectRatio: state.selectedAspectRatio,
        evolutionStep: (state.activeEvolutionParent?.evolutionStep || 0) + 1
      };

      await StorageService.saveOutfit(newAsset);
      dispatch({ type: 'ADD_OUTFIT', payload: newAsset });
      dispatch({ type: 'SET_PARENT', payload: newAsset });
    } catch (e: any) {
      dispatch({ type: 'SET_ERROR', payload: "Error Neural: " + e.message });
    } finally {
      dispatch({ type: 'SET_GENERATING', payload: false });
    }
  };

  return (
    <div className="fixed inset-0 flex flex-col bg-[#050505] text-[#e2e8f0] font-sans selection:bg-indigo-500/30 overflow-hidden">
      <Header onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)} isGenerating={state.isGenerating} />

      <div className="flex flex-1 overflow-hidden relative">
        <Sidebar 
          isOpen={isSidebarOpen}
          onClose={() => setIsSidebarOpen(false)}
          state={state}
          dispatch={dispatch}
          prompt={prompt}
          setPrompt={setPrompt}
          onGenerate={handleForge}
        />

        <main className="flex-1 overflow-y-auto custom-scrollbar bg-[radial-gradient(circle_at_center,_rgba(79,70,229,0.03)_0%,_transparent_100%)]">
          <div className="max-w-7xl mx-auto px-4 py-8 lg:px-12 lg:py-16 space-y-24 pb-48">

            {/* WORKSTATION AREA */}
            <section className="relative z-10">
              {state.error && (
                <div className="max-w-3xl mx-auto mb-10 bg-red-500/10 border border-red-500/20 text-red-400 p-6 rounded-[2rem] flex justify-between items-center animate-in slide-in-from-top-4">
                  <div className="flex items-center gap-3">
                    <div className="w-2 h-2 bg-red-500 rounded-full animate-pulse" />
                    <span className="text-[11px] font-black uppercase tracking-widest">{state.error}</span>
                  </div>
                  <button onClick={() => dispatch({ type: 'SET_ERROR', payload: null })} className="hover:bg-white/5 p-2 rounded-full">✕</button>
                </div>
              )}

              <MainEditor 
                baseImage={state.baseImage}
                parentImage={state.activeEvolutionParent?.url || null}
                onUploadBase={(url) => dispatch({ type: 'SET_BASE', payload: url })}
                isGenerating={state.isGenerating}
                onResetParent={() => dispatch({ type: 'SET_PARENT', payload: null })}
                mutationStrength={state.mutationStrength}
                magentaActive={state.renderingProtocols.magentaBackground}
                isSheetMode={state.isCharacterSheetMode}
                prompt={prompt}
                setPrompt={setPrompt}
                onGenerate={handleForge}
              />
            </section>

            {/* VAULT AREA */}
            <section className="pt-24 border-t border-white/5">
              <ResultGallery 
                outfits={state.outfits}
                activeParentId={state.activeEvolutionParent?.id || null}
                onSelectParent={handleSelectParent}
                onRemoveOutfit={handleRemoveOutfit}
                onProcessPNG={handleProcessPNG}
                isGenerating={state.isGenerating}
              />
            </section>
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useRef } from 'react';
import { QUICK_TAGS } from '../constants';

interface MainEditorProps {
  baseImage: string | null;
  parentImage: string | null;
  onUploadBase: (url: string) => void;
  isGenerating: boolean;
  onResetParent: () => void;
  mutationStrength: number;
  magentaActive: boolean;
  isSheetMode: boolean;
  prompt: string;
  setPrompt: (v: string) => void;
  onGenerate: () => void;
}

const MainEditor: React.FC<MainEditorProps> = ({ 
  baseImage, 
  parentImage, 
  onUploadBase, 
  isGenerating, 
  onResetParent, 
  mutationStrength, 
  magentaActive,
  isSheetMode,
  prompt,
  setPrompt,
  onGenerate
}) => {
  const fileRef = useRef<HTMLInputElement>(null);

  const handleUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const r = new FileReader();
      r.onload = () => onUploadBase(r.result as string);
      r.readAsDataURL(file);
    }
  };

  const addTag = (tag: string) => {
    const cleanTag = tag.trim();
    if (prompt.toLowerCase().includes(cleanTag.toLowerCase())) return;
    const newPrompt = prompt.trim() ? `${prompt.trim()}, ${cleanTag}` : cleanTag;
    setPrompt(newPrompt);
  };

  return (
    <div className="w-full max-w-5xl mx-auto flex flex-col gap-12 animate-in fade-in duration-1000">

      {/* 1. VIEWPORT DOCK */}
      <div className="relative group">
        <div className="absolute -inset-4 bg-gradient-to-b from-indigo-500/10 to-transparent opacity-50 blur-2xl rounded-[4rem] -z-10" />

        <div className={`relative border border-white/5 rounded-[4rem] overflow-hidden flex items-center justify-center shadow-3xl aspect-square md:aspect-[16/10] transition-all duration-700 ${magentaActive ? 'bg-[#FF00FF]' : 'bg-[#080808]'}`}>
          {!baseImage ? (
            <div 
              onClick={() => fileRef.current?.click()}
              className="flex flex-col items-center justify-center p-12 cursor-pointer group/upload w-full h-full hover:bg-white/[0.01] transition-all"
            >
              <div className="w-24 h-24 bg-slate-900 border border-white/10 rounded-[2.5rem] flex items-center justify-center mb-10 group-hover/upload:border-indigo-500 group-hover/upload:scale-105 transition-all duration-500 shadow-2xl">
                <svg className="w-10 h-10 text-slate-600 group-hover/upload:text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 4v16m8-8H4" />
                </svg>
              </div>
              <h2 className="text-[13px] font-black text-white uppercase tracking-[0.5em] mb-4 text-center">Protocolo Alfa: Ingresar ADN Base</h2>
              <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest text-center max-w-sm">Este modelo servirá como anclaje anatómico 109% bloqueado para todas las evoluciones.</p>
            </div>
          ) : (
            <div className="relative w-full h-full flex items-center justify-center p-12 lg:p-16">
              {!magentaActive && <div className="absolute inset-0 opacity-[0.05] pointer-events-none checker-bg" />}

              <div className="flex gap-12 items-center justify-center w-full h-full relative">
                <div className="relative h-full flex items-center justify-center">
                   <img 
                    src={baseImage} 
                    className={`max-h-full object-contain transition-all duration-1000 ${parentImage ? 'opacity-20 grayscale blur-lg scale-90' : 'opacity-100 drop-shadow-[0_0_50px_rgba(0,0,0,0.5)]'}`} 
                  />
                  {parentImage && (
                    <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                      <img src={parentImage} className="max-h-full object-contain drop-shadow-[0_0_100px_rgba(79,70,229,0.4)] animate-in zoom-in-95 duration-1000" />
                    </div>
                  )}
                </div>
              </div>

              {/* Viewport Overlay Controls */}
              <div className="absolute top-8 right-8 flex flex-col gap-3 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                <button onClick={() => fileRef.current?.click()} className="bg-black/60 backdrop-blur-xl border border-white/10 p-4 rounded-2xl hover:bg-white/10 transition-all group/btn">
                  <svg className="w-5 h-5 text-white/50 group-hover/btn:text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1M16 9l-4-4-4 4m4-4v12" /></svg>
                </button>
                {parentImage && (
                  <button onClick={onResetParent} className="bg-red-500/20 backdrop-blur-xl border border-red-500/30 p-4 rounded-2xl hover:bg-red-500 transition-all group/btn">
                    <svg className="w-5 h-5 text-red-400 group-hover/btn:text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                  </button>
                )}
              </div>
            </div>
          )}

          {isGenerating && (
            <div className="absolute inset-0 z-50 bg-[#050505]/80 backdrop-blur-xl flex flex-col items-center justify-center animate-in fade-in duration-500">
              <div className="w-24 h-24 relative mb-8">
                <div className="absolute inset-0 border-4 border-indigo-500/10 rounded-full" />
                <div className="absolute inset-0 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin" />
                <div className="absolute inset-4 border-2 border-purple-500/20 border-b-purple-500 rounded-full animate-spin-slow" />
              </div>
              <div className="flex flex-col items-center gap-3">
                <span className="text-[12px] font-black text-white uppercase tracking-[0.6em] animate-pulse">Sintetizando Assets</span>
                <span className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">Asegurando consistencia anatómica...</span>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* 2. DESIGN TERMINAL (Only active when base exists) */}
      <div id="design-console" className={`w-full max-w-4xl mx-auto space-y-8 transition-all duration-700 ${!baseImage ? 'opacity-20 pointer-events-none grayscale blur-sm' : 'opacity-100'}`}>
        <div className="flex flex-col gap-6 bg-slate-900/40 border border-white/5 rounded-[3rem] p-10 shadow-2xl backdrop-blur-sm">
          <div className="flex items-center justify-between px-2">
            <div className="flex items-center gap-4">
              <div className="w-10 h-10 bg-indigo-600/10 border border-indigo-500/30 rounded-2xl flex items-center justify-center">
                <svg className="w-5 h-5 text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
              </div>
              <div>
                <h4 className="text-[12px] font-black uppercase tracking-[0.4em] text-white">Consola de Diseño</h4>
                <p className="text-[9px] font-bold text-slate-500 uppercase tracking-widest mt-1">Escribe o selecciona descriptores tácticos</p>
              </div>
            </div>

            <div className="hidden md:flex items-center gap-6">
               <div className="flex flex-col items-end">
                 <span className="text-[8px] font-black text-slate-600 uppercase tracking-widest mb-1">DNA Strength</span>
                 <div className="w-24 h-1.5 bg-slate-800 rounded-full overflow-hidden">
                   <div className="h-full bg-indigo-500 transition-all duration-1000" style={{ width: `${mutationStrength}%` }} />
                 </div>
               </div>
            </div>
          </div>

          <div className="relative">
            <textarea 
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              placeholder="Ej: Armadura gótica pesada, estilo Queen's Blade, detalles en platino y cian neón..."
              className="w-full bg-black/40 border border-white/10 rounded-3xl p-8 text-sm text-white min-h-[140px] outline-none focus:ring-2 focus:ring-indigo-500/40 resize-none transition-all placeholder:text-slate-700 font-medium leading-relaxed"
            />
          </div>

          <div className="space-y-6 pt-4">
            {QUICK_TAGS.map((cat) => (
              <div key={cat.category} className="space-y-3">
                <span className="text-[9px] font-black text-slate-600 uppercase tracking-widest block pl-2">{cat.category}</span>
                <div className="flex flex-wrap gap-2">
                  {cat.tags.map((tag) => (
                    <button
                      key={tag}
                      onClick={() => addTag(tag)}
                      className="px-4 py-2 bg-white/[0.03] border border-white/[0.06] rounded-xl text-[10px] font-bold text-slate-400 hover:bg-indigo-600 hover:text-white hover:border-indigo-400 transition-all active:scale-95"
                    >
                      + {tag}
                    </button>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>

        <button 
          onClick={onGenerate}
          disabled={isGenerating || !baseImage}
          className={`w-full py-8 rounded-[2.5rem] font-black text-[13px] tracking-[0.7em] uppercase transition-all shadow-3xl relative overflow-hidden group ${
            isGenerating || !baseImage 
              ? 'bg-slate-900 text-slate-700 opacity-50 cursor-not-allowed' 
              : 'bg-indigo-600 hover:bg-indigo-500 text-white shadow-indigo-600/30 active:scale-[0.98]'
          }`}
        >
          <span className="relative z-10">{isGenerating ? 'PROCESANDO SÍNTESIS...' : 'EJECUTAR FORJA NEURAL'}</span>
          {!isGenerating && baseImage && (
            <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-1000" />
          )}
        </button>
      </div>

      <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={handleUpload} />
    </div>
  );
};

export default MainEditor;

import React from 'react';
import { AppState } from '../types';
import { MODEL_OPTIONS, ASPECT_RATIOS } from '../constants';

interface SidebarProps {
  isOpen: boolean;
  onClose: () => void;
  state: AppState;
  dispatch: any;
  prompt: string;
  setPrompt: (v: string) => void;
  onGenerate: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ isOpen, onClose, state, dispatch }) => {
  const toggleProtocol = (key: keyof AppState['renderingProtocols']) => {
    dispatch({ 
      type: 'UPDATE_CONFIG', 
      payload: { 
        renderingProtocols: { 
          ...state.renderingProtocols, 
          [key]: !state.renderingProtocols[key] 
        } 
      } 
    });
  };

  const toggleSheetMode = () => {
    dispatch({ 
      type: 'UPDATE_CONFIG', 
      payload: { isCharacterSheetMode: !state.isCharacterSheetMode } 
    });
  };

  return (
    <aside className={`fixed inset-y-0 left-0 z-[60] w-80 bg-[#0a0a0a] border-r border-white/5 transition-transform duration-500 ease-out lg:static lg:translate-x-0 ${isOpen ? 'translate-x-0' : '-translate-x-full'}`}>
      <div className="h-full flex flex-col p-8 space-y-10 overflow-y-auto custom-scrollbar no-scrollbar-mobile">

        <div className="flex items-center justify-between">
          <label className="text-[11px] font-black text-white uppercase tracking-[0.3em]">Configuración Técnica</label>
          <button onClick={onClose} className="lg:hidden p-2 text-slate-500 hover:text-white transition-colors">✕</button>
        </div>

        {/* ESTRUCTURA Y LAYOUT */}
        <section className="space-y-5">
          <label className="text-[10px] font-black text-slate-600 uppercase tracking-widest">Layout de Salida</label>
          <button 
            onClick={toggleSheetMode}
            className={`w-full p-5 rounded-3xl text-[10px] font-black border transition-all flex items-center justify-between ${state.isCharacterSheetMode ? 'bg-amber-600/10 border-amber-500 text-amber-400' : 'bg-white/5 border-transparent text-slate-500 hover:bg-white/10'}`}
          >
            <span>REFERENCE SHEET (3V)</span>
            <div className={`w-4 h-4 rounded-full border-2 ${state.isCharacterSheetMode ? 'bg-amber-500 border-white shadow-[0_0_8px_#f59e0b]' : 'border-slate-800'}`} />
          </button>

          {!state.isCharacterSheetMode && (
            <div className="grid grid-cols-3 gap-2">
              {ASPECT_RATIOS.map(ratio => (
                <button 
                  key={ratio}
                  onClick={() => dispatch({ type: 'UPDATE_CONFIG', payload: { selectedAspectRatio: ratio } })}
                  className={`py-3 rounded-xl text-[9px] font-black border transition-all ${state.selectedAspectRatio === ratio ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-white/5 border-transparent text-slate-600 hover:text-slate-400'}`}
                >
                  {ratio}
                </button>
              ))}
            </div>
          )}
        </section>

        {/* PROTOCOLOS DE RENDERIZADO */}
        <section className="space-y-5">
          <label className="text-[10px] font-black text-slate-600 uppercase tracking-widest">Protocolos de Síntesis</label>
          <div className="grid grid-cols-1 gap-3">
            {[
              { id: 'magentaBackground', label: 'Chroma Magenta', color: 'bg-fuchsia-500' },
              { id: 'hd2dStyle', label: 'Estilo Queen\'s Blade', color: 'bg-indigo-500' },
              { id: 'pixelPerfect', label: 'Pixel Perfect (16bit)', color: 'bg-emerald-500' },
              { id: 'strongOutline', label: 'Strong Silhouette', color: 'bg-white' },
            ].map((p) => (
              <button 
                key={p.id}
                onClick={() => toggleProtocol(p.id as any)}
                className={`p-4 rounded-2xl text-[9px] font-black border transition-all flex items-center gap-4 ${state.renderingProtocols[p.id as keyof AppState['renderingProtocols']] ? 'bg-white/10 border-white/20 text-white' : 'bg-white/5 border-transparent text-slate-600 hover:bg-white/[0.07]'}`}
              >
                <div className={`w-3 h-3 rounded-full ${state.renderingProtocols[p.id as keyof AppState['renderingProtocols']] ? p.color : 'bg-slate-800 opacity-50'}`} />
                <span className="uppercase tracking-widest">{p.label}</span>
              </button>
            ))}
          </div>
        </section>

        {/* MUTATION STRENGTH */}
        <section className="space-y-5">
          <div className="flex justify-between items-end">
            <label className="text-[10px] font-black text-slate-600 uppercase tracking-widest">Potencia de Mutación</label>
            <span className="text-[10px] font-mono text-indigo-400 font-bold">{state.mutationStrength}%</span>
          </div>
          <div className="bg-white/5 p-6 rounded-[2rem] border border-white/5">
            <input 
              type="range" min="1" max="100" value={state.mutationStrength} 
              onChange={(e) => dispatch({ type: 'UPDATE_CONFIG', payload: { mutationStrength: +e.target.value } })}
              className="w-full h-1.5 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-indigo-500"
            />
          </div>
        </section>

        {/* MOTOR NEURONAL */}
        <section className="space-y-5">
          <label className="text-[10px] font-black text-slate-600 uppercase tracking-widest">Motor Neuronal</label>
          <div className="grid grid-cols-1 gap-2">
            {MODEL_OPTIONS.map(m => (
              <button 
                key={m.id}
                onClick={() => dispatch({ type: 'UPDATE_CONFIG', payload: { selectedModel: m.id } })}
                className={`p-4 rounded-2xl text-[10px] font-black border transition-all text-left flex flex-col gap-1 ${
                  state.selectedModel === m.id 
                    ? 'bg-indigo-600 border-indigo-400 text-white shadow-xl' 
                    : 'bg-white/5 border-transparent text-slate-600 hover:text-slate-400 hover:bg-white/[0.07]'
                }`}
              >
                <span>{m.label}</span>
                <span className="text-[7px] opacity-50 tracking-widest">{m.id === 'gemini-3-pro-image-preview' ? 'HIGH PRECISION' : 'RAPID SYNTHESIS'}</span>
              </button>
            ))}
          </div>
        </section>

      </div>
    </aside>
  );
};

