    renderingProtocols: {
      magentaBackground: true,
      pixelPerfect: true,
      strongOutline: true,
      hd2dStyle: true
    }
  });

  const [prompt, setPrompt] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    StorageService.getAllOutfits().then(data => dispatch({ type: 'SET_OUTFITS', payload: data }));
  }, []);

  const handleSelectParent = (outfit: GeneratedOutfit) => {
    dispatch({ type: 'SET_PARENT', payload: outfit });
    setPrompt(outfit.prompt);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleRemoveOutfit = async (id: string) => {
    await StorageService.deleteOutfit(id);
    dispatch({ type: 'REMOVE_OUTFIT', payload: id });
    if (state.activeEvolutionParent?.id === id) {
      dispatch({ type: 'SET_PARENT', payload: null });
    }
  };

  const handleProcessPNG = async (outfit: GeneratedOutfit) => {
    try {
      const transparentUrl = await ImageProcessor.processAlpha(outfit.url, 45, 4);
      const link = document.createElement('a');
      link.href = transparentUrl;
      link.download = `outfit-export-${outfit.id}.png`;
      link.click();
    } catch (e) {
      dispatch({ type: 'SET_ERROR', payload: "Fallo en la extracción de transparencia." });
    }
  };

  const handleForge = async () => {
    if (!state.baseImage) {
      dispatch({ type: 'SET_ERROR', payload: "SIN MANIQUÍ: Sube primero la base del personaje." });
      return;
    }

    dispatch({ type: 'SET_GENERATING', payload: true });
    dispatch({ type: 'SET_ERROR', payload: null });

    try {
      const url = await GeminiService.generateEvolution(
        state.baseImage,
        state.activeEvolutionParent?.url || null,
        prompt || "Detailed fantasy character outfit",
        state.mutationStrength,
        {
          model: state.selectedModel,
          aspectRatio: state.selectedAspectRatio,
          outline: state.outline,
          isCharacterSheet: state.isCharacterSheetMode,
          size: state.selectedSize,
          protocols: state.renderingProtocols
        }
      );

      const newAsset: GeneratedOutfit = {
        id: crypto.randomUUID(),
        url: url,
        originalUrl: url,
        parentId: state.activeEvolutionParent?.id,
        prompt: prompt,
        timestamp: Date.now(),
        model: state.selectedModel,
        aspectRatio: state.selectedAspectRatio,
        evolutionStep: (state.activeEvolutionParent?.evolutionStep || 0) + 1
      };

      await StorageService.saveOutfit(newAsset);
      dispatch({ type: 'ADD_OUTFIT', payload: newAsset });
      dispatch({ type: 'SET_PARENT', payload: newAsset });
    } catch (e: any) {
      dispatch({ type: 'SET_ERROR', payload: "Neural Interruption: " + e.message });
    } finally {
      dispatch({ type: 'SET_GENERATING', payload: false });
    }
  };

  return (
    <div className="fixed inset-0 flex flex-col bg-[#050505] text-[#e2e8f0] font-sans overflow-hidden">
      <Header onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)} isGenerating={state.isGenerating} />

      <div className="flex flex-1 overflow-hidden relative">
        <Sidebar 
          isOpen={isSidebarOpen}
          onClose={() => setIsSidebarOpen(false)}
          state={state}
          dispatch={dispatch}
          prompt={prompt}
          setPrompt={setPrompt}
          onGenerate={handleForge}
        />

        <main className="flex-1 overflow-y-auto custom-scrollbar bg-[radial-gradient(circle_at_center,_rgba(79,70,229,0.03)_0%,_transparent_100%)]">
          <div className="max-w-screen-2xl mx-auto px-4 py-6 lg:px-8 lg:py-10 pb-40">

            {state.error && (
              <div className="max-w-2xl mx-auto mb-6 bg-red-500/10 border border-red-500/20 text-red-400 p-4 rounded-2xl flex justify-between items-center animate-in slide-in-from-top-2">
                <span className="text-[10px] font-black uppercase tracking-widest">{state.error}</span>
                <button onClick={() => dispatch({ type: 'SET_ERROR', payload: null })} className="p-1 hover:bg-white/5 rounded-full transition-colors">✕</button>
              </div>
            )}

            <div className="flex flex-col gap-12">
              {/* THE DRESSING STAGE */}
              <MainEditor 
                baseImage={state.baseImage}
                parentImage={state.activeEvolutionParent?.url || null}
                onUploadBase={(url) => dispatch({ type: 'SET_BASE', payload: url })}
                isGenerating={state.isGenerating}
                onResetParent={() => dispatch({ type: 'SET_PARENT', payload: null })}
                mutationStrength={state.mutationStrength}
                magentaActive={state.renderingProtocols.magentaBackground}
                isSheetMode={state.isCharacterSheetMode}
                prompt={prompt}
                setPrompt={setPrompt}
                onGenerate={handleForge}
              />

              {/* THE WARDROBE (HISTORIAL) */}
              <div className="pt-10 border-t border-white/5">
                <ResultGallery 
                  outfits={state.outfits}
                  activeParentId={state.activeEvolutionParent?.id || null}
                  onSelectParent={handleSelectParent}
                  onRemoveOutfit={handleRemoveOutfit}
                  onProcessPNG={handleProcessPNG}
                  isGenerating={state.isGenerating}
                />
              </div>
            </div>
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

