import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ModelType, ImageSize, AspectRatio, OutlineConfig, RenderingProtocols, BackgroundStyle } from "../types";

export class GeminiService {
  private static async getAIInstance() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  private static async optimizeImage(base64: string, maxDim: number = 1024): Promise<string> {
    return new Promise((resolve) => {
      const img = new Image();
      img.onload = () => {
        let width = img.width;
        let height = img.height;
        if (width > maxDim || height > maxDim) {
          const ratio = width > height ? maxDim / width : maxDim / height;
          width *= ratio;
          height *= ratio;
        }
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.imageSmoothingEnabled = true;
          ctx.imageSmoothingQuality = 'high';
          ctx.drawImage(img, 0, 0, width, height);
        }
        resolve(canvas.toDataURL('image/jpeg', 0.9));
      };
      img.src = base64;
    });
  }

  private static getBackgroundDescription(style: BackgroundStyle): string {
    switch(style) {
      case 'magenta': return 'Pure #FF00FF (Chroma Key Magenta). Absolute solid color, no variations.';
      case 'white': return 'Pure solid white (#FFFFFF). No shadows or gradients.';
      case 'gray': return 'Solid neutral gray (#808080). Flat professional look.';
      case 'gradient': return 'Subtle studio gradient from light gray to medium gray. Minimal professional look.';
      default: return 'Solid flat color.';
    }
  }

  static async generateEvolution(
    baseCharacter: string,
    parentSprite: string | null,
    prompt: string,
    mutationStrength: number,
    config: {
      model: ModelType,
      aspectRatio: AspectRatio,
      outline: OutlineConfig,
      isCharacterSheet: boolean,
      size: ImageSize,
      protocols: RenderingProtocols
    }
  ): Promise<string> {
    const ai = await this.getAIInstance();
    const optBase = await this.optimizeImage(baseCharacter);
    const optParent = parentSprite ? await this.optimizeImage(parentSprite) : null;

    // PROTOCOLO DE ANCLAJE ANATÓMICO 3.0 (ALGORITMO DE INSTRUCCIÓN)
    const anatomyLock = `
CRITICAL ANATOMY LOCK v3.0:
- Use the provided BASE IMAGE as a RIGID TEMPLATE. 
- DO NOT CHANGE: Face features, eye shape, body silhouette, breast size (must be large/voluptuous as per JRPG style), height, or pose.
- THE CHARACTER MUST OVERLAY PERFECTLY on top of the original anatomy.
- TASK: You are strictly "dressing" a paper doll. Add layers of clothing ON TOP of the base skin.`;

    const renderingLogic = `
TECHNICAL RENDERING PIPELINE:
- BACKGROUND: ${this.getBackgroundDescription(config.protocols.backgroundStyle)}
- STYLE: ${config.protocols.hd2dStyle ? 'Modern HD-2D Sprite (Death Metal/Queen\'s Blade aesthetic).' : 'Professional Concept Art.'}
- LIGHTING: Consistent top-down studio lighting. No environmental shadows.
- OUTLINE: ${config.protocols.strongOutline ? 'Sharp 2px black contour for game-engine compatibility.' : 'Soft artistic edges.'}`;

    const evolutionLogic = optParent 
      ? `DNA INJECTION: Blend the previous design's details into this new generation with a ${mutationStrength}% mutation factor. Maintain core accessories but refine them according to the prompt.` 
      : 'INITIAL LAYER SYNTHESIS: Apply the first layer of equipment to the base mannequin.';

    const systemInstruction = `You are a specialized Game Asset Generator.
${anatomyLock}
${renderingLogic}
${evolutionLogic}

REQUIRED OUTPUT: A clean, isolated character asset ready for sprite-sheet extraction. 
NO artistic backgrounds. NO floating particles. NO ground plane.`;

    const userPrompt = `[DESIGN DIRECTIVE]: ${prompt}
[STYLE NOTES]: High-detail fantasy armor, tactical cutouts (underboob/sideboob), metallic reflections, JRPG Queen's Blade influence.
[FORMAT]: Isolated sprite on requested background.`;

    try {
      const parts: any[] = [
        { inlineData: { data: optBase.split(',')[1], mimeType: 'image/jpeg' } },
        { text: "REFERENCE A: RIGID ANATOMY MANNEQUIN" }
      ];

      if (optParent) {
        parts.push({ inlineData: { data: optParent.split(',')[1], mimeType: 'image/jpeg' } });
        parts.push({ text: "REFERENCE B: PREVIOUS OUTFIT LAYER" });
      }

      parts.push({ text: userPrompt });

      const response: GenerateContentResponse = await ai.models.generateContent({
        model: config.model,
        contents: { parts },
        config: {
          systemInstruction,
          imageConfig: {
            aspectRatio: config.aspectRatio,
            ...(config.model === 'gemini-3-pro-image-preview' && { imageSize: config.size })
          }
        }
      });

      const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (imagePart?.inlineData) {
        return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
      }
      throw new Error("Neural synthesis failed to produce image data.");
    } catch (e) {
      console.error("[Neural Engine Error]", e);
      throw e;
    }
  }
}

import React, { useRef, useState } from 'react';
import { QUICK_TAGS } from '../constants';
import { BackgroundStyle } from '../types';

interface MainEditorProps {
  baseImage: string | null;
  parentImage: string | null;
  onUploadBase: (url: string) => void;
  isGenerating: boolean;
  onResetParent: () => void;
  mutationStrength: number;
  backgroundStyle: BackgroundStyle;
  isSheetMode: boolean;
  prompt: string;
  setPrompt: (v: string) => void;
  onGenerate: () => void;
}

const MainEditor: React.FC<MainEditorProps> = ({ 
  baseImage, 
  parentImage, 
  onUploadBase, 
  isGenerating, 
  onResetParent, 
  mutationStrength, 
  backgroundStyle,
  prompt,
  setPrompt,
  onGenerate
}) => {
  const fileRef = useRef<HTMLInputElement>(null);
  const [showBase, setShowBase] = useState(false);
  const [activeTab, setActiveTab] = useState(QUICK_TAGS[0].category);

  const handleUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const r = new FileReader();
      r.onload = () => onUploadBase(r.result as string);
      r.readAsDataURL(file);
    }
  };

  const getBgClass = () => {
    switch(backgroundStyle) {
      case 'magenta': return 'bg-[#FF00FF]';
      case 'white': return 'bg-white';
      case 'gray': return 'bg-[#808080]';
      case 'gradient': return 'bg-gradient-to-br from-gray-200 to-gray-500';
      default: return 'bg-[#080808]';
    }
  };

  return (
    <div className="h-full flex flex-col relative">

      {/* 1. STAGE (TOP 65%) */}
      <div className={`relative flex-1 flex items-center justify-center overflow-hidden transition-all duration-700 ${getBgClass()}`}>
        {!baseImage ? (
          <div 
            onClick={() => fileRef.current?.click()}
            className="flex flex-col items-center justify-center p-12 text-center group"
          >
            <div className="w-20 h-20 bg-slate-900 rounded-3xl flex items-center justify-center mb-6 shadow-2xl border border-white/5 animate-pulse-slow">
              <svg className="w-8 h-8 text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
              </svg>
            </div>
            <h3 className={`text-[11px] font-black uppercase tracking-[0.3em] ${backgroundStyle === 'white' ? 'text-black' : 'text-white'}`}>Cargar Maniquí</h3>
            <p className={`text-[8px] font-bold uppercase tracking-widest mt-2 max-w-[180px] ${backgroundStyle === 'white' ? 'text-slate-600' : 'text-slate-500'}`}>Sube un personaje base para comenzar la forja.</p>
          </div>
        ) : (
          <div className="relative w-full h-full p-4 flex items-center justify-center">
            {backgroundStyle !== 'magenta' && backgroundStyle !== 'white' && backgroundStyle !== 'gray' && (
              <div className="absolute inset-0 opacity-[0.05] pointer-events-none checker-bg" />
            )}

            <img 
              src={baseImage} 
              className={`max-h-full max-w-full object-contain transition-all duration-500 ${parentImage && !showBase ? 'opacity-10 blur-xl grayscale' : 'opacity-100'}`} 
            />

            {parentImage && !showBase && (
              <img 
                src={parentImage} 
                className="absolute max-h-[85%] max-w-[85%] object-contain drop-shadow-[0_0_50px_rgba(0,0,0,0.3)] animate-in zoom-in-95" 
              />
            )}

            {/* Stage Controls */}
            <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex items-center gap-2 bg-black/60 backdrop-blur-xl p-1 rounded-2xl border border-white/10 shadow-2xl">
              <button 
                onPointerDown={() => setShowBase(true)}
                onPointerUp={() => setShowBase(false)}
                onPointerLeave={() => setShowBase(false)}
                className="px-4 py-2 text-[8px] font-black uppercase tracking-widest text-slate-400 hover:text-white"
              >
                👁 Peek Base
              </button>
              {parentImage && (
                <>
                  <div className="w-px h-3 bg-white/10" />
                  <button 
                    onClick={onResetParent}
                    className="px-4 py-2 text-[8px] font-black uppercase tracking-widest text-red-400"
                  >
                    ✕ Reset
                  </button>
                </>
              )}
            </div>
          </div>
        )}

        {isGenerating && (
          <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-2xl flex flex-col items-center justify-center animate-in fade-in">
            <div className="w-12 h-12 border-2 border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin mb-4" />
            <span className="text-[9px] font-black text-white uppercase tracking-[0.4em] animate-pulse">Sintetizando...</span>
          </div>
        )}
      </div>

      {/* 2. THUMB DOCK (BOTTOM 35%) */}
      <div className={`h-[380px] bg-slate-900/60 backdrop-blur-3xl border-t border-white/5 p-6 flex flex-col gap-6 transition-all duration-500 ${!baseImage ? 'translate-y-full opacity-0' : 'translate-y-0 opacity-100'}`}>

        <div className="relative">
          <textarea 
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            placeholder="Describe el equipamiento..."
            className="w-full bg-black/40 border border-white/10 rounded-2xl p-4 text-[13px] text-white min-h-[100px] outline-none resize-none"
          />
        </div>

        <div className="flex-1 overflow-hidden flex flex-col gap-4">
          <div className="flex gap-4 overflow-x-auto no-scrollbar border-b border-white/5 pb-2">
            {QUICK_TAGS.map(cat => (
              <button 
                key={cat.category}
                onClick={() => setActiveTab(cat.category)}
                className={`whitespace-nowrap text-[9px] font-black uppercase tracking-widest pb-2 ${activeTab === cat.category ? 'text-indigo-400 border-b-2 border-indigo-500' : 'text-slate-600'}`}
              >
                {cat.category.split(':')[1] || cat.category}
              </button>
            ))}
          </div>
          <div className="flex-1 overflow-y-auto no-scrollbar flex flex-wrap gap-2 content-start">
            {QUICK_TAGS.find(c => c.category === activeTab)?.tags.map(tag => (
              <button 
                key={tag}
                onClick={() => {
                  const newPrompt = prompt.trim() ? `${prompt.trim()}, ${tag}` : tag;
                  if (!prompt.includes(tag)) setPrompt(newPrompt);
                }}
                className="px-3 py-1.5 bg-white/5 rounded-lg text-[9px] font-bold text-slate-400 border border-white/5 active:bg-indigo-600 active:text-white"
              >
                + {tag}
              </button>
            ))}
          </div>
        </div>

        <button 
          onClick={onGenerate}
          disabled={isGenerating || !baseImage}
          className="w-full py-5 bg-indigo-600 rounded-2xl font-black text-[11px] tracking-[0.4em] uppercase shadow-2xl shadow-indigo-600/20 active:scale-95 transition-all"
        >
          {isGenerating ? 'Procesando...' : 'Equipar Asset'}
        </button>
      </div>

      <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={handleUpload} />
    </div>
  );
};

export default MainEditor;

