import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ModelType, ImageSize, AspectRatio, OutlineConfig, RenderingProtocols, BackgroundStyle } from "../types";

export class GeminiService {
  private static getAIInstance() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY as string });
  }

  private static async optimizeImage(base64: string, maxDim: number = 1024): Promise<string> {
    return new Promise((resolve) => {
      const img = new Image();
      img.onload = () => {
        let width = img.width;
        let height = img.height;
        if (width > maxDim || height > maxDim) {
          const ratio = width > height ? maxDim / width : maxDim / height;
          width *= ratio;
          height *= ratio;
        }
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.imageSmoothingEnabled = true;
          ctx.imageSmoothingQuality = 'high';
          ctx.drawImage(img, 0, 0, width, height);
        }
        resolve(canvas.toDataURL('image/jpeg', 0.9));
      };
      img.src = base64;
    });
  }

  private static getBackgroundDescription(style: BackgroundStyle): string {
    switch(style) {
      case 'magenta': return 'Solid #FF00FF (Chroma Magenta). Perfect flat color for transparency keying.';
      case 'white': return 'Solid #FFFFFF white. No shadows.';
      case 'gray': return 'Solid #808080 neutral gray.';
      case 'gradient': return 'Neutral studio lighting gradient.';
      default: return 'Solid flat color.';
    }
  }

  static async generateEvolution(
    baseCharacter: string,
    parentSprite: string | null,
    prompt: string,
    mutationStrength: number,
    config: {
      model: ModelType,
      aspectRatio: AspectRatio,
      outline: OutlineConfig,
      isCharacterSheet: boolean,
      size: ImageSize,
      protocols: RenderingProtocols
    }
  ): Promise<string> {
    const ai = this.getAIInstance();
    const optBase = await this.optimizeImage(baseCharacter);
    const optParent = parentSprite ? await this.optimizeImage(parentSprite) : null;

    const anatomyLock = `
[DNA LOCK PROTOCOL v4.0]
- REFERENCE A IS THE IMMUTABLE ANATOMY MANNEQUIN.
- Maintain the EXACT body silhouette, head-to-body ratio, and limb positions.
- All equipment must conform to the body curves of Reference A.
- DO NOT add height, change the face, or alter the character's core identity.
- This is a non-destructive paper-doll layer application.
- Preservation of the base sprite's pixel style and lighting direction is mandatory.`;

    const renderingLogic = `
[TECHNICAL SPECIFICATIONS]
- ART STYLE: Professional JRPG HD-2D (Modern Pixel/Smooth Anime fusion).
- BG COLOR: ${this.getBackgroundDescription(config.protocols.backgroundStyle)}
- CONTOUR: ${config.protocols.strongOutline ? 'Crisp 1px black outline for game engine compatibility.' : 'Artistic blending.'}
- LIGHTING: Consistent soft top-down studio lighting. No complex ambient occlusion.`;

    const evolutionLogic = optParent 
      ? `[OUTFIT EVOLUTION]: Inherit ${100 - mutationStrength}% of the visual elements from Reference B (Parent Sprite) and apply ${mutationStrength}% mutation based on the new prompt. Maintain accessory locations.` 
      : '[INITIAL SYNTHESIS]: First iteration layer. Apply design directly to the mannequin.';

    const systemInstruction = `You are an expert Game Character Design Engine.
${anatomyLock}
${renderingLogic}
${evolutionLogic}
OUTPUT: ONE clean, isolated sprite on a flat background. NO GROUND. NO PARTICLE FX unless requested.`;

    const userPrompt = `[DESIGN DIRECTIVE]: ${prompt}
[OUTFIT SPECS]: Integrate the clothing items naturally onto the mannequin. Use high-quality textures (metal, fabric, leather). 
[COMPATIBILITY]: Ensure the asset is pixel-ready for 2D game engines.`;

    try {
      const parts: any[] = [
        { inlineData: { data: optBase.split(',')[1], mimeType: 'image/jpeg' } },
        { text: "REFERENCE A: ANATOMY MANNEQUIN (DNA ANCHOR)" }
      ];

      if (optParent) {
        parts.push({ inlineData: { data: optParent.split(',')[1], mimeType: 'image/jpeg' } });
        parts.push({ text: "REFERENCE B: CURRENT OUTFIT STATE (EVOLUTION SOURCE)" });
      }

      parts.push({ text: userPrompt });

      const response: GenerateContentResponse = await ai.models.generateContent({
        model: config.model,
        contents: { parts },
        config: {
          systemInstruction,
          imageConfig: {
            aspectRatio: config.aspectRatio,
            ...(config.model === 'gemini-3-pro-image-preview' && { imageSize: config.size })
          }
        }
      });

      const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (imagePart?.inlineData) {
        return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
      }
      throw new Error("Neural synthesis returned no image data.");
    } catch (e: any) {
      console.error("[Neural Engine Error]", e);
      throw e;
    }
  }
}

import React, { useRef, useState, useEffect } from 'react';
import { QUICK_TAGS } from '../constants';
