  onResetParent: () => void;
  mutationStrength: number;
  backgroundStyle: BackgroundStyle;
  isSheetMode: boolean;
  prompt: string;
  setPrompt: (v: string) => void;
  onGenerate: () => void;
}

const MainEditor: React.FC<MainEditorProps> = ({ 
  baseImage, 
  parentImage, 
  onUploadBase, 
  isGenerating, 
  onResetParent, 
  mutationStrength, 
  backgroundStyle,
  prompt,
  setPrompt,
  onGenerate
