import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ModelType, ImageSize, AspectRatio, OutlineConfig, RenderingProtocols, BackgroundStyle } from "../types";

export class GeminiService {
  private static getAIInstance() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY as string });
  }

  private static async optimizeImage(base64: string, maxDim: number = 1024): Promise<string> {
    return new Promise((resolve) => {
      const img = new Image();
      img.onload = () => {
        let width = img.width;
        let height = img.height;
        if (width > maxDim || height > maxDim) {
          const ratio = width > height ? maxDim / width : maxDim / height;
          width *= ratio;
          height *= ratio;
        }
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.imageSmoothingEnabled = true;
          ctx.imageSmoothingQuality = 'high';
          ctx.drawImage(img, 0, 0, width, height);
        }
        resolve(canvas.toDataURL('image/jpeg', 0.9));
      };
      img.src = base64;
    });
  }

  private static getBackgroundDescription(style: BackgroundStyle): string {
    switch(style) {
      case 'magenta': return 'Solid #FF00FF (Chroma Magenta). Perfect flat color for game engine extraction.';
      case 'white': return 'Solid #FFFFFF pure white. No shadows.';
      case 'gray': return 'Solid #808080 neutral gray.';
      case 'gradient': return 'Neutral studio lighting gradient.';
      default: return 'Solid flat color.';
    }
  }

  static async generateEvolution(
    baseCharacter: string,
    parentSprite: string | null,
    prompt: string,
    mutationStrength: number,
    config: {
      model: ModelType,
      aspectRatio: AspectRatio,
      outline: OutlineConfig,
      isCharacterSheet: boolean,
      size: ImageSize,
      protocols: RenderingProtocols
    }
  ): Promise<string> {
    const ai = this.getAIInstance();
    const optBase = await this.optimizeImage(baseCharacter);
    const optParent = parentSprite ? await this.optimizeImage(parentSprite) : null;

    const systemInstruction = `You are SPRITEFORGE-RPG.
The user provides a base pixel art sprite (Reference A).
Your task is to generate the SAME CHARACTER with a NEW OUTFIT based on the user prompt.

ABSOLUTE RULES:
- NEVER change face, eyes, hair, skin color, body shape or anatomy proportions.
- NEVER change pixel scale or orientation.
- NEVER change the pose of the character.
- NEVER change the silhouette anchor of the body.
- You may ONLY change clothing, armor, and accessories.
- Maintain a consistent professional JRPG HD-2D art style.
- Result must look like the same sprite evolved/cloned, not a new character.
- Output ONE single clean sprite on a FLAT background color: ${this.getBackgroundDescription(config.protocols.backgroundStyle)}
${config.protocols.strongOutline ? '- Add a crisp 1px dark contour for sprite isolation.' : ''}

Output only the image. No text explanations. No variations. Only the final evolved sprite.`;

    const userPrompt = `
[DNA ANCHOR]: Use the anatomy of Reference A.
[OUTFIT REQUEST]: ${prompt}
[EVOLUTION TARGET]: ${optParent ? `Blend ${100 - mutationStrength}% of Reference B with ${mutationStrength}% new design elements.` : 'Fresh outfit synthesis on the mannequin.'}
[EXPORT READY]: High quality, clean borders, professional game asset.`;

    try {
      const parts: any[] = [
        { inlineData: { data: optBase.split(',')[1], mimeType: 'image/jpeg' } },
        { text: "REFERENCE A: ANATOMY DNA & MANNEQUIN" }
      ];

      if (optParent) {
        parts.push({ inlineData: { data: optParent.split(',')[1], mimeType: 'image/jpeg' } });
        parts.push({ text: "REFERENCE B: CURRENT STATE TO EVOLVE" });
      }

      parts.push({ text: userPrompt });

      const response: GenerateContentResponse = await ai.models.generateContent({
        model: config.model,
        contents: { parts },
        config: {
          systemInstruction,
          imageConfig: {
            aspectRatio: config.aspectRatio,
            ...(config.model === 'gemini-3-pro-image-preview' && { imageSize: config.size })
          }
        }
      });

      const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (imagePart?.inlineData) {
        return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
      }
      throw new Error("Forge synthesis failed to return an image part.");
    } catch (e: any) {
      console.error("[SpriteForge Error]", e);
      throw e;
    }
  }
}

