import React, { useRef, useState } from 'react';
import { QUICK_TAGS } from '../constants';
import { BackgroundStyle } from '../types';

interface MainEditorProps {
  baseImage: string | null;
  parentImage: string | null;
  onUploadBase: (url: string) => void;
  isGenerating: boolean;
  onResetParent: () => void;
  mutationStrength: number;
  backgroundStyle: BackgroundStyle;
  isSheetMode: boolean;
  prompt: string;
  setPrompt: (v: string) => void;
  onGenerate: () => void;
}

const MainEditor: React.FC<MainEditorProps> = ({ 
  baseImage, 
  parentImage, 
  onUploadBase, 
  isGenerating, 
  onResetParent, 
  backgroundStyle,
  prompt,
  setPrompt,
  onGenerate
}) => {
  const fileRef = useRef<HTMLInputElement>(null);
  const [showBase, setShowBase] = useState(false);
  const [activeTab, setActiveTab] = useState(QUICK_TAGS[0].category);

  const handleUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const r = new FileReader();
      r.onload = () => onUploadBase(r.result as string);
      r.readAsDataURL(file);
    }
  };

  const getBgClass = () => {
    switch(backgroundStyle) {
      case 'magenta': return 'bg-[#FF00FF]';
      case 'white': return 'bg-white';
      case 'gray': return 'bg-[#808080]';
      case 'gradient': return 'bg-gradient-to-br from-gray-300 to-gray-600';
      default: return 'bg-[#080808]';
    }
  };

  return (
    <div className="h-full flex flex-col relative">

      {/* 1. THE STAGE (Neural Canvas) */}
      <div className={`relative flex-1 flex items-center justify-center overflow-hidden transition-all duration-700 ${getBgClass()}`}>

        {/* DNA Lock Status */}
        <div className="absolute top-4 left-6 z-10 flex items-center gap-3 bg-black/40 backdrop-blur-md px-3 py-1.5 rounded-full border border-white/5">
          <div className={`w-1.5 h-1.5 rounded-full ${baseImage ? 'bg-green-500 shadow-[0_0_10px_#22c55e]' : 'bg-red-500 shadow-[0_0_10px_#ef4444]'} transition-all`} />
          <span className="text-[9px] font-black uppercase tracking-[0.2em] text-white/60">
            {baseImage ? 'SILHOUETTE LOCK: ACTIVE' : 'SILHOUETTE LOCK: WAITING'}
          </span>
        </div>

        {!baseImage ? (
          <div 
            onClick={() => fileRef.current?.click()}
            className="flex flex-col items-center justify-center p-12 text-center group cursor-pointer"
          >
            <div className="w-24 h-24 bg-indigo-600/10 backdrop-blur-xl rounded-[2rem] flex items-center justify-center mb-8 shadow-2xl border border-indigo-500/20 group-hover:border-indigo-500 group-hover:bg-indigo-600/20 transition-all active:scale-95 animate-pulse-slow">
              <svg className="w-10 h-10 text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1M16 7l-4-4-4 4m4-4v12" />
              </svg>
            </div>
            <h3 className={`text-[13px] font-black uppercase tracking-[0.4em] ${backgroundStyle === 'white' ? 'text-black' : 'text-white'}`}>Insert DNA Anchor</h3>
            <p className={`text-[9px] font-bold uppercase tracking-widest mt-3 max-w-[240px] leading-relaxed ${backgroundStyle === 'white' ? 'text-slate-600' : 'text-slate-500'}`}>
              Upload the base sprite to define anatomy and style constraints.
            </p>
          </div>
        ) : (
          <div className="relative w-full h-full p-4 flex items-center justify-center">
            {backgroundStyle !== 'magenta' && backgroundStyle !== 'white' && (
              <div className="absolute inset-0 opacity-[0.04] pointer-events-none checker-bg scale-150" />
            )}

            <img 
              src={baseImage} 
              className={`max-h-[85%] max-w-[85%] object-contain transition-all duration-700 ${parentImage && !showBase ? 'opacity-0 scale-90 blur-3xl' : 'opacity-100 scale-100'}`} 
            />

            {parentImage && !showBase && (
              <img 
                src={parentImage} 
                className="absolute max-h-[85%] max-w-[85%] object-contain drop-shadow-[0_0_60px_rgba(0,0,0,0.6)] animate-in zoom-in-95 duration-500" 
              />
