            {/* Stage Controls */}
            <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex items-center gap-3 bg-black/90 backdrop-blur-3xl px-4 py-2 rounded-2xl border border-white/10 shadow-2xl z-20">
              <button 
                onPointerDown={() => setShowBase(true)}
                onPointerUp={() => setShowBase(false)}
                onPointerLeave={() => setShowBase(false)}
