              >
                Reveal Anchor
              </button>
              {parentImage && (
                <>
                  <div className="w-px h-4 bg-white/10" />
                  <button 
                    onClick={onResetParent}
                    className="px-6 py-2.5 text-[9px] font-black uppercase tracking-widest text-red-400 bg-red-500/10 rounded-xl border border-red-500/20 active:bg-red-500 active:text-white transition-all active:scale-95"
                  >
                    Reset Gear
                  </button>
                </>
              )}
            </div>
          </div>
        )}

        {isGenerating && (
          <div className="absolute inset-0 z-50 bg-[#050505]/95 backdrop-blur-3xl flex flex-col items-center justify-center animate-in fade-in duration-700">
            <div className="absolute inset-0 overflow-hidden pointer-events-none">
