                <span className="text-[8px] font-bold text-slate-500 uppercase tracking-widest">Applying Silhouette Constraints...</span>
            </div>
          </div>
        )}
      </div>

      {/* 2. THE CONTROL HUB */}
      <div className={`h-[420px] bg-[#0a0a0a] border-t border-white/5 p-6 flex flex-col gap-6 transition-all duration-700 ${!baseImage ? 'translate-y-full opacity-0' : 'translate-y-0 opacity-100'}`}>

        <div className="relative group">
          <textarea 
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            placeholder="Describe the new RPG outfit (e.g., Heavy steel paladin armor with gold filigree)..."
            className="w-full bg-[#050505] border border-white/10 rounded-2xl p-5 text-[14px] text-white min-h-[110px] outline-none resize-none focus:border-indigo-500/40 transition-all placeholder:text-slate-700 leading-relaxed shadow-inner"
          />
          <div className="absolute bottom-4 right-4 flex items-center gap-2 pointer-events-none">
            <span className="text-[9px] font-black text-slate-700 uppercase tracking-[0.2em]">Neural Directives</span>
          </div>
        </div>

        <div className="flex-1 overflow-hidden flex flex-col gap-4">
          <div className="flex gap-5 overflow-x-auto no-scrollbar border-b border-white/5 pb-2">
            {QUICK_TAGS.map(cat => (
              <button 
                key={cat.category}
                onClick={() => setActiveTab(cat.category)}
                className={`whitespace-nowrap text-[10px] font-black uppercase tracking-widest pb-3 transition-all relative ${activeTab === cat.category ? 'text-indigo-400' : 'text-slate-600 hover:text-slate-400'}`}
              >
                {cat.category}
                {activeTab === cat.category && <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-indigo-500 rounded-full" />}
              </button>
            ))}
          </div>
          <div className="flex-1 overflow-y-auto no-scrollbar flex flex-wrap gap-2.5 content-start">
            {QUICK_TAGS.find(c => c.category === activeTab)?.tags.map(tag => (
              <button 
                key={tag}
                onClick={() => {
                  const newPrompt = prompt.trim() ? `${prompt.trim()}, ${tag}` : tag;
                  if (!prompt.includes(tag)) setPrompt(newPrompt);
                }}
                className="px-4 py-2.5 bg-white/5 rounded-xl text-[10px] font-black text-slate-400 border border-white/5 hover:bg-white/10 hover:border-white/20 active:bg-indigo-600 active:text-white active:scale-95 transition-all shadow-sm"
              >
                + {tag}
              </button>
            ))}
          </div>
        </div>

        <button 
          onClick={onGenerate}
          disabled={isGenerating || !baseImage}
          className="w-full py-5 bg-indigo-600 hover:bg-indigo-500 rounded-2xl font-black text-[12px] tracking-[0.5em] uppercase shadow-2xl shadow-indigo-600/30 active:scale-[0.98] disabled:opacity-50 transition-all border border-indigo-400/30 text-white"
        >
          {isGenerating ? 'Synthesizing...' : 'Equip Evolved Outfit'}
        </button>
      </div>

      <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={handleUpload} />

      <style>{`
        @keyframes scan {
            0% { transform: translateY(-100%); opacity: 0; }
            50% { opacity: 1; }
            100% { transform: translateY(100vh); opacity: 0; }
        }
      `}</style>
    </div>
  );
};

