type Action = 
  | { type: 'ADD_OUTFIT'; payload: GeneratedOutfit }
  | { type: 'REMOVE_OUTFIT'; payload: string }
  | { type: 'SET_PARENT'; payload: GeneratedOutfit | null }
  | { type: 'SET_BASE'; payload: string | null }
  | { type: 'SET_GENERATING'; payload: boolean }
  | { type: 'SET_ERROR'; payload: string | null }
  | { type: 'UPDATE_CONFIG'; payload: Partial<AppState> }
  | { type: 'SET_OUTFITS'; payload: GeneratedOutfit[] };

function appReducer(state: AppState, action: Action): AppState {
  switch (action.type) {
    case 'ADD_OUTFIT': return { ...state, outfits: [action.payload, ...state.outfits] };
    case 'REMOVE_OUTFIT': return { ...state, outfits: state.outfits.filter(o => o.id !== action.payload) };
    case 'SET_PARENT': return { ...state, activeEvolutionParent: action.payload };
    case 'SET_BASE': return { ...state, baseImage: action.payload };
    case 'SET_GENERATING': return { ...state, isGenerating: action.payload };
    case 'SET_ERROR': return { ...state, error: action.payload };
    case 'UPDATE_CONFIG': return { ...state, ...action.payload };
    case 'SET_OUTFITS': return { ...state, outfits: action.payload };
    default: return state;
  }
}

const App: React.FC = () => {
  const [state, dispatch] = useReducer(appReducer, {
    baseImage: null,
    activeEvolutionParent: null,
    outfits: [],
    isGenerating: false,
    selectedModel: 'gemini-2.5-flash-image',
    selectedSize: '1K',
    selectedAspectRatio: '9:16',
    outline: { enabled: false, color: '#4f46e5', thickness: 'medium', glow: false },
    error: null,
    isCharacterSheetMode: false,
    mutationStrength: 50,
    renderingProtocols: {
      backgroundStyle: 'magenta',
      pixelPerfect: true,
      strongOutline: true,
      hd2dStyle: true
    }
  });

  const [activeTab, setActiveTab] = useState<'editor' | 'vault'>('editor');
  const [prompt, setPrompt] = useState('');
  const [isConfigOpen, setIsConfigOpen] = useState(false);
  const [needsApiKey, setNeedsApiKey] = useState(false);

  useEffect(() => {
    StorageService.getAllOutfits().then(data => dispatch({ type: 'SET_OUTFITS', payload: data }));

    const checkKey = async () => {
      if (state.selectedModel.includes('pro')) {
        const hasKey = await (window as any).aistudio.hasSelectedApiKey();
        setNeedsApiKey(!hasKey);
      } else {
        setNeedsApiKey(false);
      }
    };
    checkKey();
  }, [state.selectedModel]);

  const handleOpenKeySelector = async () => {
    await (window as any).aistudio.openSelectKey();
    setNeedsApiKey(false);
  };

  const handleSelectParent = (outfit: GeneratedOutfit) => {
    dispatch({ type: 'SET_PARENT', payload: outfit });
    setPrompt(outfit.prompt);
    setActiveTab('editor');
  };

  const handleForge = async () => {
    if (!state.baseImage) {
      dispatch({ type: 'SET_ERROR', payload: "ERROR: Upload a base DNA mannequin." });
      return;
    }

    if (needsApiKey) {
      await handleOpenKeySelector();
    }

    dispatch({ type: 'SET_GENERATING', payload: true });
    dispatch({ type: 'SET_ERROR', payload: null });

    try {
      const url = await GeminiService.generateEvolution(
        state.baseImage,
        state.activeEvolutionParent?.url || null,
        prompt || "Elite RPG combat gear",
        state.mutationStrength,
        {
          model: state.selectedModel,
          aspectRatio: state.selectedAspectRatio,
          outline: state.outline,
          isCharacterSheet: state.isCharacterSheetMode,
          size: state.selectedSize,
          protocols: state.renderingProtocols
        }
      );

      const newAsset: GeneratedOutfit = {
        id: crypto.randomUUID(),
        url: url,
        originalUrl: url,
        parentId: state.activeEvolutionParent?.id,
        prompt: prompt,
        timestamp: Date.now(),
        model: state.selectedModel,
        aspectRatio: state.selectedAspectRatio,
        evolutionStep: (state.activeEvolutionParent?.evolutionStep || 0) + 1
      };

      await StorageService.saveOutfit(newAsset);
      dispatch({ type: 'ADD_OUTFIT', payload: newAsset });
      dispatch({ type: 'SET_PARENT', payload: newAsset });
    } catch (e: any) {
      const errorMsg = e.message || "Forge disconnection";
      if (errorMsg.includes("Requested entity was not found")) {
        setNeedsApiKey(true);
        dispatch({ type: 'SET_ERROR', payload: "SESSION EXPIRED: Please re-select API Key." });
      } else {
        dispatch({ type: 'SET_ERROR', payload: "Neural Error: " + errorMsg });
      }
    } finally {
      dispatch({ type: 'SET_GENERATING', payload: false });
    }
  };

  return (
    <div className="fixed inset-0 flex flex-col bg-[#050505] text-[#e2e8f0] font-sans overflow-hidden">

      <header className="h-16 px-6 flex items-center justify-between border-b border-white/5 bg-[#050505]/90 backdrop-blur-2xl z-50">
        <div className="flex items-center gap-4">
          <div className="w-9 h-9 bg-indigo-600 rounded-xl flex items-center justify-center shadow-2xl shadow-indigo-600/30 border border-white/10">
            <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 10V3L4 14h7v7l9-11h-7z" />
            </svg>
          </div>
          <h1 className="text-[14px] font-black uppercase tracking-[0.4em] text-white">
            SpriteForge <span className="text-indigo-500">RPG</span>
          </h1>
        </div>

        <div className="flex items-center gap-3">
          {needsApiKey && (
            <button 
              onClick={handleOpenKeySelector}
              className="px-3 py-1 bg-amber-500/10 border border-amber-500/30 rounded-full text-[8px] font-black text-amber-500 uppercase tracking-widest animate-pulse"
            >
              Key Sync Needed
            </button>
          )}
          <button 
            onClick={() => setIsConfigOpen(true)}
            className="p-2.5 bg-white/5 rounded-xl border border-white/10 hover:bg-white/10 transition-all active:scale-95"
          >
            <svg className="w-5 h-5 text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.94-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
            </svg>
          </button>
        </div>
      </header>

      <main className="flex-1 overflow-hidden relative">
        {activeTab === 'editor' ? (
          <MainEditor 
            baseImage={state.baseImage}
            parentImage={state.activeEvolutionParent?.url || null}
            onUploadBase={(url) => dispatch({ type: 'SET_BASE', payload: url })}
            isGenerating={state.isGenerating}
            onResetParent={() => dispatch({ type: 'SET_PARENT', payload: null })}
            mutationStrength={state.mutationStrength}
            backgroundStyle={state.renderingProtocols.backgroundStyle}
            isSheetMode={state.isCharacterSheetMode}
            prompt={prompt}
            setPrompt={setPrompt}
            onGenerate={handleForge}
          />
        ) : (
          <div className="h-full overflow-y-auto p-8 pb-32 no-scrollbar">
            <ResultGallery 
              outfits={state.outfits}
              activeParentId={state.activeEvolutionParent?.id || null}
              onSelectParent={handleSelectParent}
              onRemoveOutfit={(id) => {
                StorageService.deleteOutfit(id);
                dispatch({ type: 'REMOVE_OUTFIT', payload: id });
              }}
              onProcessPNG={async (o) => {
                const url = await ImageProcessor.processAlpha(o.url, 45, 4);
                const link = document.createElement('a');
                link.href = url;
                link.download = `sprite-v${o.evolutionStep}-${o.id.slice(0,5)}.png`;
                link.click();
              }}
              isGenerating={state.isGenerating}
            />
          </div>
        )}

        {state.error && (
          <div className="absolute top-6 left-6 right-6 bg-red-600/95 backdrop-blur-xl p-4 rounded-2xl flex items-center justify-between z-[100] border border-red-400/30 shadow-2xl animate-in fade-in slide-in-from-top-4 duration-500">
            <span className="text-[10px] font-black uppercase tracking-widest text-white">{state.error}</span>
            <button onClick={() => dispatch({ type: 'SET_ERROR', payload: null })} className="p-2 hover:bg-white/10 rounded-lg">✕</button>
          </div>
        )}
      </main>

      <nav className="h-20 bg-[#0a0a0a]/95 backdrop-blur-3xl border-t border-white/5 flex items-center justify-around safe-bottom z-50">
        <button 
          onClick={() => setActiveTab('editor')}
          className={`flex flex-col items-center gap-1.5 transition-all duration-300 ${activeTab === 'editor' ? 'text-indigo-400 scale-110' : 'text-slate-600 hover:text-slate-400'}`}
        >
          <div className={`p-2 rounded-xl transition-colors ${activeTab === 'editor' ? 'bg-indigo-500/10' : 'bg-transparent'}`}>
            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 4a2 2 0 114 0v1a1 1 0 001 1h3a1 1 0 011 1v3a1 1 0 01-1 1h-1a2 2 0 100 4h1a1 1 0 011 1v3a1 1 0 01-1 1h-3a1 1 0 01-1-1v-1a2 2 0 10-4 0v1a1 1 0 01-1 1H7a1 1 0 01-1-1v-3a1 1 0 00-1-1H4a2 2 0 110-4h1a1 1 0 001-1V7a1 1 0 011-1h3a1 1 0 001-1V4z" />
            </svg>
          </div>
          <span className="text-[9px] font-black uppercase tracking-widest">Atelier</span>
        </button>

        <button 
          onClick={() => setActiveTab('vault')}
          className={`flex flex-col items-center gap-1.5 transition-all duration-300 ${activeTab === 'vault' ? 'text-indigo-400 scale-110' : 'text-slate-600 hover:text-slate-400'}`}
        >
          <div className={`p-2 rounded-xl transition-colors ${activeTab === 'vault' ? 'bg-indigo-500/10' : 'bg-transparent'}`}>
            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M5 8h14M5 8a2 2 0 110-4h14a2 2 0 110 4M5 8v10a2 2 0 002 2h10a2 2 0 002-2V8m-9 4h4" />
            </svg>
          </div>
          <span className="text-[9px] font-black uppercase tracking-widest">Vault</span>
        </button>
      </nav>

      <Sidebar 
        isOpen={isConfigOpen} 
        onClose={() => setIsConfigOpen(false)} 
        state={state} 
        dispatch={dispatch} 
        prompt={prompt} 
        setPrompt={setPrompt} 
        onGenerate={handleForge} 
      />
    </div>
  );
};

