import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ModelType, ImageSize, AspectRatio, OutlineConfig, RenderingProtocols, BackgroundStyle, NeuralNode } from "../types";

export class GeminiService {
  private static getAIInstance() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY as string });
  }

  private static async optimizeImage(base64: string, maxDim: number = 1024): Promise<string> {
    return new Promise((resolve) => {
      const img = new Image();
      img.onload = () => {
        let width = img.width;
        let height = img.height;
        if (width > maxDim || height > maxDim) {
          const ratio = width > height ? maxDim / width : maxDim / height;
          width *= ratio;
          height *= ratio;
        }
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.imageSmoothingEnabled = true;
          ctx.imageSmoothingQuality = 'high';
          ctx.drawImage(img, 0, 0, width, height);
        }
        resolve(canvas.toDataURL('image/jpeg', 0.8));
      };
      img.src = base64;
    });
  }

  private static getBackgroundDescription(style: BackgroundStyle): string {
    switch(style) {
      case 'magenta': return 'Solid #FF00FF (Chroma Magenta).';
      case 'white': return 'Solid #FFFFFF pure white.';
      case 'gray': return 'Solid #808080 neutral gray.';
      case 'gradient': return 'Neutral studio gradient.';
      default: return 'Solid flat color.';
    }
  }

  static async generateEvolution(
    baseCharacter: string,
    parentSprite: string | null,
    prompt: string,
    mutationStrength: number,
    config: {
      model: ModelType,
      aspectRatio: AspectRatio,
      outline: OutlineConfig,
      size: ImageSize,
      protocols: RenderingProtocols,
      neuralChain: NeuralNode[]
    }
  ): Promise<string> {
    const ai = this.getAIInstance();
    const optBase = await this.optimizeImage(baseCharacter);
    const optParent = parentSprite ? await this.optimizeImage(parentSprite) : null;

    // Composición dinámica de instrucciones del sistema basadas en los Nodos Neurales
    const activeInstructions = config.neuralChain
      .filter(node => node.isActive)
      .map(node => `[NODE: ${node.id}]\n${node.instruction}`)
      .join('\n\n');

    const systemInstruction = `YOU ARE THE SPRITEFORGE MODULAR ENGINE.
EXECUTE THE FOLLOWING NEURAL CHAIN SEQUENTIALLY:

${activeInstructions}

RENDER PROTOCOL:
- Background: ${this.getBackgroundDescription(config.protocols.backgroundStyle)}
${config.protocols.strongOutline ? '- Outline: Enable 1px crisp contour.' : ''}
${config.protocols.hd2dStyle ? '- Shading: HD-2D Professional RPG style.' : ''}`;

    const userPrompt = `
[DNA SOURCE]: Use anatomy and style from Reference A.
[EVOLUTION GOAL]: ${prompt}
[OUTFIT DRIFT]: ${mutationStrength}% modification from source.
[STATE]: ${optParent ? 'Evolve from Reference B.' : 'Fresh synthesize on Reference A.'}
`;

    try {
      const parts: any[] = [
        { inlineData: { data: optBase.split(',')[1], mimeType: 'image/jpeg' } },
        { text: "REFERENCE A: CANONICAL CHARACTER DNA" }
      ];

      if (optParent) {
        parts.push({ inlineData: { data: optParent.split(',')[1], mimeType: 'image/jpeg' } });
        parts.push({ text: "REFERENCE B: CURRENT OUTFIT STATE" });
      }

      parts.push({ text: userPrompt });

      const response: GenerateContentResponse = await ai.models.generateContent({
        model: config.model,
        contents: { parts },
        config: {
          systemInstruction,
          imageConfig: {
            aspectRatio: config.aspectRatio,
            ...(config.model === 'gemini-3-pro-image-preview' && { imageSize: config.size })
          }
        }
      });

      const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (imagePart?.inlineData) {
        return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
      }
      throw new Error("Neural chain synthesis failed to produce a valid sprite.");
    } catch (e: any) {
      console.error("[SpriteForge Forge Failure]", e);
      throw e;
    }
  }
}

import React, { useState, useEffect, useReducer } from 'react';
import { GeneratedOutfit, AppState } from './types';
import { GeminiService } from './services/geminiService';
import { StorageService } from './services/storageService';
import { ImageProcessor } from './services/imageProcessor';
import { INITIAL_NEURAL_CHAIN } from './constants';
import MainEditor from './components/MainEditor.tsx';
import ResultGallery from './components/ResultGallery.tsx';
import Sidebar from './components/Sidebar.tsx';

type Action = 
  | { type: 'ADD_OUTFIT'; payload: GeneratedOutfit }
  | { type: 'REMOVE_OUTFIT'; payload: string }
  | { type: 'SET_PARENT'; payload: GeneratedOutfit | null }
  | { type: 'SET_BASE'; payload: string | null }
  | { type: 'SET_GENERATING'; payload: boolean }
  | { type: 'SET_ERROR'; payload: string | null }
  | { type: 'UPDATE_CONFIG'; payload: Partial<AppState> }
  | { type: 'SET_OUTFITS'; payload: GeneratedOutfit[] }
  | { type: 'TOGGLE_NODE'; payload: string };

function appReducer(state: AppState, action: Action): AppState {
  switch (action.type) {
    case 'ADD_OUTFIT': return { ...state, outfits: [action.payload, ...state.outfits] };
    case 'REMOVE_OUTFIT': return { ...state, outfits: state.outfits.filter(o => o.id !== action.payload) };
    case 'SET_PARENT': return { ...state, activeEvolutionParent: action.payload };
    case 'SET_BASE': return { ...state, baseImage: action.payload };
    case 'SET_GENERATING': return { ...state, isGenerating: action.payload };
    case 'SET_ERROR': return { ...state, error: action.payload };
    case 'UPDATE_CONFIG': return { ...state, ...action.payload };
    case 'SET_OUTFITS': return { ...state, outfits: action.payload };
    case 'TOGGLE_NODE': 
      return { 
        ...state, 
        neuralChain: state.neuralChain.map(node => 
          node.id === action.payload && !node.isLocked ? { ...node, isActive: !node.isActive } : node
        ) 
      };
    default: return state;
  }
}

const App: React.FC = () => {
  const [state, dispatch] = useReducer(appReducer, {
    baseImage: null,
    activeEvolutionParent: null,
    outfits: [],
    isGenerating: false,
    selectedModel: 'gemini-2.5-flash-image',
    selectedSize: '1K',
    selectedAspectRatio: '9:16',
    outline: { enabled: false, color: '#4f46e5', thickness: 'medium', glow: false },
    error: null,
    isCharacterSheetMode: false,
    mutationStrength: 50,
    renderingProtocols: {
      backgroundStyle: 'magenta',
      pixelPerfect: true,
      strongOutline: true,
      hd2dStyle: true
    },
    neuralChain: INITIAL_NEURAL_CHAIN
  });

  const [activeTab, setActiveTab] = useState<'editor' | 'vault'>('editor');
  const [prompt, setPrompt] = useState('');
  const [isConfigOpen, setIsConfigOpen] = useState(false);
  const [needsApiKey, setNeedsApiKey] = useState(false);

  useEffect(() => {
    StorageService.getAllOutfits().then(data => dispatch({ type: 'SET_OUTFITS', payload: data }));
  }, []);

  const handleForge = async () => {
    if (!state.baseImage) {
      dispatch({ type: 'SET_ERROR', payload: "ERROR: Missing DNA Mannequin." });
      return;
    }

    dispatch({ type: 'SET_GENERATING', payload: true });
    dispatch({ type: 'SET_ERROR', payload: null });

    try {
      const url = await GeminiService.generateEvolution(
        state.baseImage,
        state.activeEvolutionParent?.url || null,
        prompt || "Elite warrior armor",
        state.mutationStrength,
        {
          model: state.selectedModel,
          aspectRatio: state.selectedAspectRatio,
          outline: state.outline,
          size: state.selectedSize,
          protocols: state.renderingProtocols,
          neuralChain: state.neuralChain
        }
      );

      const newAsset: GeneratedOutfit = {
        id: crypto.randomUUID(),
        url,
        originalUrl: url,
        parentId: state.activeEvolutionParent?.id,
        prompt,
        timestamp: Date.now(),
        model: state.selectedModel,
        aspectRatio: state.selectedAspectRatio,
        evolutionStep: (state.activeEvolutionParent?.evolutionStep || 0) + 1
      };

      await StorageService.saveOutfit(newAsset);
      dispatch({ type: 'ADD_OUTFIT', payload: newAsset });
      dispatch({ type: 'SET_PARENT', payload: newAsset });
    } catch (e: any) {
      dispatch({ type: 'SET_ERROR', payload: "Synthesis Error: " + e.message });
    } finally {
      dispatch({ type: 'SET_GENERATING', payload: false });
    }
  };

  return (
    <div className="fixed inset-0 flex flex-col bg-[#050505] text-[#e2e8f0] font-sans overflow-hidden">
