export class ImageProcessor {
  /**
   * Procesa la imagen para extraer el canal Alpha con algoritmos de suavizado.
   */
  static async processAlpha(
    sourceUrl: string, 
    threshold: number = 40, 
    feather: number = 5
  ): Promise<string> {
    const img = await this.loadImage(sourceUrl);

    const canvas = document.createElement('canvas');
    canvas.width = img.width;
    canvas.height = img.height;
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) throw new Error("Canvas context failed");

    ctx.drawImage(img, 0, 0);
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const data = imageData.data;

    let rSum = 0, gSum = 0, bSum = 0, count = 0;
    const inset = 2;

    for (let x = inset; x < canvas.width - inset; x += 10) {
      const top = (inset * canvas.width + x) * 4;
      const bottom = ((canvas.height - inset - 1) * canvas.width + x) * 4;
      rSum += data[top] + data[bottom];
      gSum += data[top + 1] + data[bottom + 1];
      bSum += data[top + 2] + data[bottom + 2];
      count += 2;
    }

    const bgR = rSum / count;
    const bgG = gSum / count;
    const bgB = bSum / count;

    for (let i = 0; i < data.length; i += 4) {
      const r = data[i], g = data[i+1], b = data[i+2];
      const dist = Math.sqrt(
        Math.pow(r - bgR, 2) * 0.299 + 
        Math.pow(g - bgG, 2) * 0.587 + 
        Math.pow(b - bgB, 2) * 0.114
      );

      if (dist < threshold) {
        data[i + 3] = 0;
      } else if (dist < threshold + feather) {
        const alpha = ((dist - threshold) / feather);
        data[i + 3] = Math.round(alpha * 255);
        data[i] = Math.min(255, data[i] * 1.05);
        data[i+1] = Math.min(255, data[i+1] * 1.05);
        data[i+2] = Math.min(255, data[i+2] * 1.05);
      }
    }

    ctx.putImageData(imageData, 0, 0);
    return canvas.toDataURL('image/png');
  }

  /**
   * PIXELGUARD™ CORE: Valida si la silueta generada se mantiene dentro de los límites de la base.
   * @returns driftScore (0-100, donde 0 es perfecto y > 5 es drift crítico)
   */
  static async checkSilhouetteDrift(baseUrl: string, genUrl: string): Promise<number> {
    const baseImg = await this.loadImage(baseUrl);
    const genImg = await this.loadImage(genUrl);

    const canvas = document.createElement('canvas');
    canvas.width = 128; // Normalize size for faster comparison
    canvas.height = 128;
    const ctx = canvas.getContext('2d', { willReadFrequently: true })!;

    // Extract Base Mask
    ctx.clearRect(0, 0, 128, 128);
    ctx.drawImage(baseImg, 0, 0, 128, 128);
    const baseData = ctx.getImageData(0, 0, 128, 128).data;
    const baseMask = new Uint8Array(128 * 128);
    for (let i = 0; i < baseData.length; i += 4) {
      // Si el pixel no es el fondo predominante (asumimos chroma o blanco/negro base)
      // Para simplificar, detectamos si es lo suficientemente diferente al color de la esquina sup-izq
      const r = baseData[i], g = baseData[i+1], b = baseData[i+2];
      const isBg = (r > 240 && g < 20 && b > 240) || (r > 240 && g > 240 && b > 240); // Magenta o Blanco
      baseMask[i/4] = isBg ? 0 : 1;
    }

    // Extract Gen Mask
    ctx.clearRect(0, 0, 128, 128);
    ctx.drawImage(genImg, 0, 0, 128, 128);
    const genData = ctx.getImageData(0, 0, 128, 128).data;

    let driftPixels = 0;
    let totalSubjectPixels = 0;

    for (let i = 0; i < genData.length; i += 4) {
      const r = genData[i], g = genData[i+1], b = genData[i+2];
      const isBg = (r > 240 && g < 20 && b > 240) || (r > 240 && g > 240 && b > 240);
      const isSubject = !isBg;

      if (isSubject) {
        totalSubjectPixels++;
        // Si el pixel generado es sujeto pero la base es fondo -> DRIFT!
        if (baseMask[i/4] === 0) {
          driftPixels++;
        }
      }
    }

    return (driftPixels / totalSubjectPixels) * 100;
  }

  private static loadImage(url: string): Promise<HTMLImageElement> {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.src = url;
      img.onload = () => resolve(img);
      img.onerror = reject;
    });
  }
}

import React, { useState, useEffect, useReducer } from 'react';
import { GeneratedOutfit, AppState } from './types';
import { GeminiService } from './services/geminiService';
import { StorageService } from './services/storageService';
import { ImageProcessor } from './services/imageProcessor';
import { INITIAL_NEURAL_CHAIN } from './constants';
import MainEditor from './components/MainEditor.tsx';
import ResultGallery from './components/ResultGallery.tsx';
import Sidebar from './components/Sidebar.tsx';

type Action = 
  | { type: 'ADD_OUTFIT'; payload: GeneratedOutfit }
  | { type: 'REMOVE_OUTFIT'; payload: string }
  | { type: 'SET_PARENT'; payload: GeneratedOutfit | null }
  | { type: 'SET_BASE'; payload: string | null }
  | { type: 'SET_GENERATING'; payload: boolean }
  | { type: 'SET_ERROR'; payload: string | null }
  | { type: 'UPDATE_CONFIG'; payload: Partial<AppState> }
  | { type: 'SET_OUTFITS'; payload: GeneratedOutfit[] }
  | { type: 'TOGGLE_NODE'; payload: string };

function appReducer(state: AppState, action: Action): AppState {
  switch (action.type) {
    case 'ADD_OUTFIT': return { ...state, outfits: [action.payload, ...state.outfits] };
    case 'REMOVE_OUTFIT': return { ...state, outfits: state.outfits.filter(o => o.id !== action.payload) };
    case 'SET_PARENT': return { ...state, activeEvolutionParent: action.payload };
    case 'SET_BASE': return { ...state, baseImage: action.payload };
    case 'SET_GENERATING': return { ...state, isGenerating: action.payload };
    case 'SET_ERROR': return { ...state, error: action.payload };
    case 'UPDATE_CONFIG': return { ...state, ...action.payload };
    case 'SET_OUTFITS': return { ...state, outfits: action.payload };
    case 'TOGGLE_NODE': 
      return { 
        ...state, 
        neuralChain: state.neuralChain.map(node => 
          node.id === action.payload && !node.isLocked ? { ...node, isActive: !node.isActive } : node
        ) 
      };
    default: return state;
  }
}

const App: React.FC = () => {
  const [state, dispatch] = useReducer(appReducer, {
    baseImage: null,
    activeEvolutionParent: null,
    outfits: [],
    isGenerating: false,
    selectedModel: 'gemini-2.5-flash-image',
    selectedSize: '1K',
    selectedAspectRatio: '9:16',
    outline: { enabled: false, color: '#4f46e5', thickness: 'medium', glow: false },
    error: null,
    isCharacterSheetMode: false,
    mutationStrength: 50,
    renderingProtocols: {
      backgroundStyle: 'magenta',
      pixelPerfect: true,
      strongOutline: true,
      hd2dStyle: true
    },
    neuralChain: INITIAL_NEURAL_CHAIN
  });

  const [activeTab, setActiveTab] = useState<'editor' | 'vault'>('editor');
  const [prompt, setPrompt] = useState('');
  const [isConfigOpen, setIsConfigOpen] = useState(false);
  const [forgeStatus, setForgeStatus] = useState<string>('');

  useEffect(() => {
    StorageService.getAllOutfits().then(data => dispatch({ type: 'SET_OUTFITS', payload: data }));
  }, []);

  const handleForge = async () => {
    if (!state.baseImage) {
      dispatch({ type: 'SET_ERROR', payload: "ERROR: Missing DNA Mannequin." });
      return;
    }

    dispatch({ type: 'SET_GENERATING', payload: true });
    dispatch({ type: 'SET_ERROR', payload: null });

    const isAutoReforgeActive = state.neuralChain.find(n => n.id === 'auto-reforge')?.isActive;
    const maxRetries = isAutoReforgeActive ? 3 : 1;
    let attempt = 0;
    let success = false;

    while (attempt < maxRetries && !success) {
      attempt++;
      setForgeStatus(attempt > 1 ? `AUTO-REFORGE ATTEMPT ${attempt}/3...` : 'SYNTHESIZING...');

      try {
        const url = await GeminiService.generateEvolution(
          state.baseImage,
          state.activeEvolutionParent?.url || null,
          prompt || "Elite warrior armor",
          state.mutationStrength,
          {
            model: state.selectedModel,
            aspectRatio: state.selectedAspectRatio,
            outline: state.outline,
            size: state.selectedSize,
            protocols: state.renderingProtocols,
            neuralChain: state.neuralChain
          }
        );

        // PIXELGUARD VALIDATION
        setForgeStatus('PIXELGUARD™ SCANNING...');
        const drift = await ImageProcessor.checkSilhouetteDrift(state.baseImage, url);

        const DRIFT_THRESHOLD = 6.5; // Tolerancia de píxeles (6.5% de desviación permitida)

        if (drift > DRIFT_THRESHOLD) {
          console.warn(`[PixelGuard] Drift detected: ${drift.toFixed(2)}%.`);
          if (attempt < maxRetries) {
            setForgeStatus(`DRIFT DETECTED (${drift.toFixed(1)}%). RETRYING...`);
            continue; 
          } else {
            throw new Error(`PIXELGUARD REJECTED: Silhouette drift too high (${drift.toFixed(1)}%). Try reducing mutation strength.`);
          }
        }

        success = true;
        const newAsset: GeneratedOutfit = {
          id: crypto.randomUUID(),
          url,
          originalUrl: url,
          parentId: state.activeEvolutionParent?.id,
          prompt,
          timestamp: Date.now(),
          model: state.selectedModel,
          aspectRatio: state.selectedAspectRatio,
          evolutionStep: (state.activeEvolutionParent?.evolutionStep || 0) + 1
        };

        await StorageService.saveOutfit(newAsset);
        dispatch({ type: 'ADD_OUTFIT', payload: newAsset });
        dispatch({ type: 'SET_PARENT', payload: newAsset });
      } catch (e: any) {
        if (attempt >= maxRetries) {
          dispatch({ type: 'SET_ERROR', payload: e.message });
          break;
        }
      }
    }

    dispatch({ type: 'SET_GENERATING', payload: false });
    setForgeStatus('');
  };

  return (
    <div className="fixed inset-0 flex flex-col bg-[#050505] text-[#e2e8f0] font-sans overflow-hidden">
      <header className="h-16 px-6 flex items-center justify-between border-b border-white/5 bg-[#050505]/90 backdrop-blur-2xl z-50">
        <div className="flex items-center gap-4">
          <div className="w-9 h-9 bg-indigo-600 rounded-xl flex items-center justify-center shadow-2xl shadow-indigo-600/30 border border-white/10">
            <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 10V3L4 14h7v7l9-11h-7z" />
            </svg>
          </div>
          <h1 className="text-[14px] font-black uppercase tracking-[0.4em] text-white">
            SpriteForge <span className="text-indigo-500">RPG</span>
          </h1>
        </div>
        <button 
          onClick={() => setIsConfigOpen(true)}
          className="p-2.5 bg-white/5 rounded-xl border border-white/10 hover:bg-white/10 transition-all"
        >
          <svg className="w-5 h-5 text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.94-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
          </svg>
        </button>
      </header>

      <main className="flex-1 overflow-hidden relative">
        {activeTab === 'editor' ? (
          <MainEditor 
            baseImage={state.baseImage}
            parentImage={state.activeEvolutionParent?.url || null}
            onUploadBase={(url) => dispatch({ type: 'SET_BASE', payload: url })}
            isGenerating={state.isGenerating}
            forgeStatus={forgeStatus}
            onResetParent={() => dispatch({ type: 'SET_PARENT', payload: null })}
