        )}

        {state.error && (
          <div className="absolute top-6 left-6 right-6 bg-red-600/95 backdrop-blur-xl p-4 rounded-2xl flex items-center justify-between z-[100] border border-red-400/30 animate-in slide-in-from-top-4 duration-500">
