            <button onClick={() => dispatch({ type: 'SET_ERROR', payload: null })} className="p-2 hover:bg-white/10 rounded-lg">✕</button>
          </div>
        )}
      </main>

      <nav className="h-20 bg-[#0a0a0a]/95 backdrop-blur-3xl border-t border-white/5 flex items-center justify-around safe-bottom z-50">
        <button onClick={() => setActiveTab('editor')} className={`flex flex-col items-center gap-1 ${activeTab === 'editor' ? 'text-indigo-400' : 'text-slate-600'}`}>
