  id: string;
  label: string;
  description: string;
  instruction: string;
  isActive: boolean;
  isLocked?: boolean;
}

export interface RenderingProtocols {
  backgroundStyle: BackgroundStyle;
  pixelPerfect: boolean;
  strongOutline: boolean;
  hd2dStyle: boolean;
}

export interface OutlineConfig {
  enabled: boolean;
  color: string;
  thickness: 'thin' | 'medium' | 'bold';
  glow: boolean;
}

export interface GeneratedOutfit {
  id: string;
  url: string;
  originalUrl: string;
  parentId?: string;
  prompt: string;
  timestamp: number;
  model: ModelType;
  aspectRatio: AspectRatio;
  outline?: OutlineConfig;
  evolutionStep: number;
}

export interface AppState {
  baseImage: string | null;
  activeEvolutionParent: GeneratedOutfit | null;
  outfits: GeneratedOutfit[];
  isGenerating: boolean;
  selectedModel: ModelType;
  selectedSize: ImageSize;
  selectedAspectRatio: AspectRatio;
  outline: OutlineConfig;
  error: string | null;
  isCharacterSheetMode: boolean;
  mutationStrength: number;
  renderingProtocols: RenderingProtocols;
  neuralChain: NeuralNode[];
}

