// --- SERVICES ---

class GeminiService {
  static async generateEvolution(baseImage: string, parentImage: string | null, prompt: string, mutationStrength: number, state: AppState): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
    const bgDesc = state.renderingProtocols.backgroundStyle === 'magenta' ? 'Solid #FF00FF' : 'Solid #FFFFFF';
    const systemInstruction = `YOU ARE SPRITEFORGE ENGINE. Evolve character based on input. 
    STYLE: Professional Pixel Art. 
    BACKGROUND: ${bgDesc}. 
    CONSTRAINTS: Stay within the provided silhouette. No artifacts outside the body volume. Return ONLY the image.`;

    const parts: any[] = [
      { inlineData: { data: baseImage.split(',')[1], mimeType: 'image/jpeg' } },
      { text: "REFERENCE A: ORIGINAL CHARACTER DESIGN" }
    ];
    if (parentImage) {
      parts.push({ inlineData: { data: parentImage.split(',')[1], mimeType: 'image/jpeg' } });
      parts.push({ text: "REFERENCE B: PREVIOUS ITERATION" });
    }
    parts.push({ text: `TRANSFORMATION DIRECTIVE: ${prompt}. INTENSITY: ${mutationStrength}%.` });

    const response: GenerateContentResponse = await ai.models.generateContent({
      model: state.selectedModel,
      contents: { parts },
      config: { 
        systemInstruction,
        imageConfig: { aspectRatio: state.selectedAspectRatio }
      },
    });

    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (imagePart?.inlineData) return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
    throw new Error("Neural chain synthesis failed.");
  }
}

class StorageService {
  static async saveOutfit(outfit: GeneratedOutfit) {
    const stored = JSON.parse(localStorage.getItem('outfits_vault_v2') || '[]');
    localStorage.setItem('outfits_vault_v2', JSON.stringify([outfit, ...stored]));
  }
  static getAllOutfits(): GeneratedOutfit[] {
    return JSON.parse(localStorage.getItem('outfits_vault_v2') || '[]');
  }
  static deleteOutfit(id: string) {
    const stored = this.getAllOutfits().filter(o => o.id !== id);
    localStorage.setItem('outfits_vault_v2', JSON.stringify(stored));
  }
}

// --- COMPONENTS ---

const MainEditorInternal: React.FC<{
  state: AppState;
  prompt: string;
  setPrompt: (v: string) => void;
  onUpload: (url: string) => void;
  onGenerate: () => void;
  onResetParent: () => void;
  isGenerating: boolean;
  forgeStatus: string;
}> = ({ state, prompt, setPrompt, onUpload, onGenerate, onResetParent, isGenerating, forgeStatus }) => {
  const fileRef = useRef<HTMLInputElement>(null);
  const [activeTagCat, setActiveTagCat] = useState(QUICK_TAGS[0].category);
  const [showBase, setShowBase] = useState(false);

  const getBg = () => {
    if (state.renderingProtocols.backgroundStyle === 'magenta') return 'bg-[#FF00FF]';
    if (state.renderingProtocols.backgroundStyle === 'white') return 'bg-white';
    return 'bg-[#080808]';
  };

  if (!state.baseImage) {
    return (
      <div className="h-full flex items-center justify-center p-8 bg-[#050505]">
        <div 
          onClick={() => fileRef.current?.click()} 
          className="w-full max-w-sm aspect-square bg-indigo-600/5 border-2 border-dashed border-indigo-500/20 rounded-[3rem] flex flex-col items-center justify-center cursor-pointer hover:bg-indigo-600/10 transition-all group"
        >
