          <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-2">Start with a base mannequin</p>
        </div>
        <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
          const f = e.target.files?.[0];
          if (f) { const r = new FileReader(); r.onload = () => onUpload(r.result as string); r.readAsDataURL(f); }
        }} />
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col overflow-hidden">
      {/* Area de Previsualización */}
      <div className={`flex-1 min-h-0 relative flex items-center justify-center transition-colors duration-500 ${getBg()}`}>
        <div className="relative w-full h-full flex items-center justify-center p-4">
          <img src={state.baseImage} className={`max-h-full max-w-full object-contain ${state.activeEvolutionParent && !showBase ? 'opacity-0' : 'opacity-100'}`} />
          {state.activeEvolutionParent && !showBase && (
            <img src={state.activeEvolutionParent.url} className="absolute max-h-full max-w-full object-contain animate-in fade-in zoom-in-95 duration-500" />
          )}

          <div className="absolute bottom-4 left-0 right-0 flex justify-center gap-3">
            <button 
              onPointerDown={() => setShowBase(true)} 
              onPointerUp={() => setShowBase(false)} 
              onMouseLeave={() => setShowBase(false)}
              className="px-4 py-2.5 bg-black/80 backdrop-blur-xl rounded-xl text-[9px] font-black uppercase tracking-widest text-white border border-white/20 shadow-2xl active:scale-95 transition-transform"
            >
              Reveal DNA Anchor
            </button>
            {state.activeEvolutionParent && (
              <button onClick={onResetParent} className="w-10 h-10 bg-red-500/80 backdrop-blur-xl rounded-xl flex items-center justify-center text-white border border-white/20 shadow-2xl">
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            )}
          </div>
        </div>

        {isGenerating && (
          <div className="absolute inset-0 bg-black/90 backdrop-blur-xl z-50 flex flex-col items-center justify-center">
            <div className="w-12 h-12 border-4 border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin mb-6 shadow-[0_0_20px_rgba(79,70,229,0.4)]" />
            <span className="text-[10px] font-black uppercase tracking-[0.4em] text-white animate-pulse">{forgeStatus || 'Forging Assets...'}</span>
          </div>
        )}
      </div>

      {/* Panel de Control */}
      <div className="bg-[#0a0a0a] border-t border-white/10 p-5 flex flex-col gap-4 max-h-[50%] shrink-0">
        <textarea 
          value={prompt} 
          onChange={(e) => setPrompt(e.target.value)} 
          placeholder="Describe armor, clothing or outfit..." 
          className="w-full bg-black/50 border border-white/10 rounded-xl p-3 text-[13px] text-white min-h-[80px] focus:border-indigo-500 transition-all outline-none resize-none font-medium" 
        />

        <div className="flex flex-col gap-3 overflow-hidden">
          <div className="flex gap-4 overflow-x-auto no-scrollbar border-b border-white/5 pb-2">
            {QUICK_TAGS.map(c => (
              <button 
                key={c.category} 
                onClick={() => setActiveTagCat(c.category)} 
                className={`whitespace-nowrap text-[8px] font-black uppercase tracking-widest pb-1 transition-colors ${activeTagCat === c.category ? 'text-indigo-400 border-b-2 border-indigo-500' : 'text-slate-600'}`}
              >
                {c.category}
              </button>
            ))}
          </div>
          <div className="flex flex-wrap gap-1.5 overflow-y-auto max-h-[80px] no-scrollbar">
            {QUICK_TAGS.find(c => c.category === activeTagCat)?.tags.map(t => (
              <button 
                key={t} 
                onClick={() => setPrompt(prompt ? `${prompt}, ${t}` : t)} 
                className="px-2.5 py-1.5 bg-white/5 border border-white/5 rounded-lg text-[8px] font-bold uppercase text-slate-400 active:bg-indigo-600 active:text-white transition-all"
              >
                + {t}
              </button>
            ))}
          </div>
        </div>

        <button 
          onClick={onGenerate} 
          disabled={isGenerating}
          className="w-full py-4 bg-indigo-600 disabled:bg-slate-800 rounded-2xl font-black text-[11px] uppercase tracking-[0.3em] text-white shadow-xl shadow-indigo-600/20 active:scale-[0.98] transition-all"
        >
          Sintetizar Outfit
        </button>
      </div>

      <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={(e) => {
        const f = e.target.files?.[0];
        if (f) { const r = new FileReader(); r.onload = () => onUpload(r.result as string); r.readAsDataURL(f); }
      }} />
    </div>
  );
};

// --- APP COMPONENT ---

const App: React.FC = () => {
  const [state, dispatch] = useReducer((s: AppState, a: any): AppState => {
    switch(a.type) {
      case 'SET_BASE': return { ...s, baseImage: a.payload };
      case 'SET_PARENT': return { ...s, activeEvolutionParent: a.payload };
      case 'ADD_OUTFIT': return { ...s, outfits: [a.payload, ...s.outfits] };
      case 'SET_GENERATING': return { ...s, isGenerating: a.payload };
      case 'SET_ERROR': return { ...s, error: a.payload };
      case 'TOGGLE_NODE': return { ...s, neuralChain: s.neuralChain.map(n => n.id === a.payload && !n.isLocked ? { ...n, isActive: !n.isActive } : n) };
      case 'UPDATE_BG': return { ...s, renderingProtocols: { ...s.renderingProtocols, backgroundStyle: a.payload } };
      case 'SET_OUTFITS': return { ...s, outfits: a.payload };
      case 'REMOVE_OUTFIT': return { ...s, outfits: s.outfits.filter(o => o.id !== a.payload) };
      default: return s;
    }
  }, {
    baseImage: null, activeEvolutionParent: null, outfits: [], isGenerating: false,
    selectedModel: 'gemini-2.5-flash-image', selectedSize: '1K', selectedAspectRatio: '1:1',
    outline: { enabled: false, color: '#4f46e5', thickness: 'medium', glow: false },
    error: null, isCharacterSheetMode: false, mutationStrength: 50,
    renderingProtocols: { backgroundStyle: 'magenta', pixelPerfect: true, strongOutline: true, hd2dStyle: true },
    neuralChain: INITIAL_NEURAL_CHAIN
  });

  const [activeTab, setActiveTab] = useState<'editor' | 'vault'>('editor');
  const [prompt, setPrompt] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [forgeStatus, setForgeStatus] = useState('');

  useEffect(() => { 
    dispatch({ type: 'SET_OUTFITS', payload: StorageService.getAllOutfits() }); 
  }, []);

  const handleGenerate = async () => {
    if (!state.baseImage) return;
    dispatch({ type: 'SET_GENERATING', payload: true });
    setForgeStatus('NEURAL LINK ESTABLISHED...');
    try {
      const url = await GeminiService.generateEvolution(state.baseImage, state.activeEvolutionParent?.url || null, prompt, state.mutationStrength, state);
      const newOutfit: GeneratedOutfit = {
        id: crypto.randomUUID(), url, originalUrl: url, prompt, timestamp: Date.now(),
        model: state.selectedModel, aspectRatio: state.selectedAspectRatio,
        evolutionStep: (state.activeEvolutionParent?.evolutionStep || 0) + 1
      };
      await StorageService.saveOutfit(newOutfit);
      dispatch({ type: 'ADD_OUTFIT', payload: newOutfit });
      dispatch({ type: 'SET_PARENT', payload: newOutfit });
    } catch (e: any) { 
      dispatch({ type: 'SET_ERROR', payload: e.message || "Synthesis failed." }); 
    }
    finally { 
      dispatch({ type: 'SET_GENERATING', payload: false }); 
      setForgeStatus(''); 
    }
  };

  return (
    <div className="fixed inset-0 flex flex-col bg-[#050505] text-[#f8fafc] font-sans overflow-hidden">
      <header className="h-16 px-6 shrink-0 flex items-center justify-between border-b border-white/5 bg-[#050505]/80 backdrop-blur-xl z-50">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-600/20"><svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg></div>
          <h1 className="text-[12px] font-black uppercase tracking-[0.3em]">SpriteForge <span className="text-indigo-500">RPG</span></h1>
        </div>
        <button onClick={() => setIsSidebarOpen(true)} className="p-2.5 bg-white/5 rounded-xl border border-white/10 active:bg-white/10 transition-colors"><svg className="w-5 h-5 text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.94-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /></svg></button>
      </header>

      <main className="flex-1 overflow-hidden relative">
        {activeTab === 'editor' ? (
          <MainEditorInternal 
            state={state} 
            prompt={prompt} 
            setPrompt={setPrompt} 
            onUpload={(url) => dispatch({ type: 'SET_BASE', payload: url })} 
            onGenerate={handleGenerate} 
            onResetParent={() => dispatch({ type: 'SET_PARENT', payload: null })} 
            isGenerating={state.isGenerating} 
            forgeStatus={forgeStatus} 
          />
        ) : (
          <div className="h-full overflow-y-auto p-6 pb-24 grid grid-cols-2 gap-4 no-scrollbar">
            {state.outfits.map(o => (
              <div 
                key={o.id} 
                onClick={() => { dispatch({ type: 'SET_PARENT', payload: o }); setPrompt(o.prompt); setActiveTab('editor'); }} 
                className="aspect-[3/4] bg-[#0a0a0a] rounded-2xl border border-white/5 p-3 relative group cursor-pointer overflow-hidden hover:border-indigo-500/50 transition-all"
              >
                <div className="absolute inset-0 opacity-[0.03] checker-bg" />
                <img src={o.url} className="w-full h-full object-contain relative z-10" />
                <div className="absolute top-2 left-2 px-1.5 py-0.5 bg-indigo-600 rounded-md text-[7px] font-black text-white">GEN {o.evolutionStep}</div>
                <button 
                  onClick={(e) => { e.stopPropagation(); StorageService.deleteOutfit(o.id); dispatch({ type: 'REMOVE_OUTFIT', payload: o.id }); }} 
                  className="absolute top-2 right-2 w-7 h-7 bg-red-500/80 text-white rounded-lg flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity z-20"
                >
                  ✕
                </button>
              </div>
            ))}
            {state.outfits.length === 0 && (
              <div className="col-span-2 py-20 text-center opacity-30">
                <p className="text-[10px] font-black uppercase tracking-widest">Vault Empty</p>
              </div>
            )}
          </div>
        )}

        {state.error && (
          <div className="absolute top-4 left-4 right-4 bg-red-600 p-4 rounded-xl flex items-center justify-between z-[200] animate-in slide-in-from-top duration-300">
            <span className="text-[10px] font-black uppercase text-white">{state.error}</span>
            <button onClick={() => dispatch({ type: 'SET_ERROR', payload: null })} className="p-2">✕</button>
          </div>
        )}
      </main>

      <nav className="h-20 shrink-0 bg-[#0a0a0a] border-t border-white/10 flex items-center justify-around safe-bottom z-50">
        <button onClick={() => setActiveTab('editor')} className={`flex flex-col items-center gap-1 transition-colors ${activeTab === 'editor' ? 'text-indigo-400' : 'text-slate-600'}`}>
          <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 4a2 2 0 114 0v1a1 1 0 001 1h3a1 1 0 011 1v3a1 1 0 01-1 1h-1a2 2 0 100 4h1a1 1 0 011 1v3a1 1 0 01-1 1h-3a1 1 0 01-1-1v-1a2 2 0 10-4 0v1a1 1 0 01-1 1H7a1 1 0 01-1-1v-3a1 1 0 00-1-1H4a2 2 0 110-4h1a1 1 0 001-1V7a1 1 0 011-1h3a1 1 0 001-1V4z" /></svg>
          <span className="text-[9px] font-black uppercase tracking-widest">Atelier</span>
        </button>
        <button onClick={() => setActiveTab('vault')} className={`flex flex-col items-center gap-1 transition-colors ${activeTab === 'vault' ? 'text-indigo-400' : 'text-slate-600'}`}>
          <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M5 8h14M5 8a2 2 0 110-4h14a2 2 0 110 4M5 8v10a2 2 0 002 2h10a2 2 0 002-2V8m-9 4h4" /></svg>
          <span className="text-[9px] font-black uppercase tracking-widest">Vault</span>
        </button>
      </nav>

      {isSidebarOpen && (
        <div className="fixed inset-0 z-[100] animate-in fade-in duration-300">
          <div className="absolute inset-0 bg-black/90 backdrop-blur-sm" onClick={() => setIsSidebarOpen(false)} />
          <div className="absolute bottom-0 left-0 right-0 bg-[#0a0a0a] rounded-t-[3rem] p-8 max-h-[85vh] overflow-y-auto border-t border-white/10 animate-in slide-in-from-bottom duration-500 no-scrollbar">
            <div className="w-12 h-1.5 bg-white/10 rounded-full mx-auto mb-8" />
            <h3 className="text-[14px] font-black uppercase mb-6 text-indigo-400 tracking-[0.2em]">Environment Hub</h3>
            <div className="grid grid-cols-3 gap-4 mb-10">
              {['magenta', 'white', 'gray'].map(bg => (
                <button key={bg} onClick={() => dispatch({ type: 'UPDATE_BG', payload: bg })} className={`p-4 rounded-2xl border transition-all ${state.renderingProtocols.backgroundStyle === bg ? 'border-indigo-500 bg-indigo-500/10' : 'border-white/5 bg-white/5'}`}>
                  <div className={`w-full aspect-square rounded-xl mb-3 border border-white/10 ${bg === 'magenta' ? 'bg-[#FF00FF]' : bg === 'white' ? 'bg-white' : 'bg-gray-500'}`} />
                  <span className="text-[9px] font-black uppercase tracking-widest text-white">{bg}</span>
                </button>
              ))}
            </div>
            <h3 className="text-[14px] font-black uppercase mb-6 text-indigo-400 tracking-[0.2em]">Neural Chain Nodes</h3>
            <div className="space-y-3">
              {state.neuralChain.map(node => (
                <button key={node.id} disabled={node.isLocked} onClick={() => dispatch({ type: 'TOGGLE_NODE', payload: node.id })} className={`w-full flex items-center justify-between p-5 rounded-2xl border transition-all ${node.isActive ? 'bg-indigo-600/10 border-indigo-500/40 text-white' : 'bg-white/5 border-transparent text-slate-500'}`}>
                  <div className="text-left">
                    <p className="text-[10px] font-black uppercase tracking-widest">{node.label}</p>
                    <p className="text-[8px] font-bold text-slate-500 uppercase mt-1">{node.description}</p>
                  </div>
                  {node.isActive && <div className="w-2.5 h-2.5 bg-indigo-500 rounded-full shadow-[0_0_12px_#6366f1]" />}
                </button>
              ))}
            </div>
            <div className="h-10" />
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export type ImageSize = '1K' | '2K' | '4K';
export type ModelType = 'gemini-2.5-flash-image' | 'gemini-3-pro-image-preview';
export type AspectRatio = '1:1' | '3:4' | '4:3' | '9:16' | '16:9';
export type BackgroundStyle = 'magenta' | 'white' | 'gray' | 'gradient';

export interface NeuralNode {
  id: string;
  label: string;
  description: string;
  instruction: string;
  isActive: boolean;
  isLocked?: boolean;
}

export interface RenderingProtocols {
  backgroundStyle: BackgroundStyle;
  pixelPerfect: boolean;
  strongOutline: boolean;
  hd2dStyle: boolean;
}

export interface OutlineConfig {
  enabled: boolean;
  color: string;
  thickness: 'thin' | 'medium' | 'bold';
  glow: boolean;
}

export interface GeneratedOutfit {
  id: string;
  url: string;
  originalUrl: string;
  parentId?: string;
  prompt: string;
  timestamp: number;
  model: ModelType;
  aspectRatio: AspectRatio;
  evolutionStep: number;
}

export interface ForgeConfig {
  model: ModelType;
  size: ImageSize;
  aspectRatio: AspectRatio;
  mutationStrength: number;
  protocols: RenderingProtocols;
  neuralChain: NeuralNode[];
}

export interface AppState {
  baseImage: string | null;
  activeParent: GeneratedOutfit | null;
  outfits: GeneratedOutfit[];
  isGenerating: boolean;
  config: ForgeConfig;
  error: string | null;
}

import { NeuralNode, ForgeConfig } from './types';

export const INITIAL_NEURAL_CHAIN: NeuralNode[] = [
  { id: 'engine-core', label: 'CORE ENGINE', description: 'Main evolution logic.', instruction: 'ROLE: SpriteForge RPG Engine. Evolve pixel-art. Maintain style.', isActive: true, isLocked: true },
  { id: 'identity-anchor', label: 'IDENTITY ANCHOR', description: 'Locks anatomy.', instruction: 'Keep facial features and body proportions identical to Reference A.', isActive: true },
  { id: 'silhouette-lock', label: 'SILHOUETTE LOCK', description: 'Stay in bounds.', instruction: 'Generated output must strictly occupy Reference A silhouette area.', isActive: true },
  { id: 'auto-reforge', label: 'AUTO REFORGE', description: 'Auto retry on drift.', instruction: 'If pixel drift detected, prioritize silhouette over detail.', isActive: true }
];

export const DEFAULT_CONFIG: ForgeConfig = {
  model: 'gemini-2.5-flash-image',
  size: '1K',
  aspectRatio: '1:1',
  mutationStrength: 50,
  protocols: {
    backgroundStyle: 'magenta',
    pixelPerfect: true,
    strongOutline: true,
    hd2dStyle: true
  },
  neuralChain: INITIAL_NEURAL_CHAIN
};

export const QUICK_TAGS = [
  { category: "Class Archetype", tags: ["Paladin", "Rogue", "Mage", "Cleric", "Berserker", "Artificer"] },
  { category: "Equipment Slot", tags: ["Full Plate Armor", "Leather Cloak", "Steel Greaves", "Silk Robes", "Chainmail"] },
  { category: "Visual Flavor", tags: ["Glowing Runes", "Battle Damaged", "Royal Gold", "Demonic Shadow", "Nature Infused"] }
];

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ForgeConfig } from "../types";

export class GeminiService {
  /**
   * Generates a new sprite evolution using Gemini Vision capabilities.
   */
  static async synthesizeEvolution(
    baseImage: string, 
    parentUrl: string | null, 
    prompt: string, 
    config: ForgeConfig
  ): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    // Build granular system instructions from active nodes
    const activeInstructions = config.neuralChain
      .filter(n => n.isActive)
      .map(n => `[NODE: ${n.id}] ${n.instruction}`)
      .join('\n');

    const systemInstruction = `
      YOU ARE THE SPRITEFORGE AI ENGINE.
      TASKS:
      1. Analyze Reference A (Base DNA).
      2. Analyze Reference B (Current iteration, if provided).
      3. Apply Evolution Goal: ${prompt}.
      4. Background: ${config.protocols.backgroundStyle === 'magenta' ? 'Solid #FF00FF' : 'Solid #FFFFFF'}.

      CONSTRAINTS:
      ${activeInstructions}

      OUTPUT: Return ONLY the raw image of the evolved character.
    `;

    const contents = {
      parts: [
        { inlineData: { data: baseImage.split(',')[1], mimeType: 'image/jpeg' } },
        { text: "REFERENCE A: CANONICAL BASE DNA" }
      ]
    };

    if (parentUrl) {
      contents.parts.push({ inlineData: { data: parentUrl.split(',')[1], mimeType: 'image/jpeg' } } as any);
      contents.parts.push({ text: "REFERENCE B: PREVIOUS EVOLUTION STEP" } as any);
    }

    contents.parts.push({ text: `EVOLUTION GOAL: ${prompt}. INTENSITY: ${config.mutationStrength}%` } as any);

    const response: GenerateContentResponse = await ai.models.generateContent({
      model: config.model,
      contents,
      config: { 
        systemInstruction,
        imageConfig: { 
          aspectRatio: config.aspectRatio,
          ...(config.model === 'gemini-3-pro-image-preview' && { imageSize: config.size })
        }
      },
    });

    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (imagePart?.inlineData) {
      return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
    }

    throw new Error("Neural synthesis failed to materialize the asset.");
  }
}

import React, { useState, useEffect, useReducer, useRef, useCallback, useMemo } from 'react';
import { GeneratedOutfit, AppState, ForgeConfig } from './types';
import { GeminiService } from './services/geminiService';
import { StorageService } from './services/storageService';
import { DEFAULT_CONFIG, QUICK_TAGS } from './constants';

/**
 * UTILS: Atoms for the UI to keep components small and readable.
 */
const IconButton = ({ children, onClick, active = false, danger = false }: any) => (
  <button 
    onClick={onClick}
    className={`w-10 h-10 flex items-center justify-center rounded-xl border transition-all active:scale-90 ${
      active ? 'bg-indigo-600 border-indigo-400 text-white shadow-lg shadow-indigo-600/30' : 
      danger ? 'bg-red-500/10 border-red-500/20 text-red-400' :
      'bg-white/5 border-white/10 text-slate-400 hover:bg-white/10'
    }`}
  >
    {children}
  </button>
);

const TagButton = ({ label, onClick }: any) => (
  <button 
    onClick={onClick}
    className="px-3 py-1.5 bg-white/5 border border-white/5 rounded-lg text-[10px] font-bold uppercase tracking-widest text-slate-400 hover:bg-indigo-600 hover:text-white hover:border-indigo-400 transition-all"
  >
    + {label}
  </button>
);

/**
 * MAIN ATELIER: The character workshop.
 */
const Atelier: React.FC<{
  state: AppState;
  prompt: string;
  setPrompt: (v: string) => void;
  onUpload: (url: string) => void;
  onForge: () => void;
  onResetParent: () => void;
}> = ({ state, prompt, setPrompt, onUpload, onForge, onResetParent }) => {
  const [activeCat, setActiveCat] = useState(QUICK_TAGS[0].category);
  const [showBase, setShowBase] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const bgClass = useMemo(() => {
    switch(state.config.protocols.backgroundStyle) {
      case 'magenta': return 'bg-[#FF00FF]';
      case 'white': return 'bg-white';
      default: return 'bg-[#0a0a0a]';
    }
  }, [state.config.protocols.backgroundStyle]);

  if (!state.baseImage) {
    return (
      <div className="h-full flex items-center justify-center p-8">
        <div 
          onClick={() => fileInputRef.current?.click()}
          className="w-full max-w-sm aspect-square border-2 border-dashed border-indigo-500/20 rounded-[3rem] bg-indigo-500/5 flex flex-col items-center justify-center cursor-pointer hover:bg-indigo-500/10 transition-all group"
        >
          <div className="w-20 h-20 bg-indigo-600 rounded-3xl flex items-center justify-center mb-6 shadow-2xl group-hover:scale-110 transition-transform">
            <svg className="w-8 h-8 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg>
          </div>
          <span className="text-[14px] font-black uppercase tracking-[0.4em] text-white">Import Base DNA</span>
          <p className="text-[9px] font-bold text-slate-500 uppercase tracking-widest mt-2">Upload a character mannequin</p>
          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => {
            const f = e.target.files?.[0];
            if (f) { const r = new FileReader(); r.onload = () => onUpload(r.result as string); r.readAsDataURL(f); }
          }} />
        </div>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col overflow-hidden animate-in fade-in duration-700">
      {/* Canvas Area */}
      <div className={`flex-1 relative flex items-center justify-center transition-colors duration-500 ${bgClass} min-h-0`}>
        <div className="relative w-full h-full flex items-center justify-center p-8">
          <img src={state.baseImage} className={`max-h-full max-w-full object-contain ${state.activeParent && !showBase ? 'opacity-0' : 'opacity-100'}`} alt="Base" />
          {state.activeParent && !showBase && (
            <img src={state.activeParent.url} className="absolute max-h-full max-w-full object-contain animate-in zoom-in-95 fade-in duration-500" alt="Synthesized" />
          )}

          <div className="absolute bottom-6 flex gap-3">
            <button 
              onPointerDown={() => setShowBase(true)} onPointerUp={() => setShowBase(false)} onMouseLeave={() => setShowBase(false)}
              className="px-6 py-3 bg-black/80 backdrop-blur-xl rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] text-white border border-white/20 shadow-2xl active:scale-95 transition-all"
            >
              Reveal Original
            </button>
            {state.activeParent && <IconButton danger onClick={onResetParent}><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg></IconButton>}
          </div>
        </div>

        {state.isGenerating && (
          <div className="absolute inset-0 bg-black/90 backdrop-blur-xl z-[100] flex flex-col items-center justify-center">
            <div className="w-16 h-16 border-4 border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin mb-6" />
            <span className="text-[11px] font-black uppercase tracking-[0.5em] text-white animate-pulse">Synthesis in Progress...</span>
          </div>
        )}
      </div>

      {/* Control Panel */}
      <div className="bg-[#0a0a0a] border-t border-white/10 p-6 flex flex-col gap-6 shrink-0 shadow-[0_-20px_50px_rgba(0,0,0,0.5)]">
        <textarea 
          value={prompt} onChange={(e) => setPrompt(e.target.value)}
          placeholder="Describe the armor or outfit to forge..."
          className="w-full bg-black/50 border border-white/10 rounded-2xl p-4 text-[13px] text-white focus:border-indigo-500 transition-all outline-none h-24 resize-none font-medium"
        />

        <div className="flex flex-col gap-4 overflow-hidden">
          <div className="flex gap-4 overflow-x-auto no-scrollbar border-b border-white/5 pb-2">
            {QUICK_TAGS.map(c => (
              <button 
                key={c.category} onClick={() => setActiveCat(c.category)}
                className={`whitespace-nowrap text-[9px] font-black uppercase tracking-widest pb-1 transition-colors ${activeCat === c.category ? 'text-indigo-400 border-b-2 border-indigo-500' : 'text-slate-600'}`}
              >
                {c.category}
              </button>
            ))}
          </div>
          <div className="flex flex-wrap gap-2 overflow-y-auto max-h-24 no-scrollbar">
            {QUICK_TAGS.find(c => c.category === activeCat)?.tags.map(t => (
              <TagButton key={t} label={t} onClick={() => setPrompt(prompt ? `${prompt}, ${t}` : t)} />
            ))}
          </div>
        </div>

        <button 
          onClick={onForge} disabled={state.isGenerating}
          className="w-full py-5 bg-indigo-600 disabled:bg-slate-800 rounded-2xl font-black text-[12px] uppercase tracking-[0.4em] text-white shadow-xl shadow-indigo-600/30 active:scale-[0.98] transition-all border border-indigo-400/20"
        >
          {state.isGenerating ? 'Synthesizing...' : 'Execute Synthesis'}
        </button>
      </div>
    </div>
  );
};

/**
 * VAULT: Archive of generated assets.
 */
const Vault: React.FC<{
  outfits: GeneratedOutfit[];
  activeId?: string;
  onSelect: (o: GeneratedOutfit) => void;
  onDelete: (id: string) => void;
}> = ({ outfits, activeId, onSelect, onDelete }) => (
  <div className="h-full overflow-y-auto p-6 pb-24 grid grid-cols-2 gap-4 no-scrollbar animate-in slide-in-from-bottom-4 duration-500">
    {outfits.map(o => (
      <div 
        key={o.id} 
        onClick={() => onSelect(o)}
        className={`aspect-[3/4] bg-[#0a0a0a] rounded-3xl border p-4 relative group cursor-pointer overflow-hidden transition-all ${
          activeId === o.id ? 'border-indigo-500 ring-4 ring-indigo-500/10' : 'border-white/5 hover:border-white/20'
        }`}
      >
        <div className="absolute inset-0 opacity-[0.03] checker-bg" />
        <img src={o.url} className="w-full h-full object-contain relative z-10 transition-transform group-hover:scale-110 duration-500" alt="Archive" />
        <div className="absolute top-3 left-3 px-2 py-0.5 bg-black/80 rounded-full text-[8px] font-black text-indigo-400 border border-white/5 z-20">STEP {o.evolutionStep}</div>
        <button 
          onClick={(e) => { e.stopPropagation(); onDelete(o.id); }}
          className="absolute top-3 right-3 w-8 h-8 bg-red-500/80 text-white rounded-xl flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity z-30 shadow-xl"
        >
          <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
        </button>
      </div>
    ))}
    {outfits.length === 0 && (
      <div className="col-span-2 py-32 text-center">
        <div className="w-16 h-16 bg-white/5 rounded-full flex items-center justify-center mx-auto mb-4 border border-white/5">
          <svg className="w-8 h-8 text-slate-700" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" /></svg>
        </div>
        <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-600">Archive Offline</p>
      </div>
    )}
  </div>
);

/**
 * MAIN APP CONTAINER
 */
const App: React.FC = () => {
  const [state, dispatch] = useReducer((s: AppState, a: any): AppState => {
    switch(a.type) {
      case 'SET_BASE': return { ...s, baseImage: a.payload };
      case 'SET_PARENT': return { ...s, activeParent: a.payload };
      case 'ADD_OUTFIT': return { ...s, outfits: [a.payload, ...s.outfits] };
      case 'SET_OUTFITS': return { ...s, outfits: a.payload };
      case 'REMOVE_OUTFIT': return { ...s, outfits: s.outfits.filter(o => o.id !== a.payload) };
      case 'SET_GENERATING': return { ...s, isGenerating: a.payload };
      case 'SET_ERROR': return { ...s, error: a.payload };
      case 'UPDATE_BG': return { ...s, config: { ...s.config, protocols: { ...s.config.protocols, backgroundStyle: a.payload } } };
      case 'TOGGLE_NODE': return { ...s, config: { ...s.config, neuralChain: s.config.neuralChain.map(n => n.id === a.payload && !n.isLocked ? { ...n, isActive: !n.isActive } : n) } };
      default: return s;
    }
  }, {
    baseImage: null, activeParent: null, outfits: [], isGenerating: false,
    config: DEFAULT_CONFIG, error: null
  });

  const [activeTab, setActiveTab] = useState<'editor' | 'vault'>('editor');
  const [prompt, setPrompt] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => { 
    StorageService.getAllOutfits().then(data => dispatch({ type: 'SET_OUTFITS', payload: data }));
  }, []);

  const handleForge = useCallback(async () => {
    if (!state.baseImage) return;
    dispatch({ type: 'SET_GENERATING', payload: true });
    dispatch({ type: 'SET_ERROR', payload: null });

    try {
      const url = await GeminiService.synthesizeEvolution(state.baseImage, state.activeParent?.url || null, prompt, state.config);
      const newOutfit: GeneratedOutfit = {
        id: crypto.randomUUID(), url, originalUrl: url, prompt, timestamp: Date.now(),
        model: state.config.model, aspectRatio: state.config.aspectRatio,
        evolutionStep: (state.activeParent?.evolutionStep || 0) + 1
      };
      await StorageService.saveOutfit(newOutfit);
      dispatch({ type: 'ADD_OUTFIT', payload: newOutfit });
      dispatch({ type: 'SET_PARENT', payload: newOutfit });
    } catch (e: any) {
      dispatch({ type: 'SET_ERROR', payload: e.message });
    } finally {
      dispatch({ type: 'SET_GENERATING', payload: false });
    }
  }, [state, prompt]);

  return (
    <div className="fixed inset-0 flex flex-col bg-[#050505] text-[#f8fafc] font-sans overflow-hidden">
      {/* Navbar */}
      <header className="h-16 px-6 flex items-center justify-between border-b border-white/5 bg-[#050505]/80 backdrop-blur-xl z-[200]">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-600/30">
            <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
          </div>
          <h1 className="text-[12px] font-black uppercase tracking-[0.4em]">SpriteForge <span className="text-indigo-500">X</span></h1>
        </div>
        <IconButton onClick={() => setIsSidebarOpen(true)}>
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.94-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /></svg>
        </IconButton>
      </header>

      {/* Main Viewport */}
      <main className="flex-1 relative overflow-hidden">
        {activeTab === 'editor' ? (
          <Atelier 
            state={state} prompt={prompt} setPrompt={setPrompt}
            onUpload={(url) => dispatch({ type: 'SET_BASE', payload: url })}
            onForge={handleForge} onResetParent={() => dispatch({ type: 'SET_PARENT', payload: null })}
          />
        ) : (
          <Vault 
            outfits={state.outfits} activeId={state.activeParent?.id}
            onSelect={(o) => { dispatch({ type: 'SET_PARENT', payload: o }); setPrompt(o.prompt); setActiveTab('editor'); }}
            onDelete={(id) => { StorageService.deleteOutfit(id); dispatch({ type: 'REMOVE_OUTFIT', payload: id }); }}
          />
        )}

        {state.error && (
          <div className="absolute top-4 left-4 right-4 bg-red-600 p-4 rounded-2xl flex items-center justify-between z-[300] animate-in slide-in-from-top-4 duration-300 shadow-2xl">
            <span className="text-[10px] font-black uppercase text-white">{state.error}</span>
            <button onClick={() => dispatch({ type: 'SET_ERROR', payload: null })} className="p-2 bg-black/20 rounded-lg">✕</button>
          </div>
        )}
      </main>

      {/* Tab Bar */}
      <nav className="h-20 shrink-0 bg-[#0a0a0a] border-t border-white/5 flex items-center justify-around safe-bottom z-[200]">
        <button onClick={() => setActiveTab('editor')} className={`flex flex-col items-center gap-1 transition-colors ${activeTab === 'editor' ? 'text-indigo-400' : 'text-slate-600'}`}>
          <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 4a2 2 0 114 0v1a1 1 0 001 1h3a1 1 0 011 1v3a1 1 0 01-1 1h-1a2 2 0 100 4h1a1 1 0 011 1v3a1 1 0 01-1 1h-3a1 1 0 01-1-1v-1a2 2 0 10-4 0v1a1 1 0 01-1 1H7a1 1 0 01-1-1v-3a1 1 0 00-1-1H4a2 2 0 110-4h1a1 1 0 001-1V7a1 1 0 011-1h3a1 1 0 001-1V4z" /></svg>
          <span className="text-[9px] font-black uppercase tracking-widest">Atelier</span>
        </button>
        <button onClick={() => setActiveTab('vault')} className={`flex flex-col items-center gap-1 transition-colors ${activeTab === 'vault' ? 'text-indigo-400' : 'text-slate-600'}`}>
          <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M5 8h14M5 8a2 2 0 110-4h14a2 2 0 110 4M5 8v10a2 2 0 002 2h10a2 2 0 002-2V8m-9 4h4" /></svg>
          <span className="text-[9px] font-black uppercase tracking-widest">Vault</span>
        </button>
      </nav>

      {/* Sidebar Overlay */}
      {isSidebarOpen && (
        <div className="fixed inset-0 z-[500] animate-in fade-in duration-300">
          <div className="absolute inset-0 bg-black/90 backdrop-blur-sm" onClick={() => setIsSidebarOpen(false)} />
          <div className="absolute bottom-0 left-0 right-0 bg-[#0a0a0a] rounded-t-[3rem] p-8 border-t border-white/10 animate-in slide-in-from-bottom duration-500 max-h-[85vh] overflow-y-auto no-scrollbar">
            <div className="w-12 h-1.5 bg-white/10 rounded-full mx-auto mb-8" />

            <section className="mb-10">
              <h3 className="text-[12px] font-black uppercase tracking-[0.3em] text-indigo-400 mb-6">Synthesis Environment</h3>
              <div className="grid grid-cols-3 gap-4">
                {['magenta', 'white', 'gray'].map(bg => (
                  <button key={bg} onClick={() => dispatch({ type: 'UPDATE_BG', payload: bg })} className={`p-4 rounded-[2rem] border transition-all ${state.config.protocols.backgroundStyle === bg ? 'border-indigo-500 bg-indigo-500/10' : 'border-white/5 bg-white/5'}`}>
                    <div className={`w-full aspect-square rounded-2xl mb-3 border border-white/10 ${bg === 'magenta' ? 'bg-[#FF00FF]' : bg === 'white' ? 'bg-white' : 'bg-slate-600'}`} />
                    <span className="text-[9px] font-black uppercase tracking-widest text-white">{bg}</span>
                  </button>
                ))}
              </div>
            </section>

            <section>
              <h3 className="text-[12px] font-black uppercase tracking-[0.3em] text-indigo-400 mb-6">Neural Protocol Chain</h3>
              <div className="space-y-3">
                {state.config.neuralChain.map(node => (
                  <button 
                    key={node.id} disabled={node.isLocked}
                    onClick={() => dispatch({ type: 'TOGGLE_NODE', payload: node.id })}
                    className={`w-full flex items-center justify-between p-5 rounded-2xl border transition-all ${
                      node.isActive ? 'bg-indigo-600/10 border-indigo-500/40 text-white' : 'bg-white/5 border-transparent text-slate-500'
                    }`}
                  >
                    <div className="text-left">
                      <p className="text-[10px] font-black uppercase tracking-widest">{node.label}</p>
                      <p className="text-[8px] font-bold opacity-50 uppercase mt-1">{node.description}</p>
                    </div>
                    {node.isActive && <div className="w-2.5 h-2.5 bg-indigo-500 rounded-full shadow-[0_0_15px_#6366f1]" />}
                  </button>
                ))}
              </div>
            </section>

            <div className="h-10" />
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React from 'react';

/**
 * Botón circular o cuadrado con icono, usado para acciones rápidas.
 */
export const IconButton: React.FC<{
  children: React.ReactNode;
  onClick: () => void;
  variant?: 'primary' | 'secondary' | 'danger';
  className?: string;
  disabled?: boolean;
}> = ({ children, onClick, variant = 'primary', className = '', disabled = false }) => {
  const themes = {
    primary: 'bg-white/5 border-white/10 text-slate-400 hover:bg-white/10',
    secondary: 'bg-indigo-600 border-indigo-400 text-white shadow-lg shadow-indigo-600/30',
    danger: 'bg-red-500/10 border-red-500/20 text-red-400 hover:bg-red-500/20'
  };

  return (
    <button 
      onClick={onClick}
      disabled={disabled}
