import { useState, useEffect, useCallback, useReducer } from 'react';
import { AppState, GeneratedOutfit, ForgeConfig } from '../types';
import { GeminiService } from '../services/geminiService';
import { StorageService } from '../services/storageService';
import { DEFAULT_CONFIG } from '../constants';

type ForgeAction = 
  | { type: 'SET_BASE_IMAGE'; payload: string }
  | { type: 'SET_ACTIVE_PARENT'; payload: GeneratedOutfit | null }
  | { type: 'SET_OUTFITS'; payload: GeneratedOutfit[] }
  | { type: 'ADD_OUTFIT'; payload: GeneratedOutfit }
  | { type: 'REMOVE_OUTFIT'; payload: string }
  | { type: 'SET_LOADING'; payload: boolean }
  | { type: 'SET_ERROR'; payload: string | null }
  | { type: 'UPDATE_CONFIG'; payload: Partial<ForgeConfig> };

function forgeReducer(state: AppState, action: ForgeAction): AppState {
  switch (action.type) {
    case 'SET_BASE_IMAGE': return { ...state, baseImage: action.payload, activeParent: null };
    case 'SET_ACTIVE_PARENT': return { ...state, activeParent: action.payload };
    case 'SET_OUTFITS': return { ...state, outfits: action.payload };
    case 'ADD_OUTFIT': return { ...state, outfits: [action.payload, ...state.outfits] };
    case 'REMOVE_OUTFIT': return { ...state, outfits: state.outfits.filter(o => o.id !== action.payload) };
    case 'SET_LOADING': return { ...state, isGenerating: action.payload };
    case 'SET_ERROR': return { ...state, error: action.payload };
    case 'UPDATE_CONFIG': return { ...state, config: { ...state.config, ...action.payload } };
    default: return state;
  }
}

/**
 * Hook central de la aplicación SpriteForge.
 * Maneja el estado, la persistencia y las llamadas a la API.
 */
export function useSpriteForge() {
  const [state, dispatch] = useReducer(forgeReducer, {
    baseImage: null,
    activeParent: null,
    outfits: [],
    isGenerating: false,
    config: DEFAULT_CONFIG,
    error: null
  });

  // Cargar datos iniciales desde IndexedDB
  useEffect(() => {
    StorageService.getAllOutfits().then(data => 
      dispatch({ type: 'SET_OUTFITS', payload: data })
    );
  }, []);

  const uploadBaseDNA = useCallback((url: string) => {
    dispatch({ type: 'SET_BASE_IMAGE', payload: url });
  }, []);

  const deleteAsset = useCallback(async (id: string) => {
    await StorageService.deleteOutfit(id);
    dispatch({ type: 'REMOVE_OUTFIT', payload: id });
  }, []);

  /**
   * Ejecuta la síntesis de una nueva evolución del personaje.
   */
  const executeSynthesis = useCallback(async (prompt: string) => {
    if (!state.baseImage) return;

    dispatch({ type: 'SET_LOADING', payload: true });
    dispatch({ type: 'SET_ERROR', payload: null });

    try {
      const url = await GeminiService.synthesizeEvolution(
        state.baseImage,
        state.activeParent?.url || null,
        prompt,
        state.config
      );

      const newAsset: GeneratedOutfit = {
        id: crypto.randomUUID(),
        url,
        originalUrl: url,
        prompt,
        timestamp: Date.now(),
        model: state.config.model,
        aspectRatio: state.config.aspectRatio,
        evolutionStep: (state.activeParent?.evolutionStep || 0) + 1
      };

      await StorageService.saveOutfit(newAsset);
      dispatch({ type: 'ADD_OUTFIT', payload: newAsset });
      dispatch({ type: 'SET_ACTIVE_PARENT', payload: newAsset });
    } catch (error: any) {
      dispatch({ type: 'SET_ERROR', payload: error.message || 'Error en la síntesis neural.' });
    } finally {
      dispatch({ type: 'SET_LOADING', payload: false });
    }
  }, [state.baseImage, state.activeParent, state.config]);

  return {
    state,
    dispatch,
    uploadBaseDNA,
    executeSynthesis,
    deleteAsset
  };
}

import React, { useState, useRef, useMemo } from 'react';
import { AppState, GeneratedOutfit } from '../types';
import { QUICK_TAGS } from '../constants';
import { IconButton, Tag, Loader } from './UI';

interface AtelierProps {
  state: AppState;
  prompt: string;
  setPrompt: (v: string) => void;
  onUpload: (url: string) => void;
  onForge: () => void;
  onResetParent: () => void;
}

export const Atelier: React.FC<AtelierProps> = ({ 
  state, prompt, setPrompt, onUpload, onForge, onResetParent 
}) => {
  const [activeCategory, setActiveCategory] = useState(QUICK_TAGS[0].category);
  const [isComparing, setIsComparing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const backgroundStyle = useMemo(() => {
    const bg = state.config.protocols.backgroundStyle;
    if (bg === 'magenta') return 'bg-[#FF00FF]';
    if (bg === 'white') return 'bg-white';
    return 'bg-[#0a0a0a]';
  }, [state.config.protocols.backgroundStyle]);

  // Pantalla de carga/estado inicial si no hay imagen base
  if (!state.baseImage) {
    return (
      <div className="h-full flex items-center justify-center p-8 bg-[#050505]">
        <div 
          onClick={() => fileInputRef.current?.click()}
          className="w-full max-w-sm aspect-square border-2 border-dashed border-indigo-500/20 rounded-[3rem] bg-indigo-500/5 flex flex-col items-center justify-center cursor-pointer hover:bg-indigo-500/10 transition-all group"
        >
          <div className="w-20 h-20 bg-indigo-600 rounded-3xl flex items-center justify-center mb-6 shadow-2xl group-hover:scale-110 transition-transform">
            <svg className="w-8 h-8 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg>
          </div>
          <span className="text-[14px] font-black uppercase tracking-[0.4em] text-white">Importar DNA Base</span>
          <p className="text-[9px] font-bold text-slate-500 uppercase tracking-widest mt-2 text-center px-8">Sube el maniquí de tu personaje para empezar</p>
          <input 
            type="file" 
            ref={fileInputRef} 
            className="hidden" 
            accept="image/*" 
            onChange={(e) => {
              const file = e.target.files?.[0];
              if (file) {
                const reader = new FileReader();
                reader.onload = () => onUpload(reader.result as string);
                reader.readAsDataURL(file);
              }
            }} 
          />
        </div>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col overflow-hidden animate-in fade-in duration-700">
      {/* Zona de Visualización (Canvas) */}
      <div className={`flex-1 relative flex items-center justify-center transition-colors duration-500 ${backgroundStyle} min-h-0`}>
        <div className="relative w-full h-full flex items-center justify-center p-8">
          <img 
            src={state.baseImage} 
            className={`max-h-full max-w-full object-contain ${state.activeParent && !isComparing ? 'opacity-0' : 'opacity-100'}`} 
            alt="Base Character" 
          />
          {state.activeParent && !isComparing && (
            <img 
              src={state.activeParent.url} 
              className="absolute max-h-full max-w-full object-contain animate-in zoom-in-95 fade-in duration-500" 
              alt="Synthesized Outfit" 
            />
          )}

          <div className="absolute bottom-6 flex gap-3">
            <button 
              onPointerDown={() => setIsComparing(true)} 
              onPointerUp={() => setIsComparing(false)} 
              onMouseLeave={() => setIsComparing(false)}
              className="px-6 py-3 bg-black/80 backdrop-blur-xl rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] text-white border border-white/20 shadow-2xl active:scale-95 transition-all"
            >
              Comparar con Base
            </button>
            {state.activeParent && (
              <IconButton variant="danger" onClick={onResetParent}>
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </IconButton>
            )}
          </div>
        </div>

        {state.isGenerating && <Loader message="Sintetizando Equipo..." />}
      </div>

      {/* Panel de Control de Síntesis */}
      <div className="bg-[#0a0a0a] border-t border-white/10 p-6 flex flex-col gap-6 shrink-0 shadow-[0_-20px_50px_rgba(0,0,0,0.5)]">
        <div className="relative">
          <textarea 
            value={prompt} 
            onChange={(e) => setPrompt(e.target.value)}
            placeholder="Describe la armadura o atuendo a sintetizar..."
            className="w-full bg-black/50 border border-white/10 rounded-2xl p-4 text-[13px] text-white focus:border-indigo-500 transition-all outline-none h-24 resize-none font-medium placeholder:text-slate-600"
          />
          {prompt && (
            <button onClick={() => setPrompt('')} className="absolute top-4 right-4 text-slate-600 hover:text-white transition-colors">
              <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
          )}
        </div>

        <div className="flex flex-col gap-4 overflow-hidden">
          <div className="flex gap-4 overflow-x-auto no-scrollbar border-b border-white/5 pb-2">
            {QUICK_TAGS.map(cat => (
              <button 
                key={cat.category} 
                onClick={() => setActiveCategory(cat.category)}
