              </button>
            ))}
          </div>
          <div className="flex flex-wrap gap-2 overflow-y-auto max-h-24 no-scrollbar">
            {QUICK_TAGS.find(c => c.category === activeCategory)?.tags.map(tag => (
              <Tag key={tag} label={tag} onClick={() => setPrompt(prompt ? `${prompt}, ${tag}` : tag)} />
            ))}
          </div>
        </div>

        <button 
          onClick={onForge} 
          disabled={state.isGenerating || !prompt}
          className="w-full py-5 bg-indigo-600 disabled:bg-slate-800 disabled:opacity-50 rounded-2xl font-black text-[12px] uppercase tracking-[0.4em] text-white shadow-xl shadow-indigo-600/30 active:scale-[0.98] transition-all border border-indigo-400/20"
        >
          {state.isGenerating ? 'Sintetizando...' : 'Ejecutar Evolución'}
        </button>
      </div>
    </div>
  );
};

