 * Especializado en tareas de visión y generación de imágenes por capas.
 */
export class GeminiService {
  /**
   * Genera una nueva evolución de sprite utilizando las capacidades de visión de Gemini.
   * 
   * @param baseImage - La imagen del maniquí base (Base64).
   * @param parentUrl - La iteración anterior para mantener continuidad (opcional).
   * @param prompt - Descripción textual de los cambios deseados.
   * @param config - Configuración de la red neural y protocolos de renderizado.
   * @returns La URL de la imagen sintetizada en Base64.
   */
  static async synthesizeEvolution(
    baseImage: string, 
    parentUrl: string | null, 
    prompt: string, 
    config: ForgeConfig
  ): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    // Construir instrucciones detalladas basadas en los nodos activos de la cadena neural
    const neuralInstructions = config.neuralChain
      .filter(n => n.isActive)
      .map(n => `[PROTOCOLO ${n.id.toUpperCase()}]: ${n.instruction}`)
      .join('\n');

    const backgroundDescription = config.protocols.backgroundStyle === 'magenta' 
      ? 'Fondo sólido #FF00FF (Magenta Puro para Chroma Key)' 
      : 'Fondo sólido Blanco Puro #FFFFFF';

    const systemInstruction = `
      ERES EL MOTOR DE SÍNTESIS SPRITEFORGE RPG.
      TU MISIÓN: Evolucionar un personaje pixel-art añadiendo atuendos y equipo.

      REFERENCIAS:
      - REFERENCIA A: Es el ADN CANÓNICO del personaje (maniquí base). NO PUEDES CAMBIAR su cara ni proporciones.
      - REFERENCIA B (Si existe): Es el estado actual de la evolución. Mantén coherencia con los materiales mostrados aquí.

      PROTOCOLO DE RENDERIZADO:
      - ESTILO: Pixel art de alta calidad, RPG clásico.
      - FONDO: ${backgroundDescription}.
      - TRANSFORMACIÓN: Aplica "${prompt}" manteniendo estrictamente la anatomía de la Referencia A.

      REGLAS DE LA CADENA NEURAL:
      ${neuralInstructions}

      SALIDA: Devuelve exclusivamente la imagen sintetizada del personaje.
    `;

    // Preparar el payload de partes para el modelo de visión
    const contents: any = {
      parts: [
        { inlineData: { data: this.stripBase64(baseImage), mimeType: 'image/jpeg' } },
        { text: "REFERENCIA A: ADN BASE DEL PERSONAJE" }
      ]
    };

    if (parentUrl) {
      contents.parts.push({ inlineData: { data: this.stripBase64(parentUrl), mimeType: 'image/jpeg' } });
      contents.parts.push({ text: "REFERENCIA B: ESTADO ACTUAL DE LA EVOLUCIÓN" });
    }

    contents.parts.push({ 
      text: `DIRECTIVA DE EVOLUCIÓN: "${prompt}". INTENSIDAD DE MUTACIÓN: ${config.mutationStrength}%` 
    });

    try {
      const response: GenerateContentResponse = await ai.models.generateContent({
        model: config.model,
        contents,
        config: { 
          systemInstruction,
          imageConfig: { 
            aspectRatio: config.aspectRatio,
            ...(config.model === 'gemini-3-pro-image-preview' && { imageSize: config.size })
          }
        },
      });

      const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);

      if (imagePart?.inlineData) {
        return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
      }

      throw new Error("La síntesis no produjo un resultado válido de imagen.");
    } catch (error: any) {
      console.error("[GeminiService Error]:", error);
      throw new Error(`Fallo en el enlace neural: ${error.message}`);
    }
  }

  /**
   * Limpia el prefijo de data URI para obtener solo los bytes base64.
   */
  private static stripBase64(url: string): string {
    return url.split(',')[1] || url;
  }
}

