            </div>
          )}
        </div>

        {/* Botón de Reset para volver al estado base */}
        {state.activeParent && (
          <div className="absolute top-6 right-6">
            <IconButton variant="danger" onClick={onResetParent} className="shadow-2xl">
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
              </svg>
            </IconButton>
          </div>
        )}

        {state.isGenerating && <Loader message="Procesando Estructura Neural..." />}
      </div>

      {/* Forja de Atuendos (Controls) */}
      <div className="bg-[#0a0a0a] border-t border-white/5 p-6 flex flex-col gap-6 shrink-0 shadow-[0_-30px_60px_rgba(0,0,0,0.8)] z-50">
        <div className="relative group">
          <textarea 
            value={prompt} onChange={(e) => setPrompt(e.target.value)}
            placeholder="Describe el equipo: 'Heavy plate armor with glowing runes'..."
            className="w-full bg-black/40 border border-white/5 rounded-2xl p-5 text-[14px] text-white focus:border-indigo-500/50 transition-all outline-none h-28 resize-none font-medium placeholder:text-slate-700 shadow-inner"
          />
          {prompt && (
            <button onClick={() => setPrompt('')} className="absolute top-4 right-4 text-slate-700 hover:text-white transition-colors p-2">
              <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
          )}
        </div>

        <div className="flex flex-col gap-4 overflow-hidden">
          <div className="flex gap-6 overflow-x-auto no-scrollbar border-b border-white/5 pb-2">
            {QUICK_TAGS.map(cat => (
              <button 
                key={cat.category} onClick={() => setActiveCategory(cat.category)}
                className={`whitespace-nowrap text-[9px] font-black uppercase tracking-[0.2em] pb-2 transition-all ${activeCategory === cat.category ? 'text-indigo-400 border-b-2 border-indigo-500' : 'text-slate-600 hover:text-slate-400'}`}
              >
                {cat.category}
              </button>
            ))}
          </div>
          <div className="flex flex-wrap gap-2 overflow-y-auto max-h-24 no-scrollbar py-1">
            {QUICK_TAGS.find(c => c.category === activeCategory)?.tags.map(tag => (
              <Tag key={tag} label={tag} onClick={() => setPrompt(prompt ? `${prompt}, ${tag}` : tag)} />
            ))}
          </div>
        </div>

        <button 
          onClick={onForge} disabled={state.isGenerating || !prompt}
          className="group relative w-full py-5 bg-indigo-600 disabled:bg-slate-900 disabled:opacity-40 rounded-2xl font-black text-[12px] uppercase tracking-[0.4em] text-white shadow-2xl shadow-indigo-600/20 active:scale-[0.98] transition-all overflow-hidden border border-indigo-400/20"
        >
          <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-1000" />
          {state.isGenerating ? 'Sintetizando...' : 'Ejecutar Forja Neural'}
        </button>
      </div>
    </div>
  );
};

