 */
export const IconButton: React.FC<{
  children: React.ReactNode;
  onClick: () => void;
  variant?: 'primary' | 'secondary' | 'danger';
  className?: string;
  disabled?: boolean;
}> = ({ children, onClick, variant = 'primary', className = '', disabled = false }) => {
  const themes = {
    primary: 'bg-white/5 border-white/10 text-slate-400 hover:bg-white/10',
    secondary: 'bg-indigo-600 border-indigo-400 text-white shadow-lg shadow-indigo-600/30',
    danger: 'bg-red-500/10 border-red-500/20 text-red-400 hover:bg-red-500/20'
  };

  return (
    <button 
      onClick={onClick}
      disabled={disabled}
      className={`w-10 h-10 flex items-center justify-center rounded-xl border transition-all active:scale-90 disabled:opacity-50 disabled:cursor-not-allowed ${themes[variant]} ${className}`}
    >
      {children}
    </button>
  );
};

/**
 * Slider de comparación profesional (Before/After).
 * Optimizado para sprites: usa renderizado pixelado y escala maximizada.
 */
export const ComparisonSlider: React.FC<{
  before: string;
  after: string;
  className?: string;
}> = ({ before, after, className = "" }) => {
  const [sliderPos, setSliderPos] = useState(50);
  const containerRef = useRef<HTMLDivElement>(null);

  const handleMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
    const position = ((x - rect.left) / rect.width) * 100;
    setSliderPos(Math.max(0, Math.min(100, position)));
  };

  const imageStyle: React.CSSProperties = {
    imageRendering: 'pixelated',
    maxWidth: '100%',
    maxHeight: '100%',
    objectFit: 'contain',
    transform: 'scale(1.2)' // Zoom de cortesía para assets con padding
  };

  return (
    <div 
      ref={containerRef}
      className={`relative w-full h-full select-none touch-none overflow-hidden ${className}`}
      onMouseMove={handleMove}
      onTouchMove={handleMove}
    >
      {/* Capa de fondo: Imagen base (DNA Original) */}
      <div className="absolute inset-0 w-full h-full flex items-center justify-center pointer-events-none">
        <img 
          src={before} 
          style={imageStyle}
          className="opacity-50" 
          alt="Original DNA" 
        />
      </div>

      {/* Capa superior: Imagen sintetizada con recorte dinámico */}
      <div 
        className="absolute inset-0 w-full h-full flex items-center justify-center pointer-events-none z-10"
        style={{ clipPath: `inset(0 ${100 - sliderPos}% 0 0)` }}
      >
        <img 
          src={after} 
          style={imageStyle}
          className="drop-shadow-[0_0_30px_rgba(99,102,241,0.4)]" 
          alt="Evolved Sprite" 
        />
      </div>

      {/* Línea divisoria del Slider con efecto Neon */}
      <div 
        className="absolute inset-y-0 w-0.5 bg-indigo-500 shadow-[0_0_25px_rgba(99,102,241,1)] z-20 pointer-events-none"
        style={{ left: `${sliderPos}%` }}
      >
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-12 h-12 bg-indigo-600/90 backdrop-blur-md rounded-2xl flex items-center justify-center border-2 border-white/20 shadow-[0_0_40px_rgba(79,70,229,0.6)] rotate-45">
          <svg className="w-6 h-6 text-white -rotate-45" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M8 7l-4 4m0 0l4 4m-4-4h16m-4-4l4 4m0 0l-4 4" />
          </svg>
        </div>
      </div>

      {/* Indicadores flotantes minimalistas */}
      <div className="absolute bottom-6 left-6 px-4 py-2 bg-black/40 backdrop-blur-xl rounded-xl text-[9px] font-black uppercase text-white/50 tracking-[0.2em] pointer-events-none z-30 border border-white/5">
        Original DNA
      </div>
      <div className="absolute bottom-6 right-6 px-4 py-2 bg-indigo-600/50 backdrop-blur-xl rounded-xl text-[9px] font-black uppercase text-white tracking-[0.2em] pointer-events-none z-30 border border-indigo-400/20">
        Synthesized
      </div>
    </div>
  );
};

