import React, { useMemo } from 'react';
import { GeneratedOutfit } from '../types';

interface TreeNodeProps {
  outfit: GeneratedOutfit;
  level: number;
  onSelect: (o: GeneratedOutfit) => void;
  isActive: boolean;
}

const TreeNode: React.FC<TreeNodeProps> = ({ outfit, onSelect, isActive }) => (
  <div 
    onClick={() => onSelect(outfit)}
    className={`relative shrink-0 w-24 h-24 rounded-2xl border-2 transition-all duration-500 cursor-pointer group ${
      isActive 
      ? 'border-indigo-500 bg-indigo-500/20 shadow-[0_0_20px_rgba(99,102,241,0.4)]' 
      : 'border-white/10 bg-black/40 hover:border-white/30'
    }`}
  >
    <div className="absolute inset-0 opacity-[0.05] checker-bg rounded-2xl overflow-hidden pointer-events-none" />
    <img 
      src={outfit.url} 
      className="w-full h-full object-contain p-2 relative z-10 transition-transform group-hover:scale-110" 
      style={{ imageRendering: 'pixelated' }}
      alt="Node"
    />
    <div className="absolute -bottom-6 left-1/2 -translate-x-1/2 whitespace-nowrap">
      <span className="text-[7px] font-black uppercase tracking-widest text-slate-500 bg-black/40 px-1.5 py-0.5 rounded border border-white/5">
        STEP {outfit.evolutionStep}
      </span>
    </div>
  </div>
);

interface EvolutionTreeProps {
  outfits: GeneratedOutfit[];
  baseImage: string | null;
  activeId?: string;
  onSelect: (o: GeneratedOutfit) => void;
}

export const EvolutionTree: React.FC<EvolutionTreeProps> = ({ outfits, baseImage, activeId, onSelect }) => {
  // Construir estructura de árbol: Root -> Nivel 1 -> Nivel 2...
  const levels = useMemo(() => {
    const tree: Record<number, GeneratedOutfit[]> = {};
    outfits.forEach(o => {
      const step = o.evolutionStep || 1;
      if (!tree[step]) tree[step] = [];
      tree[step].push(o);
    });
    return Object.entries(tree).sort(([a], [b]) => Number(a) - Number(b));
  }, [outfits]);

  if (!baseImage) return null;

  return (
    <div className="h-full w-full bg-[#050505] overflow-auto p-12 no-scrollbar flex flex-col items-center gap-24">
      {/* Root Node (Base DNA) */}
      <div className="relative flex flex-col items-center">
        <div className="w-28 h-28 rounded-[2.5rem] border-4 border-indigo-600/30 bg-indigo-600/5 p-4 relative group">
          <div className="absolute inset-0 bg-indigo-600/10 blur-2xl rounded-full opacity-50" />
          <img 
            src={baseImage} 
            className="w-full h-full object-contain relative z-10 opacity-60 grayscale group-hover:grayscale-0 transition-all duration-700" 
            style={{ imageRendering: 'pixelated' }}
            alt="Base DNA"
          />
          <div className="absolute -top-8 left-1/2 -translate-x-1/2 text-[9px] font-black text-indigo-400 uppercase tracking-[0.3em]">
            Origin Point
          </div>
        </div>

        {/* Línea de conexión al primer nivel */}
        {levels.length > 0 && (
          <div className="absolute top-full h-24 w-0.5 bg-gradient-to-b from-indigo-500 to-transparent opacity-50" />
        )}
      </div>

      {/* Niveles de Evolución */}
      {levels.map(([step, nodes], levelIndex) => (
        <div key={step} className="relative flex flex-col items-center gap-24 w-full">
          <div className="flex gap-12 justify-center flex-wrap max-w-4xl">
            {nodes.map(node => (
              <div key={node.id} className="relative">
                {/* Conector superior curvo para ramas */}
                <TreeNode 
                  outfit={node} 
                  level={Number(step)} 
                  onSelect={onSelect} 
                  isActive={activeId === node.id}
                />
              </div>
            ))}
          </div>

          {/* Línea hacia el siguiente nivel si existe */}
          {levelIndex < levels.length - 1 && (
            <div className="h-24 w-0.5 bg-gradient-to-b from-indigo-500/20 to-indigo-500/50" />
          )}
        </div>
      ))}

      {outfits.length === 0 && (
        <div className="flex flex-col items-center opacity-30 mt-20">
          <div className="w-1 h-32 bg-gradient-to-b from-indigo-500 to-transparent" />
          <p className="text-[10px] font-black uppercase tracking-[0.5em] mt-8 text-slate-500">Waiting for Genetic Mutation</p>
        </div>
      )}

      <div className="h-24 shrink-0" />
    </div>
  );
};

