import { useState, useEffect, useCallback, useReducer } from 'react';
import { AppState, GeneratedOutfit, ForgeConfig } from '../types';
import { GeminiService } from '../services/geminiService';
import { StorageService } from '../services/storageService';
import { DEFAULT_CONFIG } from '../constants';

type ForgeAction = 
  | { type: 'SET_BASE_IMAGE'; payload: string }
  | { type: 'SET_ACTIVE_PARENT'; payload: GeneratedOutfit | null }
  | { type: 'SET_OUTFITS'; payload: GeneratedOutfit[] }
  | { type: 'ADD_OUTFIT'; payload: GeneratedOutfit }
  | { type: 'REMOVE_OUTFIT'; payload: string }
  | { type: 'SET_LOADING'; payload: boolean }
  | { type: 'SET_ERROR'; payload: string | null }
  | { type: 'UPDATE_CONFIG'; payload: Partial<ForgeConfig> }
  | { type: 'UPDATE_BG'; payload: 'magenta' | 'white' | 'gray' }
  | { type: 'TOGGLE_NODE'; payload: string };

function forgeReducer(state: AppState, action: ForgeAction): AppState {
  switch (action.type) {
    case 'SET_BASE_IMAGE': return { ...state, baseImage: action.payload, activeParent: null };
    case 'SET_ACTIVE_PARENT': return { ...state, activeParent: action.payload };
    case 'SET_OUTFITS': return { ...state, outfits: action.payload };
    case 'ADD_OUTFIT': return { ...state, outfits: [action.payload, ...state.outfits] };
    case 'REMOVE_OUTFIT': return { ...state, outfits: state.outfits.filter(o => o.id !== action.payload) };
    case 'SET_LOADING': return { ...state, isGenerating: action.payload };
    case 'SET_ERROR': return { ...state, error: action.payload };
    case 'UPDATE_CONFIG': return { ...state, config: { ...state.config, ...action.payload } };
    case 'UPDATE_BG': return { ...state, config: { ...state.config, protocols: { ...state.config.protocols, backgroundStyle: action.payload } } };
    case 'TOGGLE_NODE': return { 
      ...state, 
      config: { 
        ...state.config, 
        neuralChain: state.config.neuralChain.map(n => n.id === action.payload ? { ...n, isActive: !n.isActive } : n) 
      } 
    };
    default: return state;
  }
}

export function useSpriteForge() {
  const [state, dispatch] = useReducer(forgeReducer, {
    baseImage: null,
    activeParent: null,
    outfits: [],
    isGenerating: false,
    config: DEFAULT_CONFIG,
    error: null
  });

  useEffect(() => {
    StorageService.getAllOutfits().then(data => 
      dispatch({ type: 'SET_OUTFITS', payload: data })
    );
  }, []);

  const uploadBaseDNA = useCallback((url: string) => {
    dispatch({ type: 'SET_BASE_IMAGE', payload: url });
  }, []);

  const deleteAsset = useCallback(async (id: string) => {
    await StorageService.deleteOutfit(id);
    dispatch({ type: 'REMOVE_OUTFIT', payload: id });
  }, []);

  const executeSynthesis = useCallback(async (prompt: string) => {
    if (!state.baseImage) return;

    dispatch({ type: 'SET_LOADING', payload: true });
    dispatch({ type: 'SET_ERROR', payload: null });

    try {
      const url = await GeminiService.synthesizeEvolution(
        state.baseImage,
        state.activeParent?.url || null,
        prompt,
        state.config
      );

      const newAsset: GeneratedOutfit = {
        id: crypto.randomUUID(),
        url,
        originalUrl: url,
        parentId: state.activeParent?.id,
        prompt,
        timestamp: Date.now(),
        model: state.config.model,
        aspectRatio: state.config.aspectRatio,
        evolutionStep: (state.activeParent?.evolutionStep || 0) + 1
      };

      await StorageService.saveOutfit(newAsset);
      dispatch({ type: 'ADD_OUTFIT', payload: newAsset });
      dispatch({ type: 'SET_ACTIVE_PARENT', payload: newAsset });
    } catch (error: any) {
      dispatch({ type: 'SET_ERROR', payload: error.message || 'Error en la síntesis neural.' });
    } finally {
      dispatch({ type: 'SET_LOADING', payload: false });
    }
  }, [state.baseImage, state.activeParent, state.config]);

  return {
    state,
    dispatch,
    uploadBaseDNA,
    executeSynthesis,
    deleteAsset
  };
}

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ForgeConfig } from "../types";

/**
 * Servicio central para la comunicación con la API de Gemini.
 */
export class GeminiService {
  /**
   * Extrae el "ADN" de un personaje: quita ropa y equipo dejando solo el maniquí base.
   */
  static async extractBaseDNA(
    sourceImage: string,
    config: ForgeConfig
  ): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    const systemInstruction = `
      ACTÚA COMO UN EXPERTO EN DISEÑO DE ASSETS PARA VIDEOJUEGOS (SPRITE TEMPLATES).
      OBJETIVO: Recibir un personaje con equipo y generar su PLANTILLA BASE (MANIQUÍ).

      INSTRUCCIONES CRÍTICAS:
      1. IDENTIFICA la anatomía, rostro, color de piel y cabello del personaje.
      2. ELIMINA toda armadura, túnica, armas, cascos y accesorios complejos.
      3. DIBUJA al personaje exclusivamente en ropa interior básica (estilo RPG clásico, simple).
      4. MANTÉN el estilo Pixel Art exacto de la fuente.
      5. NO ALTERES las proporciones corporales ni los rasgos faciales.
      6. FONDO: Debe ser sólido #FF00FF (Magenta) para facilitar el recorte posterior.

      SALIDA: Solo la imagen del personaje base purificado.
    `;

    const contents = {
      parts: [
        { inlineData: { data: this.stripBase64(sourceImage), mimeType: 'image/jpeg' } },
        { text: "GENERATE BASE CHARACTER TEMPLATE. REMOVE ALL ARMOR AND OUTFITS." }
      ]
    };

    try {
      const response: GenerateContentResponse = await ai.models.generateContent({
        model: config.model,
        contents,
        config: { 
          systemInstruction,
          imageConfig: { aspectRatio: config.aspectRatio }
        },
      });

      const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (imagePart?.inlineData) {
        return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
      }
      throw new Error("No se pudo extraer la anatomía base.");
    } catch (error: any) {
      throw new Error(`Fallo en la extracción genética: ${error.message}`);
    }
  }

  /**
   * Genera una nueva evolución de sprite.
   */
  static async synthesizeEvolution(
    baseImage: string, 
    parentUrl: string | null, 
    prompt: string, 
    config: ForgeConfig
  ): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    const neuralInstructions = config.neuralChain
      .filter(n => n.isActive)
      .map(n => `[PROTOCOLO ${n.id.toUpperCase()}]: ${n.instruction}`)
      .join('\n');

    const backgroundDescription = config.protocols.backgroundStyle === 'magenta' 
      ? 'Fondo sólido #FF00FF (Magenta Puro)' 
      : 'Fondo sólido Blanco Puro #FFFFFF';

    const systemInstruction = `
      ERES EL MOTOR DE SÍNTESIS SPRITEFORGE RPG.
      TU MISIÓN: Evolucionar un personaje pixel-art añadiendo atuendos y equipo.

      REFERENCIAS:
      - REFERENCIA A: ADN CANÓNICO (maniquí base). Mantén cara y proporciones.
      - REFERENCIA B (Si existe): Estado actual. Mantén coherencia de materiales.

      PROTOCOLO:
      - ESTILO: Pixel art de alta calidad.
      - FONDO: ${backgroundDescription}.
      - TRANSFORMACIÓN: Aplica "${prompt}" sobre la anatomía de la Referencia A.

      ${neuralInstructions}

      SALIDA: La imagen sintetizada.
    `;

    const contents: any = {
      parts: [
        { inlineData: { data: this.stripBase64(baseImage), mimeType: 'image/jpeg' } },
        { text: "REFERENCIA A: ADN BASE" }
      ]
    };

    if (parentUrl) {
      contents.parts.push({ inlineData: { data: this.stripBase64(parentUrl), mimeType: 'image/jpeg' } });
      contents.parts.push({ text: "REFERENCIA B: ESTADO ACTUAL" });
    }

    contents.parts.push({ text: `DIRECTIVA: "${prompt}"` });

    try {
      const response: GenerateContentResponse = await ai.models.generateContent({
        model: config.model,
        contents,
        config: { 
          systemInstruction,
          imageConfig: { 
            aspectRatio: config.aspectRatio,
            ...(config.model === 'gemini-3-pro-image-preview' && { imageSize: config.size })
          }
        },
      });

      const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (imagePart?.inlineData) return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
      throw new Error("La síntesis no produjo un resultado válido.");
    } catch (error: any) {
      throw new Error(`Fallo en el enlace neural: ${error.message}`);
    }
  }

  private static stripBase64(url: string): string {
    return url.split(',')[1] || url;
  }
}

