import React, { useState, useRef, useMemo } from 'react';
import { AppState } from '../types';
import { QUICK_TAGS } from '../constants';
import { IconButton, Tag, Loader, ComparisonSlider } from './UI';

interface AtelierProps {
  state: AppState;
  prompt: string;
  setPrompt: (v: string) => void;
  onUpload: (url: string) => void;
  onForge: () => void;
  onExtractBase: (url: string) => void;
  onResetParent: () => void;
}

/**
 * ATELIER: El corazón del SpriteForge.
 */
export const Atelier: React.FC<AtelierProps> = ({ 
  state, prompt, setPrompt, onUpload, onForge, onExtractBase, onResetParent 
}) => {
  const [activeCategory, setActiveCategory] = useState(QUICK_TAGS[0].category);
  const [hasJustUploaded, setHasJustUploaded] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const backgroundTheme = useMemo(() => {
    const bg = state.config.protocols.backgroundStyle;
    if (bg === 'magenta') return 'bg-[#FF00FF]';
    if (bg === 'white') return 'bg-white';
    return 'bg-[#0a0a0a]';
  }, [state.config.protocols.backgroundStyle]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = () => {
        onUpload(reader.result as string);
        setHasJustUploaded(true);
      };
      reader.readAsDataURL(file);
    }
  };

  if (!state.baseImage) {
    return (
      <div className="h-full flex items-center justify-center p-10 bg-[#050505]">
        <div 
          onClick={() => fileInputRef.current?.click()}
          className="w-full max-w-sm aspect-square border-2 border-dashed border-indigo-500/20 rounded-[3.5rem] bg-indigo-500/5 flex flex-col items-center justify-center cursor-pointer hover:bg-indigo-500/10 transition-all group shadow-2xl shadow-indigo-500/5"
        >
          <div className="w-20 h-20 bg-indigo-600 rounded-3xl flex items-center justify-center mb-6 shadow-2xl group-hover:scale-110 transition-transform shadow-indigo-600/40">
            <svg className="w-8 h-8 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" />
            </svg>
          </div>
          <span className="text-[14px] font-black uppercase tracking-[0.4em] text-white">Neural Load</span>
          <p className="text-[9px] font-bold text-slate-500 uppercase tracking-widest mt-2 text-center px-12 leading-relaxed">Sube el maniquí o un personaje equipado para extraer su ADN</p>
          <input 
            type="file" ref={fileInputRef} className="hidden" accept="image/*" 
            onChange={handleFileChange} 
          />
        </div>
      </div>
    );
  }

