      <span className="text-[7px] font-black uppercase tracking-widest text-indigo-300 bg-black/60 px-2 py-0.5 rounded border border-white/5">
        STEP {outfit.evolutionStep}
      </span>
    </div>
  </div>
);

interface EvolutionTreeProps {
  outfits: GeneratedOutfit[];
  baseImage: string | null;
  activeId?: string;
  onSelect: (o: GeneratedOutfit) => void;
}

export const EvolutionTree: React.FC<EvolutionTreeProps> = ({ outfits, baseImage, activeId, onSelect }) => {
  const containerRef = useRef<HTMLDivElement>(null);

  const treeStructure = useMemo(() => {
    const levels: Record<number, GeneratedOutfit[]> = {};
    outfits.forEach(o => {
      const step = o.evolutionStep || 1;
      if (!levels[step]) levels[step] = [];
      levels[step].push(o);
    });
    return Object.entries(levels).sort(([a], [b]) => Number(a) - Number(b));
  }, [outfits]);

  if (!baseImage) return null;

  return (
    <div className="h-full w-full bg-[#050505] overflow-auto relative no-scrollbar flex flex-col items-center py-20 px-10 gap-24" ref={containerRef}>
      {/* Origin Point */}
      <div className="relative z-20">
        <div className="w-32 h-32 rounded-[3rem] border-4 border-indigo-600/30 bg-indigo-600/5 p-6 relative group transition-all hover:border-indigo-500/60">
          <div className="absolute inset-0 bg-indigo-600/10 blur-3xl rounded-full opacity-50 group-hover:opacity-100 transition-opacity" />
          <img 
            src={baseImage} 
            className="w-full h-full object-contain relative z-10 opacity-40 grayscale group-hover:grayscale-0 group-hover:opacity-100 transition-all duration-700" 
            style={{ imageRendering: 'pixelated' }}
            alt="Base"
          />
          <div className="absolute -top-10 left-1/2 -translate-x-1/2 text-[10px] font-black text-indigo-400 uppercase tracking-[0.5em] whitespace-nowrap">
            Genetic Origin
          </div>
        </div>
        {treeStructure.length > 0 && (
          <div className="absolute top-full left-1/2 -translate-x-1/2 h-24 w-0.5 bg-gradient-to-b from-indigo-500 to-indigo-500/20" />
        )}
      </div>

      {/* Evolution Branches */}
      {treeStructure.map(([step, nodes]) => (
        <div key={step} className="flex flex-col items-center gap-24 w-full">
          <div className="flex gap-16 justify-center flex-wrap max-w-6xl relative z-20">
            {nodes.map(node => (
              <TreeNode 
                key={node.id}
                id={`node-${node.id}`}
                outfit={node} 
                onSelect={onSelect} 
                isActive={activeId === node.id}
              />
            ))}
          </div>
          {/* Vertical Path to next step if exists */}
          {Number(step) < treeStructure.length && (
             <div className="h-24 w-0.5 bg-indigo-500/20" />
          )}
        </div>
      ))}

      {outfits.length === 0 && (
        <div className="flex flex-col items-center opacity-30 mt-10">
          <div className="w-0.5 h-32 bg-gradient-to-b from-indigo-500 to-transparent" />
          <p className="text-[10px] font-black uppercase tracking-[0.6em] mt-10 text-slate-500">Awaiting Evolution</p>
        </div>
      )}

      {/* Decorative Grid and Dust */}
      <div className="fixed inset-0 pointer-events-none opacity-[0.03] checker-bg z-0" />
      <div className="fixed inset-0 pointer-events-none bg-[radial-gradient(circle_at_50%_50%,rgba(79,70,229,0.05),transparent)] z-0" />

      <div className="h-40 shrink-0" />
    </div>
  );
};

import React, { useState, useRef, useMemo } from 'react';
import { AppState } from '../types';
import { QUICK_TAGS } from '../constants';
import { IconButton, Tag, Loader, ComparisonSlider, NeuralLog } from './UI';

interface AtelierProps {
  state: AppState;
  prompt: string;
  setPrompt: (v: string) => void;
  onUpload: (url: string) => void;
  onForge: () => void;
  onExtractBase: (url: string) => void;
  onResetParent: () => void;
}

export const Atelier: React.FC<AtelierProps> = ({ 
  state, prompt, setPrompt, onUpload, onForge, onExtractBase, onResetParent 
}) => {
  const [activeCategory, setActiveCategory] = useState(QUICK_TAGS[0].category);
  const [hasJustUploaded, setHasJustUploaded] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const backgroundTheme = useMemo(() => {
    const bg = state.config.protocols.backgroundStyle;
    if (bg === 'magenta') return 'bg-[#FF00FF]';
    if (bg === 'white') return 'bg-white';
    return 'bg-[#0a0a0a]';
  }, [state.config.protocols.backgroundStyle]);

  const handleDownload = async () => {
    const url = state.activeParent ? state.activeParent.url : state.baseImage;
    if (!url) return;
    const link = document.createElement('a');
    link.href = url;
    link.download = `spriteforge-${Date.now()}.png`;
    link.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = () => {
        onUpload(reader.result as string);
        setHasJustUploaded(true);
      };
      reader.readAsDataURL(file);
    }
  };

  if (!state.baseImage) {
    return (
      <div className="h-full flex items-center justify-center p-10 bg-[#050505]">
        <div 
          onClick={() => fileInputRef.current?.click()}
          className="w-full max-w-sm aspect-square border-2 border-dashed border-indigo-500/20 rounded-[4rem] bg-indigo-500/5 flex flex-col items-center justify-center cursor-pointer hover:bg-indigo-500/10 transition-all group shadow-2xl shadow-indigo-500/10 border-indigo-400/20"
        >
          <div className="w-24 h-24 bg-indigo-600 rounded-[2rem] flex items-center justify-center mb-8 shadow-2xl group-hover:scale-110 transition-transform shadow-indigo-600/50">
            <svg className="w-10 h-10 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
            </svg>
          </div>
          <span className="text-[15px] font-black uppercase tracking-[0.5em] text-white">Neural Intake</span>
          <p className="text-[9px] font-bold text-slate-500 uppercase tracking-widest mt-3 text-center px-12 leading-relaxed opacity-60">
            Carga el ADN de origen para iniciar la síntesis
          </p>
          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileChange} />
        </div>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col overflow-hidden animate-in fade-in duration-700">
      <div className={`flex-1 relative overflow-hidden transition-colors duration-500 ${backgroundTheme}`}>
        <div className="absolute inset-0 opacity-[0.05] checker-bg pointer-events-none" />

        {/* Visor Borders (Futuristic Aesthetic) */}
        <div className="absolute inset-4 border border-white/5 pointer-events-none rounded-[2rem] overflow-hidden">
           <div className="absolute top-0 left-0 w-20 h-20 border-t-2 border-l-2 border-indigo-500/30 rounded-tl-[2rem]" />
           <div className="absolute bottom-0 right-0 w-20 h-20 border-b-2 border-r-2 border-indigo-500/30 rounded-br-[2rem]" />
        </div>

        <NeuralLog active={state.isGenerating} />

        <div className="absolute inset-0 flex items-center justify-center">
          {state.activeParent ? (
            <ComparisonSlider before={state.baseImage} after={state.activeParent.url} className="w-full h-full" />
          ) : (
            <div className="relative w-full h-full flex items-center justify-center group animate-in zoom-in-95 duration-1000">
              <img 
                src={state.baseImage} 
                style={{ imageRendering: 'pixelated', transform: 'scale(1.2)' }}
                className="max-h-[80%] max-w-[80%] object-contain relative z-10 transition-transform group-hover:scale-[1.25] duration-1000 ease-out" 
                alt="DNA Base" 
              />
              <div className="absolute top-10 left-10 px-5 py-2.5 bg-black/80 backdrop-blur-xl rounded-2xl border border-indigo-500/30 text-[9px] font-black uppercase tracking-[0.3em] text-indigo-400 shadow-2xl">
                Active Genetic Source
              </div>
            </div>
          )}
        </div>

        {/* Acciones del Visor */}
        <div className="absolute top-8 right-8 flex flex-col gap-4 z-40">
           <IconButton variant="primary" onClick={handleDownload} className="scale-110 shadow-2xl backdrop-blur-xl bg-black/40">
             <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
               <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
             </svg>
           </IconButton>
           {state.activeParent && (
             <IconButton variant="danger" onClick={onResetParent} className="scale-110 shadow-2xl backdrop-blur-xl bg-black/40">
               <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
               </svg>
             </IconButton>
           )}
        </div>

        {hasJustUploaded && !state.activeParent && !state.isGenerating && (
          <div className="absolute inset-x-0 bottom-12 flex justify-center z-[60]">
            <button 
              onClick={() => { onExtractBase(state.baseImage!); setHasJustUploaded(false); }}
              className="px-10 py-4 bg-indigo-600 rounded-[1.5rem] border border-indigo-400 shadow-[0_0_50px_rgba(79,70,229,0.5)] flex items-center gap-4 group active:scale-95 transition-all"
            >
              <div className="w-6 h-6 flex items-center justify-center">
                <svg className="w-full h-full text-white animate-pulse" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" />
                </svg>
              </div>
              <span className="text-[12px] font-black uppercase tracking-[0.4em] text-white">Extract Base ADN</span>
            </button>
          </div>
        )}

        {state.isGenerating && <Loader message="Accessing Neural Network..." />}
      </div>

      {/* Control Panel (Refined) */}
      <div className="bg-[#0a0a0a] border-t border-white/10 p-5 pb-8 flex flex-col gap-5 shrink-0 shadow-[0_-40px_100px_rgba(0,0,0,1)] z-50">
        <div className="relative group">
          <textarea 
            value={prompt} onChange={(e) => setPrompt(e.target.value)}
            placeholder="Describe el atuendo o equipo..."
            className="w-full bg-black/60 border border-white/5 rounded-2xl p-5 text-[14px] text-white focus:border-indigo-500/40 transition-all outline-none h-24 resize-none font-medium placeholder:text-slate-700 shadow-inner"
          />
          {prompt && (
            <button onClick={() => setPrompt('')} className="absolute top-3 right-3 text-slate-700 hover:text-white transition-colors p-2">
              <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
          )}
        </div>

        <div className="flex flex-col gap-4 overflow-hidden">
          <div className="flex gap-6 overflow-x-auto no-scrollbar border-b border-white/5 pb-2">
            {QUICK_TAGS.map(cat => (
              <button 
                key={cat.category} onClick={() => setActiveCategory(cat.category)}
                className={`whitespace-nowrap text-[9px] font-black uppercase tracking-[0.3em] pb-2 transition-all ${activeCategory === cat.category ? 'text-indigo-400 border-b-2 border-indigo-500' : 'text-slate-600 hover:text-slate-400'}`}
              >
                {cat.category}
              </button>
            ))}
          </div>
          <div className="flex flex-wrap gap-2.5 overflow-y-auto max-h-20 no-scrollbar py-1">
            {QUICK_TAGS.find(c => c.category === activeCategory)?.tags.map(tag => (
              <Tag key={tag} label={tag} onClick={() => setPrompt(prompt ? `${prompt}, ${tag}` : tag)} />
            ))}
          </div>
        </div>

        <button 
          onClick={onForge} disabled={state.isGenerating || !prompt}
          className="group relative w-full py-5 bg-indigo-600 disabled:bg-slate-900 rounded-2xl font-black text-[13px] uppercase tracking-[0.5em] text-white shadow-[0_20px_40px_rgba(79,70,229,0.3)] active:scale-[0.98] transition-all overflow-hidden border border-indigo-400/20"
        >
          {state.isGenerating ? 'Synthesizing...' : 'Execute Neural Forge'}
        </button>
      </div>
    </div>
  );
};

