                    className={`w-full flex items-center justify-between p-7 rounded-[2rem] border-2 transition-all ${node.isActive ? 'bg-indigo-600/10 border-indigo-500/50 text-white shadow-lg' : 'bg-white/5 border-transparent text-slate-600 opacity-50'}`}
