import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ForgeConfig } from "../types";

/**
 * Servicio central para la comunicación con la API de Gemini.
 */
export class GeminiService {
  /**
   * Extrae el "ADN" de un personaje: quita ropa y equipo dejando solo el maniquí base.
   */
  static async extractBaseDNA(
    sourceImage: string,
    config: ForgeConfig
  ): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    const systemInstruction = `
      ACTÚA COMO UN EXPERTO EN DISEÑO DE ASSETS PARA VIDEOJUEGOS (SPRITE TEMPLATES).
      OBJETIVO: Recibir un personaje con equipo y generar su PLANTILLA BASE (MANIQUÍ).

      INSTRUCCIONES CRÍTICAS:
      1. IDENTIFICA la anatomía, rostro, color de piel y cabello del personaje.
      2. ELIMINA toda armadura, túnica, armas, cascos y accesorios complejos.
      3. DIBUJA al personaje exclusivamente en ropa interior básica (estilo RPG clásico, simple).
      4. MANTÉN el estilo Pixel Art exacto de la fuente.
      5. NO ALTERES las proporciones corporales ni los rasgos faciales.
      6. FONDO: Debe ser sólido #FF00FF (Magenta) para facilitar el recorte posterior.

      SALIDA: Solo la imagen del personaje base purificado.
    `;

    const contents = {
      parts: [
        { inlineData: { data: this.stripBase64(sourceImage), mimeType: 'image/jpeg' } },
        { text: "GENERATE BASE CHARACTER TEMPLATE. REMOVE ALL ARMOR AND OUTFITS." }
      ]
    };

    try {
      const response: GenerateContentResponse = await ai.models.generateContent({
        model: config.model,
        contents,
        config: { 
          systemInstruction,
          imageConfig: { aspectRatio: config.aspectRatio }
        },
      });

      const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (imagePart?.inlineData) {
        return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
      }
      throw new Error("No se pudo extraer la anatomía base.");
    } catch (error: any) {
      throw new Error(`Fallo en la extracción genética: ${error.message}`);
    }
  }

  /**
   * Genera una nueva evolución de sprite.
   */
  static async synthesizeEvolution(
    baseImage: string, 
    parentUrl: string | null, 
    prompt: string, 
    config: ForgeConfig
  ): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    const neuralInstructions = config.neuralChain
      .filter(n => n.isActive)
      .map(n => `[PROTOCOLO ${n.id.toUpperCase()}]: ${n.instruction}`)
      .join('\n');

    const backgroundDescription = config.protocols.backgroundStyle === 'magenta' 
      ? 'Fondo sólido #FF00FF (Magenta Puro)' 
      : 'Fondo sólido Blanco Puro #FFFFFF';

    // Inyectamos la Mutation Strength dinámicamente en el prompt de sistema
    const mutationGuidance = config.mutationStrength > 80 
      ? "MUTATION_LEVEL: CRITICAL. Desvíate significativamente de la silueta para crear formas extravagantes."
      : config.mutationStrength < 20
      ? "MUTATION_LEVEL: LOW. Mantén el atuendo muy pegado a la anatomía original, cambios mínimos."
      : "MUTATION_LEVEL: BALANCED. Equilibrio entre fidelidad anatómica y diseño creativo.";

    const systemInstruction = `
      ERES EL MOTOR DE SÍNTESIS SPRITEFORGE RPG.
      TU MISIÓN: Evolucionar un personaje pixel-art añadiendo atuendos y equipo.

      ${mutationGuidance}

      REFERENCIAS:
      - REFERENCIA A: ADN CANÓNICO (maniquí base). Mantén cara y proporciones.
      - REFERENCIA B (Si existe): Estado actual. Mantén coherencia de materiales.

      PROTOCOLO:
      - ESTILO: Pixel art de alta calidad.
      - FONDO: ${backgroundDescription}.
      - TRANSFORMACIÓN: Aplica "${prompt}" sobre la anatomía de la Referencia A.

      ${neuralInstructions}

      SALIDA: La imagen sintetizada.
    `;

    const contents: any = {
      parts: [
        { inlineData: { data: this.stripBase64(baseImage), mimeType: 'image/jpeg' } },
        { text: "REFERENCIA A: ADN BASE" }
      ]
    };

    if (parentUrl) {
      contents.parts.push({ inlineData: { data: this.stripBase64(parentUrl), mimeType: 'image/jpeg' } });
      contents.parts.push({ text: "REFERENCIA B: ESTADO ACTUAL" });
    }

    contents.parts.push({ text: `DIRECTIVA: "${prompt}"` });

    try {
      const response: GenerateContentResponse = await ai.models.generateContent({
        model: config.model,
        contents,
        config: { 
          systemInstruction,
          imageConfig: { 
            aspectRatio: config.aspectRatio,
            ...(config.model === 'gemini-3-pro-image-preview' && { imageSize: config.size })
          }
        },
      });

      const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (imagePart?.inlineData) return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
      throw new Error("La síntesis no produjo un resultado válido.");
    } catch (error: any) {
      throw new Error(`Fallo en el enlace neural: ${error.message}`);
    }
  }

  private static stripBase64(url: string): string {
    return url.split(',')[1] || url;
  }
}

