interface EvolutionTreeProps {
  outfits: GeneratedOutfit[];
  baseImage: string | null;
  activeId?: string;
  onSelect: (o: GeneratedOutfit) => void;
}

export const EvolutionTree: React.FC<EvolutionTreeProps> = ({ outfits, baseImage, activeId, onSelect }) => {
  // Agrupamos outfits por su parentId para construir ramas reales
  const lineage = useMemo(() => {
    const map: Record<string, GeneratedOutfit[]> = { 'base': [] };
    outfits.forEach(o => {
      const parent = o.parentId || 'base';
      if (!map[parent]) map[parent] = [];
      map[parent].push(o);
    });
    return map;
  }, [outfits]);

  // Niveles por profundidad real
  const levels = useMemo(() => {
    const lvls: Record<number, GeneratedOutfit[]> = {};
    outfits.forEach(o => {
      const step = o.evolutionStep || 1;
      if (!lvls[step]) lvls[step] = [];
      lvls[step].push(o);
    });
    return Object.entries(lvls).sort(([a], [b]) => Number(a) - Number(b));
  }, [outfits]);

  if (!baseImage) return null;

  return (
    <div className="h-full w-full bg-[#030303] overflow-auto relative no-scrollbar flex flex-col items-center py-24 px-10 gap-32">
      {/* Decorative SVG Lines Layer (Conceptual Connection) */}
      <div className="absolute inset-0 pointer-events-none z-0 overflow-visible">
        {/* Aquí se podrían dibujar líneas SVG dinámicas entre IDs de nodos */}
      </div>

      {/* Origen Genético */}
      <div className="relative z-20">
        <div className="w-36 h-36 rounded-[3.5rem] border-2 border-indigo-600/20 bg-indigo-600/5 p-8 relative group transition-all hover:border-indigo-500/40">
          <div className="absolute inset-0 bg-indigo-600/10 blur-[80px] rounded-full opacity-40 group-hover:opacity-60 transition-opacity" />
          <img 
            src={baseImage} 
            className="w-full h-full object-contain relative z-10 opacity-60 grayscale group-hover:grayscale-0 group-hover:opacity-100 transition-all duration-1000" 
            style={{ imageRendering: 'pixelated' }}
            alt="Source DNA"
          />
          <div className="absolute -top-12 left-1/2 -translate-x-1/2 text-[10px] font-black text-indigo-400/60 uppercase tracking-[0.6em] whitespace-nowrap">
            Genetic Origin
          </div>
          <div className="absolute -bottom-16 left-1/2 -translate-x-1/2 w-0.5 h-16 bg-gradient-to-b from-indigo-500/40 to-indigo-500/10" />
        </div>
      </div>

      {/* Evoluciones Jerárquicas */}
      {levels.map(([step, nodes]) => (
        <div key={step} className="flex flex-col items-center gap-32 w-full animate-in slide-in-from-bottom-8 duration-500">
          <div className="flex gap-20 justify-center flex-wrap max-w-5xl relative z-20">
            {nodes.map(node => (
              <div key={node.id} className="relative">
                {/* Connector from top */}
                <div className="absolute -top-16 left-1/2 -translate-x-1/2 w-0.5 h-16 bg-indigo-500/10" />
                <TreeNode 
                  id={`node-${node.id}`}
                  outfit={node} 
                  onSelect={onSelect} 
                  isActive={activeId === node.id}
                />
              </div>
            ))}
          </div>
        </div>
      ))}

      {outfits.length === 0 && (
        <div className="flex flex-col items-center opacity-20 mt-10">
          <div className="w-0.5 h-48 bg-gradient-to-b from-indigo-500 to-transparent" />
          <p className="text-[10px] font-black uppercase tracking-[0.8em] mt-12 text-slate-500">Awaiting Genetic Diversification</p>
        </div>
      )}

      {/* Grilla de fondo sutil */}
      <div className="fixed inset-0 pointer-events-none opacity-[0.02] checker-bg z-0" />
      <div className="h-64 shrink-0" />
    </div>
  );
};

