interface EvolutionTreeProps {
  outfits: GeneratedOutfit[];
  baseImage: string | null;
  activeId?: string;
  onSelect: (o: GeneratedOutfit) => void;
}

export const EvolutionTree: React.FC<EvolutionTreeProps> = ({ outfits, baseImage, activeId, onSelect }) => {
  // Construimos el árbol: cada nodo sabe quiénes son sus hijos
  const treeData = useMemo(() => {
    const rootNodes = outfits.filter(o => !o.parentId);
    const childrenMap = new Map<string, GeneratedOutfit[]>();

    outfits.forEach(o => {
      if (o.parentId) {
        const children = childrenMap.get(o.parentId) || [];
        children.push(o);
        childrenMap.set(o.parentId, children);
      }
    });

    return { rootNodes, childrenMap };
  }, [outfits]);

  // Agrupamos por Steps para el layout vertical pero manteniendo la conexión visual
  const steps = useMemo(() => {
    const map = new Map<number, GeneratedOutfit[]>();
    outfits.forEach(o => {
      const step = o.evolutionStep;
      const current = map.get(step) || [];
      current.push(o);
      map.set(step, current);
    });
    return Array.from(map.entries()).sort((a, b) => a[0] - b[0]);
  }, [outfits]);

  if (!baseImage) return null;

  return (
    <div className="h-full w-full bg-[#030303] overflow-auto relative no-scrollbar flex flex-col items-center py-20 px-6 gap-24">
      {/* Origen Genético Principal */}
      <div className="relative z-20 flex flex-col items-center">
        <div className="w-32 h-32 sm:w-40 sm:h-40 rounded-[3rem] sm:rounded-[4rem] border-2 border-indigo-600/30 bg-indigo-600/5 p-8 relative group transition-all">
          <div className="absolute inset-0 bg-indigo-600/10 blur-[60px] rounded-full opacity-40" />
          <img src={baseImage} className="w-full h-full object-contain relative z-10 opacity-40" style={{ imageRendering: 'pixelated' }} />
          <div className="absolute -top-10 left-1/2 -translate-x-1/2 text-[9px] font-black text-indigo-400 uppercase tracking-[0.4em]">Genetic Source</div>
        </div>
        <div className="w-0.5 h-16 bg-gradient-to-b from-indigo-500/50 to-indigo-500/10 mt-4" />
      </div>

      {/* Niveles de Evolución con Ramificaciones */}
      {steps.map(([step, nodes]) => (
        <div key={step} className="flex flex-col items-center gap-16 w-full max-w-6xl">
          <div className="flex gap-8 sm:gap-16 justify-center flex-wrap px-4">
            {nodes.map(node => (
              <div key={node.id} className="relative flex flex-col items-center">
                {/* Línea que conecta con el padre (conceptual) */}
                <div className="absolute -top-16 w-0.5 h-16 bg-indigo-500/10" />
                <TreeNode outfit={node} onSelect={onSelect} isActive={activeId === node.id} />
              </div>
            ))}
          </div>
          {/* Línea hacia el siguiente nivel si existe */}
          <div className="w-0.5 h-16 bg-gradient-to-b from-indigo-500/10 to-indigo-500/5" />
        </div>
      ))}

      {outfits.length === 0 && (
        <p className="text-[10px] font-black uppercase tracking-[0.5em] text-slate-700 mt-10">Neural archive pending synchronization...</p>
      )}

      <div className="h-40 shrink-0" />
    </div>
  );
};

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ForgeConfig } from "../types";

/**
 * Servicio central optimizado para el motor SpriteForge Modular.
 */
export class GeminiService {
  /**
   * Proceso de purificación anatómica (Base DNA Extraction).
   */
  static async extractBaseDNA(sourceImage: string, config: ForgeConfig): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    const systemInstruction = `
      ACT AS SPRITEFORGE BASE EXTRACTOR.
      OBJECTIVE: Extract character mannequin (pure anatomy).

      RULES:
      1. Identify anatomy, skin and hair.
      2. Remove armor, weapons, and accessories.
      3. Draw character in simple base RPG underwear.
      4. Maintain pixel art scale and proportions.
      5. BACKGROUND: Solid #FF00FF (Magenta).
    `;

    const contents = {
      parts: [
        { inlineData: { data: this.stripBase64(sourceImage), mimeType: 'image/jpeg' } },
        { text: "GENERATE CHARACTER TEMPLATE. NO GEAR." }
      ]
    };

    try {
      const response: GenerateContentResponse = await ai.models.generateContent({
        model: config.model,
        contents,
        config: { systemInstruction, imageConfig: { aspectRatio: config.aspectRatio } },
      });

      const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (imagePart?.inlineData) return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
      throw new Error("Base extraction failed.");
    } catch (error: any) {
      throw new Error(`Neural Link Error: ${error.message}`);
    }
  }

  /**
   * Proceso de síntesis modular evolutiva.
   */
  static async synthesizeEvolution(baseImage: string, parentUrl: string | null, prompt: string, config: ForgeConfig): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    // ENSAMBLAJE MODULAR: Combinamos las instrucciones de todos los nodos activos
    const modularChainInstructions = config.neuralChain
      .filter(n => n.isActive)
      .map(n => `[MODULE ${n.id.toUpperCase()}]: ${n.instruction}`)
      .join('\n');

    const systemInstruction = `
      ERES EL MOTOR MODULAR SPRITEFORGE RPG.
      TU FUNCIÓN: Evolucionar el ADN base con nuevos atuendos.

      DIRECTIVAS NEURALES ACTIVAS:
      ${modularChainInstructions}

      REFERENCIAS CRÍTICAS:
      - REF A: ADN CANÓNICO (Anatomía base).
      - REF B: ESTADO ACTUAL (Para evoluciones de equipo).

      REQUISITO FINAL:
      - Renderiza "${prompt}" sobre la REF A.
      - Respeta estrictamente el Body Morphology Lock y el Identity DNA Lock.
    `;

    const contents: any = {
      parts: [
        { inlineData: { data: this.stripBase64(baseImage), mimeType: 'image/jpeg' } },
        { text: "REF A: CANONICAL DNA" }
      ]
    };

    if (parentUrl) {
      contents.parts.push({ inlineData: { data: this.stripBase64(parentUrl), mimeType: 'image/jpeg' } });
      contents.parts.push({ text: "REF B: CURRENT STATE" });
    }

    contents.parts.push({ text: `DIRECTIVE: Apply "${prompt}" evolution.` });

    try {
      const response: GenerateContentResponse = await ai.models.generateContent({
        model: config.model,
        contents,
        config: { 
          systemInstruction,
          imageConfig: { 
            aspectRatio: config.aspectRatio,
            ...(config.model === 'gemini-3-pro-image-preview' && { imageSize: config.size })
          }
        },
      });

      const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (imagePart?.inlineData) return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
      throw new Error("Synthesis failed.");
    } catch (error: any) {
      throw new Error(`Synthesis Link Failure: ${error.message}`);
    }
  }

  private static stripBase64(url: string): string {
    return url.split(',')[1] || url;
  }
}

