interface EvolutionTreeProps {
  outfits: GeneratedOutfit[];
  baseImage: string | null;
  activeId?: string;
  onSelect: (o: GeneratedOutfit) => void;
}

export const EvolutionTree: React.FC<EvolutionTreeProps> = ({ outfits, baseImage, activeId, onSelect }) => {
  // Organización jerárquica por parentId para crear ramas visuales
  const branches = useMemo(() => {
    const rootNodes = outfits.filter(o => !o.parentId);
    const map = new Map<string, GeneratedOutfit[]>();
    outfits.forEach(o => {
      if (o.parentId) {
        const children = map.get(o.parentId) || [];
        children.push(o);
        map.set(o.parentId, children);
      }
    });
    return { rootNodes, childrenMap: map };
  }, [outfits]);

  if (!baseImage) return null;

  return (
    <div className="h-full w-full bg-[#030303] overflow-auto relative no-scrollbar flex flex-col items-center py-20 px-8 gap-32">
      {/* ORIGEN GENÉTICO */}
      <div className="relative z-20 flex flex-col items-center">
        <div className="w-36 h-36 rounded-[4rem] border-2 border-indigo-600/30 bg-indigo-600/5 p-8 relative group transition-all">
          <div className="absolute inset-0 bg-indigo-600/10 blur-[80px] rounded-full opacity-40 group-hover:opacity-60 transition-opacity" />
          <img src={baseImage} className="w-full h-full object-contain relative z-10 opacity-40 grayscale group-hover:grayscale-0 group-hover:opacity-100 transition-all duration-700" style={{ imageRendering: 'pixelated' }} alt="Source" />
          <div className="absolute -top-10 left-1/2 -translate-x-1/2 text-[9px] font-black text-indigo-400/60 uppercase tracking-[0.6em] whitespace-nowrap">Source DNA</div>
        </div>
        <div className="w-0.5 h-16 bg-gradient-to-b from-indigo-500/50 to-indigo-500/10 mt-4" />
      </div>

      {/* RAMAS EVOLUTIVAS */}
      <div className="flex flex-col items-center gap-32 w-full max-w-5xl">
        <div className="flex flex-wrap gap-20 justify-center relative">
          {branches.rootNodes.map(node => (
            <div key={node.id} className="relative flex flex-col items-center gap-24">
              <TreeNode outfit={node} onSelect={onSelect} isActive={activeId === node.id} />

              {/* Renderizar Hijos de primer nivel */}
              {branches.childrenMap.get(node.id) && (
                <div className="flex gap-16 relative">
                  <div className="absolute -top-16 left-1/2 -translate-x-1/2 w-0.5 h-16 bg-indigo-500/10" />
                  {branches.childrenMap.get(node.id)!.map(child => (
                    <TreeNode key={child.id} outfit={child} onSelect={onSelect} isActive={activeId === child.id} />
                  ))}
                </div>
              )}
            </div>
          ))}
        </div>
      </div>

      {outfits.length === 0 && (
        <p className="text-[10px] font-black uppercase tracking-[0.5em] text-slate-700 mt-20">Neural Forge Idle: Awaiting first synthesis</p>
      )}

      {/* Grid de fondo técnica */}
      <div className="fixed inset-0 pointer-events-none opacity-[0.02] checker-bg z-0" />
      <div className="h-40 shrink-0" />
    </div>
  );
};

