                  <button 
                    key={cat.category} onClick={() => setActiveCategory(cat.category)}
                    className={`whitespace-nowrap text-[8px] font-black uppercase tracking-[0.2em] pb-2 transition-all ${activeCategory === cat.category ? 'text-indigo-400 border-b-2 border-indigo-500' : 'text-slate-600'}`}
