export const Atelier: React.FC<AtelierProps> = ({ 
  state, prompt, setPrompt, onUpload, onForge, onExtractBase, onResetParent, onUpdateMutation, onSetMode, onApplyMacro
}) => {
  const [activeCategory, setActiveCategory] = useState(QUICK_TAGS[0].category);
  const [isControlsExpanded, setIsControlsExpanded] = useState(false);
  const [isDesktop, setIsDesktop] = useState(window.innerWidth >= 768);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleResize = () => setIsDesktop(window.innerWidth >= 768);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const backgroundTheme = useMemo(() => {
    const bg = state.config.protocols.backgroundStyle;
    if (bg === 'magenta') return 'bg-[#FF00FF]';
    if (bg === 'white') return 'bg-white';
    return 'bg-[#0a0a0a]';
  }, [state.config.protocols.backgroundStyle]);

  if (!state.baseImage) {
    return (
      <div className="h-full flex items-center justify-center p-8 bg-[#050505] safe-top safe-bottom">
        <div 
          onClick={() => fileInputRef.current?.click()}
          className="w-full max-w-sm aspect-square border-2 border-dashed border-indigo-500/20 rounded-[3rem] bg-indigo-500/5 flex flex-col items-center justify-center cursor-pointer hover:bg-indigo-500/10 transition-all active:scale-[0.98] group"
