              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
            </svg>
          </div>
          <span className="text-[13px] font-black uppercase tracking-[0.4em] text-white">Neural Intake</span>
          <p className="text-[8px] font-bold text-slate-500 uppercase tracking-widest mt-2 text-center px-10 leading-relaxed opacity-60">
