          </p>
          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => {
            const file = e.target.files?.[0];
            if (file) {
              const reader = new FileReader();
              reader.onload = () => onUpload(reader.result as string);
              reader.readAsDataURL(file);
            }
          }} />
        </div>
      </div>
    );
  }

  const Controls = () => (
    <div className="flex flex-col gap-6 h-full overflow-hidden">
      <div className="shrink-0">
        <Slider label="Mutation Pressure" value={state.config.mutationStrength} min={0} max={100} onChange={onUpdateMutation} />
      </div>

      <div className="flex-1 flex flex-col gap-4 min-h-0">
        <textarea 
          value={prompt} onChange={(e) => setPrompt(e.target.value)}
          placeholder="Describre el outfit o usa los tags..."
          className="w-full h-full bg-black/40 border border-white/5 rounded-2xl p-4 text-[14px] text-white focus:border-indigo-500/40 transition-all outline-none resize-none font-medium placeholder:text-slate-700 no-scrollbar"
        />

        <div className="flex flex-col gap-3 shrink-0">
          <div className="flex gap-4 overflow-x-auto no-scrollbar border-b border-white/5 pb-1">
            {QUICK_TAGS.map(cat => (
              <button 
                key={cat.category} onClick={() => setActiveCategory(cat.category)}
                className={`whitespace-nowrap text-[8px] md:text-[9px] font-black uppercase tracking-[0.2em] pb-2 transition-all ${activeCategory === cat.category ? 'text-indigo-400 border-b-2 border-indigo-500' : 'text-slate-600'}`}
              >
                {cat.category}
              </button>
            ))}
          </div>
          <div className="flex flex-wrap gap-2 overflow-y-auto max-h-24 md:max-h-none no-scrollbar">
            {QUICK_TAGS.find(c => c.category === activeCategory)?.tags.map(tag => (
              <Tag key={tag} label={tag} onClick={() => setPrompt(prompt ? `${prompt}, ${tag}` : tag)} />
            ))}
          </div>
        </div>
      </div>

      <button 
        onClick={onForge} disabled={state.isGenerating || !prompt}
        className="w-full py-5 bg-indigo-600 disabled:bg-slate-900 rounded-2xl font-black text-[13px] uppercase tracking-[0.4em] text-white shadow-2xl active:scale-[0.97] transition-all shrink-0 border border-indigo-400/20"
      >
        {state.isGenerating ? 'Synthesizing...' : 'Execute Forge'}
      </button>
    </div>
  );

  return (
    <div className="h-full flex flex-col md:flex-row overflow-hidden bg-black">
      {/* 1. VIEWPORT */}
      <div className={`flex-1 relative overflow-hidden transition-colors duration-500 ${backgroundTheme}`}>
        <div className="absolute inset-0 opacity-[0.05] checker-bg pointer-events-none" />

        <div className="absolute top-12 left-6 right-6 flex justify-between items-start z-30 safe-top">
          <div className="flex flex-col gap-2">
            <div className={`px-3 py-1 rounded-full border bg-black/40 backdrop-blur-md flex items-center gap-2 ${state.isGenerating ? 'border-indigo-500/50' : 'border-white/10'}`}>
              <div className={`w-1.5 h-1.5 rounded-full ${state.isGenerating ? 'bg-indigo-500 animate-pulse' : 'bg-emerald-500'}`} />
              <span className="text-[7px] font-black uppercase tracking-widest text-white">
                {state.isGenerating ? 'SYNTHESIZING' : 'LINK READY'}
              </span>
            </div>
            {state.activeParent && (
              <div className="px-3 py-1 rounded-full border border-white/10 bg-black/40 backdrop-blur-md self-start">
                <span className="text-[7px] font-black uppercase tracking-widest text-indigo-400">Step {state.activeParent.evolutionStep}</span>
              </div>
            )}
          </div>

          <IconButton variant="primary" onClick={onResetParent} className="bg-black/40 backdrop-blur-md rounded-2xl w-12 h-12">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
            </svg>
          </IconButton>
        </div>

        <div className="absolute inset-0 flex items-center justify-center p-4">
          {state.activeParent ? (
            <ComparisonSlider before={state.baseImage} after={state.activeParent.url} className="w-full h-full" />
          ) : (
            <img 
              src={state.baseImage} 
              style={{ imageRendering: 'pixelated', transform: isDesktop ? 'scale(2.5)' : 'scale(1.5)' }}
              className="max-h-[70%] max-w-[80%] object-contain relative z-10 transition-transform duration-700" 
              alt="Source" 
            />
          )}
        </div>

        {/* Anatomical Macros */}
        <div className="absolute left-4 md:left-8 bottom-1/3 md:bottom-1/2 md:translate-y-1/2 flex flex-col gap-5 z-40">
          {ANATOMICAL_MACROS.map(macro => (
            <div key={macro.id} className="flex flex-col items-center gap-1.5 group">
              <button 
                onClick={() => onApplyMacro(macro)}
                className={`w-14 md:w-16 h-14 md:h-16 rounded-2xl flex items-center justify-center backdrop-blur-xl border transition-all active:scale-90 shadow-2xl ${state.config.activeMacroId === macro.id ? `bg-indigo-600 border-indigo-400 shadow-[0_0_20px_rgba(99,102,241,0.5)]` : 'bg-black/40 border-white/10 hover:border-white/30'}`}
              >
                <MacroIcon type={macro.icon} />
              </button>
              <span className={`text-[7px] font-black uppercase tracking-widest transition-opacity group-hover:opacity-100 ${isDesktop ? 'opacity-0' : 'opacity-100'} ${state.config.activeMacroId === macro.id ? 'text-indigo-400 opacity-100' : 'text-slate-500'}`}>
                {macro.name.split(' ')[0]}
              </span>
            </div>
          ))}
        </div>

        <NeuralLog active={state.isGenerating} />
        {state.isGenerating && <Loader message="Accessing Neural Chain..." />}
      </div>

      {/* 2. CONTROL PANEL (Responsive) */}
      {isDesktop ? (
        <aside className="w-[450px] bg-[#080808] border-l border-white/5 p-10 flex flex-col gap-8 shrink-0 relative z-[100] shadow-[-20px_0_50px_rgba(0,0,0,0.5)]">
           <div className="flex items-center gap-4 mb-4">
             <div className="w-10 h-1 bg-indigo-600 rounded-full" />
             <span className="text-[12px] font-black uppercase tracking-[0.4em] text-white">Synthesizer Core</span>
           </div>
           <div className="flex-1">
            <Controls />
           </div>
        </aside>
      ) : (
        <div className={`bg-[#080808] border-t border-white/10 flex flex-col transition-all duration-500 ease-in-out z-[100] safe-bottom ${isControlsExpanded ? 'h-[75vh]' : 'h-[320px]'}`}>
          <div 
            onClick={() => setIsControlsExpanded(!isControlsExpanded)}
            className="h-8 flex items-center justify-center cursor-pointer group shrink-0"
          >
            <div className={`w-12 h-1 rounded-full transition-colors ${isControlsExpanded ? 'bg-indigo-500' : 'bg-white/10 group-hover:bg-white/20'}`} />
          </div>
          <div className="flex-1 px-5 pb-6 overflow-hidden">
            <Controls />
          </div>
        </div>
      )}
    </div>
  );
};

