        <div 
          onClick={() => fileInputRef.current?.click()}
          className="w-full max-w-sm aspect-square border-2 border-dashed border-indigo-500/20 rounded-[3rem] bg-indigo-500/5 flex flex-col items-center justify-center cursor-pointer hover:bg-indigo-500/10 transition-all active:scale-[0.98] group"
        >
          <div className="w-20 h-20 bg-indigo-600 rounded-[1.5rem] flex items-center justify-center mb-6 shadow-2xl shadow-indigo-600/40">
            <svg className="w-8 h-8 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
            </svg>
          </div>
          <span className="text-[13px] font-black uppercase tracking-[0.4em] text-white">Neural Intake</span>
          <p className="text-[8px] font-bold text-slate-500 uppercase tracking-widest mt-2 text-center px-10 leading-relaxed opacity-60">
            Carga el sprite para iniciar el pipeline de 29 módulos
          </p>
          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => {
            const file = e.target.files?.[0];
            if (file) {
              const reader = new FileReader();
              reader.onload = () => onUpload(reader.result as string);
              reader.readAsDataURL(file);
            }
          }} />
        </div>
      </div>
    );
  }

  const Controls = () => (
    <div className="flex flex-col gap-6 h-full overflow-hidden">
      <div className="shrink-0">
        <Slider label="Mutation Pressure" value={state.config.mutationStrength} min={0} max={100} onChange={onUpdateMutation} />
      </div>

      <div className="flex-1 flex flex-col gap-4 min-h-0">
        <textarea 
          value={prompt} onChange={(e) => setPrompt(e.target.value)}
          placeholder="Describre el outfit o usa los tags..."
          className="w-full h-full bg-black/40 border border-white/5 rounded-2xl p-4 text-[14px] text-white focus:border-indigo-500/40 transition-all outline-none resize-none font-medium placeholder:text-slate-700 no-scrollbar"
        />

        <div className="flex flex-col gap-3 shrink-0">
          <div className="flex gap-4 overflow-x-auto no-scrollbar border-b border-white/5 pb-1">
            {QUICK_TAGS.map(cat => (
              <button 
                key={cat.category} onClick={() => setActiveCategory(cat.category)}
                className={`whitespace-nowrap text-[8px] md:text-[9px] font-black uppercase tracking-[0.2em] pb-2 transition-all ${activeCategory === cat.category ? 'text-indigo-400 border-b-2 border-indigo-500' : 'text-slate-600'}`}
              >
                {cat.category}
              </button>
            ))}
          </div>
          <div className="flex flex-wrap gap-2 overflow-y-auto max-h-24 md:max-h-none no-scrollbar">
            {QUICK_TAGS.find(c => c.category === activeCategory)?.tags.map(tag => (
              <Tag key={tag} label={tag} onClick={() => setPrompt(prompt ? `${prompt}, ${tag}` : tag)} />
            ))}
          </div>
        </div>
      </div>

      <button 
        onClick={onForge} disabled={state.isGenerating || !prompt}
        className="w-full py-5 bg-indigo-600 disabled:bg-slate-900 rounded-2xl font-black text-[13px] uppercase tracking-[0.4em] text-white shadow-2xl active:scale-[0.97] transition-all shrink-0 border border-indigo-400/20"
      >
        {state.isGenerating ? 'Synthesizing...' : 'Execute Forge'}
      </button>
    </div>
  );

  return (
    <div className="h-full flex flex-col md:flex-row overflow-hidden bg-black">
      {/* 1. VIEWPORT */}
      <div className={`flex-1 relative overflow-hidden transition-colors duration-500 ${backgroundTheme}`}>
        <div className="absolute inset-0 opacity-[0.05] checker-bg pointer-events-none" />

        <div className="absolute top-12 left-6 right-6 flex justify-between items-start z-30 safe-top">
          <div className="flex flex-col gap-2">
            <div className={`px-3 py-1 rounded-full border bg-black/40 backdrop-blur-md flex items-center gap-2 ${state.isGenerating ? 'border-indigo-500/50' : 'border-white/10'}`}>
              <div className={`w-1.5 h-1.5 rounded-full ${state.isGenerating ? 'bg-indigo-500 animate-pulse' : 'bg-emerald-500'}`} />
              <span className="text-[7px] font-black uppercase tracking-widest text-white">
                {state.isGenerating ? 'SYNTHESIZING' : 'LINK READY'}
              </span>
            </div>
            {state.activeParent && (
              <div className="px-3 py-1 rounded-full border border-white/10 bg-black/40 backdrop-blur-md self-start">
                <span className="text-[7px] font-black uppercase tracking-widest text-indigo-400">Step {state.activeParent.evolutionStep}</span>
              </div>
            )}
          </div>

          <div className="flex gap-2">
            {state.activeParent && (
              <IconButton 
                variant="success" 
                onClick={() => onPromoteToBase(state.activeParent!.url)} 
                className="bg-black/40 backdrop-blur-md rounded-2xl w-12 h-12 border-emerald-500/30"
                title="Promote to Base DNA"
              >
                <svg className="w-5 h-5 text-emerald-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M5 11l7-7 7 7M5 19l7-7 7 7" />
                </svg>
              </IconButton>
            )}
            <IconButton variant="primary" onClick={handleDownload} className="bg-black/40 backdrop-blur-md rounded-2xl w-12 h-12">
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
              </svg>
            </IconButton>
            <IconButton variant="danger" onClick={onResetParent} className="bg-black/40 backdrop-blur-md rounded-2xl w-12 h-12">
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
              </svg>
            </IconButton>
          </div>
        </div>

        <div className="absolute inset-0 flex items-center justify-center p-4">
          {state.activeParent ? (
            <ComparisonSlider before={state.baseImage} after={state.activeParent.url} className="w-full h-full" />
          ) : (
            <img 
              src={state.baseImage} 
              style={{ imageRendering: 'pixelated', transform: isDesktop ? 'scale(2.5)' : 'scale(1.5)' }}
              className="max-h-[70%] max-w-[80%] object-contain relative z-10 transition-transform duration-700" 
              alt="Source" 
            />
          )}
        </div>

        {/* Anatomical Macros */}
        <div className="absolute left-4 md:left-8 bottom-1/3 md:bottom-1/2 md:translate-y-1/2 flex flex-col gap-5 z-40">
          {ANATOMICAL_MACROS.map(macro => (
            <div key={macro.id} className="flex flex-col items-center gap-1.5 group">
              <button 
                onClick={() => onApplyMacro(macro)}
                className={`w-14 md:w-16 h-14 md:h-16 rounded-2xl flex items-center justify-center backdrop-blur-xl border transition-all active:scale-90 shadow-2xl ${state.config.activeMacroId === macro.id ? `bg-indigo-600 border-indigo-400 shadow-[0_0_20px_rgba(99,102,241,0.5)]` : 'bg-black/40 border-white/10 hover:border-white/30'}`}
              >
                <MacroIcon type={macro.icon} />
              </button>
              <span className={`text-[7px] font-black uppercase tracking-widest transition-opacity group-hover:opacity-100 ${isDesktop ? 'opacity-0' : 'opacity-100'} ${state.config.activeMacroId === macro.id ? 'text-indigo-400 opacity-100' : 'text-slate-500'}`}>
                {macro.name.split(' ')[0]}
              </span>
            </div>
          ))}
        </div>

        <NeuralLog active={state.isGenerating} />
        {state.isGenerating && <Loader message="Accessing Neural Chain..." />}
      </div>

      {/* 2. CONTROL PANEL (Responsive) */}
      {isDesktop ? (
        <aside className="w-[450px] bg-[#080808] border-l border-white/5 p-10 flex flex-col gap-8 shrink-0 relative z-[100] shadow-[-20px_0_50px_rgba(0,0,0,0.5)]">
           <div className="flex items-center gap-4 mb-4">
             <div className="w-10 h-1 bg-indigo-600 rounded-full" />
             <span className="text-[12px] font-black uppercase tracking-[0.4em] text-white">Synthesizer Core</span>
           </div>
           <div className="flex-1">
            <Controls />
           </div>
        </aside>
      ) : (
        <div className={`bg-[#080808] border-t border-white/10 flex flex-col transition-all duration-500 ease-in-out z-[100] safe-bottom ${isControlsExpanded ? 'h-[75vh]' : 'h-[320px]'}`}>
          <div 
            onClick={() => setIsControlsExpanded(!isControlsExpanded)}
            className="h-8 flex items-center justify-center cursor-pointer group shrink-0"
          >
            <div className={`w-12 h-1 rounded-full transition-colors ${isControlsExpanded ? 'bg-indigo-500' : 'bg-white/10 group-hover:bg-white/20'}`} />
          </div>
          <div className="flex-1 px-5 pb-6 overflow-hidden">
            <Controls />
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useSpriteForge } from './hooks/useSpriteForge';
import { Atelier } from './components/Atelier';
import { Vault } from './components/Vault';
import { EvolutionTree } from './components/EvolutionTree';
import { IconButton } from './components/UI';
import { ImageModal } from './components/ImageModal';
import { GeneratedOutfit, ForgeMode, NeuralMacro } from './types';
import { ANATOMICAL_MACROS } from './constants';

const App: React.FC = () => {
  const { state, dispatch, uploadBaseDNA, executeBaseExtraction, executeSynthesis, deleteAsset } = useSpriteForge();

  const [prompt, setPrompt] = useState('');
  const [isConfigOpen, setIsConfigOpen] = useState(false);
  const [activeTab, setActiveTab] = useState<'forge' | 'vault' | 'tree'>('forge');
  const [selectedOutfit, setSelectedOutfit] = useState<GeneratedOutfit | null>(null);
  const [isDesktop, setIsDesktop] = useState(window.innerWidth >= 768);

  useEffect(() => {
    const handleResize = () => setIsDesktop(window.innerWidth >= 768);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleSelectAsset = (outfit: GeneratedOutfit) => setSelectedOutfit(outfit);

  const handleApplyAsParent = (outfit: GeneratedOutfit) => {
    dispatch({ type: 'SET_ACTIVE_PARENT', payload: outfit });
    setPrompt(outfit.prompt || '');
    setActiveTab('forge');
  };

  const handlePromoteToBase = (url: string) => {
    if (confirm("Promote this sprite as the new genetic baseline? This will restart the current linear evolution chain from this image.")) {
      dispatch({ type: 'SET_BASE_IMAGE', payload: url });
    }
  };

  const handleApplyMacro = (macro: NeuralMacro) => {
    const resetChain = state.config.neuralChain.map(node => ({ ...node, isActive: true }));
    const newChain = resetChain.map(node => ({
      ...node,
      isActive: !macro.nodesToDisable.includes(node.id)
    }));

    dispatch({ 
      type: 'UPDATE_CONFIG', 
      payload: { 
        neuralChain: newChain,
        mutationStrength: macro.mutationStrength,
        activeMacroId: macro.id
      } 
    });

    if (macro.promptSuffix && !prompt.includes(macro.promptSuffix)) {
       setPrompt(prev => prev ? `${prev}, ${macro.promptSuffix}` : macro.promptSuffix);
    }
  };

  const SidebarItem = ({ tab, icon, label }: { tab: typeof activeTab; icon: React.ReactNode; label: string }) => (
    <button 
      onClick={() => setActiveTab(tab)} 
      className={`w-full flex items-center gap-4 px-6 py-4 transition-all border-r-2 ${
        activeTab === tab 
        ? 'bg-indigo-600/10 border-indigo-500 text-indigo-400' 
        : 'border-transparent text-slate-500 hover:text-white hover:bg-white/5'
      }`}
    >
      <div className={`${activeTab === tab ? 'scale-110' : ''} transition-transform`}>{icon}</div>
      <span className="text-[10px] font-black uppercase tracking-[0.2em]">{label}</span>
    </button>
  );

  return (
    <div className="fixed inset-0 flex bg-[#020202] text-[#f8fafc] font-sans overflow-hidden">

      {/* DESKTOP SIDEBAR */}
      {isDesktop && (
        <aside className="w-72 bg-[#050505] border-r border-white/5 flex flex-col shrink-0 z-50">
          <div className="h-20 px-8 flex items-center border-b border-white/5">
            <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-600/30 mr-3">
              <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" />
              </svg>
            </div>
            <h1 className="text-[10px] font-black uppercase tracking-[0.3em]">
              SpriteForge <span className="text-indigo-500">RPG</span>
            </h1>
          </div>

          <nav className="flex-1 py-10 flex flex-col gap-2">
            <SidebarItem tab="forge" label="Neural Atelier" icon={
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
            } />
            <SidebarItem tab="vault" label="Genetic Vault" icon={
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M5 8h14M5 8a2 2 0 110-4h14a2 2 0 110 4M5 8v10a2 2 0 002 2h10a2 2 0 002-2V8m-9 4h4" /></svg>
            } />
            <SidebarItem tab="tree" label="Evolution Tree" icon={
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" /></svg>
            } />
          </nav>

          <div className="p-8 border-t border-white/5">
            <button 
              onClick={() => setIsConfigOpen(true)}
              className="w-full flex items-center justify-between px-6 py-4 bg-white/5 border border-white/10 rounded-2xl text-[9px] font-black uppercase tracking-widest text-slate-400 hover:text-white hover:border-indigo-500/50 transition-all"
            >
              <span>Chain Status</span>
              <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse" />
            </button>
          </div>
        </aside>
      )}

      {/* Main Content Area */}
      <div className="flex-1 relative flex flex-col min-w-0">
        <main className="flex-1 relative overflow-hidden">
          {activeTab === 'forge' && (
            <Atelier 
              state={state} prompt={prompt} setPrompt={setPrompt}
              onUpload={uploadBaseDNA}
              onForge={() => executeSynthesis(prompt)}
              onExtractBase={executeBaseExtraction}
              onResetParent={() => dispatch({ type: 'SET_ACTIVE_PARENT', payload: null })}
              onUpdateMutation={(v) => dispatch({ type: 'UPDATE_CONFIG', payload: { mutationStrength: v, activeMacroId: undefined } })}
              onSetMode={(m) => dispatch({ type: 'SET_FORGE_MODE', payload: m })}
              onApplyMacro={handleApplyMacro}
              onPromoteToBase={handlePromoteToBase}
            />
          )}

          {activeTab === 'vault' && (
            <div className="h-full bg-[#050505] animate-in fade-in duration-300 flex flex-col">
              <header className="h-16 md:h-20 px-6 md:px-12 flex items-center justify-between border-b border-white/5 safe-top shrink-0">
                <div className="flex flex-col">
                  <span className="text-[10px] font-black uppercase tracking-[0.4em] text-indigo-400">Genetic Archive</span>
                  <p className="text-[8px] font-bold text-slate-600 uppercase tracking-widest hidden md:block">Storage of all neural evolutions</p>
                </div>
              </header>
              <div className="flex-1 overflow-hidden">
                <Vault outfits={state.outfits} activeId={state.activeParent?.id} onSelect={handleSelectAsset} onDelete={deleteAsset} />
              </div>
            </div>
          )}

          {activeTab === 'tree' && (
            <div className="h-full bg-[#030303] animate-in fade-in zoom-in-95 duration-500">
              <EvolutionTree outfits={state.outfits} baseImage={state.baseImage} activeId={state.activeParent?.id} onSelect={handleSelectAsset} />
            </div>
          )}
        </main>

        {/* MOBILE TAB BAR: Solo visible en mobile */}
        {!isDesktop && (
          <nav className="h-20 bg-black/80 backdrop-blur-3xl border-t border-white/10 flex items-center justify-around px-6 safe-bottom shrink-0 z-[1000]">
            <button onClick={() => setActiveTab('forge')} className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'forge' ? 'text-indigo-500 scale-110' : 'text-slate-600'}`}>
              <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
              <span className="text-[7px] font-black uppercase tracking-widest">Atelier</span>
            </button>
            <button onClick={() => setActiveTab('vault')} className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'vault' ? 'text-indigo-500 scale-110' : 'text-slate-600'}`}>
              <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M5 8h14M5 8a2 2 0 110-4h14a2 2 0 110 4M5 8v10a2 2 0 002 2h10a2 2 0 002-2V8m-9 4h4" /></svg>
              <span className="text-[7px] font-black uppercase tracking-widest">Vault</span>
            </button>
            <button onClick={() => setActiveTab('tree')} className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'tree' ? 'text-indigo-500 scale-110' : 'text-slate-600'}`}>
              <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" /></svg>
              <span className="text-[7px] font-black uppercase tracking-widest">Tree</span>
            </button>
            <button onClick={() => setIsConfigOpen(true)} className="flex flex-col items-center gap-1 text-slate-600 active:text-white transition-all">
              <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4" /></svg>
              <span className="text-[7px] font-black uppercase tracking-widest">Chain</span>
            </button>
          </nav>
        )}
      </div>

      {/* Modals & Overlays */}
      {selectedOutfit && (
        <ImageModal outfit={selectedOutfit} onClose={() => setSelectedOutfit(null)} onDelete={deleteAsset} onSelectAsParent={handleApplyAsParent} />
      )}

      {isConfigOpen && (
        <div className="fixed inset-0 z-[2100] animate-in fade-in duration-300 flex items-end md:items-center justify-center">
          <div className="absolute inset-0 bg-black/98 backdrop-blur-xl" onClick={() => setIsConfigOpen(false)} />
          <div className="relative w-full md:max-w-2xl bg-[#0a0a0a] rounded-t-[3rem] md:rounded-[3rem] p-8 md:p-12 border-t md:border border-white/10 animate-in slide-in-from-bottom duration-500 max-h-[85vh] overflow-y-auto no-scrollbar safe-bottom">
            <div className="w-12 h-1 bg-white/10 rounded-full mx-auto mb-8 md:hidden" />
            <div className="flex items-center justify-between mb-10">
              <h3 className="text-[12px] md:text-[14px] font-black uppercase tracking-[0.4em] text-indigo-400 border-l-4 border-indigo-600 px-4">Chain Configuration</h3>
              <button onClick={() => setIsConfigOpen(false)} className="hidden md:block text-slate-500 hover:text-white uppercase text-[10px] font-black tracking-widest">Close</button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              {state.config.neuralChain.map(node => (
                <button 
                  key={node.id} disabled={node.isLocked} onClick={() => dispatch({ type: 'TOGGLE_NODE', payload: node.id })}
                  className={`flex items-center justify-between p-4 rounded-2xl border-2 transition-all active:scale-[0.98] ${node.isActive ? 'bg-indigo-600/10 border-indigo-500/40 text-white' : 'bg-white/5 border-transparent text-slate-600 opacity-40'}`}
                >
                  <div className="text-left">
                    <p className="text-[9px] md:text-[10px] font-black uppercase tracking-widest">{node.label}</p>
                    <p className="text-[7px] md:text-[8px] font-bold opacity-40 uppercase mt-0.5">{node.description}</p>
                  </div>
                  {node.isActive && <div className="w-2 h-2 bg-indigo-500 rounded-full shadow-[0_0_10px_#6366f1]" />}
                </button>
              ))}
            </div>
            <div className="h-10 md:hidden" />
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useMemo, useEffect } from 'react';
import { AppState, ForgeMode, NeuralMacro } from '../types';
import { QUICK_TAGS, ANATOMICAL_MACROS } from '../constants';
import { IconButton, Tag, Loader, ComparisonSlider, NeuralLog, Slider } from './UI';

interface AtelierProps {
  state: AppState;
  prompt: string;
  setPrompt: (v: string) => void;
  onUpload: (url: string) => void;
  onForge: () => void;
  onExtractBase: (url: string) => void;
  onResetParent: () => void;
  onUpdateMutation: (v: number) => void;
  onSetMode: (mode: ForgeMode) => void;
  onApplyMacro: (macro: NeuralMacro) => void;
  onPromoteToBase: (url: string) => void;
}

const MacroIcon = ({ type }: { type: string }) => {
  switch (type) {
    case 'ENHANCE':
      return (
        <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" />
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M16 8l-4-4-4 4" />
        </svg>
      );
    case 'REDUCE':
      return (
        <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M20 12H4" />
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M8 16l4 4 4-4" />
        </svg>
      );
    case 'LOCK':
      return (
        <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
