import React, { useState, useRef, useMemo, useEffect } from 'react';
import { AppState, ForgeMode, NeuralMacro } from '../types';
import { QUICK_TAGS, ANATOMICAL_MACROS } from '../constants';
import { IconButton, Tag, Loader, ComparisonSlider, NeuralLog, Slider, InfoBadge } from './UI';
import { GeminiService } from '../services/geminiService';

interface AtelierProps {
  state: AppState;
  prompt: string;
  setPrompt: (v: string) => void;
  onUpload: (url: string) => void;
  onForge: () => void;
  onExtractBase: (url: string) => void;
  onResetParent: () => void;
  onUpdateMutation: (v: number) => void;
  onSetMode: (mode: ForgeMode) => void;
  onApplyMacro: (macro: NeuralMacro) => void;
  onPromoteToBase: (url: string) => void;
  hasApiKey: boolean;
}

export const Atelier: React.FC<AtelierProps> = ({ 
  state, prompt, setPrompt, onUpload, onForge, onExtractBase, onResetParent, onUpdateMutation, onSetMode, onApplyMacro, onPromoteToBase, hasApiKey
}) => {
  const [activeCategory, setActiveCategory] = useState(QUICK_TAGS[0].category);
  const [isControlsExpanded, setIsControlsExpanded] = useState(false);
  const [isAlchemizing, setIsAlchemizing] = useState(false);
  const [isDesktop, setIsDesktop] = useState(window.innerWidth >= 768);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleResize = () => setIsDesktop(window.innerWidth >= 768);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleAlchemy = async () => {
    if (!prompt) return;
    setIsAlchemizing(true);
    try {
      const enhanced = await GeminiService.enhancePrompt(prompt);
      setPrompt(enhanced);
    } finally {
      setIsAlchemizing(false);
    }
  };

  const currentStatusText = useMemo(() => {
    if (!state.baseImage) return "Sube un personaje";
    if (state.isGenerating) return "Forjando equipo...";
    if (!hasApiKey) return "Vincular llave para empezar";
    return "Sistema Listo";
  }, [state.baseImage, state.isGenerating, hasApiKey]);

  if (!state.baseImage) {
    return (
      <div className="absolute inset-0 bg-[#050505] overflow-y-auto safe-top safe-bottom">
        <div className="min-h-full flex flex-col items-center p-8 pb-32 md:justify-center">
          <div className="mb-12 text-center max-w-xs">
            <h2 className="text-[14px] font-black uppercase tracking-[0.5em] text-white mb-3">SpriteForge Initializer</h2>
            <p className="text-[9px] font-bold text-slate-500 uppercase tracking-widest leading-relaxed">Sube el maniquí o sprite base para empezar el proceso de forja neural.</p>
          </div>
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="group relative w-full max-w-sm h-64 border-2 border-dashed border-indigo-500/20 rounded-[3rem] bg-indigo-500/5 flex flex-col items-center justify-center cursor-pointer hover:bg-indigo-500/10 transition-all active:scale-[0.98]"
          >
            <div className="w-20 h-20 bg-indigo-600 rounded-[1.5rem] flex items-center justify-center mb-6 shadow-2xl shadow-indigo-600/40 group-hover:scale-110 transition-transform">
              <svg className="w-8 h-8 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
            </div>
            <span className="text-[13px] font-black uppercase tracking-[0.4em] text-white">Cargar Sprite Base</span>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => {
              const file = e.target.files?.[0];
              if (file) {
                const reader = new FileReader();
                reader.onload = () => onUpload(reader.result as string);
                reader.readAsDataURL(file);
              }
            }} />
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col md:flex-row overflow-hidden bg-black">
      <div className={`flex-1 relative overflow-hidden transition-colors duration-500 bg-[#0a0a0a]`}>
        <div className="absolute inset-0 opacity-[0.05] checker-bg pointer-events-none" />
        <div className="absolute top-12 left-6 right-6 flex justify-between items-start z-30 safe-top">
          <div className={`px-4 py-2 rounded-full border bg-black/60 backdrop-blur-md flex items-center gap-3 ${hasApiKey ? 'border-indigo-500/50' : 'border-amber-500/50'}`}>
            <div className={`w-2 h-2 rounded-full ${state.isGenerating ? 'bg-indigo-500 animate-pulse' : hasApiKey ? 'bg-emerald-500' : 'bg-amber-500'}`} />
            <span className="text-[8px] font-black uppercase tracking-[0.2em] text-white">{currentStatusText}</span>
          </div>
          <div className="flex gap-2">
            <IconButton variant="primary" onClick={onResetParent} className="bg-black/40 backdrop-blur-md rounded-2xl w-12 h-12"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg></IconButton>
          </div>
        </div>

        <div className="absolute inset-0 flex items-center justify-center p-4">
          {state.activeParent ? (
            <ComparisonSlider before={state.baseImage} after={state.activeParent.url} className="w-full h-full" />
          ) : (
            <div className="relative group">
               <img 
                src={state.baseImage} 
                style={{ imageRendering: 'pixelated', transform: isDesktop ? 'scale(2.5)' : 'scale(1.8)' }}
                className="max-h-[70%] max-w-[80%] object-contain relative z-10 transition-transform duration-1000" 
                alt="Mannequin" 
              />
            </div>
          )}
        </div>

        <NeuralLog active={state.isGenerating} />
        {state.isGenerating && <Loader message="Sintetizando..." />}
      </div>

      <aside className={`md:w-[450px] bg-[#080808] border-l border-white/5 p-6 md:p-10 flex flex-col gap-6 shrink-0 relative z-[100]`}>
        <div className="flex-1 flex flex-col gap-6 overflow-y-auto no-scrollbar">
          <section>
            <div className="flex justify-between items-center mb-4">
              <span className="text-[9px] font-black uppercase tracking-[0.2em] text-indigo-400">Directiva Neural</span>
              <button onClick={handleAlchemy} disabled={isAlchemizing || !prompt} className={`flex items-center gap-2 px-3 py-1.5 rounded-lg border transition-all ${isAlchemizing ? 'bg-indigo-600 animate-pulse border-white/20' : 'bg-white/5 border-white/10 hover:border-indigo-500'}`}>
                <span className="text-[8px] font-black uppercase tracking-widest text-white">{isAlchemizing ? 'Procesando...' : 'Alquimia IA'}</span>
              </button>
            </div>
            <textarea value={prompt} onChange={(e) => setPrompt(e.target.value)} placeholder="Ej: Armadura rúnica..." className="w-full h-32 bg-black/40 border border-white/5 rounded-2xl p-4 text-[14px] text-white focus:border-indigo-500/40 transition-all outline-none resize-none" />
          </section>

          <section className="space-y-4">
            <div className="flex flex-wrap gap-2">
              {QUICK_TAGS[0].tags.map(tag => (
                <Tag key={tag} label={tag} onClick={() => setPrompt(prompt ? `${prompt}, ${tag}` : tag)} />
              ))}
            </div>
          </section>

          <section className="space-y-6">
            <Slider label="Fuerza de Mutación" value={state.config.mutationStrength} min={0} max={100} onChange={onUpdateMutation} />
            <div className="flex items-center gap-4 bg-white/5 p-4 rounded-2xl border border-white/5">
              <div className="flex flex-col">
                <span className="text-[8px] font-black text-indigo-400 uppercase">Nivel Activo</span>
                <span className="text-[10px] font-black text-white uppercase">{state.config.model === 'gemini-2.5-flash-image' ? 'ESTÁNDAR (Free)' : 'PREMIUM (HD)'}</span>
              </div>
              <div className="ml-auto flex items-center gap-2">
                 <div className={`w-1.5 h-1.5 rounded-full ${hasApiKey ? 'bg-emerald-500' : 'bg-amber-500'}`} />
                 <span className="text-[7px] font-bold text-slate-500 uppercase">{hasApiKey ? 'KEY OK' : 'NO KEY'}</span>
              </div>
            </div>
          </section>
        </div>

        {state.error && (
          <div className="bg-red-500/10 border border-red-500/20 p-4 rounded-xl text-red-400 text-[9px] font-black uppercase tracking-widest">
            ERROR: {state.error}
          </div>
        )}

        <button 
          onClick={onForge} disabled={state.isGenerating || !prompt}
          className={`w-full py-5 rounded-2xl font-black text-[13px] uppercase tracking-[0.4em] text-white shadow-2xl active:scale-[0.97] transition-all border border-indigo-400/20 ${!prompt ? 'bg-slate-900 cursor-not-allowed opacity-50' : 'bg-indigo-600 hover:bg-indigo-500 animate-pulse-slow'}`}
        >
          {state.isGenerating ? 'Generando...' : hasApiKey ? 'FORJAR AHORA' : 'VINCULAR LLAVE'}
        </button>
      </aside>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useSpriteForge } from './hooks/useSpriteForge';
