import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ForgeConfig } from "../types";

export class GeminiService {
  private static getClient(): GoogleGenAI {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
      throw new Error("Conexión no activa. Por favor, haz clic en 'Activar Conexión' en el panel.");
    }
    return new GoogleGenAI({ apiKey });
  }

  static async enhancePrompt(userPrompt: string): Promise<string> {
    const ai = this.getClient();
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Act as a RPG Lead Artist. Convert this description into a professional game asset prompt. Use technical terms for materials and armor types. Output ONLY the prompt. Input: "${userPrompt}"`,
      });
      return response.text?.trim() || userPrompt;
    } catch (error) {
      return userPrompt;
    }
  }

  static async extractBaseDNA(sourceImage: string, config: ForgeConfig): Promise<string> {
    const ai = this.getClient();
    const systemInstruction = `
      GAME-READY ASSET ENGINE: DNA EXTRACTOR.
      1. Extract the base mannequin anatomy from the image.
      2. REMOVE all clothing and equipment.
      3. Render in standard T-pose or neutral pose.
      4. STYLE: High-quality Pixel Art.
      5. BACKGROUND: Pure Magenta (#FF00FF) for easy transparency removal.
      6. OUTPUT: One clean sprite centered.
    `;

    try {
      const response: GenerateContentResponse = await ai.models.generateContent({
        model: config.model,
        contents: {
          parts: [
            { inlineData: { data: this.stripBase64(sourceImage), mimeType: 'image/jpeg' } },
            { text: "GENERATE BASE DNA MANNEQUIN." }
          ]
        },
        config: { systemInstruction, imageConfig: { aspectRatio: config.aspectRatio } },
      });

      const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (imagePart?.inlineData) return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
      throw new Error("Error extrayendo base.");
    } catch (error: any) {
      throw error;
    }
  }

  static async synthesizeEvolution(baseImage: string, parentUrl: string | null, prompt: string, config: ForgeConfig): Promise<string> {
    const ai = this.getClient();

    const systemInstruction = `
      GAME-READY ASSET ENGINE: OUTFIT FORGE.
      OBJECTIVE: Create a new outfit on the BASE DNA provided.

      RULES:
      1. MAINTAIN EXACT ANATOMY: Don't change height, face, skin tone, or pose of REF A.
      2. OUTFIT ONLY: Generate the equipment requested in the prompt.
      3. STYLE: Professional RPG Pixel Art. Consistent lighting.
      4. GAME READY: Centered sprite, no artifacts.
      5. BACKGROUND: Pure Magenta (#FF00FF).
      6. SILHOUETTE: Keep it within the character bounds.
    `;

    const contents: any = {
      parts: [
        { inlineData: { data: this.stripBase64(baseImage), mimeType: 'image/jpeg' } },
        { text: "REF A: BASE DNA MANNEQUIN" }
      ]
    };

    if (parentUrl) {
      contents.parts.push({ inlineData: { data: this.stripBase64(parentUrl), mimeType: 'image/jpeg' } });
      contents.parts.push({ text: "REF B: PREVIOUS STATE" });
    }

    contents.parts.push({ text: `DIRECTIVE: Forja este atuendo: "${prompt}"` });

    try {
      const response: GenerateContentResponse = await ai.models.generateContent({
        model: config.model,
        contents,
        config: { 
          systemInstruction,
          imageConfig: { 
            aspectRatio: config.aspectRatio,
            ...(config.model.includes('pro') && { imageSize: config.size })
          }
        },
      });

      const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (imagePart?.inlineData) return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
      throw new Error("La síntesis falló.");
    } catch (error: any) {
      throw error;
    }
  }

  private static stripBase64(url: string): string {
    return url.split(',')[1] || url;
  }
}

import React, { useState, useRef } from 'react';
import { AppState, ForgeMode, NeuralMacro } from '../types';
import { QUICK_TAGS } from '../constants';
import { IconButton, Tag, Loader, ComparisonSlider, NeuralLog, Slider } from './UI';
