        <section className="space-y-4">
          <p className="text-[8px] font-black uppercase tracking-[0.3em] text-slate-600">Paleta de Estilo</p>
          <div className="flex flex-wrap gap-2">
            {QUICK_TAGS[0].tags.map(tag => (
