import React, { useState, useEffect, useCallback } from 'react';
import { useSpriteForge } from './hooks/useSpriteForge';
import { Atelier } from './components/Atelier';
import { ResultGallery } from './components/ResultGallery.tsx';
import { EvolutionTree } from './components/EvolutionTree';
import { ImageModal } from './components/ImageModal';
import { GeneratedOutfit, ModelType } from './types';

const App: React.FC = () => {
  const { state, dispatch, uploadBaseDNA, generateMannequin, executeBaseExtraction, executeSynthesis, deleteAsset } = useSpriteForge();

  const [prompt, setPrompt] = useState('');
  const [activeTab, setActiveTab] = useState<'forge' | 'vault' | 'tree'>('forge');
  const [selectedOutfit, setSelectedOutfit] = useState<GeneratedOutfit | null>(null);

  // Gestión de API Key Manual
  const [manualKey, setManualKey] = useState(localStorage.getItem('SF_API_KEY') || '');
  const [hasApiKey, setHasApiKey] = useState<boolean>(!!localStorage.getItem('SF_API_KEY') || !!process.env.API_KEY);
  const [isSetupOpen, setIsSetupOpen] = useState(!hasApiKey);
  const [showKey, setShowKey] = useState(false);

  const handleSaveManualKey = (val: string) => {
    const key = val.trim();
    setManualKey(key);
    if (key.length > 10) {
      localStorage.setItem('SF_API_KEY', key);
      setHasApiKey(true);
    } else if (key === '') {
      localStorage.removeItem('SF_API_KEY');
      setHasApiKey(!!process.env.API_KEY);
    }
  };

  const handleModelChange = (model: ModelType) => {
    dispatch({ type: 'UPDATE_CONFIG', payload: { model } });
  };

  const handleSelectAsParent = (o: GeneratedOutfit) => {
    dispatch({ type: 'SET_ACTIVE_PARENT', payload: o }); 
    setPrompt(o.prompt || ''); 
    setActiveTab('forge');
    setSelectedOutfit(null);
  };

  const handleForge = useCallback(async () => {
    try {
      await executeSynthesis(prompt);
    } catch (error: any) {
      if (error.message === 'RESELECT_KEY' || error.message === 'API_KEY_MISSING') {
        setIsSetupOpen(true);
      }
    }
  }, [executeSynthesis, prompt]);

  return (
    <div className="fixed inset-0 flex bg-[#020202] text-[#f8fafc] font-sans overflow-hidden">

      {/* SIDEBAR */}
      <aside className="w-20 md:w-24 bg-[#050505] border-r border-white/5 flex flex-col items-center py-10 z-50">
        <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center shadow-lg mb-12">
          <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" />
          </svg>
        </div>

        <nav className="flex-1 flex flex-col gap-6">
          <NavButton active={activeTab === 'forge'} onClick={() => setActiveTab('forge')} icon={
            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg>
          } />
          <NavButton active={activeTab === 'vault'} onClick={() => setActiveTab('vault')} icon={
            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M5 8h14M5 8a2 2 0 1 1 0-4h14a2 2 0 1 1 0 4M5 8v10a2 2 0 0 1-2 2h10a2 2 0 0 1-2-2V8m-9 4h4" /></svg>
          } />
          <NavButton active={activeTab === 'tree'} onClick={() => setActiveTab('tree')} icon={
            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 19v-6a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v6a2 2 0 0 0 2 2h2a2 2 0 0 0 2-2zm0 0V9a2 2 0 0 1 2-2h2a2 2 0 0 1 2 2v10m-6 0a2 2 0 0 0 2 2h2a2 2 0 0 0 2-2m0 0V5a2 2 0 0 1 2-2h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-2a2 2 0 0 1-2-2z" /></svg>
          } />
        </nav>

        <button 
          onClick={() => setIsSetupOpen(true)}
          className={`w-12 h-12 flex items-center justify-center rounded-2xl transition-all ${isSetupOpen ? 'bg-indigo-600 text-white' : 'text-slate-600 hover:text-white'}`}
        >
          <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 0 0 2.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 0 0 1.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 0 0-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 0 0-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 0 0-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 0 0-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 0 0 1.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
          </svg>
        </button>
      </aside>

      <div className="flex-1 flex flex-col min-w-0">
        <main className="flex-1 relative overflow-hidden">
          {activeTab === 'forge' && (
            <Atelier 
              state={state} prompt={prompt} setPrompt={setPrompt}
              onUpload={uploadBaseDNA}
              onForge={handleForge}
              onExtractBase={executeBaseExtraction}
              onGenerateMannequin={generateMannequin}
              onResetParent={() => dispatch({ type: 'SET_ACTIVE_PARENT', payload: null })}
              onUpdateMutation={(v) => dispatch({ type: 'UPDATE_CONFIG', payload: { mutationStrength: v } })}
              onSetMode={(m) => dispatch({ type: 'SET_FORGE_MODE', payload: m })}
              onApplyMacro={(macro) => dispatch({ type: 'UPDATE_CONFIG', payload: { activeMacroId: macro.id } })}
              onPromoteToBase={(url) => dispatch({ type: 'SET_BASE_IMAGE', payload: url })}
              hasApiKey={hasApiKey}
            />
          )}
          {activeTab === 'vault' && (
            <ResultGallery 
              outfits={state.outfits} 
              activeId={state.activeParent?.id} 
              onSelect={setSelectedOutfit} 
              onDelete={deleteAsset}
              onSelectAsParent={handleSelectAsParent}
            />
          )}
          {activeTab === 'tree' && (
            <EvolutionTree outfits={state.outfits} baseImage={state.baseImage} activeId={state.activeParent?.id} onSelect={setSelectedOutfit} />
          )}
        </main>
      </div>

      {isSetupOpen && (
        <div className="fixed inset-0 z-[6000] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/95 backdrop-blur-md" onClick={() => setIsSetupOpen(false)} />
          <div className="relative max-w-lg w-full bg-[#0a0a0a] border border-white/10 rounded-[2.5rem] p-8 sm:p-10 shadow-2xl animate-in zoom-in duration-300">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-sm font-black uppercase tracking-[0.4em] text-white">Motor Setup</h3>
              <button onClick={() => setIsSetupOpen(false)} className="text-slate-500 hover:text-white p-2">
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>

            <div className="space-y-8">
              <section>
                <div className="flex justify-between mb-4">
                  <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Manual API Key</p>
                  {manualKey.length > 10 && <span className="text-[8px] font-black text-emerald-500 uppercase">Activa</span>}
                </div>
                <div className="relative">
                  <input 
                    type={showKey ? "text" : "password"}
                    value={manualKey}
                    onChange={(e) => handleSaveManualKey(e.target.value)}
                    placeholder="Pega tu API Key aquí..."
                    className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-sm font-mono text-indigo-400 outline-none focus:border-indigo-500 transition-all pr-12"
                  />
                  <button onClick={() => setShowKey(!showKey)} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-600 hover:text-white">
                    {showKey ? <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0z" /></svg> : <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.875 18.825A10.05 10.05 0 0 1 12 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 0 1 1.563-3.029m5.858.908a3 3 0 1 1 4.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l18 18" /></svg>}
                  </button>
                </div>
                <p className="text-[9px] text-slate-600 mt-2 uppercase tracking-widest">Se guarda localmente para futuras sesiones.</p>
              </section>

              <section>
                <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-4">Modelo IA</p>
                <div className="grid grid-cols-2 gap-3">
                  <button onClick={() => handleModelChange('gemini-2.5-flash-image')} className={`p-4 rounded-2xl border-2 text-left transition-all ${state.config.model.includes('flash') ? 'bg-indigo-600/10 border-indigo-500 text-white' : 'bg-white/5 border-transparent opacity-40 hover:opacity-100'}`}>
                    <p className="text-[10px] font-black uppercase">Flash 2.5</p>
                    <p className="text-[8px] font-bold text-slate-500">Rápido / Gratis</p>
                  </button>
                  <button onClick={() => handleModelChange('gemini-3-pro-image-preview')} className={`p-4 rounded-2xl border-2 text-left transition-all ${state.config.model.includes('pro') ? 'bg-indigo-600/10 border-indigo-500 text-white' : 'bg-white/5 border-transparent opacity-40 hover:opacity-100'}`}>
                    <p className="text-[10px] font-black uppercase">Pro 3.0</p>
                    <p className="text-[8px] font-bold text-slate-500">Calidad / Pago</p>
                  </button>
                </div>
              </section>

              <button 
                onClick={() => setIsSetupOpen(false)}
                className="w-full py-5 bg-white text-black rounded-2xl font-black uppercase tracking-widest hover:bg-indigo-600 hover:text-white transition-all active:scale-95"
              >
                Cerrar Panel
              </button>
            </div>
          </div>
        </div>
      )}

      {selectedOutfit && (
        <ImageModal 
          outfit={selectedOutfit} 
          onClose={() => setSelectedOutfit(null)} 
          onDelete={deleteAsset} 
          onSelectAsParent={handleSelectAsParent} 
        />
      )}
    </div>
  );
};

const NavButton = ({ active, onClick, icon }: { active: boolean, onClick: () => void, icon: React.ReactNode }) => (
  <button onClick={onClick} className={`w-12 h-12 flex items-center justify-center rounded-2xl transition-all ${active ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/30' : 'text-slate-600 hover:text-white hover:bg-white/5'}`}>
    {icon}
  </button>
);

export default App;

