import React, { useState, useRef } from 'react';
import { AppState, ForgeMode, NeuralMacro } from '../types';
import { QUICK_TAGS } from '../constants';
import { IconButton, Tag, Loader, ComparisonSlider, NeuralLog, Slider, InfoBadge } from './UI';
import { GeminiService } from '../services/geminiService';

interface AtelierProps {
  state: AppState;
  prompt: string;
  setPrompt: (v: string) => void;
  onUpload: (url: string) => void;
  onForge: () => void;
  onExtractBase: (url: string) => void;
  onResetParent: () => void;
  onUpdateMutation: (v: number) => void;
  onSetMode: (mode: ForgeMode) => void;
  onApplyMacro: (macro: NeuralMacro) => void;
  onPromoteToBase: (url: string) => void;
  onGenerateMannequin: () => void;
  hasApiKey: boolean;
}

export const Atelier: React.FC<AtelierProps> = ({ 
  state, prompt, setPrompt, onUpload, onForge, onExtractBase, onResetParent, onUpdateMutation, onSetMode, onApplyMacro, onPromoteToBase, onGenerateMannequin, hasApiKey
}) => {
  const [isAlchemizing, setIsAlchemizing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleAlchemy = async () => {
    if (!prompt) return;
    setIsAlchemizing(true);
    try {
      const enhanced = await GeminiService.enhancePrompt(prompt);
      setPrompt(enhanced);
    } finally {
      setIsAlchemizing(false);
    }
  };

  if (!state.baseImage) {
    return (
      <div className="h-full flex flex-col items-center justify-center p-8 bg-[#050505]">
        <div className="max-w-md w-full text-center space-y-12">
          <div className="space-y-4">
            <h2 className="text-2xl font-black uppercase tracking-[0.4em] text-white">GENETIC SOURCE INJECTION</h2>
            <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest leading-loose">
              Para empezar, necesitamos un personaje base (maniquí) sin ropa para proyectar los outfits.
              Este paso consume <span className="text-indigo-400">1 Generación de Estructura</span>.
            </p>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 w-full">
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="aspect-square border-2 border-dashed border-white/5 rounded-[3.5rem] bg-white/[0.02] flex flex-col items-center justify-center group hover:bg-white/[0.04] hover:border-indigo-500/20 transition-all active:scale-95"
            >
              <div className="w-14 h-14 bg-white/5 rounded-2xl flex items-center justify-center mb-4 group-hover:bg-indigo-600 transition-all">
                <svg className="w-7 h-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
              </div>
              <span className="text-[9px] font-black uppercase tracking-widest text-slate-500 group-hover:text-white">Upload Reference</span>
              <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => {
                const file = e.target.files?.[0];
                if (file) {
                  const reader = new FileReader();
                  reader.onload = () => onUpload(reader.result as string);
                  reader.readAsDataURL(file);
                }
              }} />
            </button>

            <button 
              onClick={onGenerateMannequin}
              disabled={state.isGenerating}
              className="aspect-square border-2 border-indigo-500/20 rounded-[3.5rem] bg-indigo-500/5 flex flex-col items-center justify-center group hover:bg-indigo-600/10 hover:border-indigo-500 transition-all active:scale-95"
            >
              <div className="w-14 h-14 bg-indigo-600/10 rounded-2xl flex items-center justify-center mb-4 group-hover:bg-indigo-600 transition-all">
                <svg className="w-7 h-7 text-indigo-400 group-hover:text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
              </div>
              <span className="text-[9px] font-black uppercase tracking-widest text-indigo-400 group-hover:text-white">Forge Mannequin</span>
            </button>
          </div>
          {state.isGenerating && <Loader message="Generating Neural Base..." subMessage="Phase 1/1: Anatomical Calibration" />}
        </div>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col md:flex-row bg-[#020202] overflow-hidden">
      <div className="flex-1 relative bg-[#080808] overflow-hidden">
        <div className="absolute inset-0 checker-bg opacity-[0.02]" />

        {/* TOP STATUS BAR */}
        <div className="absolute top-8 left-8 right-8 z-30 flex items-center justify-between">
          <div className="flex gap-4">
            <div className="bg-black/60 backdrop-blur-xl border border-white/5 px-6 py-2.5 rounded-full flex items-center gap-3">
               <div className={`w-2 h-2 rounded-full ${state.isGenerating ? 'bg-indigo-500 animate-pulse' : 'bg-emerald-500'}`} />
               <span className="text-[8px] font-black uppercase tracking-[0.3em] text-white/60">
                 {state.isGenerating ? 'SYNTHESIS IN PROGRESS' : 'ENGINE READY'}
               </span>
            </div>
            <InfoBadge text={state.activeParent ? "Branching" : "Root Synthesis"} />
          </div>

          <button onClick={() => onPromoteToBase(null as any)} className="bg-white/5 hover:bg-white/10 text-white px-5 py-2.5 rounded-full text-[8px] font-black uppercase tracking-[0.3em] border border-white/5 transition-all">
            RESET GENETIC ROOT
          </button>
        </div>

        {/* VISOR CENTRAL */}
        <div className="absolute inset-0 flex items-center justify-center p-12">
           {state.activeParent ? (
             <ComparisonSlider before={state.baseImage} after={state.activeParent.url} className="max-w-[75%] max-h-[75%]" />
           ) : (
             <div className="relative group">
                <div className="absolute inset-0 bg-indigo-600/20 blur-[150px] opacity-20" />
                <img 
                  src={state.baseImage} 
                  className="max-h-[60vh] object-contain relative z-10 scale-[1.8] drop-shadow-[0_0_80px_rgba(79,70,229,0.2)] transition-transform duration-700 group-hover:scale-[1.9]" 
                  style={{ imageRendering: 'pixelated' }}
                  alt="Current Base" 
                />
             </div>
           )}
        </div>

        <NeuralLog active={state.isGenerating} />
        {state.isGenerating && (
          <Loader 
            message={state.activeParent ? "Evolving Branch..." : "Synthesizing Asset..."} 
            subMessage={state.activeParent ? "Phase 1/1: Morphing existing materials" : "Phase 1/1: Projecting gear onto DNA"} 
          />
        )}
      </div>

      <aside className="md:w-[420px] bg-[#050505] border-l border-white/5 p-8 flex flex-col gap-8 shrink-0 overflow-y-auto no-scrollbar">
        {/* TELEMETRY CONSOLE */}
        <section className="bg-white/[0.02] border border-white/5 rounded-3xl p-6 space-y-4">
          <div className="flex justify-between">
            <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest">Active Pipeline</span>
            <span className="text-[8px] font-black text-indigo-400 uppercase tracking-widest">{state.activeParent ? 'INCREMENTAL PATCH' : 'DIRECT PROJECTION'}</span>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
               <p className="text-[7px] font-bold text-slate-600 uppercase">Neural Cost</p>
               <p className="text-[10px] font-black text-white">1 GENERATION</p>
            </div>
            <div className="space-y-1">
               <p className="text-[7px] font-bold text-slate-600 uppercase">Anatomical Lock</p>
               <p className="text-[10px] font-black text-emerald-500">STABLE (98%)</p>
            </div>
          </div>
        </section>

        <section className="space-y-4">
          <div className="flex justify-between items-center">
            <h4 className="text-[10px] font-black uppercase tracking-[0.4em] text-indigo-400">GEAR SPECIFICATIONS</h4>
            <button 
              onClick={handleAlchemy} 
              disabled={isAlchemizing || !prompt}
              className={`text-[8px] font-black uppercase tracking-widest transition-all ${isAlchemizing ? 'text-indigo-400 animate-pulse' : 'text-slate-600 hover:text-white'}`}
            >
              Enhance Prompt
            </button>
          </div>
          <textarea 
            value={prompt} 
            onChange={(e) => setPrompt(e.target.value)}
            placeholder="Escribe el equipo a forjar sobre la base..."
            className="w-full h-32 bg-white/[0.03] border border-white/10 rounded-3xl p-6 text-sm text-white focus:border-indigo-500/40 focus:bg-white/[0.05] outline-none transition-all resize-none font-medium placeholder:text-slate-700"
          />
        </section>

        <section className="space-y-4">
          <p className="text-[8px] font-black uppercase tracking-[0.3em] text-slate-600">Style Modifiers</p>
          <div className="flex flex-wrap gap-2">
            {QUICK_TAGS[0].tags.map(tag => (
              <Tag key={tag} label={tag} onClick={() => setPrompt(prompt ? `${prompt}, ${tag}` : tag)} />
            ))}
          </div>
        </section>

        <section className="space-y-8">
          <Slider 
            label="Neural Mutation" 
            value={state.config.mutationStrength} 
            min={0} max={100} 
            onChange={onUpdateMutation} 
          />
        </section>

        <div className="mt-auto space-y-4">
          {state.error && (
            <div className="bg-red-500/10 border border-red-500/20 p-4 rounded-2xl text-red-400 text-[8px] font-bold uppercase text-center">
              {state.error}
            </div>
          )}

          <button 
            onClick={onForge}
            disabled={state.isGenerating || !prompt}
            className={`w-full py-6 rounded-[2.5rem] text-[12px] font-black uppercase tracking-[0.4em] text-white shadow-2xl transition-all ${state.isGenerating || !prompt ? 'bg-white/5 text-slate-600 cursor-not-allowed' : 'bg-indigo-600 hover:bg-indigo-500 shadow-indigo-600/20 hover:-translate-y-1'}`}
          >
            {state.isGenerating ? 'PROCESSING...' : 'FORGE ASSET'}
          </button>
          <div className="flex justify-center gap-6">
            <span className="text-[7px] font-bold text-slate-700 uppercase tracking-widest">Output: .PNG (Pixel Art)</span>
            <span className="text-[7px] font-bold text-slate-700 uppercase tracking-widest">Format: 1K HD</span>
          </div>
        </div>
      </aside>
    </div>
  );
};

