interface EvolutionTreeProps {
  outfits: GeneratedOutfit[];
  baseImage: string | null;
  activeId?: string;
  onSelect: (o: GeneratedOutfit) => void;
}

export const EvolutionTree: React.FC<EvolutionTreeProps> = ({ outfits, baseImage, activeId, onSelect }) => {
  const [filterStep, setFilterStep] = useState<number | 'all'>('all');

  const levels = useMemo(() => {
    const map = new Map<number, GeneratedOutfit[]>();
    outfits.forEach(o => {
      const step = o.evolutionStep || 1;
      if (filterStep !== 'all' && step !== filterStep) return;
      const current = map.get(step) || [];
      current.push(o);
      map.set(step, current);
    });
    return Array.from(map.entries()).sort((a: [number, any], b: [number, any]) => a[0] - b[0]);
  }, [outfits, filterStep]);

  const stepsAvailable = useMemo(() => 
    Array.from(new Set(outfits.map(o => o.evolutionStep))).sort((a: number, b: number) => a - b),
  [outfits]);

  if (!baseImage) {
    return (
      <div className="h-full w-full bg-[#050505] flex flex-col items-center justify-center p-12 text-center space-y-6 overflow-y-auto">
        <div className="w-20 h-20 bg-white/5 rounded-[2rem] flex items-center justify-center text-slate-700 animate-pulse">
          <svg className="w-10 h-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
        </div>
        <div className="space-y-2">
          <h3 className="text-sm font-black uppercase tracking-[0.5em] text-white/20">Archive Offline</h3>
          <p className="text-[9px] font-bold text-slate-600 uppercase tracking-widest max-w-xs leading-relaxed">Inyecta un ADN Base para iniciar el archivo evolutivo.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full w-full bg-[#030303] flex flex-col overflow-hidden">

      {/* HEADER DE LABORATORIO */}
      <header className="shrink-0 z-50 px-6 sm:px-10 py-6 sm:py-8 flex flex-col sm:flex-row items-center justify-between gap-6 border-b border-white/5 bg-black/40 backdrop-blur-xl">
        <div className="flex flex-col gap-1 items-center sm:items-start text-center sm:text-left">
          <h2 className="text-[10px] sm:text-[11px] font-black uppercase tracking-[0.4em] sm:tracking-[0.6em] text-white">Genetic Evolution Archive</h2>
          <div className="flex items-center gap-3">
             <span className="flex items-center gap-1.5 text-[8px] font-bold text-indigo-400 uppercase tracking-widest">
               <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-pulse" />
               Live Database
             </span>
             <span className="text-[8px] font-bold text-slate-600 uppercase tracking-widest">Total Assets: {outfits.length}</span>
          </div>
        </div>

        <div className="flex items-center gap-2 sm:gap-4 bg-white/5 p-1 rounded-2xl border border-white/5 overflow-x-auto max-w-full">
          <button 
            onClick={() => setFilterStep('all')}
            className={`shrink-0 px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${filterStep === 'all' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-500 hover:text-white'}`}
          >
            All
          </button>
          {stepsAvailable.slice(-4).map(step => (
            <button 
              key={step}
              onClick={() => setFilterStep(step)}
              className={`shrink-0 px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${filterStep === step ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-white'}`}
            >
              Step {step}
            </button>
          ))}
        </div>
      </header>

      {/* ÁREA DE VISUALIZACIÓN */}
      <div className="flex-1 overflow-auto relative">
        <div className="min-h-full min-w-full flex flex-col items-center py-24 sm:py-32 px-6 sm:px-10 gap-32 sm:gap-40 relative pb-48">

          {/* ADN ORIGEN (ROOT) */}
          <div className="relative z-30">
            <div className="w-32 h-32 sm:w-40 sm:h-40 rounded-[4rem] sm:rounded-[4.5rem] border-2 border-indigo-600/30 bg-[#080808] p-8 sm:p-10 relative group transition-all duration-700 hover:border-indigo-500">
              <div className="absolute inset-0 bg-indigo-600/10 blur-[100px] rounded-full opacity-40 group-hover:opacity-100 transition-opacity" />
              <img 
                src={baseImage} 
                className="w-full h-full object-contain relative z-10 opacity-40 grayscale group-hover:grayscale-0 group-hover:opacity-100 group-hover:scale-110 transition-all duration-1000" 
                style={{ imageRendering: 'pixelated' }} 
                alt="Source DNA" 
              />
              <div className="absolute -top-14 left-1/2 -translate-x-1/2 text-[10px] font-black text-indigo-400 uppercase tracking-[0.8em] whitespace-nowrap opacity-60">Neural Root</div>

              {/* Conector Vertical Principal */}
              <div className="absolute -bottom-24 left-1/2 -translate-x-1/2 w-[2px] h-24 bg-gradient-to-b from-indigo-500/50 via-indigo-500/10 to-transparent" />
            </div>
          </div>

          {/* NIVELES DE EVOLUCIÓN */}
          {levels.map(([step, nodes], idx) => (
            <div key={step} className="flex flex-col items-center gap-32 sm:gap-40 w-full animate-in zoom-in-95 duration-700">
              <div className="flex gap-12 sm:gap-20 justify-center flex-wrap max-w-7xl relative z-20 px-4 sm:px-10">
                {nodes.map(node => (
                  <div key={node.id} className="relative">
                    {/* Conector Genético dinámico */}
                    <div className="absolute -top-20 left-1/2 -translate-x-1/2 w-[1px] h-20 bg-white/5 group-hover:bg-indigo-500/20" />
                    <TreeNode outfit={node} onSelect={onSelect} isActive={activeId === node.id} />
                  </div>
                ))}
              </div>

              {/* Conector al siguiente nivel */}
              {idx < levels.length - 1 && (
                <div className="w-px h-24 bg-gradient-to-b from-indigo-500/10 to-indigo-500/5" />
              )}
            </div>
          ))}

          {/* Footer del Archivo */}
          <div className="h-64 flex flex-col items-center justify-center opacity-10">
            <div className="w-px h-32 bg-gradient-to-b from-white to-transparent" />
            <span className="text-[9px] font-black uppercase tracking-[1em] mt-10">End of Genomic Record</span>
          </div>
        </div>

        {/* Fondo Técnico */}
        <div className="fixed inset-0 pointer-events-none opacity-[0.03] checker-bg z-0" />
        <div className="fixed inset-0 pointer-events-none bg-gradient-to-b from-[#030303] via-transparent to-[#030303] z-10" />
      </div>
    </div>
  );
};

