export const ComparisonSlider: React.FC<{
  before: string;
  after: string;
  className?: string;
}> = ({ before, after, className = "" }) => {
  const [sliderPos, setSliderPos] = useState(50);
  const containerRef = useRef<HTMLDivElement>(null);

  const handleMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
    const position = ((x - rect.left) / rect.width) * 100;
    setSliderPos(Math.max(0, Math.min(100, position)));
  };

  return (
    <div 
      ref={containerRef}
      className={`relative w-full h-full select-none touch-none overflow-hidden rounded-[3rem] border border-white/5 ${className}`}
      onMouseMove={handleMove}
      onTouchMove={handleMove}
    >
      <div className="absolute inset-0 w-full h-full flex items-center justify-center pointer-events-none">
        <img src={before} style={{imageRendering:'pixelated', transform:'scale(1.2)'}} className="opacity-20 max-h-full max-w-full object-contain" alt="Original" />
        <div className="absolute top-6 left-6 bg-black/60 px-3 py-1 rounded-full text-[8px] font-black uppercase tracking-widest text-white/40">DNA SOURCE</div>
      </div>
      <div 
        className="absolute inset-0 w-full h-full flex items-center justify-center pointer-events-none z-10"
        style={{ clipPath: `inset(0 ${100 - sliderPos}% 0 0)` }}
      >
        <img src={after} style={{imageRendering:'pixelated', transform:'scale(1.2)'}} className="max-h-full max-w-full object-contain drop-shadow-[0_0_60px_rgba(99,102,241,0.6)]" alt="Synthesized" />
        <div className="absolute top-6 right-6 bg-indigo-600/40 px-3 py-1 rounded-full text-[8px] font-black uppercase tracking-widest text-white">EQUIPMENT OVERLAY</div>
      </div>
      <div className="absolute inset-y-0 w-0.5 bg-indigo-500 shadow-[0_0_20px_rgba(99,102,241,1)] z-20 pointer-events-none" style={{ left: `${sliderPos}%` }}>
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-10 h-10 bg-indigo-600/90 backdrop-blur-md rounded-xl flex items-center justify-center border border-white/20 rotate-45 shadow-2xl">
          <svg className="w-5 h-5 text-white -rotate-45" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M8 7l-4 4m0 0l4 4m-4-4h16m-4-4l4 4m0 0l-4 4" />
          </svg>
        </div>
      </div>
    </div>
  );
};

export const NeuralLog: React.FC<{ active: boolean }> = ({ active }) => {
  const [logs, setLogs] = useState<string[]>([]);
  const allLogs = [
    "> INITIALIZING NEURAL LINK...",
    "> MAPPING ANATOMICAL MESH...",
    "> INJECTING MATERIAL SHADERS...",
    "> STABILIZING PIXEL GRID...",
    "> CALCULATING LIGHT BOUNCES...",
    "> RESOLVING GENETIC DRIFT...",
    "> COMPILING SPRITE ASSET...",
    "> SYNTHESIS COMPLETE."
  ];

  useEffect(() => {
    if (!active) {
      setLogs([]);
      return;
    }
    let i = 0;
    const interval = setInterval(() => {
      if (i < allLogs.length) {
        setLogs(prev => [...prev.slice(-3), allLogs[i]]);
        i++;
      }
    }, 800);
    return () => clearInterval(interval);
  }, [active]);

  if (!active) return null;

  return (
    <div className="absolute bottom-6 left-6 right-6 z-[110] font-mono text-[8px] text-indigo-400 bg-black/90 backdrop-blur-2xl p-4 rounded-2xl border border-indigo-500/20 shadow-2xl animate-in slide-in-from-bottom-2">
      {logs.map((log, idx) => (
        <div key={idx} className={`${idx === logs.length - 1 ? 'text-white font-bold opacity-100' : 'opacity-30'}`}>
          {log}
        </div>
      ))}
    </div>
  );
};

