export const ComparisonSlider: React.FC<{
  before: string;
  after: string;
  className?: string;
}> = ({ before, after, className = "" }) => {
  const [sliderPos, setSliderPos] = useState(50);
  const containerRef = useRef<HTMLDivElement>(null);

  const handleMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
    const position = ((x - rect.left) / rect.width) * 100;
    setSliderPos(Math.max(0, Math.min(100, position)));
  };

  return (
    <div 
      ref={containerRef}
      className={`relative w-full h-full select-none touch-none overflow-hidden rounded-[4rem] border border-white/5 shadow-3xl bg-[#0a0a0a] ${className}`}
      onMouseMove={handleMove}
      onTouchMove={handleMove}
    >
      <div className="absolute inset-0 w-full h-full flex items-center justify-center pointer-events-none">
        <img src={before} className="opacity-15 max-h-full max-w-full object-contain pixelated scale-110" alt="DNA Source" />
        <div className="absolute top-8 left-8 bg-black/60 px-4 py-1.5 rounded-full text-[8px] font-black uppercase tracking-widest text-white/30 border border-white/5">GENETIC BASE</div>
      </div>
      <div 
        className="absolute inset-0 w-full h-full flex items-center justify-center pointer-events-none z-10"
        style={{ clipPath: `inset(0 ${100 - sliderPos}% 0 0)` }}
      >
        <img src={after} className="max-h-full max-w-full object-contain drop-shadow-[0_0_80px_rgba(99,102,241,0.5)] pixelated scale-110" alt="Synthesized Gear" />
        <div className="absolute top-8 right-8 bg-indigo-600/60 px-4 py-1.5 rounded-full text-[8px] font-black uppercase tracking-widest text-white border border-white/10 shadow-2xl">EVOLUTION ACTIVE</div>
      </div>
      <div className="absolute inset-y-0 w-0.5 bg-indigo-500 shadow-[0_0_25px_rgba(99,102,241,1)] z-20 pointer-events-none" style={{ left: `${sliderPos}%` }}>
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-12 h-12 bg-indigo-600/95 backdrop-blur-xl rounded-2xl flex items-center justify-center border border-white/20 rotate-45 shadow-2xl">
          <svg className="w-6 h-6 text-white -rotate-45" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M8 7l-4 4m0 0l4 4m-4-4h16m-4-4l4 4m0 0l-4 4" />
          </svg>
        </div>
      </div>
    </div>
  );
};

export const NeuralLog: React.FC<{ active: boolean }> = ({ active }) => {
  const [logs, setLogs] = useState<string[]>([]);
  const allLogs = [
    "> CONNECTING TO NEURAL HUB...",
    "> EXTRACTING DNA MASK...",
    "> SYNCING VOXEL GRID...",
    "> PROJECTING ASSET GEOMETRY...",
    "> BAKING MATERIAL TEXTURES...",
    "> PIXELGUARD VALIDATION...",
    "> ASSET STABILIZED."
  ];

  useEffect(() => {
    if (!active) {
      setLogs([]);
      return;
    }
    let i = 0;
    const interval = setInterval(() => {
      if (i < allLogs.length) {
        setLogs(prev => [...prev.slice(-3), allLogs[i]]);
        i++;
      }
    }, 900);
    return () => clearInterval(interval);
  }, [active]);

  if (!active) return null;

  return (
    <div className="absolute bottom-8 left-8 right-8 z-[110] font-mono text-[8px] text-indigo-400/80 bg-black/95 backdrop-blur-3xl p-5 rounded-3xl border border-indigo-500/20 shadow-3xl animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col gap-1">
        {logs.map((log, idx) => (
          <div key={idx} className={`${idx === logs.length - 1 ? 'text-white font-bold' : 'opacity-25'}`}>
            {log}
          </div>
        ))}
      </div>
    </div>
  );
};

